def _webapp_telegram_user(init_data):
    """Verify Telegram Mini App initData before reading a user's shop records."""
    try:
        if not TOKEN or not isinstance(init_data, str) or len(init_data) > 8192:
            return None
        values = urllib.parse.parse_qs(init_data, strict_parsing=True, keep_blank_values=True)
        if any(len(v) != 1 for v in values.values()):
            return None
        supplied = values.pop('hash', [None])[0]
        auth_date = int(values.get('auth_date', ['0'])[0])
        if not supplied or abs(time.time() - auth_date) > 3600:
            return None
        check_string = '\n'.join(f'{key}={values[key][0]}' for key in sorted(values))
        secret = hmac.new(b'WebAppData', TOKEN.encode(), hashlib.sha256).digest()
        actual = hmac.new(secret, check_string.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(supplied, actual):
            return None
        identity = json.loads(values.get('user', [''])[0])
        uid = identity.get('id')
        return identity if isinstance(uid, int) and uid > 0 else None
    except (ValueError, TypeError, KeyError, json.JSONDecodeError):
        return None


def _webapp_store_snapshot(identity):
    """A bounded, read-only view of the same collections used by the bot."""
    uid = identity['id']
    user = db.users.find_one({'user_id': uid}, {'balance': 1, 'is_banned': 1})
    if not user or user.get('is_banned') == 1:
        return None
    products = []
    for p in db.products.find({'is_hidden': {'$ne': True}},
            {'id': 1, 'name_ar': 1, 'desc_ar': 1, 'price': 1, 'stock': 1, 'category': 1}).limit(100):
        products.append({'id': str(p.get('id') or p['_id']),
                         'name': str(p.get('name_ar') or 'منتج رقمي')[:100],
                         'description': str(p.get('desc_ar') or '')[:220],
                         'price': float(p.get('price') or 0),
                         'stock': p.get('stock'), 'category': str(p.get('category') or '')[:50]})
    # Keep catalog names in English regardless of the visitor's description language.
    names_en = {str(p.get('id') or p['_id']): p.get('name_en')
                for p in db.products.find({'is_hidden': {'$ne': True}},
                    {'id': 1, 'name_en': 1}).limit(100)}
    for item in products:
        if names_en.get(item['id']):
            item['name'] = str(names_en[item['id']])[:100]
    orders = []
    for o in db.orders.find({'user_id': uid},
            {'product_id': 1, 'total_price': 1, 'price': 1, 'status': 1}).sort('_id', -1).limit(20):
        orders.append({'id': str(o['_id']), 'product': str(o.get('product_id') or '')[:80],
                       'date': o['_id'].generation_time.strftime('%Y-%m-%d'),
                       'amount': float(o.get('total_price') or o.get('price') or 0),
                       'status': str(o.get('status') or 'completed')[:30]})
    return {'connected': True, 'user': {'id': uid, 'first_name': str(identity.get('first_name') or '')[:80]},
            'balance': float(user.get('balance') or 0), 'products': products, 'orders': orders}


def _webapp_translate(identity, lang, items):
    """Translate only requested public UI/product copy; cache by language and source hash."""
    if not isinstance(lang, str) or not isinstance(items, list) or len(items) > 30:
        raise ValueError('Invalid translation request')
    supported = set(GoogleTranslator().get_supported_languages(as_dict=True).values())
    if lang not in supported and lang != 'ar':
        raise ValueError('Unsupported language')
    if any(not isinstance(x, str) or len(x) > 600 for x in items):
        raise ValueError('Invalid translation text')
    output = []
    for value in items:
        if not value.strip() or lang == 'ar':
            output.append(value)
            continue
        cache_id = hashlib.sha256((lang + '\0' + value).encode()).hexdigest()
        cached = db.webapp_i18n.find_one({'_id': cache_id}, {'value': 1})
        if cached:
            output.append(cached['value'])
            continue
        # Bound new provider calls to protect the bot's bandwidth and translation quota.
        day = time.strftime('%Y-%m-%d', time.gmtime())
        usage = db.webapp_translation_usage.find_one_and_update(
            {'_id': f"{identity['id']}:{day}", 'count': {'$lt': 50}},
            {'$inc': {'count': 1}}, return_document=True)
        if usage is None:
            existing = db.webapp_translation_usage.find_one({'_id': f"{identity['id']}:{day}"})
            if existing:
                output.append(value)
                continue
            try:
                db.webapp_translation_usage.insert_one({'_id': f"{identity['id']}:{day}", 'count': 1})
            except Exception:
                output.append(value)
                continue
        try:
            translated = GoogleTranslator(source='auto', target=lang).translate(value)
            result = str(translated or value)[:1200]
            db.webapp_i18n.update_one({'_id': cache_id},
                {'$setOnInsert': {'value': result}}, upsert=True)
            output.append(result)
        except Exception:
            output.append(value)
    return output


def _api_http_guard(func):
    @functools.wraps(func)
    def wrapped(self):
        # Only the public health probe may run while module definitions and DB
        # initialization are still being loaded by the main thread.
        if not _API_READY.is_set() and not (
                func.__name__ == 'do_GET' and urllib.parse.urlparse(self.path).path.rstrip('/') == ''):
            return _json_resp(self, 503, {'success': False, 'code': 'initializing',
                'error': 'API is starting. Retry shortly.'})
        try:
            return func(self)
        except (BrokenPipeError, ConnectionResetError):
            return
        except Exception as exc:
            # Never put the secret URL, authentication headers or body into logs.
            import traceback
            frames = traceback.extract_tb(exc.__traceback__)
            location = ' > '.join(f'{f.name}:{f.lineno}' for f in frames[-6:])
            missing = getattr(exc, 'name', '') if isinstance(exc, NameError) else ''
            logger.error('Reseller API %s failed (%s) missing=%s at=%s',
                         func.__name__, type(exc).__name__, missing, location)
            return _json_resp(self, 503, {
                'success': False, 'error': 'API temporarily unavailable',
                'code': 'service_unavailable',
                'message': 'For a purchase, check your orders before retrying; its outcome may be unknown.'})
    return wrapped


def _json_resp(h, code, data):
    capture = globals().get('_error_capture')
    context = globals().get('_ERROR_CONTEXT')
    current = getattr(context, 'value', None) or {}
    if capture and code >= 500 and not current.get('last_error'):
        capture('HTTP operation failed: ' + str(data.get('error', 'server_error')) if isinstance(data, dict) else 'HTTP operation failed')
    hook = getattr(h, '_idem_hook', None)
    if hook:
        h._idem_hook = None
        try:
            hook(code, data)            # نحفظ النتيجة قبل الإرسال — حتى لو انقطع الاتصال
        except Exception as e:
            logger.warning(f"idempotency save failed: {e}")
    try:
        import gzip
        raw = getattr(h, '_net_json_payload', None)
        if hasattr(h, '_net_json_payload'):
            del h._net_json_payload
        if raw is None:
            raw = json.dumps(data, ensure_ascii=False, separators=(',', ':')).encode('utf-8')
        compressed = code != 304 and len(raw) > 1024 and _net_accepts_gzip(getattr(h, 'headers', {}))
        payload = gzip.compress(raw, compresslevel=5, mtime=0) if compressed else raw
        h.send_response(code)
        h.send_header('Content-Type', 'application/json; charset=utf-8')
        h.send_header('X-Bot-API-Revision', 'ext-purchase-v3')
        h.send_header('Access-Control-Allow-Origin', '*')
        h.send_header('Access-Control-Allow-Headers', 'Authorization, Content-Type, X-API-Key, X-Shop-API-Key, Idempotency-Key, X-Telegram-Init-Data, If-None-Match')
        h.send_header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS')
        h.send_header('Access-Control-Expose-Headers', 'ETag')
        h.send_header('Cache-Control', 'private, no-cache' if getattr(h, '_net_etag', None) else 'no-store')
        h.send_header('Vary', 'Accept-Encoding')
        if getattr(h, '_net_etag', None):
            h.send_header('ETag', h._net_etag)
        if code != 304:
            h.send_header('Content-Length', str(len(payload)))
            if compressed:
                h.send_header('Content-Encoding', 'gzip')
        h.end_headers()
        if code != 304:
            h.wfile.write(payload)
    except (BrokenPipeError, ConnectionResetError):
        # العميل قطع الاتصال قبل اكتمال الإرسال — غير ضار، نتجاهله بهدوء
        pass
    except Exception as e:
        logger.debug(f"_json_resp err: {e}")

def _api_idem_begin(uid, key, sig):
    """Idempotency-Key لكل المنتجات: نفس المفتاح = نفس الطلب (ما ينخصم مرتين)."""
    if not isinstance(key, str) or not 1 <= len(key.strip()) <= 128:
        return None, (400, {'error': 'Idempotency-Key must be a nonempty string of at most 128 characters'})
    ref = 'IDEM_' + hashlib.sha256(f'{uid}:{key.strip()}'.encode()).hexdigest()[:40]
    try:
        db.api_idempotency.insert_one({'_id': ref, 'api_user_id': uid, 'sig': sig, 'status': 'pending', 'at': int(time.time())})
        return ref, None
    except Exception as exc:
        if type(exc).__name__ != 'DuplicateKeyError':
            raise
    d = db.api_idempotency.find_one({'_id': ref}) or {}
    if d.get('sig') != sig:
        return None, (409, {'error': 'Idempotency-Key already used for a different purchase', 'code': 'idempotency_conflict'})
    if d.get('status') == 'done':
        return None, (int(d.get('code') or 200), dict(d.get('data') or {}, idempotent_replay=True))
    return None, (409, {'error': 'This purchase is still processing or its outcome is unknown. Check GET /orders before retrying.',
                        'code': 'idempotency_in_progress'})


def _api_idem_finish(ref, code, data):
    refunded = isinstance(data, dict) and (data.get('refunded') is True or 'refunded' in str(data.get('error', '')).lower())
    if code == 200:
        db.api_idempotency.update_one({'_id': ref}, {'$set': {'status': 'done', 'code': code, 'data': data, 'done_at': int(time.time())}})
    elif code >= 500 and not refunded:
        db.api_idempotency.update_one({'_id': ref}, {'$set': {'status': 'unknown', 'code': code}})   # النتيجة مو مؤكدة — لا نعيد الشراء
    else:
        db.api_idempotency.delete_one({'_id': ref})          # ما انخصم شي → المفتاح يقدر ينعاد


def _read_body(h):
    """قراءة body آمنة تدعم Content-Length و chunked encoding"""
    try:
        cl = h.headers.get('Content-Length')
        if cl:
            return h.rfile.read(int(cl)).decode('utf-8')
        # chunked أو بدون Content-Length
        te = h.headers.get('Transfer-Encoding', '').lower()
        if 'chunked' in te:
            chunks = []
            while True:
                line = h.rfile.readline().decode('utf-8').strip()
                size = int(line, 16)
                if size == 0:
                    break
                chunks.append(h.rfile.read(size).decode('utf-8'))
                h.rfile.readline()
            return ''.join(chunks)
        return ''
    except Exception:
        return ''

# Rate limiter بسيط: max 30 طلب/دقيقة لكل API key
_api_rate = {}
_api_rate_lock = __import__('threading').Lock()

def _check_rate_limit(api_key):
    """True = مسموح، False = محظور مؤقتاً"""
    import time as _t
    now = _t.time()
    window = 60  # ثانية
    max_req = 30
    with _api_rate_lock:
        if api_key not in _api_rate:
            _api_rate[api_key] = []
        # نحذف الطلبات القديمة
        _api_rate[api_key] = [ts for ts in _api_rate[api_key] if now - ts < window]
        if len(_api_rate[api_key]) >= max_req:
            return False
        _api_rate[api_key].append(now)
        return True


def _extract_emoji_ids_from_text(text):
    """🌟 يستخرج كل معرّفات الإيموجي المميز من نص يحتوي على وسوم <tg-emoji emoji-id="...">"""
    if not text:
        return []
    try:
        return re.findall(r'<tg-emoji\s+emoji-id="([^"]+)"', str(text))
    except Exception:
        return []


def _build_emoji_fields(pr, name_custom_emoji_id, desc_ar, desc_en):
    """
    🌟 يبني كل حقول الإيموجي المميز لمنتج (للاسم والوصف معاً).
    يرجّع dict جاهز يُدمج في رد الـ API.
    - desc_ar_html / desc_en_html: الوصف كامل جاهز للعرض مع parse_mode=HTML
    - desc_ar / desc_en: الوصف بدون تعديل (نص خام)
    """
    desc_ar_ids = _extract_emoji_ids_from_text(desc_ar)
    desc_en_ids = _extract_emoji_ids_from_text(desc_en)
    desc_ids = list(dict.fromkeys(desc_ar_ids + desc_en_ids))
    all_ids = []
    if name_custom_emoji_id:
        all_ids.append(str(name_custom_emoji_id))
    all_ids = list(dict.fromkeys(all_ids + desc_ids))

    # الوصف يحتوي أصلاً على وسوم <tg-emoji> — نُرجعه كما هو جاهزاً للعرض
    # لو ما فيه إيموجي يُرجع نص عادي أيضاً، لا فرق
    return {
        'desc_ar_html': desc_ar or '',       # جاهز للعرض المباشر في تيليغرام بـ parse_mode=HTML
        'desc_en_html': desc_en or '',       # جاهز للعرض المباشر في تيليغرام بـ parse_mode=HTML
        'desc_has_premium_emoji': bool(desc_ids),
        'desc_emoji_ids': desc_ids,
        'all_emoji_ids': all_ids
    }


def _build_api_owner_profile(uid):
    """
    🔍 يبني نص بيانات صاحب الـ API للإشعار (الأونر فقط):
    - الاسم الكامل + لينك البروفايل (قابل للنقر)
    - اليوزرنيم (لو موجود)
    - الأيدي + الرصيد الحالي
    """
    try:
        u = db.users.find_one({'user_id': uid}) or {}
        api_doc = db.api_keys.find_one({'user_id': uid, 'is_active': True}) or {}

        name = u.get('name', '') or api_doc.get('username', str(uid))
        username = u.get('username', '') or api_doc.get('username', '')
        balance = round(float(u.get('balance', 0)), 2) if u else 0.0

        # 🆙 محاولة جلب الاسم الحالي من تيليجرام (أحدث من DB)
        try:
            chat = bot.get_chat(uid)
            full_name = chat.first_name or ''
            if chat.last_name:
                full_name += f' {chat.last_name}'
            if full_name.strip():
                name = full_name.strip()
            if chat.username:
                username = chat.username.lower()
        except Exception:
            pass

        safe_name = html.escape(name or str(uid))

        # لينك بروفايل قابل للنقر (يشتغل حتى بدون يوزرنيم)
        profile_link = f'<a href="tg://user?id={uid}">{safe_name}</a>'

        lines = [
            f"👤 <b>صاحب الـ API:</b>",
            f"   🔗 {profile_link}",
            f"   🆔 <code>{uid}</code>",
        ]
        if username:
            lines.append(
                f'   📛 <a href="https://t.me/{username}">@{username}</a>'
            )
        lines.append(f"   💰 رصيده الحالي: <b>${balance:.2f}</b>")

        return "\n".join(lines)
    except Exception as e:
        logger.debug(f"_build_api_owner_profile error: {e}")
        return f"👤 API User: <code>{uid}</code>"


