# ================================================================
# ChatGPT Business Seat Manager — مدمج مع البوت
# ================================================================

_CGPT_DATA_LOCK = threading.RLock()
_CGPT_ACCOUNT_LOCKS = {}
_CGPT_STOCK_CACHE = {}
_CGPT_CAPACITY_CACHE = {}
_CGPT_STOCK_LOCK = threading.RLock()
_CGPT_MEMBER_HEALTH = {}
_CGPT_MEMBER_HEALTH_LOCK = threading.RLock()


def _cgpt_account_lock(account_id):
    with _CGPT_DATA_LOCK:
        return _CGPT_ACCOUNT_LOCKS.setdefault(str(account_id), threading.RLock())


def _cgpt_data_fingerprint(data):
    snapshot = dict(data or {})
    snapshot['allowed_emails'] = sorted(set(snapshot.get('allowed_emails') or []))
    return hashlib.sha256(json.dumps(snapshot, sort_keys=True, separators=(',', ':'), default=str).encode()).hexdigest()


def _cgpt_stock_key(account, access, session, manual=None):
    return str(account) + ':' + hashlib.sha256(f'{access}|{session}|{manual}'.encode()).hexdigest()[:24]


def _cgpt_stock_invalidate(capacity=False):
    with _CGPT_STOCK_LOCK:
        _CGPT_STOCK_CACHE.clear()
        if capacity:
            _CGPT_CAPACITY_CACHE.clear()
    _CGPT_SEATS_CACHE['exp'] = 0
    _CGPT_DISPLAY_SEATS['expires'] = 0


def _cgpt_member_health(manager):
    """Keep outage backoff across the temporary managers built by the daemon."""
    key = str(getattr(manager, '_account_key', None) or manager.account_id or 'main')
    credentials = hashlib.sha256((str(manager.access_token or '') + '\0' +
                                 str(manager.session_token or '')).encode()).hexdigest()
    with _CGPT_MEMBER_HEALTH_LOCK:
        state = _CGPT_MEMBER_HEALTH.get(key)
        if not state or state.get('credentials') != credentials:
            if len(_CGPT_MEMBER_HEALTH) >= 256:
                _CGPT_MEMBER_HEALTH.pop(next(iter(_CGPT_MEMBER_HEALTH)), None)
            state = {'credentials': credentials, 'failures': 0, 'retry_at': 0, 'references': []}
            _CGPT_MEMBER_HEALTH[key] = state
        return state


def _cgpt_member_ready(manager):
    state = _cgpt_member_health(manager)
    if state.get('retry_at', 0) > time.time():
        manager._last_fetch_failed = True
        manager._last_fetch_status = state.get('status', 'connection')
        return False
    return True


def _cgpt_member_defer(manager, status, exc=None, retry_after=0):
    """A failed read is never an empty member list and never proves expired cookies."""
    state = _cgpt_member_health(manager)
    with _CGPT_MEMBER_HEALTH_LOCK:
        state['failures'] = min(10, state.get('failures', 0) + 1)
        delay = 3600 if status in (401, 403) else min(900, 60 * 2 ** (state['failures'] - 1))
        try:
            delay = max(delay, min(3600, max(0, int(retry_after))))
        except (TypeError, ValueError):
            pass
        state.update(status=status, retry_at=time.time() + delay)
    manager._last_fetch_failed = True
    manager._last_fetch_status = status
    with _error_scope(source='background', operation='cgpt:members:' +
                      str(getattr(manager, '_account_key', None) or manager.account_id or 'main')):
        reference = _error_capture('ChatGPT member lookup unavailable; cleanup deferred safely',
            exc=exc, level='WARNING', location='ChatGPTSeatManager._get_org_users',
            browser_trace='Read status: ' + str(status) + '; retry after ' + str(delay) + ' seconds.')
    if reference and reference not in state['references']:
        state['references'] = (state['references'] + [reference])[-8:]


def _cgpt_member_recovered(manager):
    state = _cgpt_member_health(manager)
    references = list(state.get('references', []))
    with _CGPT_MEMBER_HEALTH_LOCK:
        state.update(failures=0, retry_at=0, status=200, references=[])
    manager._last_fetch_failed = False
    manager._last_fetch_status = 200
    for reference in references:
        _error_resolve_automatic(reference, 'ChatGPT member lookup recovered')


def _cgpt_manager_guard(func):
    @functools.wraps(func)
    def guarded(self, *args, **kwargs):
        with _cgpt_account_lock(getattr(self, '_account_key', 'main')):
            doc = db.cgpt_invites_data.find_one({'_id': getattr(self, '_account_key', 'main')})
            if doc and doc.get('data'):
                self.invites_data = doc['data']
                self._saved_data_digest = _cgpt_data_fingerprint(doc['data'])
                self.allowed_emails = set(self.invites_data.get('allowed_emails', []))
                if self.owner_email:
                    self.allowed_emails.add(self.owner_email)
            return func(self, *args, **kwargs)
    return guarded


class ChatGPTSeatManager:
    """
    مدير مقاعد ChatGPT Business.
    يعمل كـ singleton — استخدم get_cgpt_manager().
    """
    _instance = None

    def __init__(self):
        _raw_path = get_setting('cgpt_token_path')
        self.token_file = _raw_path if _raw_path and _raw_path != 'Not Set' else 'pasted_content.txt'
        self.data_file  = get_setting('cgpt_data_file') or 'cookie_seat_invites.json'
        self.access_token  = None
        self.session_token = None
        self.org_id        = None
        self.account_id    = None
        self.owner_email   = None
        self._loaded       = False
        self._load_tokens()
        self.invites_data  = self._load_data()
        self.allowed_emails = set(self.invites_data.get('allowed_emails', []))

    # ---------- token / data ----------
    def _load_tokens(self):
        # 1) نحاول من قاعدة البيانات أولاً (دائم على Render)
        try:
            db_doc = db.cgpt_cookies.find_one({'_id': 'main'})
            if db_doc and db_doc.get('data'):
                c = db_doc['data']
                self.access_token  = c.get('accessToken')
                self.session_token = c.get('sessionToken')
                acct = c.get('account', {})
                self.org_id     = acct.get('organizationId')
                self.account_id = acct.get('id')
                user = c.get('user', {})
                self.owner_email = user.get('email')
                self._loaded = bool(self.access_token and self.session_token)
                if self._loaded:
                    logger.info("[CGPT] Loaded tokens from DB")
                    return
        except Exception as db_err:
            logger.debug(f"[CGPT] DB load failed: {db_err}")

        # لا توجد كوكيز في DB
        logger.info("[CGPT] No cookies in DB yet — admin must add them")
        self._loaded = False

    def _headers(self):
        return {
            'Authorization': f'Bearer {self.access_token}',
            'Content-Type':  'application/json',
            'Cookie':        f'__Secure-next-auth.session-token={self.session_token}',
            'User-Agent':    'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
            'Accept':        'application/json',
            'Origin':        'https://chatgpt.com',
            'Referer':       'https://chatgpt.com/'
        }

    def _load_data(self):
        """تحميل بيانات الدعوات من MongoDB"""
        try:
            doc = db.cgpt_invites_data.find_one({'_id': 'main'})
            if doc and doc.get('data'):
                return doc['data']
        except Exception as e:
            logger.debug(f"[CGPT] load_data DB err: {e}")
        return {'invites': {}, 'allowed_emails': [self.owner_email] if self.owner_email else []}

    def _save_data(self):
        """حفظ بيانات الدعوات في MongoDB (لكل حساب على حدة)"""
        self.invites_data['allowed_emails'] = sorted(self.allowed_emails)
        digest = _cgpt_data_fingerprint(self.invites_data)
        if getattr(self, '_saved_data_digest', None) == digest:
            return True
        _key = getattr(self, '_account_key', 'main')
        try:
            db.cgpt_invites_data.update_one(
                {'_id': _key},
                {'$set': {'data': self.invites_data}},
                upsert=True
            )
            self._saved_data_digest = digest
            return True
        except Exception as e:
            logger.error(f"[CGPT] save_data DB err: {e}")

    def reload_token(self):
        """إعادة تحميل الـ token من MongoDB"""
        self._load_tokens()
        return self._loaded

    # ---------- core API ----------
    def check_subscription_status(self):
        """يفحص حالة اشتراك البيزنس. يرجّع:
        'active' | 'deactivated' | 'no_seats' | 'error' | 'unauthorized'"""
        if not CFFI_AVAILABLE or not self._loaded:
            return 'unauthorized'
        try:
            # endpoint الرسمي لفحص حالة الحساب
            url = 'https://chatgpt.com/backend-api/accounts/check/v4-2023-04-27'
            r = cffi_requests.get(url, headers=self._headers(),
                                  impersonate='chrome110', timeout=15)
            if r.status_code == 402:
                # workspace معطّل (اشتراك ملغى/فاتورة غير مدفوعة)
                return 'deactivated'
            if r.status_code == 401:
                return 'unauthorized'
            if r.status_code == 200:
                data = r.json()
                # نبحث عن حالة الاشتراك في بنية الرد
                accounts = data.get('accounts', {})
                for acc_key, acc_val in accounts.items():
                    if not isinstance(acc_val, dict):
                        continue
                    acc = acc_val.get('account', acc_val)
                    # لو الحساب هو حسابنا
                    if acc.get('account_id') == self.account_id or acc_key == self.account_id or acc_key == 'default':
                        plan = acc.get('plan_type', acc.get('structure', ''))
                        is_deactivated = acc.get('is_deactivated', False)
                        if is_deactivated:
                            return 'deactivated'
                        # لو فيه اشتراك بيزنس/تيم فعّال
                        return 'active'
                return 'active'  # الحساب موجود ويعمل
            return 'error'
        except Exception as e:
            logger.debug(f"[CGPT] check_subscription err: {e}")
            return 'error'

    def _get_org_users(self):
        if not CFFI_AVAILABLE or not self._loaded:
            self._last_fetch_failed = True
            self._last_fetch_status = 401
            return []
        with _cgpt_account_lock(getattr(self, '_account_key', None) or self.account_id or 'main'):
            if not _cgpt_member_ready(self):
                return []
            self._last_fetch_failed = True
            self._last_fetch_status = None
            try:
                url = f'https://chatgpt.com/backend-api/accounts/{self.account_id}/users'
                r = cffi_requests.get(url, headers=self._headers(), impersonate='chrome110', timeout=(5, 20))
                if r.status_code == 200:
                    data = r.json()
                    users = data.get('items') if isinstance(data, dict) else None
                    if not isinstance(users, list) or any(not isinstance(u, dict) for u in users):
                        raise ValueError('Invalid ChatGPT member-list response')
                    if (data.get('has_more') or data.get('next') or data.get('next_cursor') or
                            int(data.get('total', len(users)) or 0) > len(users)):
                        raise ValueError('Incomplete ChatGPT member-list response; cleanup deferred')
                    _cgpt_member_recovered(self)
                    return users
                _cgpt_member_defer(self, r.status_code,
                                  retry_after=getattr(r, 'headers', {}).get('Retry-After', 0))
            except Exception as e:
                kind = 'timeout' if getattr(e, 'code', None) == 28 or 'timeout' in type(e).__name__.lower() else 'connection'
                _cgpt_member_defer(self, kind, exc=e)
        return []

    @_cgpt_manager_guard
    def invite_user(self, email: str, minutes_valid: int) -> dict:
        """
        يدعو مستخدم ويرجع dict:
        {'ok': True/False, 'expires_at': '...', 'error': '...'}
        """
        if not CFFI_AVAILABLE:
            return {'ok': False, 'error': 'curl_cffi غير مثبتة'}
        if not self._loaded:
            return {'ok': False, 'error': 'لم يتم تحميل الـ token'}
        try:
            url = f'https://chatgpt.com/backend-api/accounts/{self.account_id}/invites'
            payload = {'email_addresses': [email], 'role': 'standard-user'}
            r = cffi_requests.post(url, headers=self._headers(), json=payload,
                                   impersonate='chrome110', timeout=15)
            if r.status_code in [200, 201]:
                expires_at = (_dt_mod.datetime.now() +
                              _dt_mod.timedelta(minutes=minutes_valid)).isoformat()
                self.invites_data['invites'][email] = {
                    'invited_at': _dt_mod.datetime.now().isoformat(),
                    'expires_at': expires_at,
                    'status': 'active',
                    'minutes': minutes_valid,
                    'telegram_uid': getattr(self, '_last_buyer_uid', None)
                }
                self.allowed_emails.add(email)
                self._save_data()
                return {'ok': True, 'expires_at': expires_at}
            else:
                err = r.text[:300]
                logger.error(f"[CGPT] invite failed {r.status_code}: {err}")
                return {'ok': False, 'error': f'{r.status_code}: {err}'}
        except Exception as e:
            return {'ok': False, 'error': str(e)}

    def remove_user_by_email(self, email: str) -> bool:
        """يحذف مستخدم بالإيميل"""
        users = self._get_org_users()
        for u in users:
            if u.get('email') == email:
                return self._remove_user(u.get('id'), email)
        return False

    def remove_by_email(self, email):
        """Remove a member or pending invite; distinguish absence from failed checks."""
        if not CFFI_AVAILABLE or not self._loaded:
            return 'error'
        email_l = str(email).strip().lower()
        if email_l == str(self.owner_email or '').strip().lower():
            return 'error'
        try:
            users = self._get_org_users()
            if getattr(self, '_last_fetch_failed', False):
                return 'error'
            for user in users:
                if str(user.get('email') or '').strip().lower() == email_l:
                    user_id = user.get('id') or user.get('user_id')
                    return 'member' if user_id and self._remove_user(user_id, email) else 'error'
            url = f'https://chatgpt.com/backend-api/accounts/{self.account_id}/invites'
            response = cffi_requests.get(url, headers=self._headers(), impersonate='chrome110', timeout=15)
            if response.status_code != 200:
                return 'error'
            data = response.json()
            invites = data if isinstance(data, list) else data.get('items', data.get('invites')) if isinstance(data, dict) else None
            if not isinstance(invites, list):
                return 'error'
            for invite in invites:
                if str(invite.get('email_address', invite.get('email', ''))).strip().lower() != email_l:
                    continue
                invite_id = invite.get('id') or invite.get('invite_id')
                if invite_id:
                    try:
                        removed = cffi_requests.delete(f'{url}/{invite_id}', headers=self._headers(),
                            impersonate='chrome110', timeout=15)
                        if removed.status_code in (200, 204):
                            return 'pending'
                    except Exception:
                        pass
                try:
                    removed = cffi_requests.delete(url, headers=self._headers(), json={'email_address': email},
                        impersonate='chrome110', timeout=15)
                    if removed.status_code in (200, 204):
                        return 'pending'
                except Exception:
                    pass
                return 'error'
            # Do not claim absence if the invitation list is paginated/incomplete.
            if isinstance(data, dict) and (data.get('has_more') or data.get('next') or data.get('next_cursor')
                    or int(data.get('total', len(invites)) or 0) > len(invites)):
                return 'error'
            return 'not_found'
        except Exception:
            logger.warning('[CGPT] member/invitation removal could not be verified')
            return 'error'


    def _remove_user(self, user_id, email) -> bool:
        if email == self.owner_email: return False
        try:
            url = f'https://chatgpt.com/backend-api/accounts/{self.account_id}/users/{user_id}'
            r = cffi_requests.delete(url, headers=self._headers(), impersonate='chrome110', timeout=15)
            ok = r.status_code in [200, 204]
            if ok:
                # إشعار الأدمن بتفاصيل الطرد
                try:
                    info = self.invites_data.get('invites', {}).get(email, {})
                    tg_uid = info.get('telegram_uid', '?')
                    reason = info.get('_remove_reason', 'انتهاء المدة')
                    kmsg = (
                        f"🗑 <b>تم طرد مستخدم من ChatGPT</b>\n\n"
                        f"📧 <b>الإيميل:</b> <code>{email}</code>\n"
                        f"👤 <b>اليوزر (Telegram):</b> <code>{tg_uid}</code>\n"
                        f"🏢 <b>الحساب:</b> <code>{self.owner_email}</code>\n"
                        f"📋 <b>السبب:</b> {reason}"
                    )
                    for admin in db.users.find({'is_admin': 1}):
                        try: bot.send_message(admin['user_id'], kmsg, parse_mode="HTML")
                        except Exception: pass
                except Exception:
                    pass
            return ok
        except Exception as e:
            logger.error(f"[CGPT] remove error: {e}")
            return False

    @_cgpt_manager_guard
    def check_and_cleanup(self):
        """Remove expired access and unexpected members without punishing other customers."""
        current_users = self._get_org_users()
        if getattr(self, '_last_fetch_failed', False):
            logger.debug('[CGPT] member read unavailable; cleanup deferred')
            return
        owner = str(self.owner_email or '').strip().lower()
        members = {str(u.get('email') or '').strip().lower(): u for u in current_users}
        invites = self.invites_data.setdefault('invites', {})
        expired = []
        for email, info in invites.items():
            if info.get('status') != 'active' or str(email).strip().lower() == owner:
                continue
            try:
                exp = _dt_mod.datetime.fromisoformat(info['expires_at'])
                if _dt_mod.datetime.now(exp.tzinfo) > exp:
                    expired.append(email)
            except (ValueError, TypeError, KeyError):
                logger.warning('[CGPT] invalid expiry; manual review needed')

        allowed = {str(e).strip().lower() for e in self.allowed_emails}
        allowed.update(str(e).strip().lower() for e, info in invites.items() if info.get('status') == 'active')
        unauthorized = [u for e, u in members.items() if e and e != owner and e not in allowed
                        and e not in {str(x).strip().lower() for x in expired}]
        unexpected = sorted(str(u.get('email') or '') for u in unauthorized)
        prior = self.invites_data.get('unauthorized_notice') or {}
        if unexpected and (prior.get('emails') != unexpected or int(time.time()) - prior.get('at', 0) >= 3600):
            notify_admins('⚠️ <b>ChatGPT — أعضاء مضافون خارج البوت</b>\n' +
                '\n'.join(f'📧 <code>{html.escape(e)}</code>' for e in unexpected) +
                '\nسيُزال هؤلاء الأعضاء فقط. اشتراكات العملاء المسجلة محفوظة.')
            self.invites_data['unauthorized_notice'] = {'emails': unexpected, 'at': int(time.time())}
        for user in unauthorized:
            if not self._remove_user(user.get('id') or user.get('user_id'), user.get('email')):
                logger.warning('[CGPT] could not remove an unexpected member; will retry')

        for email in expired:
            info = invites[email]
            member = members.get(str(email).strip().lower())
            if member:
                result = 'member' if self._remove_user(member.get('id') or member.get('user_id'), email) else 'error'
            else:
                result = self.remove_by_email(email)   # also checks and revokes pending invitations
            if result not in ('member', 'pending', 'not_found'):
                if int(time.time()) - int(info.get('_expiry_retry_notice', 0)) >= 3600:
                    notify_admins(f'⚠️ تعذّر إلغاء اشتراك ChatGPT المنتهي؛ سيُعاد الفحص.\n📧 <code>{html.escape(email)}</code>')
                    info['_expiry_retry_notice'] = int(time.time())
                continue
            info.update(status='expired', removed_at=_dt_mod.datetime.now().isoformat(), removal_result=result)
            self.allowed_emails = {e for e in self.allowed_emails if str(e).strip().lower() != str(email).strip().lower()}
            notify_admins(f'⌛ <b>انتهت مدة ChatGPT وأُلغي الوصول</b>\n📧 <code>{html.escape(email)}</code>\nالحالة: {result}')
            tg_uid = info.get('telegram_uid')
            if tg_uid and str(tg_uid).isdigit():
                try:
                    bot.send_message(int(tg_uid), get_text(int(tg_uid), 'cg_expired_removed', html.escape(email)), parse_mode='HTML')
                except Exception:
                    pass
        self._save_data()


    def list_active(self):
        """يرجع قائمة المدعوين النشطين"""
        now = _dt_mod.datetime.now()
        result = []
        for email, info in self.invites_data['invites'].items():
            if info.get('status') != 'active': continue
            try:
                exp = _dt_mod.datetime.fromisoformat(info['expires_at'])
                remaining = exp - now
                result.append({
                    'email': email,
                    'expires_at': info['expires_at'],
                    'remaining_hours': max(0, int(remaining.total_seconds() // 3600)),
                    'remaining_days':  max(0, remaining.days)
                })
            except: pass
        return result

    def purge_old_records(self, days_old=7):
        """يحذف سجلات العملاء المنتهية/المخالفة القديمة (أقdم من X يوم)."""
        now = _dt_mod.datetime.now()
        invites = self.invites_data.get('invites', {})
        to_delete = []
        for email, info in invites.items():
            status = info.get('status', '')
            if status in ('expired', 'violated', 'migrated', 'removed'):
                # نفحص متى أُزيل/انتهى
                ref_time = info.get('removed_at') or info.get('expires_at')
                if ref_time:
                    try:
                        rt = _dt_mod.datetime.fromisoformat(ref_time)
                        if (now - rt).days >= days_old:
                            to_delete.append(email)
                    except Exception:
                        to_delete.append(email)  # تاريخ تالف → نحذف
                else:
                    to_delete.append(email)  # بلا تاريخ → قديم
        for email in to_delete:
            invites.pop(email, None)
        self._save_data()
        return len(to_delete)

    def diagnose(self):
        """يفحص الاتصالل الفعلي ويرجّع: الاتصالل، الإيميل، المقاعد المستخدمة/المتاحة."""
        report = {}
        report['loaded'] = self._loaded
        report['owner_email'] = self.owner_email or 'غير معروف'
        report['org_id'] = self.org_id or 'غير معروف'
        report['account_id'] = self.account_id or 'غير معروف'
        if not self._loaded:
            report['connected'] = False
            report['error'] = 'لا توجد cookies محمّلة'
            return report
        # نستعلم عن المستخدمين الفعليين (يؤكد الاتصالل)
        try:
            url = f'https://chatgpt.com/backend-api/accounts/{self.account_id}/users'
            r = cffi_requests.get(url, headers=self._headers(),
                                  impersonate='chrome110', timeout=15)
            report['http_status'] = r.status_code
            if r.status_code == 200:
                data = r.json()
                users = data.get('items') if isinstance(data, dict) else None
                if not isinstance(users, list) or any(not isinstance(u, dict) for u in users):
                    raise ValueError('Invalid ChatGPT member-list response')
                if (data.get('has_more') or data.get('next') or data.get('next_cursor') or
                        int(data.get('total', len(users)) or 0) > len(users)):
                    raise ValueError('Incomplete ChatGPT member-list response')
                report['connected'] = True
                # المالك لا يُحسب كمقعd مُستهلَك (مقعده ليس للبيع)
                non_owner = [u for u in users
                             if str(u.get('email', '')).lower() != str(self.owner_email or '').lower()]
                report['used_seats'] = len(non_owner)
                capacity_key = _cgpt_stock_key(self.account_id, self.access_token, self.session_token)
                with _CGPT_STOCK_LOCK:
                    cached_capacity = _CGPT_CAPACITY_CACHE.get(capacity_key)
                if (getattr(self, '_capacity_cache_allowed', False) and cached_capacity and
                        cached_capacity['expires'] > time.time()):
                    total_seats = cached_capacity['total']
                    report['total_seats'] = total_seats
                    if total_seats:
                        report['available_seats'] = max(0, int(total_seats) - len(users))
                else:
                    # نحاول جلب سعة المقاعد الكلية (بحث عميق في كل الأماكن)
                    try:
                        acc_url = f'https://chatgpt.com/backend-api/accounts/{self.account_id}'
                        ar = cffi_requests.get(acc_url, headers=self._headers(),
                                               impersonate='chrome110', timeout=15)
                        if ar.status_code == 200:
                            acc = ar.json()
                            report['_raw_account'] = str(acc)[:500]  # للتشخيص
    
                            # بحث عميق عن أي مفتاح يحوي "seat" في كل البنية
                            def _find_seats(obj, depth=0):
                                if depth > 5 or not isinstance(obj, dict):
                                    return None
                                # المفاتيح المحتملة لعدد المقاعد
                                for k in ('max_member_count', 'max_seats', 'seats',
                                          'seat_count', 'total_seats', 'member_limit',
                                          'max_members', 'paid_seats', 'licenses',
                                          'subscription_seats', 'num_seats'):
                                    v = obj.get(k)
                                    if isinstance(v, int) and v > 0:
                                        return v
                                # نغوص في المستويات
                                for nested in ('account', 'plan', 'subscription',
                                               'billing', 'workspace', 'limits'):
                                    if isinstance(obj.get(nested), dict):
                                        found = _find_seats(obj[nested], depth + 1)
                                        if found:
                                            return found
                                return None
    
                            total_seats = _find_seats(acc)
                            # نجرّب أيضاً من endpoint الفواتير/الاشتراك
                            if not total_seats:
                                try:
                                    sub_url = f'https://chatgpt.com/backend-api/accounts/{self.account_id}/subscription'
                                    sr = cffi_requests.get(sub_url, headers=self._headers(),
                                                           impersonate='chrome110', timeout=12)
                                    if sr.status_code == 200:
                                        total_seats = _find_seats(sr.json())
                                except Exception:
                                    pass
                            # نجرّب endpoint check (فيه معلومات الاشتراك الكاملة)
                            if not total_seats:
                                try:
                                    chk_url = 'https://chatgpt.com/backend-api/accounts/check/v4-2023-04-27'
                                    cr = cffi_requests.get(chk_url, headers=self._headers(),
                                                           impersonate='chrome110', timeout=12)
                                    if cr.status_code == 200:
                                        chk = cr.json()
                                        report['_raw_check'] = str(chk)[:800]
                                        total_seats = _find_seats(chk)
                                        # نبحث في accounts داخل check
                                        if not total_seats and isinstance(chk.get('accounts'), dict):
                                            for _av in chk['accounts'].values():
                                                found = _find_seats(_av) if isinstance(_av, dict) else None
                                                if found:
                                                    total_seats = found
                                                    break
                                except Exception:
                                    pass
                            report['total_seats'] = total_seats
                            if total_seats:
                                report['available_seats'] = max(0, int(total_seats) - len(users))
                    except Exception as _se:
                        report['_seat_err'] = str(_se)[:100]
                    with _CGPT_STOCK_LOCK:
                        if len(_CGPT_CAPACITY_CACHE) >= 128:
                            _CGPT_CAPACITY_CACHE.pop(next(iter(_CGPT_CAPACITY_CACHE)), None)
                        total_seats = report.get('total_seats')
                        _CGPT_CAPACITY_CACHE[capacity_key] = {'total': total_seats,
                            'expires': time.time() + (21600 if total_seats else 3600)}
                # قائمة الإيميلات
                report['user_emails'] = [u.get('email', '') for u in users][:20]
            elif r.status_code == 401:
                report['connected'] = False
                report['error'] = 'الكوكيز منتهية (401) — أعد إضافتها'
            else:
                report['connected'] = False
                report['error'] = f'HTTP {r.status_code}: {r.text[:150]}'
        except Exception as e:
            report['connected'] = False
            report['error'] = str(e)[:200]
        return report

    def get_stats(self):
        invites = self.invites_data.get('invites', {})
        total   = len(invites)
        active  = sum(1 for i in invites.values() if i.get('status') == 'active')
        expired = total - active
        return {'total': total, 'active': active, 'expired': expired}


# Singleton accessor
_cgpt_manager_instance = None
_cgpt_lock = __import__('threading').Lock()

def _cgpt_build_manager_from_doc(doc):
    """يبني مدير ChatGPT مؤقت من مستند حساب (لحساب معيّن)."""
    mgr = ChatGPTSeatManager.__new__(ChatGPTSeatManager)
    mgr.token_file = ''
    mgr.data_file = ''
    c = doc.get('data', {})
    mgr.access_token = c.get('accessToken')
    mgr.session_token = c.get('sessionToken')
    acct = c.get('account', {})
    mgr.org_id = acct.get('organizationId')
    mgr.account_id = acct.get('id')
    user = c.get('user', {})
    mgr.owner_email = user.get('email')
    mgr._loaded = bool(mgr.access_token and mgr.session_token)
    # بيانات الدعوات مشتركة (نفس invites_data) لكن نربطها بالحساب
    mgr._account_key = str(doc.get('_id'))
    try:
        idata = db.cgpt_invites_data.find_one({'_id': mgr._account_key})
        mgr.invites_data = idata.get('data', {'invites': {}, 'allowed_emails': []}) if idata else {'invites': {}, 'allowed_emails': []}
    except Exception:
        mgr.invites_data = {'invites': {}, 'allowed_emails': []}
    if mgr.owner_email and mgr.owner_email not in mgr.invites_data.get('allowed_emails', []):
        mgr.invites_data.setdefault('allowed_emails', []).append(mgr.owner_email)
    mgr.allowed_emails = set(mgr.invites_data.get('allowed_emails', []))
    mgr._saved_data_digest = _cgpt_data_fingerprint(mgr.invites_data)
    return mgr


def _cgpt_all_accounts():
    """يرجّع كل حسابات ChatGPT المخزّنة (متعددة).
    يشمل الحساب القديم (main) للتوافق."""
    accounts = []
    try:
        for doc in db.cgpt_accounts.find():
            accounts.append(doc)
    except Exception:
        pass
    # نضيف الحساب القديم (main) لو موجود ولم يُنقل بعد
    try:
        main = db.cgpt_cookies.find_one({'_id': 'main'})
        if main and main.get('data'):
            # نتفادى التكرار لو نُقل
            if not any(str(a.get('_id')) == 'main' for a in accounts):
                accounts.append({'_id': 'main', 'data': main['data'],
                                 'name': 'الحساب الرئيسي',
                                 'manual_seats': main.get('manual_seats')})
    except Exception:
        pass
    return accounts


def _cgpt_stock_guard(func):
    @functools.wraps(func)
    def guarded(doc, *args, **kwargs):
        with _cgpt_account_lock(str(doc.get('_id'))):
            return func(doc, *args, **kwargs)
    return guarded


@_cgpt_stock_guard
def _cgpt_account_seat_info(doc, fresh=False):
    """يفحص حساباً ويرجّع معلومات مقاعده."""
    key = _cgpt_stock_key(str(doc.get('_id')), doc.get('data', {}).get('accessToken'), doc.get('data', {}).get('sessionToken'), doc.get('manual_seats'))
    with _CGPT_STOCK_LOCK:
        hit = _CGPT_STOCK_CACHE.get(key)
        if not fresh and hit and hit['expires'] > time.time():
            return dict(hit['info'])
    mgr = _cgpt_build_manager_from_doc(doc)
    try:
        mgr._capacity_cache_allowed = True
        rep = mgr.diagnose()
    except Exception:
        rep = {'connected': False, 'error': 'تعذر الاتصال بالحساب أثناء الفحص'}
    finally:
        mgr._capacity_cache_allowed = False
    total = rep.get('total_seats')
    used = rep.get('used_seats', 0)
    avail = rep.get('available_seats')
    # لو الكشف التلقائي فشل، نستخدم القيمة اليدوية المحفوظة (لو موجودة)
    manual_seats = doc.get('manual_seats')
    if not total and manual_seats:
        total = int(manual_seats)
        avail = max(0, total - used) if rep.get('connected') else None
    info = {
        'id': str(doc.get('_id')),
        'name': doc.get('name', doc.get('data', {}).get('user', {}).get('email', 'حساب')),
        'email': doc.get('data', {}).get('user', {}).get('email') or rep.get('owner_email') or '?',
        'connected': rep.get('connected', False),
        'used_seats': used,
        'total_seats': total,
        'available_seats': avail,
        'manual': bool(manual_seats and not rep.get('total_seats')),
        'error': rep.get('error'),
        'mgr': mgr,
    }
    with _CGPT_STOCK_LOCK:
        if len(_CGPT_STOCK_CACHE) >= 128:
            _CGPT_STOCK_CACHE.pop(next(iter(_CGPT_STOCK_CACHE)), None)
        _CGPT_STOCK_CACHE[key] = {'expires': time.time() + (600 if info['connected'] else 120), 'info': dict(info)}
    return info


def _cgpt_process_pending_migrations():
    """ينقل العملاء المعلّقين (من حسابات ماتت) لما تتوفّr مقاعd."""
    try:
        pending = list(db.cgpt_pending_migration.find({'status': 'waiting'}))
    except Exception:
        return
    if not pending:
        return
    for pm in pending:
        email = pm.get('email')
        rem_min = pm.get('remaining_minutes', 0)
        if rem_min <= 0:
            db.cgpt_pending_migration.update_one({'_id': pm['_id']},
                {'$set': {'status': 'expired'}})
            continue
        target = _cgpt_find_available_account()
        if not target:
            return  # لا مقاعd بعd — ننتظر
        tgt_mgr = target['mgr']
        tgt_mgr._last_buyer_uid = pm.get('telegram_uid')
        res = tgt_mgr.invite_user(email, rem_min)
        if res.get('ok'):
            db.cgpt_pending_migration.update_one({'_id': pm['_id']},
                {'$set': {'status': 'migrated', 'to': target['email'],
                          'migrated_at': int(time.time())}})
            _cgpt_stock_invalidate()
            # رسالة للعميل
            tg_uid = pm.get('telegram_uid')
            if tg_uid:
                try:
                    days = round(rem_min / 1440, 1)
                    bot.send_message(tg_uid,
                        f"🔄 <b>توفّر مقعd جديd — تم نقل اشتراكك!</b>\n\n"
                        f"📧 <b>الحساب الجديd:</b> <code>{html.escape(str(target['email']))}</code>\n"
                        f"⏳ <b>المتبقّي:</b> {days} يوم\n\n"
                        f"✅ وصلتك دعوة على بريدك — اقبلها لتكمل.",
                        parse_mode="HTML")
                except Exception:
                    pass
            # إشعm الأدمن
            try:
                for admin in db.users.find({'is_admin': 1}):
                    bot.send_message(admin['user_id'],
                        f"✅ نُقل معلّق: {email} → {target['email']}")
            except Exception:
                pass


def _cgpt_migrate_dead_account(dead_doc):
    """عند موت اشتراك حساب: ينقل عملاءه (الذين لهم مدة متبقية) لحساب حيّ.
    يرسل لكل عميل دعوة جديدة + رسالة، ويُشعر الأدمن."""
    dead_mgr = _cgpt_build_manager_from_doc(dead_doc)
    dead_email = dead_mgr.owner_email or dead_doc.get('name', 'حساب')
    now = _dt_mod.datetime.now()
    migrated = []
    failed = []
    # نجمع عملاء الحساب الميت الذين لهم مدة متبقية
    active_customers = []
    for email, info in dead_mgr.invites_data.get('invites', {}).items():
        if info.get('status') != 'active':
            continue
        try:
            exp = _dt_mod.datetime.fromisoformat(info['expires_at'])
            if exp > now:
                remaining_min = int((exp - now).total_seconds() / 60)
                active_customers.append((email, info, remaining_min))
        except Exception:
            pass
    if not active_customers:
        return  # لا عملاء للنقل
    for email, info, remaining_min in active_customers:
        # نجد حساباً حياً فيه مقعد فارغ
        target = _cgpt_find_available_account()
        if not target:
            failed.append(email)
            continue
        tgt_mgr = target['mgr']
        # لا ننقل لنفس الحساب الميت
        if getattr(tgt_mgr, '_account_key', '') == getattr(dead_mgr, '_account_key', ''):
            failed.append(email)
            continue
        tgt_mgr._last_buyer_uid = info.get('telegram_uid')
        res = tgt_mgr.invite_user(email, remaining_min)
        if res.get('ok'):
            migrated.append((email, target['email'], remaining_min))
            # نزيل من الحساب الميت
            dead_mgr.invites_data['invites'][email]['status'] = 'migrated'
            dead_mgr.invites_data['invites'][email]['migrated_to'] = target['email']
            # رسالة للعميل
            tg_uid = info.get('telegram_uid')
            if tg_uid:
                try:
                    days = round(remaining_min / 1440, 1)
                    bot.send_message(tg_uid,
                        f"🔄 <b>تم نقل اشتراكك لحساب جديد</b>\n\n"
                        f"📧 <b>الحساب الجديد:</b> <code>{html.escape(str(target['email']))}</code>\n"
                        f"⏳ <b>المدة المتبقية:</b> {days} يوم\n\n"
                        f"✅ <b>وصلتك دعوة جديدة على إيميلك</b> — اقبلها لتكمل اشتراكك.\n"
                        f"📩 تحقق من بريدك: <code>{html.escape(str(email))}</code>",
                        parse_mode="HTML")
                except Exception:
                    pass
        else:
            # لا مقعd متاح → نسجّله كـ "معلّق للنقل" (يُنقل لاحقاً تلقائياً)
            failed.append(email)
            try:
                db.cgpt_pending_migration.update_one(
                    {'email': email},
                    {'$set': {
                        'email': email,
                        'from_account': getattr(dead_mgr, '_account_key', ''),
                        'from_email': dead_email,
                        'remaining_minutes': remaining_min,
                        'telegram_uid': info.get('telegram_uid'),
                        'product_id': info.get('product_id', ''),
                        'created_at': int(time.time()),
                        'status': 'waiting'
                    }}, upsert=True)
            except Exception:
                pass
    dead_mgr._save_data()
    # إشعار الأدمن
    lines = [f"🔄 <b>نقل تلقائي — حساب مات</b>\n"]
    lines.append(f"💀 الحساب الميت: <code>{html.escape(str(dead_email))}</code>\n")
    if migrated:
        lines.append(f"✅ <b>نُقل ({len(migrated)}):</b>")
        for em, to, rem in migrated[:15]:
            lines.append(f"  • <code>{em}</code> → {to} ({round(rem/1440,1)}ي)")
    if failed:
        lines.append(f"\n⚠️ <b>تعذّر نقلهم ({len(failed)}) — لا مقاعد فارغة:</b>")
        for em in failed[:15]:
            lines.append(f"  • <code>{em}</code>")
        lines.append("\n<i>أضف حساباً جديداً فيه مقاعد فارغة.</i>")
    try:
        for admin in db.users.find({'is_admin': 1}):
            try: bot.send_message(admin['user_id'], "\n".join(lines), parse_mode="HTML")
            except Exception: pass
        bot.send_message(OWNER_ID, "\n".join(lines), parse_mode="HTML")
    except Exception:
        pass


_CGPT_SEATS_CACHE = {'val': None, 'exp': 0}


# Browsing uses a separate snapshot: it never waits for cookie/network checks
# and never marks the purchase-validation cache as freshly checked.
_CGPT_DISPLAY_SEATS = {'value': None, 'expires': 0}
_CGPT_DISPLAY_LOCK = __import__('threading').Lock()


def _cgpt_refresh_display_seats():
    try:
        value = _cgpt_total_available_seats()
        _CGPT_DISPLAY_SEATS.update(value=value, expires=time.time() + 300)
    except Exception:
        # Keep the last known value and avoid spawning repeated failing checks.
        _CGPT_DISPLAY_SEATS['expires'] = time.time() + 15
        logger.warning('Business display stock refresh failed')
    finally:
        _CGPT_DISPLAY_LOCK.release()


def _cgpt_display_seats():
    """Return immediately; at most one background refresh runs at a time."""
    now = time.time()
    if _CGPT_SEATS_CACHE['exp'] > now:
        return _CGPT_SEATS_CACHE['val']
    if _CGPT_DISPLAY_SEATS['expires'] <= now and _CGPT_DISPLAY_LOCK.acquire(blocking=False):
        try:
            __import__('threading').Thread(target=_cgpt_refresh_display_seats,
                daemon=True, name='business-display-stock').start()
        except Exception:
            _CGPT_DISPLAY_SEATS['expires'] = now + 15
            _CGPT_DISPLAY_LOCK.release()
            logger.warning('Could not start Business display stock refresh')
    return _CGPT_DISPLAY_SEATS['value']


def _cgpt_get_seats_cached():
    """يرجّع المقاعd المتاحة مع cache 30 ثانية (تفادي بطء الاستعلام المتكرر)."""
    now = time.time()
    if _CGPT_SEATS_CACHE['exp'] > now:
        return _CGPT_SEATS_CACHE['val']
    val = _cgpt_total_available_seats(fresh=True)
    _CGPT_SEATS_CACHE['val'] = val
    _CGPT_SEATS_CACHE['exp'] = now + 30
    return val


def _cgpt_total_available_seats(fresh=False):
    """يرجّع إجمالي المقاعd المتاحة عبر كل الحسابات (تُستخdم كمخزون).
    دائماً يرجّع رقماً (لا غير محدود) — الحسابات بلا مقاعd مضبوطة تُعتبر 0."""
    total = 0
    for doc in _cgpt_all_accounts():
        try:
            info = _cgpt_account_seat_info(doc, fresh=fresh)
            if not info.get('connected'):
                continue
            avail = info.get('available_seats')
            if avail is not None:
                total += max(0, int(avail))
            # لو السعة غير معروفة (لم تُضبط) → 0 متاح لهذا الحساب (حتى يُضبط)
        except Exception:
            pass
    return total
    return total


def _cgpt_find_available_account():
    """يجد أول حساب فيه مقعد فارغ (للتوزيع التلقائي)."""
    for doc in _cgpt_all_accounts():
        info = _cgpt_account_seat_info(doc, fresh=True)
        if not info['connected']:
            continue
        avail = info.get('available_seats')
        # لو عرفنا السعة والمتاح > 0
        if avail is not None and avail > 0:
            return info
        # لو لم نعرف السعة لكن الحساب متصل، نعتبره متاحاً (احتياط)
        if avail is None and info['connected']:
            return info
    return None


def get_cgpt_manager() -> ChatGPTSeatManager:
    global _cgpt_manager_instance
    with _cgpt_lock:
        if _cgpt_manager_instance is None:
            _cgpt_manager_instance = ChatGPTSeatManager()
        return _cgpt_manager_instance


