def _cgpt_check_account(doc):
    """Do not turn a temporary upstream outage into a cookie-expiry alert."""
    manager = _cgpt_build_manager_from_doc(doc)
    email = manager.owner_email or doc.get('name', 'حساب')
    account = str(doc.get('_id'))
    if not manager._loaded:
        _cgpt_notify_cookie_expired(account, email, 'لا كوكيز')
        return False
    if not _cgpt_member_ready(manager):
        _cgpt_send_expiry_reminders(manager)
        return False
    subscription = manager.check_subscription_status()
    if subscription == 'deactivated':
        logger.warning('[CGPT] subscription deactivated; migrating registered customers')
        _cgpt_migrate_dead_account(doc)
        _cgpt_notify_subscription_dead(account, email)
        return False
    if subscription == 'unauthorized':
        _cgpt_member_defer(manager, 401)
        _cgpt_notify_cookie_expired(account, email, '401 كوكيز')
        return False
    if subscription == 'error':
        _cgpt_member_defer(manager, 'subscription-check')
        _cgpt_send_expiry_reminders(manager)
        return False
    manager.check_and_cleanup()
    if getattr(manager, '_last_fetch_failed', False) and getattr(manager, '_last_fetch_status', None) in (401, 403):
        _cgpt_notify_cookie_expired(account, email, manager._last_fetch_status)
    _cgpt_send_expiry_reminders(manager)
    return not getattr(manager, '_last_fetch_failed', False)


def _cgpt_daemon_loop():
    """Daemon thread يعمل كل 5 دقائق"""
    import time as _t
    logger.info("[CGPT] Daemon started")
    while True:
        try:
            # نجلب الـ interval بأمان — لو 'Not Set' أو أي قيمة غير رقمية نستخدم 300
            raw_interval = get_setting('cgpt_check_interval')
            try:
                interval = int(raw_interval) if str(raw_interval).isdigit() else 300
            except (ValueError, TypeError):
                interval = 300
            _t.sleep(interval)
            _cgpt_retry_api_receipts()
            _cgpt_retry_renewal_receipts()
            # ننظّف كل الحسابات (متعددة)
            _accs = _cgpt_all_accounts()
            if _accs:
                for _doc in _accs:
                    try:
                        _cgpt_check_account(_doc)
                    except Exception as _ce:
                        logger.debug(f"[CGPT] account cleanup err: {_ce}")
                # بعd التنظيف: ننقل المعلّقين لو توفّرت مقاعd
                try:
                    _cgpt_process_pending_migrations()
                except Exception as _pm_e:
                    logger.debug(f"[CGPT] pending migration err: {_pm_e}")
            else:
                mgr = get_cgpt_manager()
                mgr.check_and_cleanup()
        except Exception as e:
            logger.error(f"[CGPT] daemon error: {e}")
            _t.sleep(300)  # لو صار خطأ ننام 5 دقائق بدل ما نعيد فوراً


# ============================================================
# 🔄 نظام مزامنة API — Webhooks + Polling
# ============================================================
# هدف هذا النظام: لما يصير أي تغيير في الستوك/المنتجات
# (بيع، إضافة، حذف، تعديل) — البوتات المتصلة بالـ API
# تستلم إشعار فوري عبر webhook، أو تقدر تسأل عبر /changes.
#
# الأحداث المدعومة:
#   stock.added      — أضيف ستوك جديد (qty_added, remaining_stock)
#   stock.sold       — تم بيع (qty_sold, remaining_stock, via_api)
#   stock.removed    — حُذف ستوك يدوياً (qty_removed, remaining_stock)
#   stock.updated    — تم تعديل كود في الستوك
#   product.created  — منتج جديد
#   product.updated  — تعديل منتج (price/name/desc/visibility/emoji)
#   product.deleted  — حُذف منتج
#   order.completed  — اكتمل طلب يدوي عبر API
# ============================================================

import hmac as _hmac
import hashlib as _hashlib
from queue import Queue as _Queue, Empty as _QEmpty

# قائمة انتظار الأحداث (in-memory) — الـ worker يسحب منها
_event_queue = _Queue(maxsize=10000)

# TTL للأحداث المخزنة في DB (لـ polling) — 24 ساعة
_EVENT_TTL_SECONDS = 24 * 60 * 60

# يُنشَأ index على api_events.created_at مرة واحدة (TTL)
def _ensure_event_indexes():
    try:
        db.api_events.create_index('created_at', expireAfterSeconds=_EVENT_TTL_SECONDS)
        db.api_events.create_index([('created_at', -1)])
        db.api_webhooks.create_index('api_user_id', unique=True)
    except Exception as _ie:
        logger.debug(f"event index create skipped: {_ie}")

try: _ensure_event_indexes()
except Exception: pass


def _build_product_snapshot(pr):
    """ينشئ snapshot صغير من المنتج للأحداث"""
    if not pr: return {}
    pid = str(pr.get('id', str(pr.get('_id', ''))))
    manual = pr.get('is_manual', False)
    return {
        'product_id': pid,
        'name_ar': pr.get('name_ar', ''),
        'name_en': pr.get('name_en', ''),
        'price': float(pr.get('price', 0)),
        'is_manual': manual,
        'is_hidden': pr.get('is_hidden', False),
        'stock': 'unlimited' if manual else get_product_stock_count(pid)
    }


def _emit_event(event_type, data, product_id=None):
    """
    🔔 يبث حدث لكل المطورين (يُحفظ في DB + يُرسل لـ webhooks).

    event_type: نوع الحدث (stock.sold / stock.added / product.updated / ...)
    data: dict يحتوي تفاصيل الحدث
    product_id: للفلترة (اختياري)
    """
    try:
        if str(event_type).startswith(('product.', 'stock.')):
            invalidate = globals().get('_invalidate_products_cache')
            if invalidate:
                invalidate()
            invalidate_webapp = globals().get('_wa_invalidate_catalog')
            if invalidate_webapp:
                invalidate_webapp()
        import time as _t
        now = _t.time()
        evt = {
            'event_id': f"evt_{int(now*1000)}_{secrets.token_hex(4)}",
            'event_type': event_type,
            'timestamp': int(now),
            'created_at': datetime.datetime.utcnow(),
            'data': data or {},
        }
        if product_id is not None:
            evt['product_id'] = str(product_id)

        # 1) خزّن في DB للـ polling
        try:
            db.api_events.insert_one(dict(evt))
        except Exception as _de:
            logger.debug(f"event insert err: {_de}")

        # 2) ادفع في queue الـ webhooks
        try:
            # نظّف ObjectId و datetime قبل ما نضعها في queue (للـ JSON)
            evt_for_q = {
                'event_id': evt['event_id'],
                'event_type': evt['event_type'],
                'timestamp': evt['timestamp'],
                'data': evt['data'],
                'product_id': evt.get('product_id')
            }
            _event_queue.put_nowait(evt_for_q)
        except Exception:
            pass  # queue ممتلئة — الـ polling لسه شغال
    except Exception as _ee:
        logger.debug(f"_emit_event error: {_ee}")


def _sign_webhook_body(secret, body_bytes, timestamp):
    """HMAC-SHA256(secret, f'{timestamp}.{body}')"""
    msg = f"{timestamp}.".encode('utf-8') + body_bytes
    return _hmac.new(secret.encode('utf-8'), msg, _hashlib.sha256).hexdigest()


def _url_is_public(url):
    """http(s) URL whose host resolves only to public internet addresses."""
    try:
        import ipaddress, socket as _sock
        u = urllib.parse.urlparse(str(url or ''))
        if u.scheme not in ('http', 'https') or not u.hostname or u.username or u.password:
            return False
        host = u.hostname.strip().lower()
        if host in ('localhost',) or host.endswith('.local') or host.endswith('.internal'):
            return False
        infos = _sock.getaddrinfo(host, u.port or (443 if u.scheme == 'https' else 80), proto=_sock.IPPROTO_TCP)
        if not infos:
            return False
        for info in infos:
            ip = ipaddress.ip_address(info[4][0])
            if not ip.is_global or ip.is_multicast:
                return False
        return True
    except Exception:
        return False


def _deliver_webhook(webhook_doc, evt):
    """
    يرسل event لـ webhook URL واحد — مع retry بسيط.
    webhook_doc: {api_user_id, url, secret, event_filter (optional), failures}
    """
    url = webhook_doc.get('url')
    secret = webhook_doc.get('secret', '')
    if not url:
        return False

    # فلترة: لو المطور حدد أنواع معينة فقط
    ev_filter = webhook_doc.get('event_filter') or []
    if ev_filter and evt['event_type'] not in ev_filter:
        return True  # ما هو خطأ — مفلتر

    import time as _t
    timestamp = str(int(_t.time()))
    body = json.dumps(evt, ensure_ascii=False, separators=(',', ':')).encode('utf-8')
    sig = _sign_webhook_body(secret, body, timestamp) if secret else ''

    headers = {
        'Content-Type': 'application/json; charset=utf-8',
        'User-Agent': 'ShopBot-Webhook/1.0',
        'X-Event-Id': evt['event_id'],
        'X-Event-Type': evt['event_type'],
        'X-Webhook-Timestamp': timestamp,
    }
    if sig:
        headers['X-Webhook-Signature'] = f"sha256={sig}"

    for attempt in range(3):
        try:
            if not _url_is_public(url):
                return False
            r = requests.post(url, data=body, headers=headers, timeout=8, allow_redirects=False)
            if 200 <= r.status_code < 300:
                # نجاح — صفّر العداد
                if webhook_doc.get('failures', 0) > 0:
                    db.api_webhooks.update_one(
                        {'_id': webhook_doc['_id']},
                        {'$set': {'failures': 0, 'last_success': datetime.datetime.utcnow()}}
                    )
                return True
        except Exception as _we:
            logger.debug(f"webhook attempt {attempt+1} fail: {_we}")
        _t.sleep(1 + attempt)  # 1s, 2s, 3s

    # فشل كل المحاولات — زِد عداد الفشل
    try:
        db.api_webhooks.update_one(
            {'_id': webhook_doc['_id']},
            {'$inc': {'failures': 1},
             '$set': {'last_failure': datetime.datetime.utcnow()}}
        )
        # لو فشل 50 مرة متتالية — نعطّل الـ webhook تلقائياً
        fresh = db.api_webhooks.find_one({'_id': webhook_doc['_id']})
        if fresh and fresh.get('failures', 0) >= 50:
            db.api_webhooks.update_one(
                {'_id': webhook_doc['_id']},
                {'$set': {'is_active': False, 'disabled_reason': 'Too many failures'}}
            )
            logger.warning(f"Webhook auto-disabled (50 failures): {url}")
    except Exception:
        pass
    return False


def _webhook_worker():
    """Thread خلفي يسحب من queue ويوزع لكل المطورين المسجلين"""
    logger.info("[Webhook] worker started")
    while True:
        try:
            evt = _event_queue.get(timeout=10)
        except _QEmpty:
            continue
        try:
            # كل webhooks النشطة
            hooks = list(db.api_webhooks.find({'is_active': True}))
            for h in hooks:
                # نشغل كل تسليم في thread صغير عشان webhook بطيء ما يعطّل البقية
                threading.Thread(
                    target=_deliver_webhook,
                    args=(h, evt),
                    daemon=True
                ).start()
        except Exception as _wre:
            logger.debug(f"webhook worker iter err: {_wre}")


threading.Thread(target=_webhook_worker, daemon=True, name="webhook_worker").start()


_PRODUCTS_CACHE = None  # cache لرد /products (يقلّل استعلامات DB المتكررة)


def _api_find_external_product(public_id):
    raw_id = str(public_id)[4:]
    candidates = [raw_id]
    try:
        candidates.insert(0, ObjectId(raw_id))
    except Exception:
        pass
    return db.ext_products.find_one({'_id': {'$in': candidates}})


_ADMIN_NOTICE_WAKE = threading.Event()


def _queue_api_purchase_notice(order_id, text, approval_token=None, buttons=None):
    # Keep financial notices ahead of routine alerts when the durable queue has a backlog.
    message_lower = str(text or '').lower()
    priority = 20 if (str(order_id).startswith('CGPT_') or any(term in message_lower for term in
                         ('إيداع', 'deposit', 'إشعار إدارة (شراء)', 'شراء مقعد', 'purchase',
                          'تم خصم', 'business seat', 'بيع عبر الموزعين'))) else 0
    result = db.api_purchase_notices.update_one({'_id': str(order_id)}, {'$setOnInsert': {
        'text': text, 'status': 'pending', 'created_at': time.time(),
        'priority': priority, 'approval_token': approval_token,
        **({'buttons': buttons} if buttons else {})}}, upsert=True)
    if result.upserted_id is not None:
        _ADMIN_NOTICE_WAKE.set()


def _retry_api_purchase_notices():
    # API purchase receipts go to all registered admins plus the environment owner.
    processed = 0
    for _ in range(100):
        now = time.time()
        token = secrets.token_hex(12)
        job = db.api_purchase_notices.find_one_and_update({'$or': [
            {'status': 'pending', 'retry_at': {'$exists': False}},
            {'status': 'pending', 'retry_at': {'$lte': now}},
            {'status': 'sending', 'lease_until': {'$lt': now}}]},
            {'$set': {'status': 'sending', 'lease_until': now + 120, 'worker_token': token}},
            sort=[('priority', -1), ('created_at', 1)], return_document=True)
        if not job:
            break
        processed += 1
        markup = None
        if job.get('buttons') and not job.get('approval_token'):
            markup = _notice_markup(job['buttons'])
        if job.get('approval_token'):
            approval = db.ext_broadcast_approvals.find_one({'_id': job['approval_token']})
            if (not approval or approval.get('status') not in ('pending', 'notification_failed')
                    or approval.get('kind') not in ('stock', 'new')
                    or approval.get('created_at', 0) < _EXT_APPROVAL_EPOCH):
                db.api_purchase_notices.update_one({'_id': job['_id'], 'worker_token': token},
                    {'$set': {'status': 'cancelled'}})
                continue
            markup = InlineKeyboardMarkup(row_width=1)
            markup.add(InlineKeyboardButton('✅ إرسال البرودكاست', callback_data='extbc_yes_' + job['approval_token']))
            markup.add(InlineKeyboardButton('❌ تجاهل', callback_data='extbc_no_' + job['approval_token']))
        recipients = {int(u['user_id']) for u in db.users.find({'is_admin': 1}, {'user_id': 1})}
        if OWNER_ID:
            recipients.add(int(OWNER_ID))
        sent_to = set(job.get('sent_to', []))
        for recipient in sorted(recipients - sent_to):
            claim = {'_id': job['_id'], 'worker_token': token, 'status': 'sending'}
            renewed = db.api_purchase_notices.update_one(claim,
                {'$set': {'lease_until': time.time() + 120}})
            if not renewed.matched_count:
                break
            if notify_admins(job['text'], recipient_ids={recipient}, reply_markup=markup):
                db.api_purchase_notices.update_one(claim, {'$addToSet': {'sent_to': recipient}})
                sent_to.add(recipient)
        delivered = bool(recipients) and recipients.issubset(sent_to)
        retry_at = min((max(time.time() + 60, _ADMIN_NOTICE_PAUSED.get(uid, 0))
                        for uid in recipients - sent_to), default=time.time() + 60)
        db.api_purchase_notices.update_one({'_id': job['_id'], 'worker_token': token},
            {'$set': {'status': 'sent' if delivered else 'pending',
                      'retry_at': retry_at}})
    return processed


def _admin_notification_worker():
    """Deliver durable admin notices promptly and drain bursts without minute-long polling gaps."""
    while True:
        _ADMIN_NOTICE_WAKE.wait(timeout=30)
        _ADMIN_NOTICE_WAKE.clear()
        try:
            # Continue in bounded chunks while work is immediately available.
            while _retry_api_purchase_notices() >= 100:
                pass
        except Exception:
            logger.exception('Admin notification queue worker failed')
            time.sleep(2)


def _api_external_supplier_order(store, product_id, qty, reference):
    """One purchase attempt only. Never probe alternative URLs with a paid POST."""
    payload = {'product_id': _ext_int_or_str(product_id), 'quantity': qty}
    if _ext_is_insight(store):
        ok, result = _insight_request(store, 'POST', '/orders', payload, reference)
        if not ok and isinstance(result, dict) and int(result.get('http_status', 0) or 0) >= 500:
            result['uncertain'] = True
        return ok, result
    headers = _ext_api_headers(store)
    headers['Idempotency-Key'] = reference
    try:
        response = requests.post(_ext_api_base(store) + '/orders', headers=headers,
            json=payload, timeout=25, allow_redirects=False)
        try:
            result = response.json()
        except Exception:
            return False, {'uncertain': True}
        if response.status_code in (200, 201) and isinstance(result, dict):
            if result.get('success') is not False and not result.get('error'):
                return True, result
        # Only explicit client rejections are safe to refund automatically.
        rejection = {'uncertain': response.status_code not in (400, 401, 403, 404, 409, 422, 429),
                     'http_status': response.status_code}
        if isinstance(result, dict):
            # Used only for classification, never forwarded to the reseller or logs.
            rejection['code'] = result.get('code', '')
            rejection['error'] = result.get('error', '')
        return False, rejection
    except Exception:
        return False, {'uncertain': True}


def _api_external_replay(order):
    if order.get('response') is not None:
        return int(order.get('response_code', 200)), order['response']
    return 202, {'success': True, 'order_id': order['order_id'],
        'product_id': order['product_id'], 'status': order.get('status', 'processing'),
        'codes': [], 'message': 'Order is being verified. Do not submit a new purchase; check /order/' + order['order_id']}


def _api_external_live_stock(store, ep, qty):
    """Check the supplier, not a stale local count, before any reseller debit."""
    data = _ext_api_get(store, '/products')
    if not _ext_valid_catalog(data):
        logger.warning('Reseller external stock check unavailable: product=%s', ep['_id'])
        return None, (503, {'success': False, 'code': 'supplier_stock_check_failed',
            'error': 'Unable to verify supplier stock. No balance was deducted.',
            'source': 'supplier_catalog', 'charged': False})
    remote = next((row for row in _ext_parse_products(data)
        if _ext_extract_fields(row)['ext_id'] == str(ep.get('ext_id', ''))), None)
    fields = _ext_extract_fields(remote) if remote is not None else {
        'stock': 0, 'available': False, 'unlimited': False}
    current = dict(ep, stock=fields['stock'], unlimited=fields.get('unlimited', False))
    # A valid snapshot can refresh the displayed stock. Invalid replies never zero it.
    db.ext_products.update_one({'_id': ep['_id']}, {'$set': {
        'stock': current['stock'], 'unlimited': current['unlimited'],
        'stock_checked_at': int(time.time())}})
    global _PRODUCTS_CACHE
    _PRODUCTS_CACHE = None
    _invalidate_products_cache()
    if not fields['available'] or (not current['unlimited'] and current['stock'] < qty):
        logger.info('Reseller external stock insufficient: product=%s quantity=%s available=%s',
                    ep['_id'], qty, current['stock'])
        return None, (409, {'success': False, 'code': 'supplier_out_of_stock',
            'error': 'Not enough stock at supplier', 'available': current['stock'],
            'source': 'supplier_catalog', 'charged': False})
    return current, None


def _api_external_rejection(response):
    """Classify rejection without exposing supplier credentials or raw messages."""
    error = response.get('error', '')
    if isinstance(error, dict):
        code = error.get('code', '')
    else:
        code = response.get('code') or error
    code = str(code).strip().lower().replace(' ', '_').replace('-', '_')
    if code in ('out_of_stock', 'insufficient_stock', 'not_enough_stock',
                'stock_unavailable', 'product_out_of_stock', 'insufficient_quantity'):
        return 409, 'supplier_out_of_stock', 'Supplier stock changed before the order was placed; balance refunded'
    status = int(response.get('http_status', 0) or 0)
    if status in (401, 403):
        return 502, 'supplier_auth_failed', 'Supplier authentication failed; balance refunded'
    if status == 429:
        return 503, 'supplier_rate_limited', 'Supplier is busy; balance refunded'
    return 502, 'supplier_rejected', 'Supplier rejected the order; balance refunded'


def _api_purchase_external(uid, product_id, qty, buyer_info='', idempotency_key=None):
    """Resolve the public ext_ ID and journal the debit before contacting its supplier."""
    import hashlib
    import math
    supplied_key = idempotency_key is not None
    if supplied_key and (not isinstance(idempotency_key, str) or not 1 <= len(idempotency_key.strip()) <= 128):
        return 400, {'error': 'Idempotency-Key must be a nonempty string of at most 128 characters'}
    request_key = idempotency_key.strip() if supplied_key else secrets.token_hex(24)
    reference = 'APIEXT_' + hashlib.sha256(f'{uid}:{request_key}'.encode()).hexdigest()[:40]
    signature = {'product_id': product_id, 'qty': qty, 'buyer_info': buyer_info}
    existing = db.api_orders.find_one({'_id': reference, 'api_user_id': uid})
    if existing:
        if existing.get('request_signature') != signature:
            return 409, {'error': 'Idempotency-Key already used for a different purchase'}
        return _api_external_replay(existing)
    logger.info('Reseller external purchase received: uid=%s product=%s qty=%s revision=ext-purchase-v3',
                uid, product_id, qty)
    ep = _api_find_external_product(product_id)
    if not ep or ep.get('hidden') or db.api_hidden.find_one({'api_user_id': uid, 'product_id': product_id}):
        return 404, {'error': 'Product not found', 'code': 'external_product_not_found',
                     'source': 'local_catalog', 'product_id': product_id}
    try:
        store = db.ext_stores.find_one({'_id': ObjectId(ep.get('store_id', ''))})
    except Exception:
        store = None
    if not store:
        return 503, {'error': 'Supplier unavailable', 'charged': False}
    ep, stock_error = _api_external_live_stock(store, ep, qty)
    if stock_error:
        return stock_error
    # Catalog discovery may have populated api_prefix on this store document.
    store = db.ext_stores.find_one({'_id': store['_id']}) or store
    unit = float(ep.get('sell_price', ep.get('base_price', 0)) or 0)
    total = round(unit * qty, 2)
    if not math.isfinite(total) or unit < 0:
        return 503, {'error': 'Product price is invalid', 'charged': False}
    order = {'_id': reference, 'order_id': reference, 'api_user_id': uid,
        **signature, 'request_signature': signature, 'product_name': str(ep.get('name', '')),
        'total_price': total, 'unit_price': unit, 'codes': [], 'status': 'processing',
        'created_at': int(time.time()), 'date': datetime.datetime.now(datetime.timezone.utc).isoformat(),
        'store_id': str(store['_id']), 'ext_product_id': str(ep['_id']),
        'supplier_reference': reference, 'idempotency_supplied': supplied_key}
    try:
        db.api_orders.insert_one(order)
    except Exception as exc:
        if type(exc).__name__ != 'DuplicateKeyError':
            raise
        existing = db.api_orders.find_one({'_id': reference, 'api_user_id': uid})
        if not existing or existing.get('request_signature') != signature:
            return 409, {'error': 'Conflicting purchase reference'}
        return _api_external_replay(existing)
    debit_field = '_api_ext_debits.' + reference
    # Debit and its marker are a single atomic change to the user's document.
    # An interrupted order remains pending; replay never charges it a second time.
    updated = db.users.find_one_and_update({'user_id': uid, 'balance': {'$gte': total - MONEY_EPS},
            debit_field: {'$exists': False}},
        {'$inc': {'balance': -total}, '$set': {debit_field: total}}, return_document=True)
    _invalidate_user_cache(uid)
    if not updated:
        result = {'success': False, 'error': 'Insufficient balance', 'order_id': reference,
                  'required': total, 'charged': False, 'status': 'failed'}
        db.api_orders.update_one({'_id': reference}, {'$set': {'status': 'failed',
            'response_code': 402, 'response': result}})
        return 402, result
    db.api_orders.update_one({'_id': reference}, {'$set': {'debited': True}})
    try:
        ok, response = _api_external_supplier_order(store, ep.get('ext_id'), qty, reference)
    except Exception:
        ok, response = False, {'uncertain': True}
    uncertain = not isinstance(response, dict) or bool(response.get('uncertain'))
    codes = _ext_extract_codes(response) if ok and isinstance(response, dict) else []
    remote = response.get('order') if isinstance(response, dict) else None
    if not isinstance(remote, dict):
        remote = response if isinstance(response, dict) else {}
    remote_status = str(remote.get('status', '')).lower()
    remote_id = str(remote.get('order_id') or remote.get('id') or '')
    # A success HTTP response without delivery is not a completed customer order.
    complete = ok and not uncertain and len(codes) >= qty and remote_status not in (
        'failed', 'cancelled', 'canceled', 'pending', 'processing') and not remote.get('test') and not any(
            str(code).startswith('TEST-') for code in codes)
    if not ok and not uncertain:
        refunded = db.users.find_one_and_update({'user_id': uid, debit_field: total},
            {'$inc': {'balance': total}, '$unset': {debit_field: ''}}, return_document=True)
        _invalidate_user_cache(uid)
        if refunded is None:
            uncertain = True
        else:
            failure_http, failure_code, failure_message = _api_external_rejection(response)
            logger.warning('Reseller external purchase rejected: order=%s reason=%s supplier_http=%s',
                           reference, failure_code, response.get('http_status', 0))
            result = {'success': False, 'error': failure_message, 'code': failure_code,
                'source': 'supplier_order',
                'order_id': reference, 'product_id': product_id, 'status': 'failed',
                'refunded': True, 'new_balance': round(float(refunded.get('balance', 0)), 2)}
            db.api_orders.update_one({'_id': reference}, {'$set': {'status': 'failed',
                'response_code': failure_http, 'response': result, 'refunded': True}})
            return failure_http, result
    status = 'completed' if complete else 'pending_verification'
    result = {'success': True, 'order_id': reference, 'product_id': product_id,
        'qty': qty, 'unit_price': unit, 'total_price': total,
        'new_balance': round(float(updated.get('balance', 0)), 2), 'status': status,
        'codes': codes if complete else [], 'codes_count': len(codes) if complete else 0}
    if not complete:
        result['message'] = 'Awaiting supplier verification. Do not repurchase; check /order/' + reference
    # Save delivery before side effects or notifications; replay returns this receipt.
    db.api_orders.update_one({'_id': reference}, {'$set': {'status': status,
        'codes': result['codes'], 'supplier_codes': codes, 'ext_order_id': remote_id,
        'response_code': 200 if complete else 202, 'response': result}})
    try:
        db.ext_orders.update_one({'api_order_id': reference}, {'$setOnInsert': {
            'api_order_id': reference, 'store_id': str(store['_id']),
            'ext_product_id': str(ep['_id']), 'user_id': uid, 'product_name': order['product_name'],
            'price': total, 'quantity': qty, 'created_at': int(time.time()),
            'idempotency_key': reference, 'ext_order_id': remote_id,
            'status': 'success' if complete else status, 'codes': result['codes']}}, upsert=True)
        if complete:
            db.users.update_one({'user_id': uid}, {'$unset': {debit_field: ''}})
            if not ep.get('unlimited'):
                db.ext_products.update_one({'_id': ep['_id'], 'stock': {'$gte': qty}},
                    {'$inc': {'stock': -qty}})
            global _PRODUCTS_CACHE
            _PRODUCTS_CACHE = None
            _invalidate_products_cache()
    except Exception:
        logger.warning('External reseller receipt saved; auxiliary update failed: %s', reference)
    try:
        _queue_api_purchase_notice(reference, f"{'✅ بيع عبر الموزّعين' if complete else '⚠️ طلب موزّع يحتاج التحقق'}\n"
            f"User: {uid}\nProduct: {html.escape(order['product_name'])} ×{qty}\n"
            f"Total: ${total:.2f}\nOrder: {reference}\nSupplier order: {html.escape(remote_id)}")
    except Exception:
        logger.warning('External reseller admin notice failed: %s', reference)
    return (200 if complete else 202), result


class APIHandler(BaseHTTPRequestHandler):
    def log_message(self, *a): pass

    def do_OPTIONS(self):
        self.send_response(200)
        self.send_header('Access-Control-Allow-Origin', '*')
        self.send_header('Access-Control-Allow-Headers', 'Authorization, Content-Type, X-API-Key, X-Shop-API-Key, Idempotency-Key, X-Telegram-Init-Data')
        self.send_header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS')
        self.end_headers()

    def _auth(self):
        auth = self.headers.get('Authorization', '').strip()
        key = ''
        if auth:
            parts = auth.split(None, 1)
            if len(parts) != 2 or parts[0].lower() != 'bearer':
                return None, None
            key = parts[1].strip()
        for name in ('X-API-Key', 'X-Shop-API-Key'):
            alternative = self.headers.get(name, '').strip()
            if alternative:
                if key and key != alternative:
                    return None, None
                key = alternative
        if not key:
            return None, None
        doc, user = _get_api_user(key)
        context = globals().get('_ERROR_CONTEXT')
        current = getattr(context, 'value', None)
        if doc and user and current is not None:
            gateway = '/' + _get_api_gateway()
            route = urllib.parse.urlparse(self.path).path
            route = route[len(gateway):] if route.startswith(gateway + '/') else '/'
            current.update(user_id=doc['user_id'], username=user.get('username', ''),
                           source='api', operation=route[:160])
        return doc, user

    @_api_http_guard
    def do_GET(self):
        # 🛍 Mini App: الواجهة + إيموجي/صور المنتجات
        if _wa_maybe_handle_get(self):
            return
        p = urllib.parse.urlparse(self.path).path.rstrip('/')
        params = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
        if p in ('', '/'):
            return _json_resp(self, 200, {'status': 'online'})
        if p == '/__lara/ping':
            n = str((params.get('n') or [''])[0])[:64]
            return _json_resp(self, 200, {'ok': True, 'app': 'lara', 'sig': _baseurl_sig(n)})

        gw = _get_api_gateway()

        # فحص المسار السري — لو ما يطابق، 404 عادي
        if p != f'/{gw}' and not p.startswith(f'/{gw}/'):
            return _json_resp(self, 404, {'error': 'Not found'})

        # نشيل المسار السري من الرابط ونحلل الباقي
        route = p[len(f'/{gw}'):]  # مثلاً /products أو /product/123

        doc, user = self._auth()
        if not doc or not user:
            return _json_resp(self, 401, {'error': 'Invalid API key'})
        uid = doc['user_id']

        if not _check_rate_limit(doc['api_key']):
            return _json_resp(self, 429, {'error': 'Rate limit exceeded. Max 30 requests/minute.'})

        if route in ('', '/health'):
            return _json_resp(self, 200, {'success': True, 'status': 'connected',
                'user_id': uid, 'endpoints': ['/products', '/balance', '/orders', '/purchase']})

        if route == '/products':
            return _net_api_products_response(self, uid)

        if route.startswith('/product/'):
            pid = route.split('/product/')[1]
            # 🤖 منتج ChatGPT؟ (cgpt_{id}_{dur_id})
            if pid.startswith('cgpt_'):
                try:
                    _rest = pid[5:]
                    _cgid, _, _durid = _rest.partition('_')
                    cg = db.cgpt_products.find_one({'_id': ObjectId(_cgid)})
                except Exception:
                    cg = None
                if not _cgpt_product_visible(cg, uid, pid):
                    return _json_resp(self, 404, {'error': 'Product not found'})
                dur = next((d for d in cg.get('durations', []) if d.get('dur_id') == _durid), None)
                if not dur:
                    return _json_resp(self, 404, {'error': 'Duration not found'})
                cg_emoji = cg.get('custom_emoji_id')
                full_name = f"{cg.get('name','ChatGPT')} — {dur.get('label','')}"
                try:
                    cg_seats = _cgpt_total_available_seats()
                except Exception:
                    cg_seats = None
                return _json_resp(self, 200, {'success': True, 'product': {
                    'id': pid, 'name_ar': full_name, 'name_en': full_name,
                    'desc_ar': cg.get('desc', ''), 'desc_en': cg.get('desc', ''),
                    'store_price': float(dur.get('price', 0)),
                    'stock': cg_seats if cg_seats is not None else 9999,
                    'duration_minutes': int(dur.get('minutes', 0)),
                    'duration_days': round(int(dur.get('minutes', 0)) / 1440, 1),
                    'custom_emoji_id': cg_emoji,
                    'has_premium_emoji': bool(cg_emoji),
                    'source': 'chatgpt_business',
                }})
            # 🔌 منتج API خارجي؟
            if pid.startswith('ext_'):
                try:
                    ep = db.ext_products.find_one({'_id': ObjectId(pid[4:])})
                except Exception:
                    ep = None
                if not ep or ep.get('hidden'):
                    return _json_resp(self, 404, {'error': 'Product not found'})
                ep_name = str(ep.get('name', ''))
                ep_desc = str(ep.get('desc', '') or ep.get('desc_text', ''))
                ep_emoji_id = ep.get('emoji_id')
                ep_price = float(ep.get('sell_price', ep.get('base_price', 0)))
                return _json_resp(self, 200, {'success': True, 'product': {
                    'id': pid, 'name_ar': ep_name, 'name_en': ep_name,
                    'desc_ar': _ext_description_for_lang(ep, 'ar'), 'desc_en': _ext_description_for_lang(ep, 'en'),
                    'store_price': ep_price, 'stock': ep.get('stock', 0),
                    'is_manual': False,
                    'custom_emoji_id': ep_emoji_id,
                    'has_premium_emoji': bool(ep_emoji_id),
                    'name_ar_html': f'<tg-emoji emoji-id="{ep_emoji_id}">{ep.get("emoji_char","✨")}</tg-emoji> {ep_name}' if ep_emoji_id else ep_name,
                    'name_en_html': f'<tg-emoji emoji-id="{ep_emoji_id}">{ep.get("emoji_char","✨")}</tg-emoji> {ep_name}' if ep_emoji_id else ep_name,
                    'desc_ar_html': _ext_safe_product_html(_ext_description_for_lang(ep, 'ar')), 'desc_en_html': _ext_safe_product_html(_ext_description_for_lang(ep, 'en')),
                    'source': 'external_api',
                }})
            pr = find_product(pid)
            if not pr or pr.get('is_hidden'):
                return _json_resp(self, 404, {'error': 'Product not found'})
            pid = str(pr.get('id', str(pr.get('_id', ''))))
            manual = pr.get('is_manual', False)
            base_price = float(pr.get('price', 0))
            cp = db.api_pricing.find_one({'api_user_id': uid, 'product_id': pid}) or {}
            # 🌟 دعم Premium Emoji
            custom_emoji_id = pr.get('custom_emoji_id')
            p_name_ar = cp.get('name_ar') or pr.get('name_ar', '')
            p_name_en = cp.get('name_en') or pr.get('name_en', '')
            p_desc_ar = cp.get('desc_ar') or pr.get('desc_ar', '')
            p_desc_en = cp.get('desc_en') or pr.get('desc_en', '')
            your_price_s = cp.get('sell_price') if cp else None
            product_obj = {
                'id': pid,
                'name_ar': p_name_ar,
                'name_en': p_name_en,
                'desc_ar': p_desc_ar,
                'desc_en': p_desc_en,
                'store_price': base_price,
                'your_price': your_price_s,
                'price_locked': your_price_s is not None,
                'stock': 'unlimited' if manual else get_product_stock_count(pid),
                'is_manual': manual, 'discount_tiers': pr.get('discount_tiers', []),
                # 🌟 حقول الإيموجي المميز (Premium Emoji) — الاسم
                'custom_emoji_id': custom_emoji_id,
                'has_premium_emoji': bool(custom_emoji_id),
                'name_ar_html': f'<tg-emoji emoji-id="{custom_emoji_id}">✨</tg-emoji> {p_name_ar}' if custom_emoji_id else p_name_ar,
                'name_en_html': f'<tg-emoji emoji-id="{custom_emoji_id}">✨</tg-emoji> {p_name_en}' if custom_emoji_id else p_name_en
            }
            # 🌟 إيموجي الوصف (desc_ar/desc_en تحتوي وسوم <tg-emoji> جاهزة للعرض بـ HTML)
            emoji_fields_s = _build_emoji_fields(pr, custom_emoji_id, p_desc_ar, p_desc_en)
            product_obj.update(emoji_fields_s)
            product_obj['emoji_guide'] = {
                'parse_mode': 'HTML',
                'name_ar_html': product_obj.get('name_ar_html', p_name_ar),
                'name_en_html': product_obj.get('name_en_html', p_name_en),
                'desc_ar_html': product_obj.get('desc_ar_html', p_desc_ar),
                'desc_en_html': product_obj.get('desc_en_html', p_desc_en),
                'note': 'All _html fields are ready to send directly via Telegram with parse_mode=HTML'
            }
            return _json_resp(self, 200, {'success': True, 'product': product_obj})

        if route == '/balance':
            u = get_user_data_full(uid)
            return _json_resp(self, 200, {'success': True, 'balance': round(u.get('balance', 0), 2), 'user_id': uid})

        if route == '/orders':
            try:
                limit = max(1, min(int(params.get('limit', ['20'])[0]), 100))
            except (ValueError, TypeError):
                return _json_resp(self, 400, {'error': 'limit must be an integer'})
            orders = list(db.api_orders.find({'api_user_id': uid}).sort('_id', -1).limit(limit))
            result = []
            for o in orders:
                try:
                    order_date = o['_id'].generation_time.strftime('%Y-%m-%d %H:%M:%S')
                except Exception:
                    order_date = o.get('date', '')
                result.append({
                    'order_id': o.get('order_id', ''),
                    'product_id': o.get('product_id', ''),
                    'product_name': o.get('product_name', ''),
                    'qty': o.get('qty', 1),
                    'unit_price': round(o.get('total_price', 0) / max(o.get('qty', 1), 1), 2),
                    'total_price': o.get('total_price', 0),
                    'codes': o.get('codes', []),
                    'codes_count': len(o.get('codes', [])),
                    'status': o.get('status', 'completed'),
                    'buyer_info': o.get('buyer_info', ''),
                    'date': order_date
                })
            return _json_resp(self, 200, {'success': True, 'orders': result})

        # GET /my_prices — أسعار المطوّر المخصصة
        if route == '/my_prices':
            customs = list(db.api_pricing.find({'api_user_id': uid}))
            result = []
            for cp in customs:
                pr = find_product(cp['product_id'])
                if not pr: continue
                base = float(pr.get('price', 0))
                sell = cp.get('sell_price', base)
                snap = cp.get('base_price_snapshot', base)
                item = {
                    'product_id': cp['product_id'],
                    'original_name': pr.get('name_ar', ''),
                    'your_name_ar': cp.get('name_ar', ''),
                    'your_name_en': cp.get('name_en', ''),
                    'store_price_now': base,           # سعر المتجر الحالي
                    'store_price_when_set': snap,      # سعر المتجر وقت ما ضبطت سعرك
                    'your_price': sell,                # سعرك المقفول
                    'profit_per_unit': round(sell - base, 2),  # الربح بناءً على سعر المتجر الحالي
                    'price_locked': True,
                    'price_set_at': cp.get('updated_at', '')
                }
                result.append(item)
            return _json_resp(self, 200, {'success': True, 'custom_products': result})

        # GET /order/{id} — جلب تفاصيل طلب واحد
        if route.startswith('/order/'):
            order_id = route.split('/order/')[1]
            o = db.api_orders.find_one({'order_id': order_id, 'api_user_id': uid})
            if not o:
                return _json_resp(self, 404, {'error': 'Order not found'})
            try:
                order_date = o['_id'].generation_time.strftime('%Y-%m-%d %H:%M:%S')
            except Exception:
                order_date = o.get('date', '')
            return _json_resp(self, 200, {
                'success': True,
                'order': {
                    'order_id': o.get('order_id', ''),
                    'product_id': o.get('product_id', ''),
                    'product_name': o.get('product_name', ''),
                    'qty': o.get('qty', 1),
                    'unit_price': round(o.get('total_price', 0) / max(o.get('qty', 1), 1), 2),
                    'total_price': o.get('total_price', 0),
                    'codes': o.get('codes', []),
                    'codes_count': len(o.get('codes', [])),
                    'status': o.get('status', 'completed'),
                    'buyer_info': o.get('buyer_info', ''),
                    'date': order_date
                }
            })

        # GET /webhook — عرض إعدادات الـ webhook الحالية للمطور
        if route == '/webhook':
            w = db.api_webhooks.find_one({'api_user_id': uid})
            if not w:
                return _json_resp(self, 200, {
                    'success': True,
                    'webhook': None,
                    'note': 'No webhook configured. Use POST /set_webhook to register one.'
                })
            return _json_resp(self, 200, {
                'success': True,
                'webhook': {
                    'url': w.get('url', ''),
                    'is_active': w.get('is_active', True),
                    'has_secret': bool(w.get('secret')),
                    'event_filter': w.get('event_filter', []),
                    'failures': w.get('failures', 0),
                    'last_success': str(w.get('last_success', '')),
                    'last_failure': str(w.get('last_failure', '')),
                    'disabled_reason': w.get('disabled_reason')
                },
                'supported_events': [
                    'stock.added', 'stock.sold', 'stock.removed', 'stock.updated',
                    'product.created', 'product.updated', 'product.deleted',
                    'order.completed'
                ]
            })

        # GET /changes?since=TIMESTAMP — polling fallback لو ما تستخدم webhook
        # يرجع كل الأحداث منذ timestamp معين (آخر 24 ساعة فقط)
        if route == '/changes':
            try:
                since = int(params.get('since', ['0'])[0])
            except: since = 0
            try:
                limit = min(int(params.get('limit', ['100'])[0]), 500)
            except: limit = 100

            # فلترة اختيارية بنوع
            ev_type = params.get('event_type', [None])[0]

            query = {'timestamp': {'$gt': since}}
            if ev_type:
                query['event_type'] = ev_type

            try:
                events = list(db.api_events.find(query).sort('timestamp', 1).limit(limit))
            except Exception as _ce:
                logger.debug(f"/changes query err: {_ce}")
                events = []

            result = []
            latest_ts = since
            for e in events:
                ts = e.get('timestamp', 0)
                if ts > latest_ts: latest_ts = ts
                result.append({
                    'event_id': e.get('event_id', ''),
                    'event_type': e.get('event_type', ''),
                    'timestamp': ts,
                    'data': e.get('data', {}),
                    'product_id': e.get('product_id')
                })

            import time as _tcs
            return _json_resp(self, 200, {
                'success': True,
                'events': result,
                'count': len(result),
                'cursor': latest_ts,                # ابعتها في 'since' المرة الجاية
                'server_time': int(_tcs.time()),
                'note': 'Use the "cursor" value as "since" on your next /changes call. Events older than 24h are deleted automatically.'
            })

        # GET /stats — إحصائيات المطور
        if route == '/stats':
            total_orders = db.api_orders.count_documents({'api_user_id': uid})
            completed = db.api_orders.count_documents({'api_user_id': uid, 'status': 'completed'})
            pending = db.api_orders.count_documents({'api_user_id': uid, 'status': 'pending_manual'})
            revenue = sum(o.get('total_price', 0) for o in db.api_orders.find({'api_user_id': uid, 'status': 'completed'}, {'total_price': 1}))
            u_data = get_user_data_full(uid)
            return _json_resp(self, 200, {
                'success': True,
                'balance': round(u_data.get('balance', 0), 2),
                'total_orders': total_orders,
                'completed_orders': completed,
                'pending_orders': pending,
                'total_revenue': round(revenue, 2)
            })

        return _json_resp(self, 404, {'error': 'Not found'})

    @_api_http_guard
    def do_POST(self):
        # 🛍 Mini App API (/webapp/...)
        if _wa_maybe_handle_post(self):
            return
        p = urllib.parse.urlparse(self.path).path.rstrip('/')
        if p == '/webapp/session':
            try:
                if int(self.headers.get('Content-Length', '0')) > 10000:
                    return _json_resp(self, 413, {'message': 'Request too large'})
                identity = _webapp_telegram_user(_api_json_body(self).get('initData'))
                if not identity:
                    return _json_resp(self, 401, {'message': 'Open this page from the Telegram bot'})
                snapshot = _webapp_store_snapshot(identity)
                return _json_resp(self, 200, snapshot) if snapshot else _json_resp(
                    self, 403, {'message': 'Account unavailable'})
            except (ValueError, TypeError, json.JSONDecodeError):
                return _json_resp(self, 400, {'message': 'Invalid request'})
        if p == '/webapp/translate':
            try:
                if int(self.headers.get('Content-Length', '0')) > 22000:
                    return _json_resp(self, 413, {'message': 'Request too large'})
                body = _api_json_body(self)
                identity = _webapp_telegram_user(body.get('initData'))
                if not identity or not db.users.find_one({'user_id': identity['id'], 'is_banned': {'$ne': 1}}):
                    return _json_resp(self, 401, {'message': 'Open this page from the Telegram bot'})
                return _json_resp(self, 200, {'items': _webapp_translate(
                    identity, body.get('lang'), body.get('items'))})
            except (ValueError, TypeError, json.JSONDecodeError):
                return _json_resp(self, 400, {'message': 'Invalid translation request'})
        gw = _get_api_gateway()

        if p != f'/{gw}' and not p.startswith(f'/{gw}/'):
            return _json_resp(self, 404, {'error': 'Not found'})

        route = p[len(f'/{gw}'):]
        doc, user = self._auth()
        if not doc or not user:
            return _json_resp(self, 401, {'error': 'Invalid API key'})
        uid = doc['user_id']

        if not _check_rate_limit(doc['api_key']):
            return _json_resp(self, 429, {'error': 'Rate limit exceeded. Max 30 requests/minute.'})

        if route == '/purchase':
            _LOG_SRC.v = 'api'
            try:
                body = _api_json_body(self)
            except: return _json_resp(self, 400, {'error': 'Invalid JSON'})

            product_id = str(body.get('product_id', '')).strip()
            qty = body.get('qty', 1)
            buyer_info = str(body.get('buyer_info', ''))[:200]
            buyer_email = str(body.get('email', '')).strip()  # إيميل المشتري (لمنتج ChatGPT)

            if not product_id: return _json_resp(self, 400, {'error': 'product_id required'})

            try:
                if isinstance(qty, bool) or not str(qty).isdigit() or not 1 <= int(qty) <= 50:
                    raise ValueError()
                qty = int(qty)
            except (ValueError, TypeError):
                return _json_resp(self, 400, {'error': 'qty must be an integer from 1 to 50'})
            if product_id.startswith('ext_'):
                code, result = _api_purchase_external(uid, product_id, qty, buyer_info,
                    self.headers.get('Idempotency-Key') or body.get('idempotency_key'))
                return _json_resp(self, code, result)

            if product_id.startswith('cgpt_') and qty != 1:
                return _json_resp(self, 400, {'error': 'ChatGPT purchases require qty=1 and one buyer email'})

            _idem = self.headers.get('Idempotency-Key') or body.get('idempotency_key')
            if _idem is not None:
                _ref, _early = _api_idem_begin(uid, _idem, {'product_id': product_id, 'qty': qty,
                                                            'buyer_info': buyer_info, 'email': buyer_email})
                if _early:
                    return _json_resp(self, *_early)
                self._idem_hook = lambda code, data, ref=_ref: _api_idem_finish(ref, code, data)

            # 🤖 منتج ChatGPT Business؟ (يحتاج معاملة خاصة + إيميل)
            if product_id.startswith('cgpt_'):
                # نستخرج معرّف المنتج والمدة
                _rest = product_id[5:]
                _cgid, _, _durid = _rest.partition('_')
                try:
                    cg = db.cgpt_products.find_one({'_id': ObjectId(_cgid)})
                except Exception:
                    cg = None
                if not _cgpt_product_visible(cg, uid, product_id):
                    return _json_resp(self, 404, {'error': 'Product not found'})
                dur = next((d for d in cg.get('durations', []) if d.get('dur_id') == _durid), None)
                if not dur:
                    return _json_resp(self, 404, {'error': 'Duration not found'})
                # لازم إيميل
                if not buyer_email or '@' not in buyer_email:
                    return _json_resp(self, 400, {
                        'error': 'email required for ChatGPT products',
                        'message': 'This is a ChatGPT Business seat. Send the buyer email in the "email" field so we can invite them.',
                        'example': {'product_id': product_id, 'email': 'buyer@example.com'}
                    })
                cg_price = float(dur.get('price', 0))
                cg_minutes = int(dur.get('minutes', 0))
                # نفحص المقاعd المتاحة
                try:
                    _seats = _cgpt_get_seats_cached()
                except Exception:
                    _seats = None
                if _seats is not None and _seats <= 0:
                    return _json_resp(self, 409, {'error': 'No seats available'})
                # نخصم من رصيد المطوّر
                api_user = db.users.find_one({'user_id': uid})
                api_bal = float(api_user.get('balance', 0)) if api_user else 0
                if api_bal < cg_price:
                    return _json_resp(self, 402, {'error': 'Insufficient balance',
                                                  'required': cg_price, 'balance': api_bal})
                updated = db.users.find_one_and_update(
                    {'user_id': uid, 'balance': {'$gte': cg_price - MONEY_EPS}},
                    {'$inc': {'balance': -cg_price}}, return_document=True)
                if not updated:
                    return _json_resp(self, 402, {'error': 'Insufficient balance'})
                _invalidate_user_cache(uid)
                # نجد حساباً فيه مقعd ونرسل الدعوة
                _acc = _cgpt_find_available_account()
                if not _acc:
                    db.users.update_one({'user_id': uid}, {'$inc': {'balance': cg_price}})
                    _invalidate_user_cache(uid)
                    return _json_resp(self, 409, {'error': 'No seats available (refunded)'})
                _mgr = _acc['mgr']
                _mgr._last_buyer_uid = f"api_{uid}"
                inv = _mgr.invite_user(buyer_email, cg_minutes)
                if inv.get('ok'):
                    _cgpt_stock_invalidate()
                    order_id = "CGAPI" + __import__('uuid').uuid4().hex
                    try:
                        db.api_orders.insert_one({
                            'order_id': order_id, 'api_user_id': uid,
                            'product_id': product_id, 'product_name': f"{cg.get('name','ChatGPT')} — {dur.get('label','')}",
                            'qty': 1, 'total_price': cg_price, 'email': buyer_email,
                            'expires_at': inv.get('expires_at'), 'status': 'completed',
                            'type': 'chatgpt_business'
                        })
                    except Exception:
                        pass
                    try:
                        db.orders.insert_one({'user_id': uid, 'product_id': f"cgpt_{_cgid}", 'code_delivered': f"API: {order_id}",
                                              'qty': 1, 'total_price': cg_price, 'via_api': True, 'api_order_id': order_id,
                                              'order_id': order_id, 'via': 'api', **_order_cost(f"cgpt_{_cgid}", 1)})
                    except Exception:
                        pass
                    try:
                        _cgpt_api_purchase_receipt(uid, buyer_email, cg_minutes, cg_price,
                            float(updated.get('balance', 0)), order_id, inv.get('expires_at', ''))
                    except Exception:
                        logger.exception('Business API receipt failed after successful purchase: %s', order_id)
                    return _json_resp(self, 200, {
                        'success': True, 'order_id': order_id,
                        'type': 'chatgpt_business',
                        'email': buyer_email,
                        'expires_at': inv.get('expires_at'),
                        'duration_minutes': cg_minutes,
                        'message': f'Invitation sent to {buyer_email}. The buyer must accept it from their email to activate the seat.',
                        'total': cg_price,
                        'balance_after': float(updated.get('balance', 0)) - 0,
                    })
                else:
                    db.users.update_one({'user_id': uid}, {'$inc': {'balance': cg_price}})
                    _invalidate_user_cache(uid)
                    return _json_resp(self, 500, {'error': 'Invite failed (refunded)',
                                                  'detail': str(inv.get('error', ''))[:200]})

            try:
                qty = int(qty)
                if qty < 1 or qty > 50: return _json_resp(self, 400, {'error': 'qty: 1-50'})
            except: return _json_resp(self, 400, {'error': 'qty must be integer'})

            pr = find_product(product_id)
            if not pr or pr.get('is_hidden'):
                return _json_resp(self, 404, {'error': 'Product not found'})

            pid = str(pr.get('id', str(pr.get('_id', ''))))
            is_manual = pr.get('is_manual', False)

            if not is_manual and get_product_stock_count(pid) < qty:
                return _json_resp(self, 409, {'error': 'Not enough stock', 'available': get_product_stock_count(pid)})

            # سعر الشراء الفعلي من المتجر (base) — يُستخدم للخصم من رصيد المطور
            cp_doc = db.api_pricing.find_one({'api_user_id': uid, 'product_id': pid}) or {}
            store_price = float(pr.get('price', 0))
            # الكمية → تطبيق خصومات المتجر على store_price
            purchase_unit = store_price
            for t in sorted(pr.get('discount_tiers', []), key=lambda x: x.get('min_qty', 0), reverse=True):
                if qty >= t.get('min_qty', 0):
                    purchase_unit = float(t.get('price', store_price))
                    break
            total = round(purchase_unit * qty, 2)
            # sell_price المقفول للـ response فقط (ما يؤثر على الخصم من رصيده)
            unit = float(cp_doc.get('sell_price', store_price))

            order_id = f"API_{int(time.time())}_{uid}_{secrets.token_hex(3)}"   # فريد حتى لو طلبين بنفس الثانية

            if is_manual:
                # atomic: فحص الرصيد والخصم في عملية واحدة
                updated = db.users.find_one_and_update(
                    {'user_id': uid, 'balance': {'$gte': total - MONEY_EPS}},
                    {'$inc': {'balance': -total}},
                    return_document=True
                )
                if not updated:
                    return _json_resp(self, 402, {'error': 'Insufficient balance', 'required': total})
                db.api_orders.insert_one({'order_id': order_id, 'api_user_id': uid, 'product_id': pid, 'product_name': pr.get('name_en', pr.get('name_ar', '')), 'qty': qty, 'total_price': total, 'codes': [], 'buyer_info': buyer_info, 'status': 'pending_manual'})
                db.orders.insert_one({'user_id': uid, 'product_id': pid, 'code_delivered': f"API: {order_id}", 'qty': qty, 'total_price': total, 'via_api': True, **_order_cost(pid, qty)})
                # 📢 لوق القناة
                try:
                    log_ch = get_setting('log_channel')
                    if log_ch and log_ch != 'Not Set':
                        product_name_clean = clean_name(pr.get('name_en', pr.get('name_ar', '')))
                        custom_emoji_id = pr.get('custom_emoji_id')
                        product_name_log = f'<tg-emoji emoji-id="{custom_emoji_id}">✨</tg-emoji> <b>{product_name_clean}</b>' if custom_emoji_id else f'📦 <b>{product_name_clean}</b>'
                        
                        inner_msg = LANG['en']['log_purchase'].format('API User', product_name_log, qty)
                        custom_inner = db.custom_texts.find_one({'lang': 'en', 'key': 'log_purchase'})
                        if custom_inner and custom_inner.get('value'):
                            try: inner_msg = custom_inner['value'].format('API User', product_name_log, qty)
                            except: pass
                        
                        cms_api_log = db.custom_texts.find_one({'lang': 'en', 'key': 'api_log'})
                        if cms_api_log and cms_api_log.get('value'):
                            try: pub_msg = cms_api_log['value'].format(inner_msg)
                            except: pub_msg = LANG['en']['api_log'].format(inner_msg)
                        else:
                            pub_msg = LANG['en']['api_log'].format(inner_msg)
                        
                        bot.send_message(log_ch, _log_src(pub_msg), parse_mode="HTML")
                except: pass
                # 🔔 إشعار لكل الأدمن
                try: _notify_all_admins_api_purchase(uid, pr, qty, total, order_id, buyer_info, is_manual=True)
                except: pass
                # 🔄 بث حدث API للمزامنة (manual order pending)
                try:
                    _emit_event('order.completed', {
                        'order_id': order_id,
                        'product_id': pid,
                        'qty': qty,
                        'total_price': total,
                        'status': 'pending_manual',
                        'is_manual': True,
                        'via_api': True,
                        'api_user_id': uid
                    }, product_id=pid)
                except: pass
                return _json_resp(self, 200, {
                    'success': True,
                    'order_id': order_id,
                    'status': 'pending_manual',
                    'product_id': pid,
                    'qty': qty,
                    'unit_price': unit,
                    'total_price': total,
                    'new_balance': round(updated.get('balance', 0), 2),
                    'note': 'Manual product — admin will deliver soon'
                })

            # تلقائي — حجز أكواد
            pid_str = str(pid)
            qs = [{'product_id': pid_str}]
            if pid_str.isdigit(): qs.append({'product_id': int(pid_str)})
            try: qs.append({'product_id': float(pid_str)})
            except: pass

            res_id = f"api_{uid}_{secrets.token_hex(16)}"
            reserved = []
            for _ in range(qty):
                r = db.product_stock.find_one_and_update({'$or': qs, 'is_sold': False}, {'$set': {'is_sold': True, 'reservation_id': res_id}}, return_document=True)
                if not r:
                    db.product_stock.update_many({'reservation_id': res_id}, {'$set': {'is_sold': False}, '$unset': {'reservation_id': ''}})
                    return _json_resp(self, 409, {'error': 'Stock ran out during purchase'})
                reserved.append(r)

            debit_field = '_stock_debits.' + order_id
            updated = db.users.find_one_and_update({'user_id': uid, 'balance': {'$gte': total - MONEY_EPS}},
                {'$inc': {'balance': -total}, '$set': {debit_field: total}}, return_document=True)
            if not updated:
                db.product_stock.update_many({'reservation_id': res_id}, {'$set': {'is_sold': False}, '$unset': {'reservation_id': ''}})
                return _json_resp(self, 402, {'error': 'Insufficient balance'})

            codes = []
            try:
                for item in reserved:
                    codes.append(item.get('code_line', ''))
                    db.orders.insert_one({'user_id': uid, 'product_id': pid, 'code_delivered': item.get('code_line', ''),
                        'qty': 1, 'price': purchase_unit, 'via': 'api', 'via_api': True, 'order_id': order_id,
                        'api_order_id': order_id, **_order_cost(pid, 1)})
                db.api_orders.insert_one({'order_id': order_id, 'api_user_id': uid, 'product_id': pid, 'product_name': pr.get('name_en', pr.get('name_ar', '')), 'qty': qty, 'total_price': total, 'codes': codes, 'buyer_info': buyer_info, 'status': 'completed'})
                db.product_stock.update_many({'reservation_id': res_id},
                    {'$set': {'sale_order_id': order_id}, '$unset': {'reservation_id': ''}})
            except Exception:
                refunded = _stock_refund_attempt(uid, order_id, res_id, total, debit_field,
                    [i['_id'] for i in reserved], api=True)
                return _json_resp(self, 503, {'success': False, 'error': 'Order could not be completed',
                    'code': 'purchase_failed', 'refunded': refunded, 'order_id': order_id})
            _stock_forget_debit(uid, debit_field)

            # 📢 لوق القناة — نفس شكل الشراء العادي + CMS
            try:
                log_ch = get_setting('log_channel')
                if log_ch and log_ch != 'Not Set':
                    product_name_clean = clean_name(pr.get('name_en', pr.get('name_ar', '')))
                    custom_emoji_id = pr.get('custom_emoji_id')
                    product_name_log = f'<tg-emoji emoji-id="{custom_emoji_id}">✨</tg-emoji> <b>{product_name_clean}</b>' if custom_emoji_id else f'📦 <b>{product_name_clean}</b>'
                    
                    inner_msg = LANG['en']['log_purchase'].format('API User', product_name_log, qty)
                    custom_inner = db.custom_texts.find_one({'lang': 'en', 'key': 'log_purchase'})
                    if custom_inner and custom_inner.get('value'):
                        try: inner_msg = custom_inner['value'].format('API User', product_name_log, qty)
                        except: pass
                    
                    # غلاف API
                    cms_api_log = db.custom_texts.find_one({'lang': 'en', 'key': 'api_log'})
                    if cms_api_log and cms_api_log.get('value'):
                        try: pub_msg = cms_api_log['value'].format(inner_msg)
                        except: pub_msg = LANG['en']['api_log'].format(inner_msg)
                    else:
                        pub_msg = LANG['en']['api_log'].format(inner_msg)
                    
                    bot.send_message(log_ch, _log_src(pub_msg), parse_mode="HTML")
            except: pass
            
            # 🔔 إشعار لكل الأدمن
            try: _notify_all_admins_api_purchase(uid, pr, qty, total, order_id, buyer_info, is_manual=False)
            except: pass

            # 🔔 تنبيه الستوك بعد البيع عبر API (يصل لكل الأدمن عشان يعيد التعبئة)
            try:
                remaining = get_product_stock_count(pid)
                pname = clean_name(pr.get('name_ar', pr.get('name_en', '')))
                if remaining == 0:
                    notify_admins(
                        f"🚨 <b>تنبيه: ستوك انتهى! (بيع عبر API)</b>\n\n"
                        f"📦 المنتج: <b>{pname}</b>\n"
                        f"📊 المتبقي: <b>0</b>\n\n"
                        f"⚠️ أعد إضافة ستوك لهذا المنتج الآن!"
                    )
                elif remaining <= 2:
                    notify_admins(
                        f"⚠️ <b>تنبيه: ستوك قارب على الانتهاء! (بيع عبر API)</b>\n\n"
                        f"📦 المنتج: <b>{pname}</b>\n"
                        f"📊 المتبقي: <b>{remaining}</b>\n\n"
                        f"⚠️ يُفضّل إضافة ستوك جديد قريباً!"
                    )
            except Exception as _stk_e:
                logger.debug(f"API stock alert error: {_stk_e}")

            # 🔄 بث حدث API للمزامنة (بيع تلقائي عبر API)
            try:
                _emit_event('stock.sold', {
                    'product_id': pid,
                    'qty_sold': qty,
                    'remaining_stock': get_product_stock_count(pid),
                    'is_manual': False,
                    'via_api': True,
                    'api_user_id': uid,
                    'order_id': order_id
                }, product_id=pid)
                _emit_event('order.completed', {
                    'order_id': order_id,
                    'product_id': pid,
                    'qty': qty,
                    'total_price': total,
                    'status': 'completed',
                    'is_manual': False,
                    'via_api': True,
                    'api_user_id': uid,
                    'codes_count': len(codes)
                }, product_id=pid)
            except: pass

            return _json_resp(self, 200, {
                'success': True,
                'order_id': order_id,
                'status': 'completed',
                'product_id': pid,
                'qty': qty,
                'unit_price': unit,
                'total_price': total,
                'codes': codes,
                'codes_count': len(codes),
                'new_balance': round(updated.get('balance', 0), 2)
            })

        # POST /set_price — المطوّر يحدد سعر البيع لعملائه
        if route == '/set_price':
            try:
                body = _api_json_body(self)
            except: return _json_resp(self, 400, {'error': 'Invalid JSON'})

            product_id = str(body.get('product_id', '')).strip()
            sell_price = body.get('price')

            if not product_id: return _json_resp(self, 400, {'error': 'product_id required'})

            pr = find_product(product_id)
            if not pr or pr.get('is_hidden'):
                return _json_resp(self, 404, {'error': 'Product not found'})

            pid = str(pr.get('id', str(pr.get('_id', ''))))
            base_price = float(pr.get('price', 0))

            try:
                sell_price = round(float(sell_price), 2)
                if sell_price < base_price:
                    return _json_resp(self, 400, {'error': f'Price cannot be less than base price (${base_price:.2f})'})
                if sell_price > 9999:
                    return _json_resp(self, 400, {'error': 'Price too high'})
            except (TypeError, ValueError):
                return _json_resp(self, 400, {'error': 'price must be a number'})

            import datetime as _dt2
            db.api_pricing.update_one(
                {'api_user_id': uid, 'product_id': pid},
                {'$set': {
                    'sell_price': sell_price,
                    'base_price_snapshot': base_price,  # snapshot وقت الضبط
                    'updated_at': _dt2.datetime.utcnow().strftime('%Y-%m-%d %H:%M')
                }},
                upsert=True
            )
            profit = round(sell_price - base_price, 2)
            return _json_resp(self, 200, {
                'success': True,
                'product_id': pid,
                'base_price': base_price,
                'your_price': sell_price,
                'profit_per_unit': profit,
                'note': 'Your price is locked. Store price changes will NOT affect it.'
            })

        # POST /set_webhook — تسجيل/تحديث webhook URL للمزامنة الفورية
        # Body: {"url": "https://...", "secret": "اختياري", "event_filter": [...]}
        if route == '/set_webhook':
            try:
                body = _api_json_body(self)
            except: return _json_resp(self, 400, {'error': 'Invalid JSON'})

            url = str(body.get('url', '')).strip()
            if not url:
                return _json_resp(self, 400, {'error': 'url required'})
            if not (url.startswith('http://') or url.startswith('https://')):
                return _json_resp(self, 400, {'error': 'url must start with http:// or https://'})
            if len(url) > 500:
                return _json_resp(self, 400, {'error': 'url too long'})
            if not _url_is_public(url):
                return _json_resp(self, 400, {'error': 'url must be a public internet address'})

            # secret اختياري — لو ما أرسله نولّد واحد له
            secret = str(body.get('secret', '')).strip()
            if not secret:
                secret = secrets.token_hex(24)
            if len(secret) > 200:
                return _json_resp(self, 400, {'error': 'secret too long'})

            # event_filter اختياري — قائمة بأنواع الأحداث المطلوبة فقط
            ev_filter = body.get('event_filter') or []
            if not isinstance(ev_filter, list):
                return _json_resp(self, 400, {'error': 'event_filter must be array'})
            allowed_events = {
                'stock.added', 'stock.sold', 'stock.removed', 'stock.updated',
                'product.created', 'product.updated', 'product.deleted',
                'order.completed'
            }
            ev_filter = [str(x) for x in ev_filter if str(x) in allowed_events]

            db.api_webhooks.update_one(
                {'api_user_id': uid},
                {'$set': {
                    'api_user_id': uid,
                    'url': url,
                    'secret': secret,
                    'event_filter': ev_filter,
                    'is_active': True,
                    'failures': 0,
                    'disabled_reason': None,
                    'updated_at': datetime.datetime.utcnow()
                }},
                upsert=True
            )

            return _json_resp(self, 200, {
                'success': True,
                'url': url,
                'secret': secret,
                'event_filter': ev_filter,
                'note': (
                    'Webhook registered. We will POST events to your URL.\n'
                    'Verify signature: X-Webhook-Signature header = "sha256=" + '
                    'hmac_sha256(secret, f"{X-Webhook-Timestamp}." + raw_body).\n'
                    'Respond with 2xx within 8 seconds. After 50 consecutive failures '
                    'the webhook will be disabled automatically.'
                )
            })

        # POST /delete_webhook — حذف webhook
        if route == '/delete_webhook':
            db.api_webhooks.delete_one({'api_user_id': uid})
            return _json_resp(self, 200, {'success': True, 'message': 'Webhook deleted'})

        # POST /test_webhook — يرسل event تجريبي لـ webhook
        if route == '/test_webhook':
            w = db.api_webhooks.find_one({'api_user_id': uid, 'is_active': True})
            if not w:
                return _json_resp(self, 404, {'error': 'No active webhook configured'})
            import time as _twt
            test_evt = {
                'event_id': f"evt_test_{int(_twt.time()*1000)}",
                'event_type': 'webhook.test',
                'timestamp': int(_twt.time()),
                'data': {'message': 'This is a test event from your shop bot.'},
                'product_id': None
            }
            ok = _deliver_webhook(w, test_evt)
            return _json_resp(self, 200, {
                'success': ok,
                'delivered': ok,
                'url': w.get('url', ''),
                'note': 'If delivered=false, check that your endpoint returns 2xx within 8s.'
            })

        # POST /set_product — المطوّر يعدّل اسم/وصف المنتج لعملائه
        if route == '/set_product':
            try:
                body = _api_json_body(self)
            except: return _json_resp(self, 400, {'error': 'Invalid JSON'})

            product_id = str(body.get('product_id', '')).strip()
            if not product_id: return _json_resp(self, 400, {'error': 'product_id required'})

            pr = find_product(product_id)
            if not pr or pr.get('is_hidden'):
                return _json_resp(self, 404, {'error': 'Product not found'})

            pid = str(pr.get('id', str(pr.get('_id', ''))))
            update = {}
            if 'name_ar' in body: update['name_ar'] = str(body['name_ar'])[:100]
            if 'name_en' in body: update['name_en'] = str(body['name_en'])[:100]
            if 'desc_ar' in body: update['desc_ar'] = str(body['desc_ar'])[:500]
            if 'desc_en' in body: update['desc_en'] = str(body['desc_en'])[:500]
            if 'price' in body:
                try:
                    sp = round(float(body['price']), 2)
                    base_price = float(pr.get('price', 0))
                    if sp < base_price:
                        return _json_resp(self, 400, {'error': f'Price cannot be less than ${base_price:.2f}'})
                    update['sell_price'] = sp
                except: pass

            if not update:
                return _json_resp(self, 400, {'error': 'Nothing to update. Send: name_ar, name_en, desc_ar, desc_en, or price'})

            db.api_pricing.update_one(
                {'api_user_id': uid, 'product_id': pid},
                {'$set': update},
                upsert=True
            )
            return _json_resp(self, 200, {'success': True, 'product_id': pid, 'updated': list(update.keys())})

        return _json_resp(self, 404, {'error': 'Endpoint not found'})



def keep_alive():
    port = int(os.environ.get('PORT', 10000))
    # ThreadingHTTPServer: كل طلب في خيط منفصل — طلب بطيء لا يعلّق الباقي
    try:
        from http.server import ThreadingHTTPServer
        server = ThreadingHTTPServer(('0.0.0.0', port), APIHandler)
    except Exception:
        # إصدار قديم: نبني threading يدوياً
        import socketserver
        class _ThreadedHTTP(socketserver.ThreadingMixIn, HTTPServer):
            daemon_threads = True
        server = _ThreadedHTTP(('0.0.0.0', port), APIHandler)
    server.serve_forever()

threading.Thread(target=keep_alive, daemon=True).start()

try:
    bot = telebot.TeleBot(TOKEN, use_class_middlewares=False,
                          threaded=True, num_threads=8)
except TypeError:
    # إصدار telebot قديم لا يدعم num_threads
    bot = telebot.TeleBot(TOKEN, use_class_middlewares=False)

# 🛡 حماية من خطأ "query is too old" — يصير لما المستخدم يضغط زر قديم
# بعد إعادة تشغيل البوت أو بعد 10 ثواني من ظهور الزر.
# هذا الحل يغطي كل أماكن answer_callback_query في البوت مرة واحدة.
_orig_answer_cbq = bot.answer_callback_query
def _safe_answer_cbq(callback_query_id, text='', show_alert=False, url=None, cache_time=None, **kwargs):
    try:
        return _orig_answer_cbq(
            callback_query_id,
            text=text,
            show_alert=show_alert,
            url=url,
            cache_time=cache_time,
            **kwargs
        )
    except Exception:
        pass  # query منتهي الصلاحية أو invalid — نتجاهل بهدوء
bot.answer_callback_query = _safe_answer_cbq


# ═══════════════════════════════════════════════════════════
# 🔒 حارس عملية الدفع
# يمنع المستخدم من أي زر/أمر أثناء عملية دفع نشطة.
# يعتمد على دالة is_deposit_locked() الموجودة (DB-based).
# الـ guards مسجّلة هنا مبكراً عشان تكون أول handler يطابق.
# ═══════════════════════════════════════════════════════════

# الـ callbacks المسموح بها أثناء القفل
_ALLOWED_LOCKED_CB_PREFIXES = (
    'cancel_deposit',       # زر إلغاء الدفع
    'binance_check_',       # زر فحص الدفع
    'copy_fb',              # fallback نسخ
    'open_support',         # يظل الدعم متاحاً أثناء الدفع
)


def _check_locked(uid):
    """نسخة آمنة من is_deposit_locked قبل ما تتعرّف لاحقاً في الملف"""
    try:
        return is_deposit_locked(uid)
    except NameError:
        # الدالة لسه ما اتعرّفت — نرجع False (يفتح كل شي)
        return False
    except Exception:
        return False


def send_payment_lock_warning(uid, lang=None):
    """تنبيه دفع نشط مع زر الإلغاء"""
    if not lang:
        try: lang = get_lang(uid)
        except: lang = 'ar'
    
    warn = (
        "⚠️ <b>تنبيه: لديك عملية دفع معلقة!</b>\n\n"
        "لا يمكنك القيام بأي إجراء آخر في البوت حتى تقوم بإتمام عملية الدفع الحالية أو إلغائها.\n\n"
        "💡 <b>للإلغاء والعودة لاستخدام البوت:</b>\n"
        "اضغط على الزر أدناه مباشرة 👇"
        if lang == 'ar' else
        "⚠️ <b>Warning: You have a pending payment!</b>\n\n"
        "You cannot perform any other actions in the bot until you complete or cancel the current payment.\n\n"
        "💡 <b>To cancel and return to using the bot:</b>\n"
        "Press the button below 👇"
    )
    
    markup = InlineKeyboardMarkup()
    btn_text = "❌ إلغاء عملية الدفع" if lang == 'ar' else "❌ Cancel Payment"
    markup.add(InlineKeyboardButton(btn_text, callback_data="cancel_deposit"))
    
    try:
        bot.send_message(uid, warn, parse_mode="HTML", reply_markup=markup)
    except Exception:
        pass


# ─── 🛡 الحارس العام لأزرار الأدمن (أول حارس — قبل أي معالج) ───
# أي زر من عائلات أزرار الإدارة يجي من شخص مو أدمن → يترفض ويتسجّل، حتى لو المعالج نفسه نسي يفحص.
# (تيليجرام يسمح لأي أحد يرسل callback_data مزوّرة من برنامج معدّل؛ فالفحص لازم يكون في السيرفر.)
_ADMIN_CB_PREFIXES = ('ad_', 'admin_', 'edit_txt_', 'rst_txt_', 'edit_btn_', 'btnstyle_', 'toggle_amount_protection',
                      'stk_', 'set_v_', 'set_pemj_', 'edit_p_', 'ep_', 'toggle_hide_', 'del_fsub_', 'gift_cancel_',
                      'togglecoin_', 'hide_coins_menu', 'emj_reg_', 'p_set_first_', 'ext_add_store', 'ext_api_main',
                      'refwd_', 'refdv_', 'rfl_', 'rfs_', 'rfd_', 'ref_ms_scan', 'ordinfo_', 'credit_pending_', 'vipadm_', 'pcost_', 'pprofit_', 'baseurl_', 'wasl_')


def _is_admin_cb(data):
    return str(data or '').startswith(_ADMIN_CB_PREFIXES)


@bot.callback_query_handler(func=lambda call: _is_admin_cb(call.data) and not _is_admin_check(call.from_user.id))
def _admin_cb_guard(call):
    _admin_only_middleware(call)        # يرد «ليس لديك صلاحية» ويسجّل المحاولة


# ─── الحارس الأول: callbacks ───
@bot.callback_query_handler(
    func=lambda call: _check_locked(call.from_user.id)
                      and not str(call.data or '').startswith(_ALLOWED_LOCKED_CB_PREFIXES)
)
def _deposit_lock_guard_callback(call):
    """يبلوك أي زر للمستخدم اللي في عملية دفع"""
    try:
        uid = call.from_user.id
        l = 'ar'
        try: l = get_lang(uid)
        except: pass
        warn = (
            "⚠️ أنت في عملية دفع نشطة!\n\nاضغط ❌ إلغاء أولاً قبل أي إجراء آخر."
            if l == 'ar' else
            "⚠️ You have an active payment!\n\nPress ❌ Cancel first."
        )
        bot.answer_callback_query(call.id, warn, show_alert=True)
        send_payment_lock_warning(uid, l)
    except Exception:
        pass


# ─── الحارس الثاني: الرسائل النصية ───
@bot.message_handler(
    func=lambda m: _check_locked(m.from_user.id)
)
def _deposit_lock_guard_message(message):
    """يبلوك أي رسالة للمستخدم اللي في عملية دفع"""
    send_payment_lock_warning(message.from_user.id)


# 🛡 دالة فحص صلاحية الأدمن (تُستخدم بكل دوال الأدمن)
def _is_admin_check(uid):
    """يتحقق إن المستخدم أدمن أو OWNER"""
    if uid == OWNER_ID:
        return True
    try:
        u = db.users.find_one({'user_id': int(uid)})
        return u and u.get('is_admin') == 1
    except Exception:
        return False


# 🛡 Middleware: يفحص كل callback queries اللي تبدأ بـ ad_ أو admin_
# لو المستخدم مو أدمن، يرفض الطلب فوراً قبل ما يصير أي شي
def _admin_only_middleware(call):
    """
    🛡 فحص أمني: يرفض أي محاولة وصول لدوال الأدمن من غير الأدمن.
    """
    if not call.data:
        return True  # ما فيه callback data - نسمح (مو دالة admin)
    
    # الـ callbacks المحمية
    is_admin_callback = (
        call.data.startswith('ad_') or 
        call.data.startswith('admin_') or
        call.data.startswith('edit_txt_') or
        call.data.startswith('toggle_amount_protection')
    )
    
    if not is_admin_callback:
        return True  # مو callback admin - نسمح
    
    # نشيك صلاحية المستخدم
    uid = call.from_user.id
    if _is_admin_check(uid):
        return True  # admin - مسموح
    
    # 🚨 محاولة وصول غير مصرح بها!
    try:
        bot.answer_callback_query(
            call.id, 
            bil(uid, "❌ ليس لديك صلاحية للوصول لهذه القائمة!", "❌ You don't have permission to access this menu!"),
            show_alert=True
        )
    except Exception:
        pass
    
    # نسجل المحاولة
    try:
        db.unauthorized_attempts.insert_one({
            'user_id': uid,
            'username': call.from_user.username or 'unknown',
            'callback_data': call.data[:200],
            'timestamp': int(time.time())
        })
    except Exception:
        pass
    
    logger.warning(f"🚨 محاولة وصول غير مصرح بها: المستخدم {uid} حاول {call.data}")
    return False  # رفض المعالجة


def admin_required(func):
    """
    🛡 Decorator يحمي دوال الأدمن من الوصول غير المصرح به.
    
    استخدامها:
    @admin_required
    def my_admin_function(call):
        ...
    """
    def wrapper(call, *args, **kwargs):
        uid = call.from_user.id
        if not _is_admin_check(uid):
            try:
                bot.answer_callback_query(
                    call.id,
                    bil(uid, "❌ ليس لديك صلاحية!", "❌ You don't have permission!"),
                    show_alert=True
                )
            except Exception:
                pass
            
            # نسجل المحاولة
            try:
                db.unauthorized_attempts.insert_one({
                    'user_id': uid,
                    'username': getattr(call.from_user, 'username', 'unknown') or 'unknown',
                    'callback_data': str(call.data)[:200] if hasattr(call, 'data') else 'message',
                    'timestamp': int(time.time())
                })
            except Exception:
                pass
            
            logger.warning(f"🚨 محاولة وصول غير مصرح بها: المستخدم {uid}")
            return
        return func(call, *args, **kwargs)
    
    wrapper.__name__ = func.__name__
    return wrapper

# 📡 Network accounting contains sizes and counters only; never URLs, headers or payloads.
from pymongo import monitoring as _net_mongo_monitoring
from bson import BSON as _net_BSON


class _NetworkMeter:
    def __init__(self):
        self.lock = threading.RLock()
        self.started = time.monotonic()
        self.rows = {}

    def record(self, group, label, sent=0, received=0, count=1, errors=0):
        try:
            key = (str(group)[:24], str(label)[:90])
            with self.lock:
                if key not in self.rows and len(self.rows) >= 96:
                    key = (str(group)[:24], 'other')
                row = self.rows.setdefault(key, {'requests': 0, 'sent': 0, 'received': 0, 'errors': 0})
                for field, value in [('requests', count), ('sent', sent), ('received', received), ('errors', errors)]:
                    row[field] += max(0, int(value or 0))
        except Exception:
            pass

    def snapshot(self):
        with self.lock:
            return {'seconds': max(0, time.monotonic() - self.started), 'rows': [
                dict(group=key[0], label=key[1], **row) for key, row in self.rows.items()]}


_NET_METER = _NetworkMeter()


class _NetworkMongoListener(_net_mongo_monitoring.CommandListener):
    def started(self, event):
        try:
            _NET_METER.record('mongo', event.command_name, sent=len(_net_BSON.encode(event.command)))
        except Exception:
            pass

    def succeeded(self, event):
        try:
            _NET_METER.record('mongo', event.command_name, received=len(_net_BSON.encode(event.reply)), count=0)
        except Exception:
            pass

    def failed(self, event):
        _NET_METER.record('mongo', event.command_name, count=0, errors=1)


_NET_MONGO_LISTENER = _NetworkMongoListener()


def _net_host(url):
    try:
        host = (urllib.parse.urlsplit(str(url)).hostname or '').lower()
        return host[:90] if re.fullmatch(r'[a-z0-9.-]+', host) else 'other'
    except Exception:
        return 'other'


def _net_client_label(url):
    host = _net_host(url)
    try:
        path = urllib.parse.urlsplit(str(url)).path
        if host == 'api.telegram.org':
            method = path.rsplit('/', 1)[-1]
            known = {'getUpdates', 'getChatMember', 'getChat', 'getMe', 'getFile', 'sendMessage',
                'sendDocument', 'sendPhoto', 'sendVideo', 'sendAnimation', 'editMessageText',
                'editMessageReplyMarkup', 'answerCallbackQuery', 'copyMessage', 'deleteMessage',
                'setChatMenuButton', 'getChatMenuButton', 'getCustomEmojiStickers'}
            return host + '/' + (method if method in known else 'other')
        if host == 'chatgpt.com':
            route = 'members' if path.endswith('/users') else 'subscription' if path.endswith('/subscription') else \
                    'subscription-check' if '/accounts/check/' in path else 'capacity' if re.search(r'/accounts/[^/]+/?$', path) else 'other'
            return host + '/' + route
    except Exception:
        pass
    return host


def _net_accepts_gzip(headers):
    wildcard = False
    for item in str(headers.get('Accept-Encoding', '')).split(','):
        bits = [x.strip().lower() for x in item.split(';')]
        quality = 1.0
        for part in bits[1:]:
            if part.startswith('q='):
                try: quality = float(part[2:])
                except ValueError: quality = 0.0
        if bits[0] == 'gzip':
            return quality > 0
        if bits[0] == '*':
            wildcard = quality > 0
    return wildcard


def _net_payload_size(value):
    if isinstance(value, bytes):
        return len(value)
    if isinstance(value, str):
        return len(value.encode('utf-8'))
    return 0  # Do not consume streams/files to measure them.


def _net_received_size(response):
    try:
        length = str(response.headers.get('Content-Length', ''))
        if length.isdigit():
            return int(length)
        return _net_payload_size(getattr(response, '_content', None))
    except Exception:
        return 0


def _net_request_size(request):
    try:
        body = _net_payload_size(request.body)
        return body + sum(len(str(k).encode()) + len(str(v).encode()) + 4 for k, v in request.headers.items())
    except Exception:
        return 0


def _net_install_clients():
    adapter = requests.adapters.HTTPAdapter
    if not getattr(adapter.send, '_lara_network_meter', False):
        original = adapter.send
        @functools.wraps(original)
        def measured_send(self, request, *args, **kwargs):
            response, error = None, 0
            try:
                response = original(self, request, *args, **kwargs)
                return response
            except Exception:
                error = 1
                raise
            finally:
                try:
                    _NET_METER.record('http_client', _net_client_label(request.url), sent=_net_request_size(request),
                        received=_net_received_size(response) if response is not None else 0,
                        errors=error or int(getattr(response, 'status_code', 0) >= 400))
                except Exception:
                    pass
        measured_send._lara_network_meter = True
        adapter.send = measured_send
    if CFFI_AVAILABLE and not getattr(cffi_requests.Session.request, '_lara_network_meter', False):
        old_curl = cffi_requests.Session.request
        @functools.wraps(old_curl)
        def measured_curl(self, method, url, *args, **kwargs):
            response, error = None, 0
            try:
                response = old_curl(self, method, url, *args, **kwargs)
                return response
            except Exception:
                error = 1
                raise
            finally:
                try:
                    request_size = _net_payload_size(kwargs.get('data'))
                    if kwargs.get('json') is not None:
                        try:
                            request_size += len(json.dumps(kwargs['json']).encode())
                        except Exception:
                            pass
                    headers = kwargs.get('headers') or {}
                    request_size += sum(len(str(k)) + len(str(v)) + 4 for k, v in headers.items())
                    received = _net_received_size(response) if response is not None else 0
                    if not received and response is not None and not kwargs.get('stream'):
                        received = _net_payload_size(getattr(response, 'content', None))
                    _NET_METER.record('curl_client', _net_client_label(url), sent=request_size, received=received,
                        errors=error or int(getattr(response, 'status_code', 0) >= 400))
                except Exception:
                    pass
        measured_curl._lara_network_meter = True
        cffi_requests.Session.request = measured_curl


class _NetworkWriter:
    def __init__(self, wrapped, handler):
        self.wrapped, self.handler = wrapped, handler

    def write(self, data):
        result = self.wrapped.write(data)
        self.handler._net_written += len(data) if result is None else int(result)
        return result

    def __getattr__(self, name):
        return getattr(self.wrapped, name)


def _net_server_route(path):
    try:
        parts = urllib.parse.urlsplit(path).path.strip('/').split('/')
        if not parts[0]:
            return '/'
        if parts[0] == 'app':
            return '/app/' + ('emoji' if len(parts) > 1 and parts[1] == 'emoji' else 'assets')
        if parts[0] == 'webapp':
            return '/webapp/' + (parts[1] if len(parts) > 1 and re.fullmatch('[a-z_-]{1,35}', parts[1]) else 'other')
        if parts[0] == '__lara':
            return '/health'
        allowed = {'products', 'product', 'balance', 'orders', 'order', 'changes', 'purchase', 'health'}
        return '/api/' + (parts[1] if len(parts) > 1 and parts[1] in allowed else 'other')
    except Exception:
        return '/other'


def _net_install_server():
    if getattr(APIHandler, '_network_meter_installed', False):
        return
    setup, send_response = APIHandler.setup, APIHandler.send_response
    def network_setup(self):
        setup(self)
        self._net_written = 0
        self.wfile = _NetworkWriter(self.wfile, self)
    def network_response(self, code, *args, **kwargs):
        self._net_status = code
        return send_response(self, code, *args, **kwargs)
    APIHandler.setup = network_setup
    APIHandler.send_response = network_response
    def wrap(original):
        @functools.wraps(original)
        def measured(self, *args, **kwargs):
            before = getattr(self, '_net_written', 0)
            self._net_status = 0
            self._net_etag = None
            if hasattr(self, '_net_json_payload'):
                del self._net_json_payload
            try:
                return original(self, *args, **kwargs)
            finally:
                _NET_METER.record('http_server', _net_server_route(getattr(self, 'path', '')),
                    sent=max(0, getattr(self, '_net_written', before) - before),
                    errors=int(getattr(self, '_net_status', 0) >= 400))
        return measured
    for method in ('do_GET', 'do_POST', 'do_OPTIONS'):
        if hasattr(APIHandler, method):
            setattr(APIHandler, method, wrap(getattr(APIHandler, method)))
    APIHandler._network_meter_installed = True

