# ═══════════════════════════════════════════════
# 📋 Helper: زر نسخ النص (Bot API 7.10+ CopyTextButton)
# ═══════════════════════════════════════════════
def _parse_btn_label(text):
    """
    ينظف HTML من نص الزر ويستخرج Premium Emoji كأيقونة منفصلة.
    تيليجرام ما يدعم HTML داخل label الزر — لازم نص عادي.

    مهم: لو صار الإيموجي البريميوم أيقونة الزر، نحذف الإيموجي العادي
    اللي جوّاه من النص — وإلا يظهر إيموجيان (بريميوم كأيقونة + عادي بالنص).

    Returns: (clean_text, emoji_id_or_None)
    """
    if not text:
        return text, None
    import re as _re_lbl
    emoji_id = None
    # ابحث عن أول <tg-emoji emoji-id="..."> واحفظ ID
    m = _re_lbl.search(r'<tg-emoji\s+emoji-id="(\d+)"\s*>([^<]*)</tg-emoji>', text)
    if m:
        emoji_id = m.group(1)

    if emoji_id:
        # الإيموجي البريميوم صار أيقونة → احذف الوسم ومحتواه (الإيموجي العادي) كلياً
        text = _re_lbl.sub(r'<tg-emoji[^>]*>[^<]*</tg-emoji>', '', text)
    else:
        # لا يوجد بريميوم → احتفظ بالإيموجي العادي اللي جوّا الوسم
        text = _re_lbl.sub(r'<tg-emoji[^>]*>([^<]*)</tg-emoji>', r'\1', text)

    # شيل أي HTML tags باقية
    text = _re_lbl.sub(r'<[^>]+>', '', text)
    # نظّف المسافات المزدوجة الناتجة عن الحذف
    text = _re_lbl.sub(r'\s{2,}', ' ', text)
    return text.strip(), emoji_id


def _copy_button(label, text_to_copy):
    """
    يصنع زر نسخ بـ CopyTextButton (Bot API 7.10+).
    يستخرج Premium Emoji من label تلقائياً ويحطه كأيقونة الزر.
    """
    clean_label, emoji_id = _parse_btn_label(label)
    try:
        from telebot.types import CopyTextButton
        kwargs = {'copy_text': CopyTextButton(text=str(text_to_copy)[:256])}
        if emoji_id:
            return CustomInlineButton(clean_label, icon_custom_emoji_id=emoji_id, **kwargs)
        return InlineKeyboardButton(clean_label, **kwargs)
    except Exception:
        # Fallback لإصدارات قديمة
        return InlineKeyboardButton(clean_label, callback_data="copy_fb")


def _deposit_copy_button(uid, key, value):
    """Keep payment-copy labels distinct while sharing the configured copy emoji."""
    source = get_text(uid, 'dep_btn_copy_amount')
    source_text, emoji_id = _parse_btn_label(source)
    label, _unused = _parse_btn_label(get_text(uid, key))

    def without_symbol_prefix(text):
        first, space, rest = text.partition(' ')
        return rest.strip() if space and first and not any(ch.isalnum() for ch in first) else text

    label = without_symbol_prefix(label)
    if emoji_id:
        label = f'<tg-emoji emoji-id="{emoji_id}">📋</tg-emoji> {html.escape(label)}'
    else:
        first = source_text.partition(' ')[0]
        symbol = first if first and not any(ch.isalnum() for ch in first) else ''
        label = f'{symbol} {label}'.strip()
    return _copy_button(label, value)


def _make_btn(label, callback_data=None, url=None, style=None):
    """
    drop-in replacement لـ InlineKeyboardButton ينظّف HTML تلقائياً
    ويستخرج Premium Emoji كأيقونة (icon_custom_emoji_id).
    استخدمه بدل InlineKeyboardButton لما الـ label يجي من get_text.
    """
    clean_label, emoji_id = _parse_btn_label(label)
    kwargs = {'text': clean_label}
    if callback_data: kwargs['callback_data'] = callback_data
    if url: kwargs['url'] = url
    if style: kwargs['style'] = style
    if emoji_id: kwargs['icon_custom_emoji_id'] = emoji_id
    return CustomInlineButton(**kwargs)


@bot.callback_query_handler(func=lambda call: call.data == "copy_fb")
def _copy_fb_handler(call):
    """Fallback لو CopyTextButton مش متاح"""
    try:
        bot.answer_callback_query(call.id, "💡 اضغط على النص داخل الرسالة لنسخه", show_alert=True)
    except: pass


