def _light_lookup(x):
    """المنتج من قائمة الذاكرة بأي صيغة لرقمه — بدون استعلام (اللي مو موجود = محذوف)."""
    if _PRODUCTS_BY_ID_CACHE['exp'] <= time.time():
        _get_all_products_cached()
    m = _PRODUCTS_BY_ID_CACHE['map']
    p = m.get(str(x))
    if p is None and isinstance(x, float) and x.is_integer():
        p = m.get(str(int(x)))
    if p is None and not str(x).startswith('cgpt_main_'):
        p = m.get('cgpt_main_' + str(x))
    return p


def _catalog_visible_count(cat):
    """كم منتج ظاهر وموجود في المجلد (المحذوف والمخفي ما ينحسب)."""
    seen = set()
    for x in (cat.get('product_ids') or []):
        p = _light_lookup(x)
        if not p or p.get('is_hidden'):
            continue
        seen.add(str(p.get('_id')))
    return len(seen)


def _catalog_ext_counts(cat_ids):
    out = {}
    try:
        for r in db.ext_products.aggregate([{'$match': {'catalog_id': {'$in': list(cat_ids)}, 'hidden': {'$ne': True}}},
                                            {'$group': {'_id': '$catalog_id', 'n': {'$sum': 1}}}]):
            out[str(r['_id'])] = int(r['n'])
    except Exception:
        pass
    return out


def catalog_view_helper(chat_id, uid, cat_id, lang, message_id_to_edit=None):
    try:
        logger.info(f"[HELPER] catalog_view_helper called: chat_id={chat_id}, uid={uid}, cat_id={cat_id}, lang={lang}, msg_edit={message_id_to_edit}")
        from bson import ObjectId
        try:
            cat = db.catalogs.find_one({'_id': ObjectId(cat_id)})
        except:
            cat = None
        
        if not cat:
            logger.warning(f"[HELPER] Catalog not found for cat_id={cat_id}")
            bot.send_message(chat_id, "❌ Category not found.")
            return False
        
        u = get_user_data_full(uid)
        is_admin = (u.get('is_admin') == 1 or uid == OWNER_ID) if u else False
        
        emoji = cat.get('emoji', '📁')
        emoji_id = cat.get('emoji_id')
        name = cat.get('name_en', cat.get('name_ar', '')) if lang == 'en' else cat.get('name_ar', cat.get('name_en', ''))
        
        markup = InlineKeyboardMarkup(row_width=1)
        prod_ids = cat.get('product_ids') or []

        # ⚡ نجمع المنتجات أولاً، ثم نجلب المخزون دفعة واحدة (batch) للسرعة
        cat_prods = []
        stock_ids = []
        _seen = set()
        for pid in prod_ids:
            p = _light_lookup(pid)
            if not p: continue
            if str(p.get('_id')) in _seen: continue          # نفس المنتج مسجّل مرتين بصيغتين
            _seen.add(str(p.get('_id')))
            if p.get('is_hidden', False) and not is_admin: continue
            actual_pid = p.get('id', str(p.get('_id', '')))
            cat_prods.append((p, actual_pid))
            spid = str(actual_pid)
            stock_ids.append(spid)
            if spid.isdigit():
                stock_ids.append(int(spid))

        # جلب المخزون لكل المنتجات دفعة واحدة
        cat_stock_map = {}
        try:
            if stock_ids:
                for row in db.product_stock.aggregate([
                    {'$match': {'product_id': {'$in': stock_ids}, 'is_sold': False}},
                    {'$group': {'_id': '$product_id', 'c': {'$sum': 1}}}
                ]):
                    cat_stock_map[str(row['_id'])] = row['c']
        except Exception as _cse:
            logger.debug(f"catalog stock batch err: {_cse}")

        items = []
        # نحسب المقاعd المتاحة مرة واحدة (تُستخdم كمخزون لمنتجات ChatGPT)
        _cgpt_seats = None
        _cgpt_computed = False
        for p, actual_pid in cat_prods:
            is_manual = p.get('is_manual', False)
            is_cgpt = p.get('product_type') == 'cgpt_main'
            if is_cgpt:
                if not _cgpt_computed:
                    _cgpt_seats = _cgpt_display_seats()
                    _cgpt_computed = True
                st = _cgpt_seats if _cgpt_seats is not None else 0
                in_stock = st > 0
            else:
                st = cat_stock_map.get(str(actual_pid), 0)
                in_stock = is_manual or st > 0
            items.append((p, actual_pid, st, is_manual, in_stock))

        # الترتيب: منتج ChatGPT أولاً دائماً، ثم المتوفر، ثم غير المتوفر
        items.sort(key=lambda x: (
            not (x[0].get('product_type') == 'cgpt_main' or x[0].get('cgpt_pinned', False)),
            not x[4],
            clean_name(x[0].get('name_en' if lang == 'en' else 'name_ar', '')).lower()
        ))

        for p, actual_pid, st, is_manual, in_stock in items:
            db_style = p.get('btn_style')
            btn_style = db_style if db_style and in_stock else ("success" if in_stock else "danger")
            hidden_icon = " 👻" if p.get('is_hidden', False) else ""
            n = clean_name(p.get('name_en') if lang == 'en' else p.get('name_ar'))
            short_n = n[:25] + ".." if len(n) > 25 else n
            is_cgpt_main = p.get('product_type') == 'cgpt_main'
            # الاسم + العدد (ستوك) — لمنتج ChatGPT نعرض المقاعd المتاحة
            if is_cgpt_main:
                st_text = str(st) if _cgpt_seats is not None else "…"  # عddد المقاعd المتاحة
            else:
                st_text = "FW" if is_manual else str(st)
            btn_text = f"{short_n} | 📦 {st_text}{hidden_icon}"
            callback_pid = str(actual_pid).replace("cgpt_main_", "") if str(actual_pid).startswith("cgpt_main_") else str(actual_pid)
            btn_kwargs = {'text': btn_text, 'callback_data': f"vi_p_{callback_pid}_c_{cat_id}", 'style': btn_style}
            custom_emoji_id = p.get('custom_emoji_id')
            # لمنتج ChatGPT: نجلب الرمز الطازج من cgpt_products (قد يكون تغيّر)
            if is_cgpt_main:
                try:
                    _cgp = db.cgpt_products.find_one({'_id': ObjectId(str(callback_pid))})
                    if _cgp and _cgp.get('custom_emoji_id'):
                        custom_emoji_id = _cgp['custom_emoji_id']
                except Exception:
                    pass
            if custom_emoji_id:
                btn_kwargs['icon_custom_emoji_id'] = custom_emoji_id
            markup.add(CustomInlineButton(**btn_kwargs))

        # 🔌 منتجات API المُسندة لهذا المجلد (الظاهرة فقط) — مع العدد واللون
        try:
            ext_list = list(db.ext_products.find({'catalog_id': cat_id, 'hidden': {'$ne': True}}, _EXT_LIGHT_PROJ))
            # المتوفر أولاً (أبجدياً)، غير المتوفر في الأسفل
            ext_list.sort(key=lambda e: (not (e.get('stock', 0) > 0),
                                         str(e.get('name', '')).lower()))
            for ep in ext_list:
                epid = str(ep['_id'])
                enm = str(ep.get('name', ''))
                short_e = enm[:25] + ".." if len(enm) > 25 else enm
                st = ep.get('stock', 0)
                bt = f"{short_e} | 📦 {st}"
                bstyle = "success" if st > 0 else "danger"
                bkw = {'text': bt, 'callback_data': f"vext_{epid}", 'style': bstyle}
                if ep.get('emoji_id'):
                    bkw['icon_custom_emoji_id'] = ep['emoji_id']
                markup.add(CustomInlineButton(**bkw))
        except Exception as _ee:
            logger.debug(f"ext products in catalog err: {_ee}")

        markup.add(create_btn(uid, 'btn_back', callback_data="open_shop"))
        
        txt = f"{emoji} <b>{name}</b>"
        
        if message_id_to_edit:
            try: bot.edit_message_text(txt, chat_id, message_id_to_edit, reply_markup=markup, parse_mode="HTML")
            except: pass
        else:
            bot.send_message(chat_id, txt, reply_markup=markup, parse_mode="HTML")
        return True
    except Exception as e:
        logger.error(f"Error in catalog_view_helper: {e}", exc_info=True)
        return False

