def _support_contact_links():
    """Build native Telegram and HTTPS alternatives without a network lookup."""
    username = re.sub(r'[\u200b-\u200f\ufeff]', '', str(OWNER_USER or '')).strip()
    if re.match(r'^(?:t\.me|telegram\.me|telegram\.dog)/', username, re.I):
        username = 'https://' + username
    if '://' in username:
        try:
            parsed = urllib.parse.urlsplit(username)
        except ValueError:
            username = ''
        else:
            if parsed.scheme.lower() in ('http', 'https') and parsed.hostname in ('t.me', 'telegram.me', 'telegram.dog'):
                username = urllib.parse.unquote(parsed.path.strip('/'))
            elif parsed.scheme.lower() == 'tg' and parsed.netloc.lower() == 'resolve':
                username = urllib.parse.parse_qs(parsed.query).get('domain', [''])[0]
            else:
                username = ''
    username = username.lstrip('@')
    if re.fullmatch(r'[A-Za-z][A-Za-z0-9_]{0,31}', username):
        return {'username': username,
                'native': 'tg://resolve?domain=' + username,
                'web': 'https://t.me/' + username}
    try:
        owner_id = int(OWNER_ID)
    except (ValueError, TypeError):
        owner_id = 0
    if owner_id > 0:
        return {'username': '', 'native': f'tg://user?id={owner_id}', 'web': None}
    return None


def _send_support_contact(uid, chat_id):
    """Always show a usable contact card, including a copyable username."""
    links = _support_contact_links()
    lang = get_lang(uid)
    if not links:
        text = ('الدعم غير مضبوط حالياً. يرجى المحاولة لاحقاً.' if lang == 'ar' else
                'Support is not configured yet. Please try again later.')
        return bot.send_message(chat_id, text)

    title, _ = get_btn_data(uid, 'btn_support')
    title, _ = _parse_btn_label(title)
    title = title or ('الدعم الفني' if lang == 'ar' else 'Support')
    body = ('اختر طريقة فتح المحادثة أدناه.' if lang == 'ar' else
            'Choose an option below to open the support chat.')
    text = f'<b>{html.escape(title)}</b>\n\n{body}'
    if links['username']:
        handle = html.escape('@' + links['username'])
        text += (f'\n\nمعرّف الدعم: <code>{handle}</code>\n'
                 'إذا لم يفتح الرابط، انسخ المعرّف وابحث عنه داخل Telegram.' if lang == 'ar' else
                 f'\n\nSupport username: <code>{handle}</code>\n'
                 'If a link does not open, copy the username and search for it in Telegram.')

    # Plain URL buttons keep the fallback card independent of newer emoji/style
    # features. Both URL forms are documented at https://core.telegram.org/api/links.
    markup = InlineKeyboardMarkup(row_width=1)
    markup.add(InlineKeyboardButton('فتح المحادثة داخل تيليجرام' if lang == 'ar' else 'Open in Telegram',
                                   url=links['native']))
    if links['web']:
        markup.add(InlineKeyboardButton('رابط بديل' if lang == 'ar' else 'Alternative link',
                                       url=links['web']))
    return bot.send_message(chat_id, text, parse_mode='HTML', reply_markup=markup,
                            disable_web_page_preview=True)


@bot.callback_query_handler(func=lambda call: call.data == 'open_support')
def show_support(call):
    """Support is available even while a payment is pending or an account is banned."""
    try:
        bot.answer_callback_query(call.id)
    except Exception:
        pass
    uid = call.from_user.id
    chat_id = getattr(getattr(getattr(call, 'message', None), 'chat', None), 'id', uid)
    return _send_support_contact(uid, chat_id)



@bot.message_handler(commands=['start'])
@_start_view_guard
def start_handler(message):
    is_callback = isinstance(message, types.CallbackQuery)
    chat_id = message.message.chat.id if is_callback else message.chat.id
    from_user = message.from_user
    uid = from_user.id
    uname = from_user.username.lower() if from_user.username else ""
    
    # 🛡 نمسح أي next_step handlers معلقة (يمنع تفسير /start كـ tx_id)
    try:
        bot.clear_step_handler_by_chat_id(chat_id=chat_id)
    except Exception: pass
    
    if is_user_banned(uid):
        bot.send_message(chat_id, get_text(uid, 'banned'), parse_mode="HTML")
        return

    user = get_user_data_full(uid)
    user_was_new = (user is None)
    if chat_id == uid and (uid == OWNER_ID or (user and user.get('is_admin') == 1)):
        _admin_notice_resume(uid, incoming=True)
    
    if not user:
        full_text = "" if is_callback else (message.text or "")
        args = full_text.split()
        ref_candidate = args[1] if len(args) > 1 and args[1].isdigit() else None
        
        db.users.insert_one({
            'user_id': uid, 'name': from_user.first_name, 'username': uname, 
            'balance': 0.0, 'ref_v2_earned': 0.0,
            'lang_chosen': False, 'lang': 'ar', 'is_admin': 0, 'is_banned': 0
        })
        _invalidate_user_cache(uid)
        user = get_user_data_full(uid, use_cache=False)
        
        # 🎯 تسجيل الإحالة فقط لو المستخدم جديد كلياً
        # المستخدم الموجود مسبقاً لا يُحسب أبداً
        if ref_candidate:
            try:
                referrer_id = int(ref_candidate)
                if referrer_id != uid:
                    register_new_referral(uid, referrer_id)
            except Exception as e:
                logger.error(f"Error registering new referral: {e}")
    else:
        # ⚠️ المستخدم موجود من قبل — لا تُسجَّل أي إحالة جديدة له
        if user.get('username') != uname:
            db.users.update_one({'user_id': uid}, {'$set': {'username': uname}})
            _invalidate_user_cache(uid)
    
    # 🆕 مكافآت رجعية: نتأكد إن المستخدم استلم كل مكافآته (لو فاته شي)
    try:
        _queue_start_reward_check(uid)
    except Exception as ref_err:
        logger.debug(f"Retroactive reward check error: {ref_err}")

    # حماية: لو تعذّر جلب/إنشاء المستخدم لأي سبب، نتفادى الانهيار
    if not user:
        user = {'lang_chosen': False, 'lang': 'ar', 'balance': 0.0,
                'is_admin': 0, 'is_banned': 0}

    if not user.get('lang_chosen'):
        markup = InlineKeyboardMarkup(row_width=2)
        markup.add(
            InlineKeyboardButton("🇸🇦 العربية", callback_data="init_lang_ar"),
            InlineKeyboardButton("🇬🇧 English", callback_data="init_lang_en")
        )
        bot.send_message(chat_id, "🌐 <b>الرجاء اختيار لغتك / Please choose your language:</b>", reply_markup=markup, parse_mode="HTML")
        return

    lang = user.get('lang', 'ar')
    if lang not in ['ar', 'en']: lang = 'ar'
    
    # ============================================================
    # ✅ تحديث حالة الإحالة (لو هذا المستخدم مُدعى من شخص آخر)
    # ============================================================
    ref_record = _ref_find(uid)
    
    subscription_state = check_forced_sub(uid)
    if subscription_state is not True:
        if subscription_state is None:
            markup = InlineKeyboardMarkup()
            markup.add(create_btn(uid, 'btn_check_sub', callback_data="main_menu_refresh"))
            bot.send_message(chat_id,
                '⏳ Unable to verify channel membership right now. Please try again; your referral balance was not changed.'
                if lang == 'en' else
                '⏳ تعذّر التحقق من الاشتراك الآن. أعد المحاولة؛ لم تتغير حالة الإحالة أو رصيدها.',
                reply_markup=markup)
            return
        if ref_record:
            current = ref_record.get('status', 'pending')
            if current == 'active':
                mark_referral_status(uid, 'left')
        
        markup = InlineKeyboardMarkup(row_width=1)
        try:
            _fs = forced_sub_status(uid)
        except Exception:
            _fs = []
        _todo = [c for c in _fs if c.get('joined') is not True] or _fs
        for c in _todo:
            if not c.get('url'):
                continue
            ic = '👥' if c.get('kind') == 'group' else '📢'
            markup.add(InlineKeyboardButton(f"{ic} {c['title'][:40]}", url=c['url']))
        markup.add(create_btn(uid, 'btn_check_sub', callback_data="main_menu_refresh"))
        bot.send_message(chat_id, get_text(uid, 'must_join'), reply_markup=markup, parse_mode="HTML")
        return
    else:
        if ref_record:
            current = ref_record.get('status', 'pending')
            if current in ['pending', 'left']:
                # 🛡 تحقق الجهاز: الإحالة ما تنحسب لين يسوي التحقق من الموقع
                if ref_dv_required(ref_record):
                    if ref_dv_gate(uid, chat_id, ref_record, lang):
                        return
                else:
                    mark_referral_status(uid, 'active')

    # ⚡ estimated_document_count فوري (يستخدم بيانات وصفية) بدل count_documents
    #    الذي يمسح كل الـ 18k مستخدم في كل /start → بطء شديد.
    try:
        users_total = db.users.estimated_document_count()
    except Exception:
        users_total = 0
    markup = InlineKeyboardMarkup(row_width=2)
    # 🛍 زر فتح المتجر (Mini App)
    try:
        _wa_btn = _wa_start_button(uid)
        if _wa_btn:
            markup.add(_wa_btn)
    except Exception as _wa_e:
        logger.debug(f"webapp start button err: {_wa_e}")
    
    markup.add(create_btn(uid, 'btn_products', callback_data="open_shop", style="primary"),
               create_btn(uid, 'btn_deposit', callback_data="open_deposit"))
    markup.add(create_btn(uid, 'btn_invite', callback_data="open_invite"),
               create_btn(uid, 'btn_support', callback_data="open_support"))
    # ⚙️ الإعدادات: يجمع الملف الشخصي واللغة (نص قابل للتعديل من CMS)
    markup.add(create_btn(uid, 'btn_settings', callback_data="open_settings"))

    # 🆕 زر شروط الاستخدام
    markup.add(create_btn(uid, 'btn_terms', callback_data="open_terms"))
    markup.add(create_btn(uid, 'btn_api', callback_data="open_api"))
    
    if user.get('is_admin') == 1 or uid == OWNER_ID:
        markup.add(create_btn(uid, 'btn_admin', callback_data="admin_panel_main"))

    # 🆕 التحقق من روابط المجلدات أو المنتجات العميقة (Deep Linking)
    deeplink_param = None
    if not is_callback:
        full_text = message.text or ""
        args = full_text.split()
        if len(args) > 1:
            # لا نعتبر الأرقام فقط (إحالات) كـ deep link
            candidate = args[1]
            if not candidate.isdigit():
                deeplink_param = candidate

    if deeplink_param:
        logger.info(f"[DEEPLINK] uid={uid} param={deeplink_param}")
        try:
            if deeplink_param.startswith("p_"):
                target_pid = deeplink_param[2:]
                logger.info(f"[DEEPLINK] Product deep link: pid={target_pid}")
                result = shop_detail_ui_helper(chat_id, uid, target_pid, lang)
                logger.info(f"[DEEPLINK] shop_detail_ui_helper returned: {result}")
                if result:
                    return
            elif deeplink_param.startswith("c_"):
                target_cat_id = deeplink_param[2:]
                logger.info(f"[DEEPLINK] Catalog deep link: cat_id={target_cat_id}")
                result = catalog_view_helper(chat_id, uid, target_cat_id, lang)
                logger.info(f"[DEEPLINK] catalog_view_helper returned: {result}")
                if result:
                    return
            elif deeplink_param.startswith("vext_"):
                # فتح منتج API مباشرة عبر الرابط
                epid = deeplink_param[5:]
                logger.info(f"[DEEPLINK] External product: epid={epid}")
                try:
                    ep = db.ext_products.find_one({'_id': ObjectId(epid)})
                    if ep and not ep.get('hidden'):
                        class _FakeCall:
                            def __init__(s):
                                s.id = None
                                s.data = f"vext_{epid}"
                                s.from_user = from_user
                                s.message = type('M', (), {'chat': type('C', (), {'id': chat_id})(),
                                                            'message_id': None})()
                        # نرسل عرض المنتج كرسالة جديدة
                        _ext_send_product_view(chat_id, uid, ep, lang)
                        return
                except Exception as _ve:
                    logger.debug(f"vext deeplink err: {_ve}")
        except Exception as dl_err:
            logger.error(f"[DEEPLINK] Error processing deep link '{deeplink_param}': {dl_err}", exc_info=True)

    welcome_message = get_text(uid, 'welcome', uid, from_user.first_name, users_total, user.get('balance', 0.0))
    try:
        bot.send_message(chat_id, welcome_message, reply_markup=markup, parse_mode="HTML")
    except Exception as e:
        if 'parse entities' in str(e).lower() or 'can\'t parse' in str(e).lower():
            # HTML مكسور في CMS - نرسل بدون parse_mode
            import re as _re
            clean_msg = _re.sub(r'<[^>]+>', '', welcome_message)
            try:
                bot.send_message(chat_id, clean_msg, reply_markup=markup)
            except Exception:
                bot.send_message(chat_id, "مرحباً! 👋", reply_markup=markup)
        else:
            raise


