def _shop_items(uid, is_admin=False):
    """كل المنتجات اللي يقدر يشوفها العميل (عادية + ChatGPT + متاجر API) بالاسم والسعر والمخزون — بدون الوصف."""
    l = get_lang(uid)
    prods = [p for p in _get_all_products_cached() if is_admin or not p.get('is_hidden')]
    ids = []
    for p in prods:
        sp = str(p.get('id', p.get('_id')))
        ids.append(sp)
        if sp.isdigit():
            ids.append(int(sp))
    stock = {}
    try:
        for r in db.product_stock.aggregate([{'$match': {'product_id': {'$in': ids}, 'is_sold': False}},
                                             {'$group': {'_id': '$product_id', 'c': {'$sum': 1}}}]):
            stock[str(r['_id'])] = r['c']
    except Exception:
        pass
    seats = None
    out = []
    for p in prods:
        pid = str(p.get('id', p.get('_id')))
        is_cgpt = p.get('product_type') == 'cgpt_main'
        manual = bool(p.get('is_manual'))
        if is_cgpt:
            if seats is None:
                seats = _cgpt_display_seats() or 0
            st = seats
            cb = f"vi_p_cgpt_main_{pid.replace('cgpt_main_', '')}"
        else:
            st = stock.get(pid, 0)
            cb = f"vi_p_{pid}"
        try:
            price, vipb = vip_unit(uid, pid, p.get('price', 0))
        except Exception:
            price, vipb = float(p.get('price') or 0), False
        out.append({'name_ar': clean_name(p.get('name_ar') or p.get('name_en') or ''), 'name_en': clean_name(p.get('name_en') or p.get('name_ar') or ''),
                    'cb': cb, 'price': float(price or 0), 'vip': bool(vipb), 'stock': st, 'manual': manual and not is_cgpt,
                    'in_stock': bool(manual or st > 0), 'emoji_id': p.get('custom_emoji_id'), 'hidden': bool(p.get('is_hidden')),
                    'style': p.get('btn_style'), 'cgpt': is_cgpt})
    try:
        for ep in db.ext_products.find({} if is_admin else {'hidden': {'$ne': True}}, _EXT_LIGHT_PROJ):
            nm = str(ep.get('name', ''))
            st = int(ep.get('stock', 0) or 0)
            out.append({'name_ar': nm, 'name_en': nm, 'cb': f"vext_{ep['_id']}", 'price': float(ep.get('sell_price', ep.get('base_price', 0)) or 0),
                        'vip': False, 'stock': st, 'manual': False, 'in_stock': st > 0 or bool(ep.get('unlimited')),
                        'emoji_id': ep.get('emoji_id'), 'hidden': bool(ep.get('hidden')), 'style': None, 'cgpt': False})
    except Exception as e:
        logger.debug(f"shop items ext: {e}")
    return out


def _shop_item_btn(it, l):
    n = it['name_en'] if l == 'en' else it['name_ar']
    n = n[:25] + '..' if len(n) > 25 else n
    st_txt = '∞' if it['manual'] else str(it['stock'])
    txt = f"{n} | ${it['price']:.2f}{' 👑' if it['vip'] else ''} | 📦 {st_txt}{' 👻' if it['hidden'] else ''}"
    style = it['style'] if (it['style'] and it['in_stock']) else ('success' if it['in_stock'] else 'danger')
    kw = {'text': txt, 'callback_data': it['cb'], 'style': style}
    if it.get('emoji_id'):
        kw['icon_custom_emoji_id'] = it['emoji_id']
    return CustomInlineButton(**kw)


def _shop_is_admin(uid):
    u = get_user_data_full(uid) or {}
    return u.get('is_admin') == 1 or uid == OWNER_ID


@bot.callback_query_handler(func=lambda call: call.data == 'shop_search')
def shop_search_cb(call):
    try:
        bot.answer_callback_query(call.id)
    except Exception:
        pass
    uid = call.from_user.id
    if is_user_banned(uid):
        return
    l = get_lang(uid)
    mk = InlineKeyboardMarkup()
    mk.add(create_btn(uid, 'btn_back', callback_data='open_shop'))
    txt = get_text(uid, 'shop_search_prompt')
    msg = bot.send_message(call.message.chat.id, txt, parse_mode='HTML', reply_markup=mk)
    bot.register_next_step_handler(msg, shop_search_msg)


def shop_search_msg(message):
    t = (message.text or '').strip()
    if not t:
        return
    if t.startswith('/'):
        try:
            bot.process_new_messages([message])       # أمر (مثل /start) → نشغّله عادي
        except Exception:
            pass
        return
    _shop_search_show(message.chat.id, message.from_user.id, t)


@bot.message_handler(commands=['search'])
def shop_search_cmd(message):
    if is_user_banned(message.from_user.id):
        return
    q = (message.text or '').split(None, 1)
    if len(q) < 2 or not q[1].strip():
        call = types.SimpleNamespace(id='0', from_user=message.from_user, message=message)
        return shop_search_cb(call)
    _shop_search_show(message.chat.id, message.from_user.id, q[1].strip())


def _shop_search_show(chat_id, uid, query, edit_mid=None):
    l = get_lang(uid)
    items = _shop_items(uid, _shop_is_admin(uid))
    r = shop_search(query, items)
    found = r['items']
    mk = InlineKeyboardMarkup(row_width=1)
    q_show = html.escape(query[:60])
    if found:
        head = (f"🔎 <b>{len(found)}</b> result(s) for «{q_show}»" if l == 'en' else f"🔎 لقيت <b>{len(found)}</b> لـ «{q_show}»")
        if r['corrected']:
            c = html.escape(r['corrected'])
            head = (f"🔎 No results for «{q_show}» — showing «<b>{c}</b>» ({len(found)})" if l == 'en'
                    else f"🔎 ما لقيت «{q_show}» — هذي نتائج «<b>{c}</b>» ({len(found)})")
        for it in found[:20]:
            mk.add(_shop_item_btn(it, l))
        if len(found) > 20:
            head += ("\n<i>Showing the first 20 — type more of the name to narrow it down.</i>" if l == 'en'
                     else "\n<i>أعرض أول 20 — اكتب أكثر من الاسم عشان تضيّق.</i>")
    else:
        head = (f"😕 Nothing matches «{q_show}»." if l == 'en' else f"😕 ما لقيت شي بـ «{q_show}».")
        if r['suggest']:
            _SHOP_SQ[uid] = r['suggest'][:3]
            head += ("\n\n💡 Did you mean:" if l == 'en' else "\n\n💡 هل تقصد:")
            mk.row(*[InlineKeyboardButton(w, callback_data=f"shop_sq_{i}") for i, w in enumerate(_SHOP_SQ[uid])])
        else:
            head += ("\nTry another word or a short form like <code>nf</code>." if l == 'en'
                     else "\nجرّب كلمة ثانية أو اختصار مثل <code>nf</code>.")
    mk.row(create_btn(uid, 'btn_shop_search', callback_data='shop_search'), create_btn(uid, 'btn_back', callback_data='open_shop'))
    if edit_mid:
        try:
            bot.edit_message_text(head, chat_id, edit_mid, parse_mode='HTML', reply_markup=mk)
            return
        except Exception:
            pass
    bot.send_message(chat_id, head, parse_mode='HTML', reply_markup=mk)


@bot.callback_query_handler(func=lambda call: call.data.startswith('shop_sq_'))
def shop_sq_cb(call):
    try:
        bot.answer_callback_query(call.id)
    except Exception:
        pass
    uid = call.from_user.id
    try:
        w = _SHOP_SQ.get(uid, [])[int(call.data.rsplit('_', 1)[1])]
    except Exception:
        w = None
    if not w:
        return shop_search_cb(call)
    try:
        bot.clear_step_handler_by_chat_id(chat_id=call.message.chat.id)
    except Exception:
        pass
    _shop_search_show(call.message.chat.id, uid, w, edit_mid=call.message.message_id)


@bot.callback_query_handler(func=lambda call: call.data in ('shop_available', 'shop_available_text'))
def shop_available_table_cb(call):
    try:
        bot.answer_callback_query(call.id)
    except Exception:
        pass
    uid = call.from_user.id
    if is_user_banned(uid):
        return
    if check_forced_sub(uid) is False:
        return start_handler(call)
    bot.clear_step_handler_by_chat_id(chat_id=call.message.chat.id)
    l = get_lang(uid)
    _plist_send(call.message.chat.id, uid, as_text=call.data.endswith('_text'), lang=l)
    mk = InlineKeyboardMarkup(row_width=1)
    mk.add(create_btn(uid, 'btn_shop_search', callback_data='shop_search'))
    mk.add(create_btn(uid, 'btn_refresh', callback_data='shop_available'))
    mk.add(create_btn(uid, 'btn_shop_available_text', callback_data='shop_available_text'))
    mk.add(create_btn(uid, 'btn_shop_available_list', callback_data='shop_avail_0'))
    mk.add(create_btn(uid, 'btn_back', callback_data='open_shop'))
    bot.send_message(call.message.chat.id, get_text(uid, 'shop_available_hint'),
                     parse_mode='HTML', reply_markup=mk)


@bot.callback_query_handler(func=lambda call: call.data.startswith('shop_avail_'))
def shop_avail_cb(call):
    try:
        bot.answer_callback_query(call.id)
    except Exception:
        pass
    uid = call.from_user.id
    if is_user_banned(uid):
        return
    if check_forced_sub(uid) is False:
        start_handler(call.message)
        return
    try:
        bot.clear_step_handler_by_chat_id(chat_id=call.message.chat.id)
    except Exception:
        pass
    l = get_lang(uid)
    try:
        page = max(0, int(call.data.rsplit('_', 1)[1]))
    except Exception:
        page = 0
    items = [it for it in _shop_items(uid, _shop_is_admin(uid)) if it['in_stock'] and not it['hidden']]
    items.sort(key=lambda it: (not it['cgpt'], sr_norm(it['name_en'] if l == 'en' else it['name_ar'])))
    PER = 15
    pages = max(1, (len(items) + PER - 1) // PER)
    page = min(page, pages - 1)
    mk = InlineKeyboardMarkup(row_width=1)
    for it in items[page * PER:(page + 1) * PER]:
        mk.add(_shop_item_btn(it, l))
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton("⬅️", callback_data=f"shop_avail_{page - 1}"))
    if pages > 1:
        nav.append(InlineKeyboardButton(f"{page + 1}/{pages}", callback_data="noop"))
    if page < pages - 1:
        nav.append(InlineKeyboardButton("➡️", callback_data=f"shop_avail_{page + 1}"))
    if nav:
        mk.row(*nav)
    mk.row(create_btn(uid, 'btn_shop_search', callback_data='shop_search'), create_btn(uid, 'btn_back', callback_data='open_shop'))
    head = (f"✅ <b>In stock now</b> — {len(items)} products" if l == 'en' else f"✅ <b>المتوفر الحين</b> — {len(items)} منتج")
    if not items:
        head += ("\n\nNothing is in stock right now." if l == 'en' else "\n\nما فيه شي متوفر الحين.")
    try:
        bot.edit_message_text(head, call.message.chat.id, call.message.message_id, parse_mode='HTML', reply_markup=mk)
    except Exception as e:
        if 'not modified' not in str(e).lower():
            bot.send_message(call.message.chat.id, head, parse_mode='HTML', reply_markup=mk)



@bot.callback_query_handler(func=lambda call: call.data == "open_shop")
def shop_list_ui(call):
    bot.answer_callback_query(call.id)
    uid = call.from_user.id
    if is_user_banned(uid): return
    if check_forced_sub(uid) is False: start_handler(call.message); return
    
    u = get_user_data_full(uid)
    is_admin = (u.get('is_admin') == 1 or uid == OWNER_ID)
    l = get_lang(uid)

    # وضع العرض لكل مستخدم: folders (مجلدات) أو flat (كل المنتجات بصفحات)
    display_mode = u.get('shop_display_mode', 'folders')
    if display_mode == 'flat':
        return _shop_flat_view(call, uid, l, is_admin, page=0)

    # فحص هل في كتالوجات
    catalogs = list(db.catalogs.find().sort('order', 1))
    
    if catalogs:
        # ═══ عرض الكتالوجات أولاً (مرتبة أبجدياً) ثم المنتجات العادية ═══
        markup = InlineKeyboardMarkup(row_width=2)
        _shop_tools_row(markup, uid)

        # 🤖 منتج ChatGPT Business في البداية المطلقة (قبل المجلدات)
        try:
            _cgpt_top = None
            for _cp in db.cgpt_products.find():
                _cgid = str(_cp['_id'])
                _aliases = {_cgid, f'cgpt_main_{_cgid}', f'cgpt_{_cgid}'}
                _linked = next((p for p in _get_all_products_cached()
                    if str(p.get('cgpt_product_id', '')) == _cgid
                    or str(p.get('_id', '')) in _aliases
                    or str(p.get('id', '')) in _aliases), None)
                if _linked:
                    _aliases.update(str(_linked[k]) for k in ('id', '_id') if _linked.get(k) is not None)
                if any(_aliases.intersection(str(x) for x in (c.get('product_ids') or []))
                       or (_linked and str(_linked.get('catalog_id')) == str(c['_id'])) for c in catalogs):
                    continue
                if (_cp.get('is_hidden') or (_linked and _linked.get('is_hidden'))) and not is_admin:
                    continue
                _seats = _cgpt_display_seats()
                _seats = _seats if _seats is not None else 0
                _cgnm = clean_name(get_translated_product_name(_cp, l, is_cgpt=True))
                _bt = f"{_cgnm} | 📦 {_seats if _CGPT_DISPLAY_SEATS['value'] is not None or _CGPT_SEATS_CACHE['val'] is not None else '…'}"
                _bstyle = "success" if _seats > 0 else "danger"
                _bkw = {'text': _bt, 'callback_data': f"vi_p_cgpt_main_{_cgid}", 'style': _bstyle}
                if _cp.get('custom_emoji_id'):
                    _bkw['icon_custom_emoji_id'] = _cp['custom_emoji_id']
                markup.add(CustomInlineButton(**_bkw))
        except Exception as _cge:
            logger.debug(f"cgpt top btn err: {_cge}")

        # ترتيب الكتالوجات أبجدياً
        name_key = 'name_en' if l == 'en' else 'name_ar'
        catalogs.sort(key=lambda c: (c.get(name_key) or c.get('name_ar', '')).lower())
        
        cat_buttons = []
        _ext_counts = _catalog_ext_counts([str(c.get('_id', '')) for c in catalogs])   # استعلام واحد لكل المجلدات
        for cat in catalogs:
            cat_id = str(cat.get('_id', ''))
            emoji = cat.get('emoji', '📁')
            emoji_id = cat.get('emoji_id')
            name = cat.get('name_en', cat.get('name_ar', '')) if l == 'en' else cat.get('name_ar', cat.get('name_en', ''))
            # العدد = المنتجات الظاهرة الموجودة فعلاً (من الذاكرة — بدون استعلامات)
            count = _catalog_visible_count(cat) + _ext_counts.get(cat_id, 0)
            if count == 0 and not is_admin:
                continue
            btn_text = f"{name} ({count})" if emoji_id else f"{emoji} {name} ({count})"
            btn_kwargs = {'text': btn_text, 'callback_data': f"cat_{cat_id}", 'style': 'primary'}
            if emoji_id:
                btn_kwargs['icon_custom_emoji_id'] = emoji_id
            cat_buttons.append(CustomInlineButton(**btn_kwargs))
        
        # نضيف أزرار الكتالوجات 2 جنب بعض
        for i in range(0, len(cat_buttons), 2):
            if i + 1 < len(cat_buttons):
                markup.add(cat_buttons[i], cat_buttons[i + 1])
            else:
                markup.add(cat_buttons[i])
        
        # المنتجات بدون كتالوج
        all_catalog_pids = set()
        for cat in catalogs:
            for x in (cat.get('product_ids') or []):
                # نطبّع كل صيغة ممكنة: ObjectId، نص، رقم
                all_catalog_pids.add(str(x))
                # لو مخزّن كـ ObjectId، نضيف صيغته النصية أيضاً (مطابقة مضمونة)
                try:
                    all_catalog_pids.add(str(ObjectId(str(x))))
                except Exception:
                    pass

        prods_no_cat = []
        for p in _get_all_products_cached():
            # نقارن بكل معرّفات المنتج الممكنة ضد مجموعة المجلدات
            pid_candidates = set()
            if p.get('id') is not None:
                pid_candidates.add(str(p.get('id')))
            pid_candidates.add(str(p.get('_id', '')))
            try:
                pid_candidates.add(str(ObjectId(str(p.get('_id', '')))))
            except Exception:
                pass
            # لو أي معرّف للمنتج موجود في أي مجلد → نتخطّاه (لا نعرضه خارج المجلد)
            if pid_candidates & all_catalog_pids:
                continue
            if p.get('is_hidden', False) and not is_admin:
                continue
            # منتج ChatGPT معروض في الأعلى بالفعل — نتخطّاه هنا لتفadي التكرار
            if p.get('product_type') == 'cgpt_main':
                continue
            prods_no_cat.append(p)
        
        # ترتيب المنتجات الغير مصنّفة أبجدياً
        prods_no_cat.sort(key=lambda p: (
            not (p.get('product_type') == 'cgpt_main'),
            clean_name(p.get('name_en' if l == 'en' else 'name_ar', '')).lower()))

        # ⚡ جلب عدد المخزون لكل المنتجات بلا مجلد دفعة واحدة (بدل استعلام لكل منتج)
        _stock_map = {}
        try:
            _pids = []
            for p in prods_no_cat:
                _pd = str(p.get('id', str(p.get('_id', ''))))
                _pids.append(_pd)
                if _pd.isdigit():
                    _pids.append(int(_pd))
            if _pids:
                for row in db.product_stock.aggregate([
                    {'$match': {'product_id': {'$in': _pids}, 'is_sold': False}},
                    {'$group': {'_id': '$product_id', 'c': {'$sum': 1}}}
                ]):
                    _stock_map[str(row['_id'])] = row['c']
        except Exception as _e:
            logger.debug(f"no-cat stock batch err: {_e}")

        # عرض المنتجات الغير مصنّفة كأزرار عادية
        for p in prods_no_cat:
            pid = p.get('id', str(p.get('_id', '')))
            is_manual = p.get('is_manual', False)
            is_cgpt = p.get('product_type') == 'cgpt_main'
            st = _stock_map.get(str(pid), 0)
            in_stock = is_manual or st > 0 or is_cgpt
            db_style = p.get('btn_style')
            btn_style = db_style if (db_style and in_stock) else ("success" if in_stock else "danger")
            is_hidden = p.get('is_hidden', False)
            hidden_icon = " 👻" if is_hidden else ""
            n = clean_name(p.get('name_en') if l == 'en' else p.get('name_ar'))
            short_n = n[:25] + ".." if len(n) > 25 else n
            if is_cgpt:
                _cg_seats = _cgpt_display_seats()
                _cg_seats = _cg_seats if _cg_seats is not None else 0
                in_stock = _cg_seats > 0
                st_text = str(_cg_seats) if _CGPT_DISPLAY_SEATS['value'] is not None or _CGPT_SEATS_CACHE['val'] is not None else "…"
                btn_text = f"{short_n} | 📦 {st_text}{hidden_icon}"
            else:
                st_text = "FW" if is_manual else str(st)
                _lp, _lb = vip_unit(uid, pid, p.get('price', 0))
                btn_text = f"{short_n} | ${_lp:.2f}{' 👑' if _lb else ''} | 📦 {st_text}{hidden_icon}"
            callback_pid = str(pid).replace("cgpt_main_", "") if str(pid).startswith("cgpt_main_") else str(pid)
            cb = f"vi_p_cgpt_main_{callback_pid}" if is_cgpt else f"vi_p_{callback_pid}"
            btn_kwargs = {'text': btn_text, 'callback_data': cb, 'style': btn_style}
            custom_emoji_id = p.get('custom_emoji_id')
            if is_cgpt:
                try:
                    _cgp = db.cgpt_products.find_one({'_id': ObjectId(str(callback_pid))})
                    if _cgp and _cgp.get('custom_emoji_id'):
                        custom_emoji_id = _cgp['custom_emoji_id']
                except Exception:
                    pass
            if custom_emoji_id:
                btn_kwargs['icon_custom_emoji_id'] = custom_emoji_id
            markup.add(CustomInlineButton(**btn_kwargs))

        # 🔌 منتجات API الخارجية الظاهرة (غير المخفية) وبلا مجلد فقط
        try:
            for ep in db.ext_products.find({'catalog_id': {'$in': [None, '']}}, _EXT_LIGHT_PROJ):
                if ep.get('catalog_id'):
                    continue
                if ep.get('hidden') and not is_admin:
                    continue
                epid = str(ep['_id'])
                price = float(ep.get('sell_price', ep.get('base_price', 0)))
                enm = str(ep.get('name', ''))
                short_n = enm[:30] + ".." if len(enm) > 30 else enm
                hidden_icon = " 👻(مخفي)" if ep.get('hidden') else ""
                bt = f"{short_n}{hidden_icon}"  # الاسم فقط (سريع)
                bstyle = "success"
                bkw = {'text': bt, 'callback_data': f"vext_{epid}", 'style': bstyle}
                if ep.get('emoji_id'):
                    bkw['icon_custom_emoji_id'] = ep['emoji_id']
                markup.add(CustomInlineButton(**bkw))
        except Exception as _ee:
            logger.debug(f"ext products in shop err: {_ee}")

        markup.add(create_btn(uid, 'btn_refresh', callback_data="open_shop"))
        markup.add(create_btn(uid, 'btn_main_menu', callback_data="main_menu_refresh"))
        
        store_emoji_id = get_setting('emoji_store', '')
        store_text = get_text(uid, 'store_title')
        if store_emoji_id and store_emoji_id != "Not Set":
            store_text = f'<tg-emoji emoji-id="{store_emoji_id}">✨</tg-emoji> ' + store_text
        
        try: bot.edit_message_text(store_text, call.message.chat.id, call.message.message_id, reply_markup=markup, parse_mode="HTML")
        except: pass
    else:
        # ═══ بدون كتالوجات — العرض العادي القديم ═══
        all_prods_nc = list(_get_all_products_cached())
        # جلب المخزون دفعة واحدة
        nc_ids = []
        for p in all_prods_nc:
            spid = str(p.get('id', str(p.get('_id', ''))))
            nc_ids.append(spid)
            if spid.isdigit():
                nc_ids.append(int(spid))
        nc_stock = {}
        try:
            if nc_ids:
                for row in db.product_stock.aggregate([
                    {'$match': {'product_id': {'$in': nc_ids}, 'is_sold': False}},
                    {'$group': {'_id': '$product_id', 'c': {'$sum': 1}}}
                ]):
                    nc_stock[str(row['_id'])] = row['c']
        except Exception as _nce:
            logger.debug(f"nocat stock batch err: {_nce}")

        # نبني القائمة مع حالة التوفّر
        nc_items = []
        _nc_seats = None
        _nc_seats_done = False
        for p in all_prods_nc:
            is_hidden = p.get('is_hidden', False)
            if is_hidden and not is_admin:
                continue
            is_manual = p.get('is_manual', False)
            pid = str(p.get('id', str(p.get('_id', ''))))
            is_cgpt = p.get('product_type') == 'cgpt_main'
            if is_cgpt:
                if not _nc_seats_done:
                    _nc_seats = _cgpt_display_seats()
                    _nc_seats_done = True
                st = _nc_seats if _nc_seats is not None else 0
                in_stock = st > 0
            else:
                st = nc_stock.get(pid, 0)
                in_stock = is_manual or st > 0
            nc_items.append((p, pid, st, is_manual, in_stock))

        # منتج ChatGPT أولاً، ثم المتوفر، ثم غير المتوفر
        nc_items.sort(key=lambda x: (
            not (x[0].get('product_type') == 'cgpt_main'),
            not x[4],
            clean_name(x[0].get('name_en' if l == 'en' else 'name_ar', '')).lower()))

        markup = InlineKeyboardMarkup(row_width=1)
        _shop_tools_row(markup, uid)

        for p, pid, st, is_manual, in_stock in nc_items:
            is_hidden = p.get('is_hidden', False)
            is_cgpt = p.get('product_type') == 'cgpt_main'
            db_style = p.get('btn_style') if (p.get('btn_style') and in_stock) else ("success" if in_stock else "danger")
            hidden_icon = " 👻(مخفي)" if is_hidden else ""
            n = clean_name(p.get('name_en') if l == 'en' else p.get('name_ar'))
            short_n = n[:25] + ".." if len(n) > 25 else n
            if is_cgpt:
                st_text = str(st) if _nc_seats is not None else "…"  # المقاعd المتاحة
            else:
                st_text = "FW" if is_manual else str(st)
            btn_text = f"{short_n} | 📦 {st_text}{hidden_icon}"
            callback_pid = str(pid).replace("cgpt_main_", "") if str(pid).startswith("cgpt_main_") else str(pid)
            cb = f"vi_p_cgpt_main_{callback_pid}" if is_cgpt else f"vi_p_{callback_pid}"
            btn_kwargs = {'text': btn_text, 'callback_data': cb, 'style': db_style}
            custom_emoji_id = p.get('custom_emoji_id')
            if is_cgpt:
                try:
                    _cgp = db.cgpt_products.find_one({'_id': ObjectId(str(callback_pid))})
                    if _cgp and _cgp.get('custom_emoji_id'):
                        custom_emoji_id = _cgp['custom_emoji_id']
                except Exception:
                    pass
            if custom_emoji_id:
                btn_kwargs['icon_custom_emoji_id'] = custom_emoji_id
            markup.add(CustomInlineButton(**btn_kwargs))

        # 🔌 منتجات API الخارجية (بنفس شكل المنتجات العادية)
        try:
            for ep in db.ext_products.find({'catalog_id': {'$in': [None, '']}}, _EXT_LIGHT_PROJ):
                if ep.get('catalog_id'):
                    continue
                if ep.get('hidden') and not is_admin:
                    continue
                epid = str(ep['_id'])
                price = float(ep.get('sell_price', ep.get('base_price', 0)))
                enm = str(ep.get('name', ''))
                short_n = enm[:30] + ".." if len(enm) > 30 else enm
                hidden_icon = " 👻(مخفي)" if ep.get('hidden') else ""
                bt = f"{short_n}{hidden_icon}"  # الاسم فقط (سريع)
                bstyle = "success"
                bkw = {'text': bt, 'callback_data': f"vext_{epid}", 'style': bstyle}
                if ep.get('emoji_id'):
                    bkw['icon_custom_emoji_id'] = ep['emoji_id']
                markup.add(CustomInlineButton(**bkw))
        except Exception as _ee:
            logger.debug(f"ext products no-cat branch err: {_ee}")

        markup.add(create_btn(uid, 'btn_refresh', callback_data="open_shop"))
        markup.add(create_btn(uid, 'btn_main_menu', callback_data="main_menu_refresh"))
        
        store_emoji_id = get_setting('emoji_store', '')
        store_text = get_text(uid, 'store_title')
        if store_emoji_id and store_emoji_id != "Not Set":
            store_text = f'<tg-emoji emoji-id="{store_emoji_id}">✨</tg-emoji> ' + store_text

        try: bot.edit_message_text(store_text, call.message.chat.id, call.message.message_id, reply_markup=markup, parse_mode="HTML")
        except: pass


# ═══ عرض محتويات كتالوج معيّن ═══
@bot.callback_query_handler(func=lambda call: call.data.startswith("cat_"))
def catalog_view(call):
    bot.answer_callback_query(call.id)
    uid = call.from_user.id
    if is_user_banned(uid): return
    l = get_lang(uid)
    
    cat_id = call.data.replace("cat_", "")
    catalog_view_helper(call.message.chat.id, uid, cat_id, l, message_id_to_edit=call.message.message_id)

@bot.callback_query_handler(func=lambda call: call.data.startswith("vi_p_"))
def shop_detail_ui(call):
    bot.answer_callback_query(call.id)
    uid = call.from_user.id
    if is_user_banned(uid): return
    l = get_lang(uid)
    raw = call.data.replace('vi_p_', '')
    # دعم vi_p_{pid}_c_{cat_id}
    if '_c_' in raw:
        pid, cat_id_back = raw.split('_c_', 1)
    else:
        pid = raw
        cat_id_back = None
    
    p = find_product(pid)
    if not p:
        bot.send_message(uid, bil(uid, "❌ عذراً، المنتج غير متوفر.", "❌ Sorry, product is unavailable."), parse_mode="HTML"); return
    pid = p['_id']

    u = get_user_data_full(uid)
    is_admin = (u.get('is_admin') == 1 or uid == OWNER_ID)
    if p.get('is_hidden', False) and not is_admin:
        bot.send_message(uid, bil(uid, "❌ عذراً، هذا المنتج غير متوفر حالياً.", "❌ Sorry, this product is currently unavailable."), parse_mode="HTML"); return

    # ── ChatGPT Main: صفحة موحدة بكل المدد ──
    if p.get('product_type') == 'cgpt_main' and p.get('cgpt_product_id'):
        cgpt_parent_id = p['cgpt_product_id']
        try:
            from bson import ObjectId as _ObjId
            parent = db.cgpt_products.find_one({'_id': _ObjId(cgpt_parent_id)})
        except:
            parent = None

        p_name = clean_name(get_translated_product_name(parent, l, is_cgpt=True)) if parent else clean_name(get_translated_product_name(p, l))
        p_desc = get_translated_product_desc(parent, l, is_cgpt=True) if parent else get_translated_product_desc(p, l)
        durations = (parent.get('durations', []) if parent else [])
        durations_sorted = sorted(durations, key=lambda x: x.get('price', 0))
        custom_emoji_id = p.get('custom_emoji_id')
        # نجلب الرمز الطازج من cgpt_products
        if parent and parent.get('custom_emoji_id'):
            custom_emoji_id = parent['custom_emoji_id']
        icon_html = f'<tg-emoji emoji-id="{custom_emoji_id}">✨</tg-emoji>' if custom_emoji_id else '🤖'

        # المقاعd المتاحة (المخزون الحقيقي)
        _seats = _cgpt_display_seats()
        _seats = _seats if _seats is not None else "…"

        text = get_text(uid, 'cg_page', icon_html, p_name, p_desc, _seats)

        back_cb = f"cat_{cat_id_back}" if cat_id_back else "open_shop"
        markup = InlineKeyboardMarkup(row_width=1)

        for dur in durations_sorted:
            dur_id    = dur.get('dur_id', '')
            dur_label = dur.get('label_en') if l == 'en' and dur.get('label_en') else dur.get('label', '')
            if l == 'en' and not dur.get('label_en'):
                translated_label = translate_duration_label(dur.get('label', ''), 'en')
                if translated_label and translated_label != dur.get('label', ''):
                    dur_label = translated_label
                    try:
                        db.cgpt_products.update_one(
                            {'_id': _ObjId(cgpt_parent_id), 'durations.dur_id': dur_id},
                            {'$set': {'durations.$.label_en': translated_label}}
                        )
                    except:
                        pass
            dur_price, _vbp = vip_unit(uid, f"cgpt_{cgpt_parent_id}", float(dur.get('price', 0)))
            _mins = int(dur.get('minutes', 0))
            if not dur_label or not dur_label.strip():
                if _mins >= 43200:
                    dur_label = f"{_mins // 43200} شهر" if l == 'ar' else f"{_mins // 43200} month"
                elif _mins >= 1440:
                    dur_label = f"{_mins // 1440} يوم" if l == 'ar' else f"{_mins // 1440} days"
                else:
                    dur_label = f"{_mins // 60} ساعة" if l == 'ar' else f"{_mins // 60} hours"
            _days = round(_mins / 1440, 1) if _mins else 0
            _dtxt = f" ({_days}ي)" if l == 'ar' else f" ({_days}d)"
            markup.add(_cgpt_cms_button(uid, 'cg_buy', f" — {dur_label} · ${dur_price:.2f}{' 👑' if _vbp else ''}{_dtxt}",
                callback_data=f"cgpt_buy_{cgpt_parent_id}_{dur_id}"
            ))

        markup.add(create_btn(uid, 'cg_back', callback_data=back_cb))
        if is_admin:
            short_pid = str(pid).replace("cgpt_main_", "") if str(pid).startswith("cgpt_main_") else str(pid)
            _remember_product_edit_parent(uid, short_pid,
                f"vi_p_{short_pid}_c_{cat_id_back}" if cat_id_back else f"vi_p_{short_pid}")
            edit_cb = f"edit_p_{short_pid}_c_{cat_id_back}" if cat_id_back else f"edit_p_{short_pid}"
            markup.add(InlineKeyboardButton("⚙️ ...", callback_data=edit_cb))

        try: bot.edit_message_text(text, call.message.chat.id, call.message.message_id, reply_markup=markup, parse_mode="HTML")
        except: pass
        return

    # ── منتج عادي ──
    is_manual = p.get('is_manual', False)
    st = get_product_stock_count(pid)

    if l == 'ar':
        delivery_type = "يدوي 🤝 (تواصل مع الإدارة بعد الدفع)" if is_manual else "تلقائي ⚡ (تسليم فوري)"
        st_text = "غير محدود" if is_manual else f"{st} قطعة"
    else:
        delivery_type = "Manual 🤝 (Contact admin after payment)" if is_manual else "Auto ⚡ (Instant delivery)"
        st_text = "Unlimited" if is_manual else f"{st} pcs"

    n = clean_name(get_translated_product_name(p, l))
    d = get_translated_product_desc(p, l)
    custom_emoji_id = p.get('custom_emoji_id')
    icon_html = f'<tg-emoji emoji-id="{custom_emoji_id}">✨</tg-emoji>' if custom_emoji_id else '📦'

    discount_tiers = p.get('discount_tiers', [])
    discount_text = ""
    if discount_tiers:
        sorted_tiers = sorted(discount_tiers, key=lambda x: x.get('min_qty', 0))
        if l == 'ar':
            discount_text = "\n\n🏷 <b>خصومات الكمية:</b>\n"
            for t in sorted_tiers:
                t_price = float(t.get('price', 0))
                discount_text += f"  • {t.get('min_qty')}+ قطعة = <b>${t_price:.2f}</b>/قطعة\n"
        else:
            discount_text = "\n\n🏷 <b>Quantity Discounts:</b>\n"
            for t in sorted_tiers:
                t_price = float(t.get('price', 0))
                discount_text += f"  • {t.get('min_qty')}+ units = <b>${t_price:.2f}</b>/unit\n"

    if l == 'en':
        text = f"{icon_html} <b>{n}</b>\n\n📝 {d}\n\n🚚 <b>Delivery:</b> {delivery_type}\n💰 <b>Price:</b> {vip_price_html(uid, p.get('id', pid), p.get('price', 0), 'en')}\n📊 <b>Stock:</b> {st_text}{discount_text}"
    else:
        text = f"{icon_html} <b>{n}</b>\n\n📝 {d}\n\n🚚 <b>نوع التسليم:</b> {delivery_type}\n💰 <b>السعر:</b> {vip_price_html(uid, p.get('id', pid), p.get('price', 0))}\n📊 <b>المتوفر:</b> {st_text}{discount_text}"

    back_cb = f"cat_{cat_id_back}" if cat_id_back else "open_shop"
    markup = InlineKeyboardMarkup()
    short_pid = str(pid).replace("cgpt_main_", "") if str(pid).startswith("cgpt_main_") else str(pid)
    if is_manual or st > 0:
        qty_cb = f"buy_qty_{short_pid}_c_{cat_id_back}" if cat_id_back else f"buy_qty_{short_pid}"
        markup.add(create_btn(uid, 'btn_buy_now', callback_data=qty_cb))
    markup.add(create_btn(uid, 'btn_back', callback_data=back_cb))

    if _is_admin_check(uid):
        _remember_product_edit_parent(uid, short_pid,
            f"vi_p_{short_pid}_c_{cat_id_back}" if cat_id_back else f"vi_p_{short_pid}")
        edit_cb = f"edit_p_{short_pid}_c_{cat_id_back}" if cat_id_back else f"edit_p_{short_pid}"
        markup.add(InlineKeyboardButton("⚙️ ...", callback_data=edit_cb))

    try: bot.edit_message_text(text, call.message.chat.id, call.message.message_id, reply_markup=markup, parse_mode="HTML")
    except: pass

@bot.callback_query_handler(func=lambda call: call.data.startswith("buy_qty_"))
def prompt_quantity(call):
    bot.answer_callback_query(call.id)
    uid = call.from_user.id
    if is_user_banned(uid): return
    l = get_lang(uid)
    raw_bq = call.data.replace('buy_qty_', '')
    if '_c_' in raw_bq:
        pid, cat_id_back = raw_bq.split('_c_', 1)
    else:
        pid = raw_bq
        cat_id_back = None
    
    p = find_product(pid)
    if not p: return
    
    is_manual = p.get('is_manual', False)
    if not is_manual and get_product_stock_count(pid) == 0:
        bot.send_message(uid, get_text(uid, 'out_stock'), parse_mode="HTML")
        return
    
    unit_price = float(p.get('price', 0))
    is_cgpt_flag = pid.startswith('cgpt_')
    p_name = clean_name(get_translated_product_name(p, l, is_cgpt=is_cgpt_flag))
    custom_emoji_id = p.get('custom_emoji_id')
    icon_html = f'<tg-emoji emoji-id="{custom_emoji_id}">✨</tg-emoji> ' if custom_emoji_id else '📦 '
    
    # نبني جدول الخصومات
    discount_tiers = sorted(p.get('discount_tiers', []), key=lambda x: x.get('min_qty', 0))
    
    if l == 'ar':
        qty_msg = (
            f"{icon_html}<b>{p_name}</b>\n\n"
            f"━━━━━━━━━━━━━━\n"
            f"💰 <b>السعر:</b> {vip_price_html(uid, p.get('id', pid), unit_price)} / قطعة\n"
        )
        if discount_tiers:
            qty_msg += "\n🏷 <b>خصومات الكمية:</b>\n"
            for t in discount_tiers:
                t_price = float(t.get('price', unit_price))
                qty_msg += f"  • {t['min_qty']}+ قطعة → <b>${t_price:.2f}</b>/قطعة\n"
        qty_msg += (
            f"\n━━━━━━━━━━━━━━\n"
            f"📝 <b>أرسل الكمية المطلوبة:</b>"
        )
    else:
        qty_msg = (
            f"{icon_html}<b>{p_name}</b>\n\n"
            f"━━━━━━━━━━━━━━\n"
            f"💰 <b>Price:</b> {vip_price_html(uid, p.get('id', pid), unit_price, 'en')} / unit\n"
        )
        if discount_tiers:
            qty_msg += "\n🏷 <b>Quantity Discounts:</b>\n"
            for t in discount_tiers:
                t_price = float(t.get('price', unit_price))
                qty_msg += f"  • {t['min_qty']}+ units → <b>${t_price:.2f}</b>/unit\n"
        qty_msg += (
            f"\n━━━━━━━━━━━━━━\n"
            f"📝 <b>Send the quantity:</b>"
        )
    
    msg = bot.send_message(uid, qty_msg, parse_mode="HTML")
    bot.register_next_step_handler(msg, execute_bulk_buy, pid, l)

def execute_bulk_buy(message, pid, lang):
    uid = message.from_user.id
    if is_user_banned(uid): return
    if not hasattr(message, 'text') or hasattr(message, 'data'): return
    if not message.text or not message.text.strip().isdigit():
        bot.send_message(uid, get_text(uid, 'qty_invalid'), parse_mode="HTML"); return
        
    qty = int(message.text.strip())
    if qty <= 0:
        bot.send_message(uid, get_text(uid, 'qty_invalid'), parse_mode="HTML"); return
    
    # نجلب المنتج لحساب السعر مع الخصم
    p = find_product(pid)
    if not p:
        bot.send_message(uid, bil(uid, "❌ المنتج غير موجود.", "❌ Product not found."), parse_mode="HTML")
        return
    
    unit_price = float(p.get('price', 0))
    p_name = clean_name(p.get('name_ar') if lang == 'ar' else p.get('name_en', p.get('name_ar', '')))
    discount_tiers = sorted(p.get('discount_tiers', []), key=lambda x: x.get('discount', 0), reverse=True)
    
    # 🏷 حساب الخصم - سعر ثابت بالدولار
    discounted_unit = unit_price
    for tier in sorted(discount_tiers, key=lambda x: x.get('min_qty', 0), reverse=True):
        if qty >= tier.get('min_qty', 0):
            discounted_unit = float(tier.get('price', unit_price))
            break
    _vq = vip_quote(uid, p.get('id', pid), discounted_unit, qty)
    discounted_unit = _vq['unit']
    total_price = _vq['total']
    has_discount = (discounted_unit < unit_price)
    
    # ملخص السعر للتأكيد
    if has_discount:
        if lang == 'ar':
            price_summary = (
                f"📦 <b>{p_name}</b>\n\n"
                f"━━━━━━━━━━━━━━\n"
                f"🔢 الكمية: <b>{qty}</b>\n"
                f"💵 السعر الأصلي: <strike>${unit_price:.2f}</strike>/قطعة\n"
                f"✅ سعر الخصم: <b>${discounted_unit:.2f}</b>/قطعة\n"
                f"━━━━━━━━━━━━━━\n"
                f"💰 <b>الإجمالي: ${total_price:.2f}</b>\n\n"
                f"هل تؤكد الشراء؟"
            )
        else:
            price_summary = (
                f"📦 <b>{p_name}</b>\n\n"
                f"━━━━━━━━━━━━━━\n"
                f"🔢 Qty: <b>{qty}</b>\n"
                f"💵 Original: <strike>${unit_price:.2f}</strike>/unit\n"
                f"✅ Discounted: <b>${discounted_unit:.2f}</b>/unit\n"
                f"━━━━━━━━━━━━━━\n"
                f"💰 <b>Total: ${total_price:.2f}</b>\n\n"
                f"Confirm purchase?"
            )
    else:
        if lang == 'ar':
            price_summary = (
                f"📦 <b>{p_name}</b>\n\n"
                f"━━━━━━━━━━━━━━\n"
                f"🔢 الكمية: <b>{qty}</b>\n"
                f"💵 السعر: <b>${unit_price:.2f}</b>/قطعة\n"
                f"━━━━━━━━━━━━━━\n"
                f"💰 <b>الإجمالي: ${total_price:.2f}</b>\n\n"
                f"هل تؤكد الشراء؟"
            )
        else:
            price_summary = (
                f"📦 <b>{p_name}</b>\n\n"
                f"━━━━━━━━━━━━━━\n"
                f"🔢 Qty: <b>{qty}</b>\n"
                f"💵 Price: <b>${unit_price:.2f}</b>/unit\n"
                f"━━━━━━━━━━━━━━\n"
                f"💰 <b>Total: ${total_price:.2f}</b>\n\n"
                f"Confirm purchase?"
            )
    
    if _vq['bp']:
        price_summary = price_summary.replace(
            "\n━━━━━━━━━━━━━━\n💰",
            f"\n👑 <b>VIP {_vq['level']}</b> −{_vq['pct']:g}% "
            + (f"(you save ${_vq['saved']:.2f})" if lang == 'en' else f"(وفّرت ${_vq['saved']:.2f})")
            + "\n━━━━━━━━━━━━━━\n💰", 1)
    markup = InlineKeyboardMarkup()
    markup.add(
        InlineKeyboardButton(
            "✅ تأكيد" if lang == 'ar' else "✅ Confirm",
            callback_data=f"confirm_buy_{pid}_{qty}"
        ),
        InlineKeyboardButton(
            "❌ إلغاء" if lang == 'ar' else "❌ Cancel",
            callback_data="open_shop"
        )
    )
    bot.send_message(uid, price_summary, parse_mode="HTML", reply_markup=markup)



@bot.callback_query_handler(func=lambda call: call.data.startswith("confirm_buy_"))
def confirm_buy_handler(call):
    uid = call.from_user.id
    if is_user_banned(uid): return
    lang = get_lang(uid)
    
    # 🛡 أول شيء: نحذف أزرار الرسالة فوراً عشان ما يضغط مرتين
    try:
        bot.edit_message_reply_markup(
            call.message.chat.id,
            call.message.message_id,
            reply_markup=None
        )
    except: pass
    
    bot.answer_callback_query(call.id)
    
    parts = call.data.split('_')
    try:
        qty = int(parts[-1])
        pid = '_'.join(parts[2:-1])
    except:
        return

    if is_deposit_locked(uid):
        markup = InlineKeyboardMarkup()
        markup.add(InlineKeyboardButton(
            "❌ إلغاء عملية الإيداع" if lang == 'ar' else "❌ Cancel Deposit",
            callback_data="cancel_deposit"
        ))
        bot.send_message(uid, bil(uid,
            "⚠️ <b>لديك عملية إيداع جارية!</b>\n\nيجب إكمال الإيداع أو إلغاؤه أولاً.",
            "⚠️ <b>You have a pending deposit!</b>\n\nPlease complete or cancel it first."
        ), parse_mode="HTML", reply_markup=markup)
        return

    # رسالة "جاري المعالجة" من CMS
    try:
        cms_proc = db.custom_texts.find_one({'lang': 'en', 'key': 'processing_msg'})
        proc_text = cms_proc['value'] if cms_proc and cms_proc.get('value') else bil(uid, "⏳ <b>جاري معالجة طلبك...</b>", "⏳ <b>Processing your order...</b>")
        bot.edit_message_text(proc_text, call.message.chat.id, call.message.message_id, parse_mode="HTML")
    except: pass

    _do_purchase(uid, pid, qty, lang)


# قاموس مؤقت لبيانات شراء ChatGPT
_cgpt_pending = {}
_CGPT_PENDING_LOCK = threading.RLock()


def _cgpt_take_pending(uid, order_id=None, require_email=False):
    with _CGPT_PENDING_LOCK:
        pending = _cgpt_pending.get(uid)
        if not pending or (order_id is not None and pending.get('order_id') != order_id):
            return None
        if require_email and ('price' not in pending or not pending.get('email')):
            return None
        return _cgpt_pending.pop(uid, None)


@bot.callback_query_handler(func=lambda call: call.data == "close_msg")
def _close_msg_handler(call):
    try: bot.answer_callback_query(call.id)
    except Exception: pass
    try: bot.delete_message(call.message.chat.id, call.message.message_id)
    except Exception: pass


@bot.callback_query_handler(func=lambda call: call.data.startswith("cgpt_renew_"))
def cgpt_renew(call):
    """تجديد اشتراك ChatGPT — يعرض المنتجات بالسعر الحالي."""
    try: bot.answer_callback_query(call.id)
    except Exception: pass
    uid = call.from_user.id
    if is_user_banned(uid): return
    old_email = call.data.replace("cgpt_renew_", "")
    l = get_lang(uid)
    # نعرض منتجات ChatGPT المتاحة (بالسعر الحالي) للتجديد
    products = list(db.cgpt_products.find())
    if not products:
        bot.send_message(uid, "⚠️ لا توجد باقات تجديد متاحة حالياً." if l != 'en'
                         else "⚠️ No renewal packages available.")
        return
    markup = InlineKeyboardMarkup(row_width=1)
    for p in products:
        pid = str(p.get('_id'))
        name = p.get('name', 'باقة')
        price = p.get('price', 0)
        # نمرّر الإيميل القديم ليُستخدم في التجديد
        markup.add(InlineKeyboardButton(
            f"{name} — ${price}",
            callback_data=f"cgpt_buy_{pid}_renew"))
    markup.add(InlineKeyboardButton("🔙 إلغاء", callback_data="close_msg"))
    # نحفظ الإيميل القديم مؤقتاً للتجديد
    try:
        db.cgpt_renew_pending.update_one({'_id': uid},
            {'$set': {'old_email': old_email, 'ts': int(time.time())}}, upsert=True)
    except Exception:
        pass
    bot.send_message(uid,
        (f"🔄 <b>تجديد اشتراك ChatGPT</b>\n\n"
         f"📧 الإيميل الحالي: <code>{html.escape(old_email)}</code>\n\n"
         f"اختر باقة التجديد (بالسعر الحالي):\n"
         f"<i>يمكنك استخدام نفس الإيميل أو تغييره عند الشراء.</i>") if l != 'en' else
        (f"🔄 <b>Renew ChatGPT subscription</b>\n\n"
         f"📧 Current email: <code>{html.escape(old_email)}</code>\n\n"
         f"Choose a renewal package (current price):"),
        parse_mode="HTML", reply_markup=markup)


@bot.callback_query_handler(func=lambda call: call.data.startswith("cgpt_buy_"))
def cgpt_buy_duration(call):
    """الزبون يضغط على مدة محددة → نطلب الإيميل"""
    bot.answer_callback_query(call.id)
    uid = call.from_user.id
    if is_user_banned(uid): return
    l = get_lang(uid)

    raw = call.data.replace("cgpt_buy_", "")
    parts = raw.split("_", 1)
    if len(parts) != 2:
        return
    cgpt_pid, dur_id = parts[0], parts[1]

    try:
        from bson import ObjectId as _ObjId2
        parent = db.cgpt_products.find_one({'_id': _ObjId2(cgpt_pid)})
    except:
        parent = None

    if not parent:
        bot.send_message(uid, get_text(uid, 'cg_notice_5'))
        return

    dur = next((d for d in parent.get('durations', []) if d.get('dur_id') == dur_id), None)
    if not dur:
        bot.send_message(uid, get_text(uid, 'cg_notice_6'))
        return

    _cq = vip_quote(uid, f"cgpt_{cgpt_pid}", float(dur.get('price', 0)))
    price = _cq['unit']
    label = dur.get('label_en') if l == 'en' and dur.get('label_en') else dur.get('label', '')
    if l == 'en' and not dur.get('label_en'):
        translated_label = translate_duration_label(dur.get('label', ''), 'en')
        if translated_label and translated_label != dur.get('label', ''):
            label = translated_label
            try:
                db.cgpt_products.update_one(
                    {'_id': _ObjId2(cgpt_pid), 'durations.dur_id': dur_id},
                    {'$set': {'durations.$.label_en': translated_label}}
                )
            except:
                pass
    minutes = int(dur.get('minutes', 10080))
    u = get_user_data_full(uid)
    balance = round(float(u.get('balance', 0)), 2) if u else 0.0

    if balance < price:
        send_no_balance(uid)
        return

    # نحفظ بيانات الشراء
    order_id = "CG" + secrets.token_hex(10)
    with _CGPT_PENDING_LOCK:
        _cgpt_pending[uid] = {
            'cgpt_pid': cgpt_pid,
            'dur_id': dur_id,
            'label': label,
            'price': price,
            'minutes': minutes,
            'order_id': order_id,
            'p_name': parent.get('name', ''),
            'vip_q': _cq if _cq['bp'] else None,
        }

    if l == 'ar':
        msg_txt = (
            f"✅ <b>المدة المختارة: {label} — ${price:.2f}</b>\n\n"
            f"📧 <b>أرسل إيميل حساب ChatGPT الخاص بك:</b>"
        )
    else:
        msg_txt = (
            f"✅ <b>Selected: {label} — ${price:.2f}</b>\n\n"
            f"📧 <b>Send your ChatGPT account email:</b>"
        )

    # Apply Business customization through the existing bilingual text system.
    msg_txt = get_text(uid, 'cg_email_prompt', html.escape(str(label)), f'{price:.2f}') or msg_txt
    markup = InlineKeyboardMarkup()
    markup.add(create_btn(uid, 'cg_cancel', callback_data=f"cgpt_cancel_buy_{uid}"))
    msg = bot.send_message(uid, msg_txt, parse_mode="HTML", reply_markup=markup)
    bot.register_next_step_handler(msg, cgpt_confirm_email_step, uid, l, order_id)

def _cancel_cgpt_purchase(uid, lang):
    try: bot.clear_step_handler_by_chat_id(uid)
    except: pass
    pending = _cgpt_take_pending(uid)
    if pending:
        if 'total_price' in pending:
            db.users.update_one({'user_id': uid}, {'$inc': {'balance': pending['total_price']}})
            txt = (
                get_text(uid, 'cg_refund_cancel', format(pending['total_price'], '.2f'))
            )
        else:
            txt = get_text(uid, 'cg_notice_7')
        try: bot.send_message(uid, txt, parse_mode="HTML")
        except: pass
    else:
        try: bot.send_message(uid, get_text(uid, 'cg_notice_8'))
        except: pass

@bot.callback_query_handler(func=lambda call: call.data.startswith("cgpt_cancel_buy_"))
def cgpt_cancel_buy_callback(call):
    try: bot.answer_callback_query(call.id)
    except: pass
    uid = int(call.data.replace("cgpt_cancel_buy_", ""))
    lang = get_lang(uid)
    _cancel_cgpt_purchase(uid, lang)

def cgpt_confirm_email_step(message, buyer_uid, lang, expected_order_id=None):
    """الخطوة 1: يرسل الإيميل → نطلب تأكيده"""
    if message.from_user.id != buyer_uid:
        return
    pending = _cgpt_pending.get(buyer_uid)
    if (not pending or 'price' not in pending or
            (expected_order_id is not None and pending.get('order_id') != expected_order_id)):
        bot.send_message(buyer_uid, get_text(buyer_uid, 'cg_notice_13'))
        return
    expected_order_id = pending.get('order_id')
    text_cmd = (message.text or "").strip().lower()
    if text_cmd in ['الغاء', 'cancel', '/cancel']:
        _cancel_cgpt_purchase(buyer_uid, lang)
        return
    import re as _re3
    email = (message.text or "").strip().lower()
    if not _re3.match(r'^[^@\s]+@[^@\s]+\.[^@\s]+$', email):
        bot.send_message(buyer_uid,
            get_text(buyer_uid, 'cg_notice_9'),
            parse_mode="HTML")
        pending = _cgpt_pending.get(buyer_uid)
        if pending:
            msg = bot.send_message(buyer_uid,
                get_text(buyer_uid, 'cg_notice_10'),
                parse_mode="HTML")
            bot.register_next_step_handler(msg, cgpt_confirm_email_step, buyer_uid, lang, expected_order_id)
        return

    # نطلب التأكيد
    markup = InlineKeyboardMarkup(row_width=2)
    markup.add(
        create_btn(buyer_uid, 'cg_confirm',
            callback_data=f"cgpt_email_ok_{buyer_uid}_{expected_order_id}"),
        create_btn(buyer_uid, 'cg_change',
            callback_data=f"cgpt_email_change_{buyer_uid}_{expected_order_id}")
    )
    # Work with the captured session; never recreate a cancelled/consumed order.
    with _CGPT_PENDING_LOCK:
        still_current = _cgpt_pending.get(buyer_uid) is pending
        if still_current:
            pending['email'] = email
    if not still_current:
        bot.send_message(buyer_uid, get_text(buyer_uid, 'cg_notice_13'))
        return
    bot.send_message(buyer_uid,
        get_text(buyer_uid, 'cg_email_confirm', html.escape(email)),
        parse_mode="HTML", reply_markup=markup)

@bot.callback_query_handler(func=lambda call: call.data.startswith("cgpt_email_change_"))
def cgpt_email_change(call):
    bot.answer_callback_query(call.id)
    uid_text, _, session_id = call.data[len('cgpt_email_change_'):].partition('_')
    buyer_uid = int(uid_text)
    if call.from_user.id != buyer_uid:
        return
    pending = _cgpt_pending.get(buyer_uid)
    if not pending or 'price' not in pending or (session_id and pending.get('order_id') != session_id):
        bot.send_message(buyer_uid, get_text(buyer_uid, 'cg_notice_13'))
        return
    lang = get_lang(buyer_uid)
    msg = bot.send_message(call.message.chat.id,
        get_text(buyer_uid, 'cg_notice_11'),
        parse_mode="HTML")
    bot.register_next_step_handler(msg, cgpt_confirm_email_step, buyer_uid, lang, pending.get('order_id'))

@bot.callback_query_handler(func=lambda call: call.data.startswith("cgpt_email_ok_"))
def cgpt_email_confirmed(call):
    """تأكيد الإيميل → تنفيذ الشراء"""
    bot.answer_callback_query(call.id)
    uid_text, _, session_id = call.data[len('cgpt_email_ok_'):].partition('_')
    buyer_uid = int(uid_text)
    if call.from_user.id != buyer_uid:
        return
    lang = get_lang(buyer_uid)
    pending = _cgpt_pending.get(buyer_uid)
    if not pending or 'price' not in pending or (session_id and pending.get('order_id') != session_id):
        bot.send_message(buyer_uid, get_text(buyer_uid, 'cg_notice_13'))
        return
    pending = _cgpt_take_pending(buyer_uid, pending.get('order_id'), require_email=True)
    if not pending or 'email' not in pending:
        bot.send_message(call.message.chat.id,
            get_text(buyer_uid, 'cg_notice_13'))
        return

    email   = pending['email']
    price   = pending['price']
    minutes = pending['minutes']
    label   = pending['label']
    order_id = pending['order_id']
    p_name  = pending['p_name']

    # 🪑 فحص المقاعd قبل الخصم — لو نفدت، نمنع الشراء
    _seats = _cgpt_get_seats_cached()
    if _seats is not None and _seats <= 0:
        bot.send_message(call.message.chat.id,
            (get_text(buyer_uid, 'cg_notice_14')),
            parse_mode="HTML")
        return

    # خصم الرصيد أتوميك
    updated = db.users.find_one_and_update(
        {'user_id': buyer_uid, 'balance': {'$gte': price - MONEY_EPS}},
        {'$inc': {'balance': -price}},
        return_document=True
    )
    if not updated:
        send_no_balance(buyer_uid)
        return
    vip_log_discount(buyer_uid, f"cgpt_{pending.get('cgpt_pid', '')}", pending.get('vip_q'), 'cgpt', order_id)

    bot.send_message(buyer_uid,
        get_text(buyer_uid, 'cg_notice_12'),
        parse_mode="HTML")

    # 🔀 توزيع تلقائي: نجد حساباً فيه مقعد فارغ (من كل الحسابات)
    _avail_acc = _cgpt_find_available_account()
    if _avail_acc:
        mgr = _avail_acc['mgr']
    else:
        # لا حساب متاح → نرد المال
        db.users.update_one({'user_id': buyer_uid}, {'$inc': {'balance': price}})
        _invalidate_user_cache(buyer_uid)
        # نمسح الـ cache ليعيد الحساب
        _cgpt_stock_invalidate()
        bot.send_message(buyer_uid,
            (get_text(buyer_uid, 'cg_notice_15')))
        return
    mgr._last_buyer_uid = buyer_uid
    result = mgr.invite_user(email, minutes)
    days = round(minutes / 1440, 1)

    if result['ok']:
        _cgpt_stock_invalidate()  # نمسح cache المقاعd (نقص مقعd)
        expires_iso = result['expires_at']
        db.orders.insert_one({
            'user_id': buyer_uid, 'product_id': f"cgpt_{pending['cgpt_pid']}",
            'code_delivered': f"chatgpt_seat:{email}",
            'qty': 1, 'total_price': price, **_order_extra(order_id), **_order_cost(f"cgpt_{pending['cgpt_pid']}", 1),
            'cgpt_email': email, 'cgpt_expires_at': expires_iso, 'cgpt_minutes': minutes
        })
        _cgpt_queue_admin_purchase(buyer_uid, email, label, price, order_id, expires_iso)
        u_data = get_user_data_full(buyer_uid) or {}
        buyer_m = f"@{u_data.get('username')}" if u_data and u_data.get('username') else str(buyer_uid)
        if lang == 'ar':
            success = (
                f"✅ <b>تم إرسال الدعوة بنجاح!</b>\n\n"
                f"📧 <b>الإيميل:</b> <code>{email}</code>\n"
                f"⏱ <b>المدة:</b> {label}\n"
                f"📅 <b>ينتهي في:</b> {expires_iso[:10]}\n\n"
                f"<i>تفقد بريدك الإلكتروني وقبل الدعوة 🎉</i>\n\n"
                f"🔎 لعرض اشتراكاتك والتجديد اكتب: /my_chatgpt"
            )
        else:
            success = (
                f"✅ <b>Invite sent!</b>\n\n"
                f"📧 <b>Email:</b> <code>{email}</code>\n"
                f"⏱ <b>Duration:</b> {label}\n"
                f"📅 <b>Expires:</b> {expires_iso[:10]}\n\n"
                f"<i>Check your inbox and accept the invite 🎉</i>\n\n"
                f"🔎 To view your subscriptions & renew, type: /my_chatgpt"
            )

        # Apply Business customization through the existing bilingual text system.
        success = get_text(buyer_uid, 'cg_success', html.escape(email), html.escape(label), expires_iso, format(price, '.2f'), html.escape(str(pending['order_id']))) or success
        try:
            bot.send_message(buyer_uid, success, parse_mode="HTML", reply_markup=order_copy_markup(pending.get('order_id') or '', lang))
        except Exception:
            logger.exception("Business buyer receipt failed; continuing admin receipt")

        # 📢 لوق القناة لشراء ChatGPT Duration/Package
        try:
            log_ch = get_setting('log_channel')
            if log_ch and log_ch != "Not Set":
                obs_user = obscure_text(u_data.get('username') or str(buyer_uid))
                p_name_clean = clean_name(p_name)
                product_display = f"ChatGPT Plus ({html.escape(str(label))})" if p_name_clean == "Plus" else f"{p_name_clean} ({html.escape(str(label))})"
                product_name_log = f"🤖 <b>{product_display}</b>"
                pub_msg = LANG['en']['log_purchase'].format(obs_user, product_name_log, 1)
                custom_pub = db.custom_texts.find_one({'lang': 'en', 'key': 'log_purchase'})
                if custom_pub and custom_pub.get('value'):
                    try: pub_msg = custom_pub['value'].format(obs_user, product_name_log, 1)
                    except: pass
                bot.send_message(log_ch, _log_src(pub_msg), parse_mode="HTML")
        except Exception as log_err:
            logger.debug(f"Log channel error for cgpt package: {log_err}")
    else:
        db.users.update_one({'user_id': buyer_uid}, {'$inc': {'balance': price}})
        bot.send_message(buyer_uid,
            get_text(buyer_uid, 'cg_invite_failed', html.escape(str(result.get('error', 'unknown')))),
            parse_mode="HTML")

def _cgpt_handle_email(message, buyer_uid, lang):
    text_cmd = (message.text or "").strip().lower()
    if text_cmd in ['الغاء', 'cancel', '/cancel']:
        _cancel_cgpt_purchase(buyer_uid, lang)
        return
    pending = _cgpt_take_pending(buyer_uid)
    if not pending:
        bot.send_message(buyer_uid, "\u274c \u0627\u0646\u062a\u0647\u062a \u0635\u0644\u0627\u062d\u064a\u0629 \u0627\u0644\u0637\u0644\u0628. \u062a\u0648\u0627\u0635\u0644 \u0645\u0639 \u0627\u0644\u062f\u0639\u0645.", parse_mode="HTML")
        return
    import re as _re_email
    email = (message.text or "").strip().lower()
    if not _re_email.match(r'^[^@\s]+@[^@\s]+\.[^@\s]+$', email):
        db.users.update_one({'user_id': buyer_uid}, {'$inc': {'balance': pending['total_price']}})
        bot.send_message(buyer_uid,
            f"\u274c <b>\u0625\u064a\u0645\u064a\u0644 \u063a\u064a\u0631 \u0635\u062d\u064a\u062d. \u062a\u0645 \u0625\u0631\u062c\u0627\u0639 \u0631\u0635\u064a\u062f\u0643.</b>\n"
            f"\u0627\u0644\u0631\u0635\u064a\u062f \u0627\u0644\u0645\u064f\u0631\u062c\u0639: <b>${pending['total_price']:.2f}</b>",
            parse_mode="HTML")
        return
    bot.send_message(buyer_uid, "\u23f3 <b>\u062c\u0627\u0631\u064a \u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u062f\u0639\u0648\u0629...</b>", parse_mode="HTML")
