@safe_next_step
def process_stars_amount(message, lang):
    uid = message.from_user.id
    if not message.text:
        return
    
    text = message.text.strip()
    
    # 🛡 رفض الأوامر
    if text.startswith('/'):
        return
    
    # رفض الإلغاء
    if text.lower() in ['الغاء', 'cancel', 'إلغاء']:
        bot.send_message(uid, bil(uid, "❌ تم الإلغاء.", "❌ Cancelled."))
        return
    
    try:
        usd_amount = float(text.replace(',', '.').replace('$', ''))
    except ValueError:
        err = "❌ الرجاء إرسال أرقام فقط (مثال: 5 أو 10.5)." if lang == 'ar' else "❌ Please send numbers only (e.g., 5 or 10.5)."
        bot.send_message(uid, err, parse_mode="HTML")
        return
    
    # 🛡 validation
    if usd_amount < 0.1:
        err = "❌ الحد الأدنى للشحن هو $0.10" if lang == 'ar' else "❌ Minimum deposit is $0.10"
        bot.send_message(uid, err, parse_mode="HTML")
        return
    
    if usd_amount > 1000:
        err = "❌ الحد الأقصى للشحن هو $1000" if lang == 'ar' else "❌ Maximum deposit is $1000"
        bot.send_message(uid, err, parse_mode="HTML")
        return
        
    stars_amount = int(usd_amount * STARS_RATE)
    
    # 🛡 stars_amount يجب يكون >= 1 (Telegram يرفض 0)
    if stars_amount < 1:
        err = "❌ المبلغ صغير جداً. زده قليلاً." if lang == 'ar' else "❌ Amount too small. Please increase."
        bot.send_message(uid, err, parse_mode="HTML")
        return
    
    title = "شحن رصيد المتجر" if lang == 'ar' else "Shop Balance Deposit"
    desc = f"شحن حساب بمبلغ ${usd_amount:.2f}" if lang == 'ar' else f"Deposit ${usd_amount:.2f} to your account"
    prices = [LabeledPrice(label=f"Deposit ${usd_amount:.2f}", amount=stars_amount)]
    
    try:
        bot.send_invoice(
            chat_id=uid,
            title=title,
            description=desc,
            invoice_payload=f"dep_{uid}_{usd_amount}",
            provider_token="",
            currency="XTR",
            prices=prices
        )
    except Exception as e:
        err_str = str(e).lower()
        if 'currency_total_amount_invalid' in err_str:
            msg = (
                "❌ <b>المبلغ غير صحيح!</b>\n\n"
                "💡 جرّب مبلغ أكبر أو تحقق من معدل التحويل."
            ) if lang == 'ar' else (
                "❌ <b>Invalid amount!</b>\n\n"
                "💡 Try a larger amount or check the conversion rate."
            )
        else:
            msg = (
                "❌ <b>حدث خطأ في إنشاء فاتورة الدفع.</b>\n\n"
                "💡 حاول مرة ثانية بعد قليل."
            ) if lang == 'ar' else (
                "❌ <b>Error creating invoice.</b>\n\n"
                "💡 Please try again later."
            )
        bot.send_message(uid, msg, parse_mode="HTML")
        logger.error(f"send_invoice error for user {uid}: {e}")

@bot.pre_checkout_query_handler(func=lambda query: True)
def checkout(pre_checkout_query):
    ok, why = True, None
    try:
        payload = str(pre_checkout_query.invoice_payload or '')
        if is_user_banned(pre_checkout_query.from_user.id):
            ok, why = False, 'Account unavailable'
        elif payload.startswith('dep_'):
            amt = float(payload.split('_')[2])
            if not (0.1 <= amt <= 10000) or str(pre_checkout_query.currency or '') != 'XTR':
                ok, why = False, 'Invalid invoice'
        else:
            ok, why = False, 'Unknown invoice'
    except Exception:
        ok, why = False, 'Invalid invoice'
    try:
        if ok:
            bot.answer_pre_checkout_query(pre_checkout_query.id, ok=True)
        else:
            bot.answer_pre_checkout_query(pre_checkout_query.id, ok=False, error_message=why)
    except Exception as e:
        logger.warning(f"pre_checkout answer failed: {e}")

@bot.message_handler(content_types=['successful_payment'])
def got_payment(message):
    uid = message.from_user.id
    pay_info = message.successful_payment
    payload = pay_info.invoice_payload

    if payload.startswith("dep_"):
        parts = payload.split('_')
        usd_amount = float(parts[2])
        tx_id = pay_info.telegram_payment_charge_id
        l = get_lang(uid)
        _LOG_SRC.v = 'webapp' if payload.endswith('_wa') else 'bot'
        try:
            credit_user(uid, usd_amount, tx_id, l, "Telegram Stars ⭐️", trusted_txid=True)
        finally:
            _LOG_SRC.v = None

# ============================================================
# ⚠️ تنبيه المبلغ الدقيق — لكل طرق الدفع عدا نجوم تيليجرام
# ============================================================
def _needs_exact_warning(uid, dest):
    """هل نعرض تنبيه المبلغ الدقيق؟ (كل الطرق التي تعتمد المبلغ الفريد).
    النجوم مستثناة لأنها لا تعتمد على مبلغ فريد."""
    try:
        if is_user_banned(uid):
            return False
        # فقط عند تفعيل حماية المبلغ الفريد (وإلا لا معنى للتحذير)
        if not is_amount_protection_enabled():
            return False
    except Exception:
        pass
    return True


def _show_exact_amount_warning(call, dest):
    """يعرض نافذة منبثقة إجبارية + رسالة تحذير مع زر (موافق) قبل المتابعة.
    dest: الوجهة بعد الموافقة (binance / crypto_USDT / crypto_TON / ...)."""
    uid = call.from_user.id
    try:
        bot.answer_callback_query(uid_call_id(call), get_text(uid, 'pay_alert_popup'),
                                  show_alert=True)
    except Exception:
        try:
            bot.answer_callback_query(call.id, get_text(uid, 'pay_alert_popup'), show_alert=True)
        except Exception:
            pass

    # نص التحذير الأساسي + فقرة الرسوم المناسبة للشبكة
    warn = get_text(uid, 'pay_warn_exact')
    fee_note = _fee_note_for_dest(uid, dest)
    if fee_note:
        warn = warn + "\n\n" + fee_note

    markup = InlineKeyboardMarkup(row_width=1)
    markup.add(_make_btn(get_text(uid, 'bybit_btn_understood'),
                         callback_data=f"pay_go_{dest}"))
    markup.add(_make_btn(get_text(uid, 'dep_btn_cancel'), callback_data="cancel_deposit"))
    bot.send_message(uid, warn, parse_mode="HTML", reply_markup=markup)


def _fee_note_for_dest(uid, dest):
    """فقرة تنبيه الرسوم حسب الوجهة/الشبكة.
    الرسوم مسؤولية المستخدم: يضيفها فوق المبلغ ليصلنا المبلغ المطلوب كاملاً."""
    d = str(dest).upper()
    # شبكات BEP20 (رسوم المنصة أعلى نسبياً)
    if 'BEP20' in d or dest == 'binance':
        return get_text(uid, 'pay_fee_bep20')
    # شبكات أخرى (رسوم بسيطة لكن ننبّه عموماً)
    if 'TON' in d or 'LTC' in d or 'USDT' in d:
        return get_text(uid, 'pay_fee_general')
    return get_text(uid, 'pay_fee_general')


def uid_call_id(call):
    return call.id


@bot.callback_query_handler(func=lambda call: call.data.startswith("pay_go_"))
def pay_exact_confirm(call):
    """بعد تأكيد قراءة تنبيه المبلغ → نوجّه للطريقة الأصلية."""
    uid = call.from_user.id
    if is_user_banned(uid):
        bot.answer_callback_query(call.id)
        return
    dest = call.data.replace("pay_go_", "")

    # نُنشئ نداءً وهمياً بنفس المستخدم لكن ببيانات الوجهة الأصلية
    class _C:
        pass
    c = _C()
    c.id = call.id
    c.from_user = call.from_user
    c.message = call.message

    if dest == 'binance':
        c.data = "dep_binance"
        _dep_binance_real(c)
    elif dest.startswith('crypto_'):
        c.data = "dep_" + dest   # dep_crypto_USDT ...
        _dep_crypto_real(c)
    else:
        bot.answer_callback_query(call.id)


@bot.callback_query_handler(func=lambda call: call.data == "dep_binance")
def dep_binance_ui(call):
    """Open the Binance amount prompt directly."""
    _dep_binance_real(call)


def _dep_binance_real(call):
    bot.answer_callback_query(call.id)
    uid = call.from_user.id
    if is_user_banned(uid): return
    bot.clear_step_handler_by_chat_id(chat_id=uid)

    # 🔒 قفل مبكر — حتى قبل إدخال المبلغ
    try:
        db.users.update_one(
            {'user_id': uid},
            {'$set': {
                'deposit_locked': True,
                'deposit_lock_expires': int(time.time()) + 30 * 60
            }},
            upsert=True
        )
    except Exception: pass

    # نص قابل للتعديل من admin مع إضافة زر إلغاء عملية الدفع
    msg_text = get_text(uid, 'dep_prompt_amount', 'Binance Pay')
    markup = InlineKeyboardMarkup()
    btn_text = "❌ إلغاء عملية الدفع" if get_lang(uid) == 'ar' else "❌ Cancel Payment"
    markup.add(InlineKeyboardButton(btn_text, callback_data="cancel_deposit"))
    msg = bot.send_message(uid, msg_text, parse_mode="HTML", reply_markup=markup)
    bot.register_next_step_handler(msg, ask_binance_deposit_amount)


@safe_next_step
def ask_binance_deposit_amount(message):
    """يستلم المبلغ ويعطي مبلغ فريد لـ Binance Pay"""
    uid = message.from_user.id
    if is_user_banned(uid): return

    valid_number = False
    base_amount = 0.0
    if message.text and not message.text.startswith('/'):
        try:
            base_amount = float(message.text.strip().replace(',', '.').replace('$', ''))
            valid_number = True
        except ValueError:
            pass

    if not valid_number:
        # إذا كتب إلغاء أو أي نص غير رقمي، نعرض رسالة تنبيه مع الزر ونبقى في نفس الخطوة
        send_payment_lock_warning(uid)
        msg_text = get_text(uid, 'dep_prompt_amount', 'Binance Pay')
        markup = InlineKeyboardMarkup()
        btn_text = "❌ إلغاء عملية الدفع" if get_lang(uid) == 'ar' else "❌ Cancel Payment"
        markup.add(InlineKeyboardButton(btn_text, callback_data="cancel_deposit"))
        msg = bot.send_message(uid, msg_text, parse_mode="HTML", reply_markup=markup)
        bot.register_next_step_handler(msg, ask_binance_deposit_amount)
        return

    if base_amount < 1:
        bot.send_message(uid, get_text(uid, 'dep_err_min'), parse_mode="HTML")
        msg_text = get_text(uid, 'dep_prompt_amount', 'Binance Pay')
        markup = InlineKeyboardMarkup()
        btn_text = "❌ إلغاء عملية الدفع" if get_lang(uid) == 'ar' else "❌ Cancel Payment"
        markup.add(InlineKeyboardButton(btn_text, callback_data="cancel_deposit"))
        msg = bot.send_message(uid, msg_text, parse_mode="HTML", reply_markup=markup)
        bot.register_next_step_handler(msg, ask_binance_deposit_amount)
        return

    if base_amount > 10000:
        bot.send_message(uid, get_text(uid, 'dep_err_max'), parse_mode="HTML")
        msg_text = get_text(uid, 'dep_prompt_amount', 'Binance Pay')
        markup = InlineKeyboardMarkup()
        btn_text = "❌ إلغاء عملية الدفع" if get_lang(uid) == 'ar' else "❌ Cancel Payment"
        markup.add(InlineKeyboardButton(btn_text, callback_data="cancel_deposit"))
        msg = bot.send_message(uid, msg_text, parse_mode="HTML", reply_markup=markup)
        bot.register_next_step_handler(msg, ask_binance_deposit_amount)
        return

    wallet = str(get_setting('wallet_address') or '').strip()
    if not wallet or wallet == 'Not Set':
        markup = InlineKeyboardMarkup()
        markup.add(_make_btn(get_text(uid, 'dep_btn_cancel'), callback_data='cancel_deposit'))
        bot.send_message(uid, get_text(uid, 'dep_err_general'), parse_mode='HTML', reply_markup=markup)
        return

    # نولّد مبلغ فريد بـ 4 خانات عشرية = 9000 احتمال
    unique_amount = generate_unique_amount_for_user(base_amount, uid, 'BINANCE')

    # نسجّل في DB
    pending = register_pending_deposit(uid, base_amount, unique_amount, 'BINANCE')
    if not pending:
        bot.send_message(uid, get_text(uid, 'dep_err_general'), parse_mode="HTML")
        return


    # نص قابل للتعديل من إعدادات الأدمن (key: dep_msg_binance)
    msg_text = get_text(uid, 'dep_msg_binance', f"{unique_amount:.4f}", wallet, uid)

    cancel_markup = InlineKeyboardMarkup(row_width=2)
    # المبلغ وBinance Pay ID معاً؛ آيدي Telegram يبقى للملاحظة فقط.
    cancel_markup.add(
        _deposit_copy_button(uid, 'dep_btn_copy_amount', f"{unique_amount:.4f}"),
        _deposit_copy_button(uid, 'dep_btn_copy_binance_id', wallet)
    )
    cancel_markup.add(_deposit_copy_button(uid, 'dep_btn_copy_id', str(uid)))
    cancel_markup.add(_make_btn(
        get_text(uid, 'dep_btn_check'),
        callback_data=f"binance_check_{uid}"
    ))
    cancel_markup.add(_make_btn(
        get_text(uid, 'dep_btn_cancel'),
        callback_data="cancel_deposit"
    ))
    
    bot.send_message(uid, msg_text, parse_mode="HTML", reply_markup=cancel_markup)
    bot.clear_step_handler_by_chat_id(chat_id=uid)



@bot.callback_query_handler(func=lambda call: call.data.startswith("binance_check_"))
def binance_check_payment(call):
    """يفحص Binance Pay فوراً لما المستخدم يضغط الزر"""
    bot.answer_callback_query(call.id, "⏳ جاري الفحص..." if get_lang(call.from_user.id) == 'ar' else "⏳ Checking...")
    uid = call.from_user.id
    if is_user_banned(uid): return
    l = get_lang(uid)
    
    # نرسل رسالة "جاري الفحص"
    checking_msg = bot.send_message(
        uid,
        bil(uid, "🔍 <b>جاري فحص Binance Pay...</b>\nانتظر ثوانٍ.", "🔍 <b>Checking Binance Pay...</b>\nPlease wait."),
        parse_mode="HTML"
    )
    
    found = False
    try:
        pay_response = execute_binance_call(
            lambda c: c.get_pay_trade_history(),
            max_retries=5
        )
        
        if pay_response:
            pay_history = pay_response.get('data', [])
            uid_str = str(uid)
            current_time_ms = int(time.time() * 1000)
            cutoff_ms = current_time_ms - (24 * 60 * 60 * 1000)
            
            import re as re_module
            
            for tx in pay_history[:50]:
                try:
                    # نجلب الـ Order ID
                    tx_id = str(
                        tx.get('orderId') or tx.get('transactionId') or
                        tx.get('merchantTradeNo') or ''
                    )
                    if not tx_id:
                        continue
                    
                    # نفحص الوقت
                    tx_time = int(tx.get('transactionTime') or tx.get('createTime') or 0)
                    if tx_time and tx_time < cutoff_ms:
                        continue
                    
                    tx_id_norm = normalize_tx_id(tx_id)
                    
                    # لو مستخدم مسبقاً
                    if db.used_transactions.find_one({'transaction_id': tx_id_norm}):
                        continue
                    
                    # المبلغ — نحوّله للدولار حسب العملة (بيتكوين/BNB/... مو دولار!)
                    _raw_amount = float(tx.get('amount') or tx.get('totalFee') or 0)
                    _tx_cur = _binance_tx_currency(tx) or 'USDT'
                    amount, _price_used = binance_amount_to_usd(_raw_amount, _tx_cur)
                    if amount is None or amount <= 0:
                        continue
                    
                    # نقرأ كل الحقول الممكنة للـ remark
                    remark = str(
                        tx.get('remarks') or tx.get('remark') or
                        tx.get('memo') or tx.get('note') or
                        tx.get('orderInfo') or ''
                    ).strip()
                    
                    # نشوف لو الـ uid موجود في الـ remark
                    if uid_str not in remark:
                        continue
                    
                    # تأكيد: الـ uid موجود كرقم في الـ remark
                    if not re_module.search(r'\b' + re_module.escape(uid_str) + r'\b', remark):
                        continue
                    
                    # ✅ وجدنا الحوالة!
                    credit_user(uid, amount, tx_id_norm, l, "Binance Pay")
                    # 🔓 نُغلق الإيداع المعلّق ونفكّ القفل (وإلا يظل "لديك عملية دفع معلقة")
                    close_user_pending_and_unlock(uid, tx_id_norm, via='binance_check_button')
                    found = True
                    
                    try:
                        bot.delete_message(uid, checking_msg.message_id)
                    except: pass
                    break
                    
                except Exception:
                    continue
    
    except Exception as e:
        logger.error(f"binance_check_payment error: {e}")
    
    if not found:
        try:
            bot.edit_message_text(
                bil(uid,
                    "❌ <b>لم نجد حوالة بعد!</b>\n\n"
                    "💡 تأكد من:\n"
                    "• وضع رقمك في الملاحظة بالضبط\n"
                    f"• الرقم: <code>{uid}</code>\n"
                    "• إتمام التحويل بالكامل\n\n"
                    "🔄 حاول مرة ثانية بعد دقيقة.",
                    "❌ <b>No transaction found yet!</b>\n\n"
                    "💡 Make sure:\n"
                    "• Your ID is in the Remark exactly\n"
                    f"• Your ID: <code>{uid}</code>\n"
                    "• Transfer is completed\n\n"
                    "🔄 Try again in a minute."
                ),
                uid, checking_msg.message_id,
                parse_mode="HTML",
                reply_markup=InlineKeyboardMarkup().add(
                    InlineKeyboardButton(
                        "🔄 أعد المحاولة" if l == 'ar' else "🔄 Try Again",
                        callback_data=f"binance_check_{uid}"
                    )
                )
            )
        except: pass

# ============================================================
# 🛡 نظام المبلغ الفريد (يحمي من بوتات النصب اللي تراقب blockchain)
# ============================================================
# الفكرة: المستخدم يكتب المبلغ، البوت يضيف عشر سنتين عشوائيين
# مثلاً: المستخدم يبي $5 → البوت يطلب $5.0023 بالضبط
# هذا يربط الحوالة بالمستخدم بطريقة لا يقدر النصاب يكتشفها
# ============================================================

def generate_unique_amount_for_user(base_amount_usd, uid, coin):
    """
    🛡 يولّد مبلغ فريد عشوائي لكل عملية إيداع.

    ⚠️ مهم: Bybit أحياناً لا تقرأ كل الخانات العشرية عند الإدخال.
    لذا لعملات Bybit نولّد خانتين فقط (مثل 5.01) — قصيرة، سهلة النسخ،
    وتُقرأ بموثوقية على كل واجهات Bybit. المسافة بينها 0.01 تكفي للتمييز.

    أمثلة:
    - Bybit:  $5 → $5.01 / $5.04 / $5.07 (خانتان)
    - غيرها:  $5 → $5.001847 (6 خانات، دقة أعلى للشبكات الأخرى)
    """
    base = float(base_amount_usd)
    is_bybit = str(coin).startswith('BYBIT')

    # عدد الخانات ومسافة الأمان حسب العملة
    if is_bybit:
        decimals = 2
        MIN_SPACING = 0.02     # أكبر من خطوة الخانتين (0.01)
        # الكسور بوحدات 0.01: من 0.01 إلى 0.09 (حد أقصى تسعة سنتات)
        lo, hi, div = 1, 9, 100.0
        lo2, hi2 = 1, 9            # نفس المدى (خانتان محدودتان أصلاً)
    else:
        decimals = 6
        MIN_SPACING = 0.0002
        lo, hi, div = 100, 9999, 1000000.0
        lo2, hi2 = 100, 29999

    def _is_free(amount):
        """يتأكد ما فيه إيداع معلّق قريب من هذا المبلغ (داخل مسافة الأمان).

        🛡 مهم: نفحص عبر كل العملات التي قد تصل لنفس المحفظة (Bybit).
        وإلا: شخص على USDT_BEP20 وآخر على BYBIT_BEP20 قد يأخذان نفس
        المبلغ الفريد، فيصل التحويل ويُطابق مع الشخص الخطأ."""
        try:
            # كل العملات التي تصل فعلياً لنفس محفظة الوجهة
            if str(coin).startswith('BYBIT') or coin in ('USDT', 'USDT_BEP20'):
                check_coins = list(set(
                    ['BYBIT_UID', 'BYBIT_TRC20', 'BYBIT_BEP20', 'USDT', 'USDT_BEP20']
                ))
            else:
                check_coins = [coin]
            clash = db.pending_deposits.find_one({
                'coin': {'$in': check_coins},
                'status': 'pending',
                'expires_at': {'$gt': int(time.time())},
                'unique_amount_usd': {
                    '$gte': amount - MIN_SPACING,
                    '$lte': amount + MIN_SPACING
                }
            })
            return clash is None
        except Exception:
            return False if is_bybit else True

    if is_bybit:
        # Try the cheapest distinct amount first. Never widen the surcharge.
        from decimal import Decimal, ROUND_HALF_UP
        base_decimal = Decimal(str(base_amount_usd))
        for cents in range(1, 10):
            candidate = (base_decimal + Decimal(cents) / 100).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            difference = candidate - base_decimal
            if Decimal('0') < difference <= Decimal('0.09') and _is_free(float(candidate)):
                return float(candidate)
        return None

    # المحاولة 1: المدى الأساسي
    for _ in range(400):
        unique_amount = round(base + random.randint(lo, hi) / div, decimals)
        if _is_free(unique_amount):
            return unique_amount

    # المحاولة 2: مدى أوسع لو ازدحمت الإيداعات بنفس المبلغ
    for _ in range(400):
        unique_amount = round(base + random.randint(lo2, hi2) / div, decimals)
        if _is_free(unique_amount):
            return unique_amount

    # احتياط أخير (نادر جداً)
    return round(base + random.randint(lo, hi2) / div, decimals)


def register_pending_deposit(uid, base_amount_usd, unique_amount_usd, coin, sender_uid=None):
    """
    يسجّل عملية إيداع متوقعة ويقفل المستخدم حتى يكتمل أو يُلغى.
    sender_uid: (اختياري) رقم UID المرسِل في Bybit — للمطابقة المزدوجة (UID + المبلغ).
    """
    try:
        db.pending_deposits.delete_many({'user_id': uid, 'coin': coin, 'status': 'pending'})
        
        pending_id = f"PD{uid}{int(time.time())}{random.randint(100, 999)}"
        # صلاحية أطول (ساعتان) حتى لو تأخّر المستخدم أو تأخّرت التأكيدات،
        # يبقى الإيداع قابلاً للمطابقة التلقائية. العدّاد المعروض للمستخدم يبقى 30 دقيقة.
        expires = int(time.time()) + (60 * 120)
        record = {
            'pending_id': pending_id,
            'user_id': uid,
            'base_amount_usd': float(base_amount_usd),
            'unique_amount_usd': float(unique_amount_usd),
            'coin': coin,
            'status': 'pending',
            'created_at': int(time.time()),
            'expires_at': expires
        }
        if sender_uid:
            record['sender_uid'] = str(sender_uid).strip()
        db.pending_deposits.insert_one(record)
        
        # 🔒 قفل المستخدم أثناء الإيداع
        db.users.update_one(
            {'user_id': uid},
            {'$set': {
                'deposit_locked': True,
                'deposit_lock_pending_id': pending_id,
                'deposit_lock_expires': expires
            }}
        )
        return record
    except Exception as e:
        logger.error(f"Error registering pending deposit: {e}")
        return None


def unlock_deposit(uid):
    """فك قفل الإيداع عند الاكتمال أو الإلغاء"""
    try:
        db.users.update_one(
            {'user_id': uid},
            {'$unset': {'deposit_locked': '', 'deposit_lock_pending_id': '', 'deposit_lock_expires': ''}}
        )
    except Exception: pass


def is_deposit_locked(uid):
    """هل المستخدم في عملية إيداع جارية؟ (يعتمد على flag + TTL فقط)"""
    try:
        u = db.users.find_one({'user_id': uid}, {'deposit_locked': 1, 'deposit_lock_expires': 1})
        if not u or not u.get('deposit_locked'):
            return False
        # نفحص إن القفل ما انتهت صلاحيته (TTL)
        if u.get('deposit_lock_expires', 0) < int(time.time()):
            unlock_deposit(uid)
            return False
        return True
    except Exception:
        return False


def close_user_pending_and_unlock(uid, tx_id_detected=None, via='payment'):
    """🔓 يُغلق أي إيداع معلّق للمستخدم ويفكّ قفل الإيداع.

    ⚠️ مهم جداً: بدون هذا، المستخدم يُضاف له الرصيد ويشوف "تم إضافة المبلغ"
    لكنه يظل عالقاً في "⚠️ لديك عملية دفع معلقة" وما يقدر يستخدم البوت إطلاقاً
    (لأن deposit_locked يظل مفعّلاً في users).

    وكمان يسدّ ثغرة: الإيداع المعلّق المفتوح يحجز "مبلغ فريد"، فلو ظل مفتوحاً
    ممكن تُطابَق معه حوالة ثانية لاحقاً → إضافة رصيد مرتين لنفس الإيداع.
    """
    try:
        upd = {'status': 'completed', 'completed_at': int(time.time()), 'completed_via': via}
        if tx_id_detected:
            upd['tx_id_detected'] = tx_id_detected
        db.pending_deposits.update_many(
            {'user_id': uid, 'status': 'pending'},
            {'$set': upd}
        )
    except Exception as e:
        logger.debug(f"close_user_pending_and_unlock (pending) err: {e}")
    try:
        unlock_deposit(uid)
    except Exception as e:
        logger.debug(f"close_user_pending_and_unlock (unlock) err: {e}")


_ambiguous_alert_cache = {}

def _alert_ambiguous_deposit(coin, amount_usd, records):
    """🚨 يبلّغ الأدمن عن إيداع غامض (مرة كل ساعة لنفس المبلغ لتفادي التكرار)."""
    try:
        key = f"{coin}:{round(float(amount_usd), 5)}"
        now = int(time.time())
        if now - _ambiguous_alert_cache.get(key, 0) < 3600:
            return
        _ambiguous_alert_cache[key] = now
        ids = ", ".join(
            f"{r.get('user_id')}=${float(r.get('unique_amount_usd', 0)):.6f}" for r in records[:5]
        )
        notify_admins(
            f"⚠️ <b>إيداع غامض — مراجعة يدوية مطلوبة!</b>\n\n"
            f"💳 العملة: <b>{coin}</b>\n"
            f"💰 المبلغ المُستلَم: <b>${float(amount_usd):.6f}</b>\n"
            f"🔀 يطابق أكثر من إيداع معلّق بنفس القرب:\n<code>{ids}</code>\n\n"
            f"🛡 <b>لم يُضَف الرصيد لأحد تلقائياً</b> حمايةً من إعطاء الشخص الخطأ.\n"
            f"راجع وأضف الرصيد يدوياً للشخص الصحيح من «👥 إدارة العملاء ← تعديل رصيده»."
        )
    except Exception:
        pass


def find_pending_allowing_shortfall(amount_usd, coin, up_tol=0.03, down_max=None):
    """يطابق إيداعاً معلّقاً عند نقص ضئيل جداً (رسوم شبكة فقط).

    ⚠️ خطر أمني حقيقي: لو وسّعنا النقص، قد يُنسب تحويل شخصٍ دفع فعلاً إلى
    شخصٍ آخر "جرّب فقط" وله إيداع معلّق بمبلغ قريب. لذا:
    - النقص المسموح ≤ 0.03$ فقط (رسوم نموذجية).
    - حارس 1: مرشّح وحيد ضمن النطاق الضيّق، وإلا رفض.
    - حارس 2: لا يوجد أي إيداع آخر قريب (±0.15$) من الواصل، وإلا رفض.
    - عند أي التباس: لا نعطي أحداً (أأمن من الخطأ).
    """
    try:
        amount_usd = float(amount_usd)
        # 🛡 نفحص عبر كل العملات التي تصل لنفس المحفظة (Bybit)
        if str(coin).startswith('BYBIT') or coin in ('USDT', 'USDT_BEP20'):
            match_coins = ['BYBIT_UID', 'BYBIT_TRC20', 'BYBIT_BEP20', 'USDT', 'USDT_BEP20']
        else:
            match_coins = [coin]
        records = list(db.pending_deposits.find({
            'coin': {'$in': match_coins},
            'status': 'pending',
            'expires_at': {'$gt': int(time.time())}
        }))
        if not records:
            return None

        in_band = []
        for r in records:
            req = float(r.get('unique_amount_usd', 0))
            if req <= 0:
                continue
            # 🛡 نقص ضئيل جداً فقط (رسوم شبكة): 0.03$ كحد أقصى
            #    توسيعه يسبب نسب تحويل شخص دفع إلى شخص "جرّب فقط" بمبلغ قريب.
            dmax = down_max if down_max is not None else 0.03
            if req - dmax <= amount_usd <= req + up_tol:
                in_band.append((abs(req - amount_usd), r))

        if not in_band:
            return None
        # 🛡 حارس 1: أكثر من مرشّح ضمن النطاق → رفض
        if len(in_band) > 1:
            logger.warning(f"[SHORTFALL] {len(in_band)} إيداعات ضمن نطاق ${amount_usd} ({coin}) — رُفض للأمان")
            return None
        # 🛡 حارس 2: أي إيداع آخر قريب (±0.15$) من الواصل → الوضع ملتبس → رفض
        #    يمنع إعطاء تحويل شخصٍ دفع لشخصٍ آخر جرّب بمبلغ مشابه.
        winner = in_band[0][1]
        for r in records:
            if r.get('pending_id') == winner.get('pending_id'):
                continue
            other = float(r.get('unique_amount_usd', 0))
            if abs(other - amount_usd) <= 0.15:
                logger.warning(f"[SHORTFALL] إيداع آخر قريب (${other}) من ${amount_usd} — رُفض للأمان")
                return None
        return winner
    except Exception as e:
        logger.debug(f"find_pending_allowing_shortfall err: {e}")
        return None


def find_pending_deposit_for_amount(amount_usd, coin, tolerance=0.0001):
    """
    🛡 يبحث عن إيداع معلّق مطابق للمبلغ المُستلَم.

    الإصلاح المهم:
    - يطابق على الإيداع **الأقرب** لقيمة المبلغ المُستلَم بالضبط (مو الأقدم!).
    - لو فيه إيداعان بنفس القرب تماماً (غموض) → ما يرجّع أحد + يبلّغ الأدمن
      (أأمن من إعطاء الشخص الخطأ).
    """
    try:
        amount_usd = float(amount_usd)
        # 🛡 نفحص الغموض عبر كل العملات التي تصل لنفس المحفظة (Bybit)
        if str(coin).startswith('BYBIT') or coin in ('USDT', 'USDT_BEP20'):
            match_coins = ['BYBIT_UID', 'BYBIT_TRC20', 'BYBIT_BEP20', 'USDT', 'USDT_BEP20']
        else:
            match_coins = [coin]
        records = list(db.pending_deposits.find({
            'coin': {'$in': match_coins},
            'status': 'pending',
            'unique_amount_usd': {
                '$gte': amount_usd - tolerance,
                '$lte': amount_usd + tolerance
            },
            'expires_at': {'$gt': int(time.time())}
        }))

        if not records:
            return None
        if len(records) == 1:
            return records[0]

        # 🛡 أكثر من إيداع داخل النطاق — نرتّب بالأقرب للمبلغ بالضبط (مو الأقدم)
        records.sort(key=lambda r: (
            abs(float(r.get('unique_amount_usd', 0)) - amount_usd),
            r.get('created_at', 0)
        ))
        closest, second = records[0], records[1]
        d1 = abs(float(closest.get('unique_amount_usd', 0)) - amount_usd)
        d2 = abs(float(second.get('unique_amount_usd', 0)) - amount_usd)

        # لو الأقرب أوضح من الثاني بفارق كافٍ → هو الصحيح (آمن نعطيه)
        if (d2 - d1) >= 0.00005:
            return closest

        # 🚨 غموض حقيقي: إيداعان متساويان في القرب — نوقف ونبلّغ الأدمن، ما نخاطر
        _alert_ambiguous_deposit(coin, amount_usd, records)
        return None
    except Exception as e:
        logger.error(f"Error finding pending deposit: {e}")
        return None


# ============================================================
# 🤖 نظام Auto-Detect: يفحص blockchain تلقائياً ويضيف الرصيد
# ============================================================

def auto_credit_from_pending(pending, tx_id_for_record, method_label, actual_usd=None):
    """
    يضيف رصيد للمستخدم تلقائياً من pending deposit (بدون ما يرسل tx_id).

    actual_usd: (اختياري) المبلغ الفعلي الذي وصل بالدولار.
      لو المستخدم حوّل أقل من المطلوب، نضيف له الواصل فعلاً — لا المطلوب.
      لو حوّل أكثر، نضيف الواصل أيضاً (يستفيد المستخدم).
    """
    try:
        uid = pending['user_id']
        requested_amount = float(pending.get('base_amount_usd', 0))
        unique_amount = float(pending.get('unique_amount_usd', 0))
        pending_id = pending.get('pending_id', '')

        # 💵 المبلغ الذي سيُضاف = الواصل فعلاً إن توفّر، وإلا المطلوب
        if actual_usd is not None and float(actual_usd) > 0:
            base_amount = round(float(actual_usd), 2)
        else:
            base_amount = requested_amount
        # هل الواصل يختلف عن المطلوب؟ (لإخبار المستخدم)
        shortfall = (actual_usd is not None and round(float(actual_usd), 2) < requested_amount - 0.01)

        # نعلم الـ pending كـ completed
        result = db.pending_deposits.update_one(
            {'pending_id': pending_id, 'status': 'pending'},
            {'$set': {'status': 'completed', 'completed_at': int(time.time()),
                      'tx_id_detected': tx_id_for_record,
                      'credited_usd': base_amount}}
        )
        
        if result.modified_count == 0:
            return False
        
        # 🔓 فك قفل الإيداع
        unlock_deposit(uid)
        
        # 🎉 رسالة تأكيد للمستخدم قبل ما نضيف الرصيد
        try:
            lang = get_lang(uid)
            # نعرض الـ tx_id مختصراً
            tx_short = tx_id_for_record[:20] + "..." if len(tx_id_for_record) > 20 else tx_id_for_record
            # سطر تنبيه لو وصل أقل من المطلوب
            note_ar = (f"\n⚠️ <i>وصل مبلغ أقل من المطلوب (${requested_amount:.2f})، "
                       f"أُضيف لك الواصل فعلاً.</i>\n") if shortfall else ""
            note_en = (f"\n⚠️ <i>Less than requested (${requested_amount:.2f}) arrived; "
                       f"we credited the actual amount received.</i>\n") if shortfall else ""
            if lang == 'ar':
                msg = (
                    f"✅ <b>تم استلام إيداعك تلقائياً!</b> 🎉\n\n"
                    f"━━━━━━━━━━━━━━\n"
                    f"💰 <b>المبلغ المُضاف:</b> <b>${base_amount:.2f}</b>\n"
                    f"{note_ar}"
                    f"💳 <b>الطريقة:</b> {method_label}\n"
                    f"🆔 <b>رقم العملية:</b>\n<code>{tx_id_for_record}</code>\n"
                    f"━━━━━━━━━━━━━━\n\n"
                    f"💼 <i>تم إضافة الرصيد لحسابك.</i>"
                )
            else:
                msg = (
                    f"✅ <b>Deposit auto-detected!</b> 🎉\n\n"
                    f"━━━━━━━━━━━━━━\n"
                    f"💰 <b>Amount credited:</b> <b>${base_amount:.2f}</b>\n"
                    f"{note_en}"
                    f"💳 <b>Method:</b> {method_label}\n"
                    f"🆔 <b>Transaction ID:</b>\n<code>{tx_id_for_record}</code>\n"
                    f"━━━━━━━━━━━━━━\n\n"
                    f"💼 <i>Balance added to your account.</i>"
                )
            bot.send_message(uid, msg, parse_mode="HTML")
        except Exception: pass
        
        # نضيف الرصيد
        # trusted_txid=True: هذا المسار يأتي من فحص تلقائي بـ tx_id فريد
        # (Bybit txID / hash بلوكشين) — نتخطّى فحص المبلغ+الوقت التقريبي
        # الذي كان يرفض إيداعات صحيحة بنفس المبلغ في نفس الدقيقة ويحظر أصحابها.
        credit_user(uid, base_amount, tx_id_for_record, get_lang(uid), method_label, trusted_txid=True)
        return True
    except Exception as e:
        logger.error(f"Error in auto_credit: {e}")
        return False


def check_ltc_blockchain_auto():
    """
    🔍 يفحص LTC blockchain ويلقى الحوالات اللي وصلت
    ويربطها بـ pending_deposits تلقائياً.
    """
    try:
        wallet_address = get_setting('ltc_address')
        if not wallet_address or wallet_address == "Not Set":
            return
        
        # نجيب الـ pending deposits لـ LTC
        pending_count = db.pending_deposits.count_documents({
            'coin': 'LTC',
            'status': 'pending',
            'expires_at': {'$gt': int(time.time())}
        })
        if pending_count == 0:
            return  # ما فيه pending - نوفر الـ API calls
        
        # نجيب آخر transactions من litecoinspace
        url = f"https://litecoinspace.org/api/address/{wallet_address}/txs"
        try:
            res = requests.get(url, timeout=10)
            if res.status_code != 200:
                return
            txs = res.json()
        except Exception:
            return
        
        # نجيب سعر LTC
        ltc_price = get_ltc_price_usd()
        if not ltc_price or ltc_price < 10:
            return
        
        current_time_ms = int(time.time() * 1000)
        cutoff_time_ms = current_time_ms - (45 * 60 * 1000)  # آخر 45 دقيقة
        
        for tx in txs[:30]:  # آخر 30 معاملة فقط
            try:
                tx_id = tx.get('txid', '')
                if not tx_id:
                    continue
                
                # شيك التاريخ - نتجاهل المعاملات القديمة
                tx_time = (tx.get('status', {}).get('block_time', 0) or 0) * 1000
                if tx_time and tx_time < cutoff_time_ms:
                    continue
                
                tx_id_normalized = normalize_tx_id(tx_id)
                
                # شيك إن المعاملة ما تم معالجتها
                if db.used_transactions.find_one({'transaction_id': tx_id_normalized}):
                    continue
                
                # نحسب الـ amount المُستلم
                received_ltc = 0.0
                for vout in tx.get('vout', []):
                    if vout.get('scriptpubkey_address') == wallet_address:
                        received_ltc += vout.get('value', 0) / 100000000  # satoshi → LTC
                
                if received_ltc <= 0:
                    continue
                
                usd_amount = round(received_ltc * ltc_price, 6)
                
                # نشوف لو في pending مطابق
                pending = find_pending_deposit_for_amount(usd_amount, 'LTC', tolerance=0.001)
                if pending:
                    success = auto_credit_from_pending(pending, tx_id_normalized, "Litecoin (LTC) Auto")
                    if success:
                        logger.info(f"✅ AUTO-CREDITED LTC: user {pending['user_id']} → ${pending['base_amount_usd']:.2f} (tx: {tx_id[:16]})")
            except Exception as tx_err:
                logger.debug(f"Skip tx: {tx_err}")
                continue
    except Exception as e:
        logger.error(f"check_ltc_blockchain_auto error: {e}")


def check_ton_blockchain_auto():
    """🔍 يفحص TON blockchain تلقائياً"""
    try:
        wallet_address = get_setting('ton_address')
        if not wallet_address or wallet_address == "Not Set":
            return
        
        pending_count = db.pending_deposits.count_documents({
            'coin': 'TON',
            'status': 'pending',
            'expires_at': {'$gt': int(time.time())}
        })
        if pending_count == 0:
            return
        
        # TONCenter API
        url = f"https://toncenter.com/api/v2/getTransactions?address={wallet_address}&limit=30"
        try:
            res = requests.get(url, timeout=10)
            if res.status_code != 200:
                return
            data = res.json()
            if not data.get('ok'):
                return
            txs = data.get('result', [])
        except Exception:
            return
        
        ton_price = get_ton_price_usd()
        if not ton_price or ton_price < 0.5:
            return
        
        current_time = int(time.time())
        cutoff_time = current_time - (45 * 60)  # 45 دقيقة
        
        for tx in txs:
            try:
                tx_hash = tx.get('transaction_id', {}).get('hash', '')
                if not tx_hash:
                    continue
                
                tx_time = tx.get('utime', 0)
                if tx_time and tx_time < cutoff_time:
                    continue
                
                tx_id_normalized = normalize_tx_id(tx_hash)
                
                if db.used_transactions.find_one({'transaction_id': tx_id_normalized}):
                    continue
                
                # نحسب الـ TON المُستلم
                in_msg = tx.get('in_msg', {})
                value_nanoton = int(in_msg.get('value', 0))
                if value_nanoton <= 0:
                    continue
                
                received_ton = value_nanoton / 1_000_000_000
                usd_amount = round(received_ton * ton_price, 6)
                
                # نشوف pending مطابق
                pending = find_pending_deposit_for_amount(usd_amount, 'TON', tolerance=0.001)
                if pending:
                    success = auto_credit_from_pending(pending, tx_id_normalized, "Toncoin (TON) Auto")
                    if success:
                        logger.info(f"✅ AUTO-CREDITED TON: user {pending['user_id']} → ${pending['base_amount_usd']:.2f} (tx: {tx_hash[:16]})")
            except Exception as tx_err:
                logger.debug(f"Skip TON tx: {tx_err}")
                continue
    except Exception as e:
        logger.error(f"check_ton_blockchain_auto error: {e}")


# ============================================================
# 🔗 التحقق المباشر من USDT على البلوكشين (Trust Wallet — بلا منصة)
# ============================================================
# العقود الرسمية لـ USDT (الحماية من التوكنات المزيفة: نقبل هذا العقد فقط)
USDT_CONTRACT_TRC20 = 'TR7NHqjeKQxGTCi8q8ZY4pL8otSzgjLj6t'
USDT_CONTRACT_BEP20 = '0x55d398326f99059ff775485246999027b3197955'


def _http_post_json(url, payload, timeout=10):
    """طلب POST (JSON-RPC) يرجّع JSON، مباشرةً ثم عبر البروكسيات."""
    try:
        r = requests.post(url, json=payload, timeout=timeout)
        if r.status_code == 200:
            return r.json()
    except Exception:
        pass
    try:
        pool = list(VERIFIED_PROXIES)[:4]
        random.shuffle(pool)
        for proxy in pool:
            try:
                r = requests.post(url, json=payload, timeout=8,
                                  proxies={'http': proxy, 'https': proxy})
                if r.status_code == 200:
                    return r.json()
            except Exception:
                continue
    except Exception:
        pass
    return None


# عقد RPC عامة لـ BSC (بلا مفتاح — مثل مستكشفات TON/LTC)
BSC_PUBLIC_RPCS = [
    "https://bsc-dataseed.bnbchain.org",
    "https://bsc-dataseed1.defibit.io",
    "https://bsc-dataseed1.ninicoin.io",
    "https://bsc.publicnode.com",
    "https://binance.llamarpc.com",
]


def _bsc_rpc_call(method, params):
    """ينادي BSC RPC عام (يجرّب عدة عقد) — بلا مفتاح."""
    payload = {"jsonrpc": "2.0", "id": 1, "method": method, "params": params}
    nodes = list(BSC_PUBLIC_RPCS)
    random.shuffle(nodes)
    for node in nodes:
        res = _http_post_json(node, payload, timeout=8)
        if res and 'result' in res and res['result'] is not None:
            return res['result']
    return None


def _lookup_bep20_via_rpc(txid):
    """يستعلم عن معاملة USDT على BSC بهاشها عبر RPC العام (بلا مفتاح).
    يرجّع dict فيه (amount, to, time_ms) أو None، أو {'_conn_fail': True}."""
    txid = str(txid).strip()
    if not txid.startswith('0x'):
        txid = '0x' + txid
    receipt = _bsc_rpc_call("eth_getTransactionReceipt", [txid])
    if receipt is None:
        return {'_conn_fail': True}
    try:
        if str(receipt.get('status', '0x1')).lower() == '0x0':
            return None
        # نجلب وقت البلوك
        time_ms = 0
        blk = receipt.get('blockNumber')
        if blk:
            binfo = _bsc_rpc_call("eth_getBlockByNumber", [blk, False])
            if binfo and binfo.get('timestamp'):
                try:
                    time_ms = int(binfo['timestamp'], 16) * 1000
                except Exception:
                    time_ms = 0
        logs = receipt.get('logs', [])
        TRANSFER_SIG = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef'
        for log in logs:
            if str(log.get('address', '')).lower() != USDT_CONTRACT_BEP20.lower():
                continue
            topics = log.get('topics', [])
            if not topics or str(topics[0]).lower() != TRANSFER_SIG:
                continue
            from_addr = '0x' + topics[1][-40:] if len(topics) >= 2 else ''
            to_addr = '0x' + topics[2][-40:] if len(topics) >= 3 else ''
            amount = int(log.get('data', '0x0'), 16) / (10 ** 18)
            return {'amount': round(amount, 6), 'to': to_addr,
                    'from': from_addr, 'time_ms': time_ms, 'confirmed': True}
    except Exception as e:
        logger.debug(f"bsc rpc lookup parse err: {e}")
    return None


def _http_json(url, params=None, headers=None, timeout=10):
    """طلب GET يرجّع JSON، مباشرةً ثم عبر البروكسيات."""
    try:
        r = requests.get(url, params=params, headers=headers or {}, timeout=timeout)
        if r.status_code == 200:
            return r.json()
    except Exception:
        pass
    try:
        pool = list(VERIFIED_PROXIES)[:4]
        random.shuffle(pool)
        for proxy in pool:
            try:
                r = requests.get(url, params=params, headers=headers or {}, timeout=8,
                                 proxies={'http': proxy, 'https': proxy})
                if r.status_code == 200:
                    return r.json()
            except Exception:
                continue
    except Exception:
        pass
    return None


def _fetch_trc20_usdt_deposits(address, limit=30):
    """يجلب تحويلات USDT (TRC20) الواردة لعنوان عبر TronGrid."""
    out = []
    url = f"https://api.trongrid.io/v1/accounts/{address}/transactions/trc20"
    data = _http_json(url, params={'limit': limit, 'contract_address': USDT_CONTRACT_TRC20,
                                   'only_confirmed': 'true'})
    if not data or 'data' not in data:
        return out
    for tx in data['data']:
        try:
            token = (tx.get('token_info') or {}).get('address', '')
            if token.lower() != USDT_CONTRACT_TRC20.lower():
                continue  # 🛡 عقد غير رسمي (توكن مزيف) → رفض
            if str(tx.get('to', '')).lower() != address.lower():
                continue  # وارد فقط
            # 🛡 ضد Flash USDT: نقبل المؤكّد الناجح فقط
            #    (only_confirmed في الطلب + فحص أي حقل حالة متاح)
            _st = str(tx.get('type', 'Transfer'))
            if _st and _st.lower() not in ('transfer', ''):
                continue
            raw = int(tx.get('value', 0))
            decimals = int((tx.get('token_info') or {}).get('decimals', 6))
            amount = raw / (10 ** decimals)
            tx_id = str(tx.get('transaction_id', ''))
            t_ms = int(tx.get('block_timestamp', 0))
            if tx_id and amount > 0:
                out.append((tx_id, round(amount, 6), t_ms))
        except Exception:
            continue
    return out


def _fetch_bep20_via_rpc(address, blocks_back=2400):
    """يجلب تحويلات USDT الواردة لعنوان عبر RPC العام (بلا مفتاح) باستخدام eth_getLogs.
    blocks_back: كم بلوك للخلف نمسح (2400 ≈ ساعتان على BSC بـ 3ث/بلوك).

    مهم: عقد RPC العامة تحدّ نطاق eth_getLogs (غالباً ≤5000 بلوك)، فنمسح
    على دفعات صغيرة (1000 بلوك) لتجنّب الفشل الصامت."""
    out = []
    latest_hex = _bsc_rpc_call("eth_blockNumber", [])
    if not latest_hex:
        return out
    try:
        latest = int(latest_hex, 16)
    except Exception:
        return out

    addr_clean = address.lower().replace('0x', '')
    to_topic = '0x' + '0' * 24 + addr_clean
    TRANSFER_SIG = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef'

    CHUNK = 1000
    start = max(0, latest - blocks_back)
    seen = set()
    b = start
    while b <= latest:
        end = min(b + CHUNK - 1, latest)
        params = [{
            'fromBlock': hex(b),
            'toBlock': hex(end),
            'address': USDT_CONTRACT_BEP20,
            'topics': [TRANSFER_SIG, None, to_topic],
        }]
        logs = _bsc_rpc_call("eth_getLogs", params)
        if isinstance(logs, list):
            for log in logs:
                try:
                    tx_id = str(log.get('transactionHash', ''))
                    if not tx_id or tx_id in seen:
                        continue
                    seen.add(tx_id)
                    amount = int(log.get('data', '0x0'), 16) / (10 ** 18)
                    if amount > 0:
                        out.append((tx_id, round(amount, 6), 0))
                except Exception:
                    continue
        b = end + 1
    return out


def _fetch_bep20_usdt_deposits(address, limit=30):
    """يجلب تحويلات USDT (BEP20) الواردة لعنوان.
    يجرّب RPC العام أولاً (بلا مفتاح — أثبت نجاحه)، ثم Etherscan V2 كبديل."""
    # 1️⃣ RPC العام (بلا مفتاح) — يراقب العنوان مباشرة مثل LTC
    try:
        rpc_out = _fetch_bep20_via_rpc(address)
        if rpc_out:
            return rpc_out
    except Exception as e:
        logger.debug(f"bep20 rpc fetch err: {e}")

    # 2️⃣ Etherscan V2 (بمفتاح) — بديل
    out = []
    api_key = get_setting('bscscan_api_key', '') or os.getenv('BSCSCAN_API_KEY', '')
    if api_key:
        url = "https://api.etherscan.io/v2/api"
        params = {
            'chainid': 56, 'module': 'account', 'action': 'tokentx',
            'contractaddress': USDT_CONTRACT_BEP20,
            'address': address, 'page': 1, 'offset': limit, 'sort': 'desc',
        }
        params['apikey'] = api_key
        data = _http_json(url, params=params)
        if data and data.get('status') == '1' and isinstance(data.get('result'), list):
            for tx in data['result']:
                try:
                    if str(tx.get('contractAddress', '')).lower() != USDT_CONTRACT_BEP20.lower():
                        continue
                    if str(tx.get('to', '')).lower() != address.lower():
                        continue
                    try:
                        confs = int(tx.get('confirmations', 0))
                        if confs < 15:
                            continue
                    except Exception:
                        continue
                    decimals = int(tx.get('tokenDecimal', 18))
                    amount = int(tx.get('value', 0)) / (10 ** decimals)
                    tx_id = str(tx.get('hash', ''))
                    t_ms = int(tx.get('timeStamp', 0)) * 1000
                    if tx_id and amount > 0:
                        out.append((tx_id, round(amount, 6), t_ms))
                except Exception:
                    continue
    return out


def check_usdt_blockchain_auto():
    """🔗 يفحص USDT (TRC20 + BEP20) مباشرةً من البلوكشين (Trust Wallet).
    يتحقق من العقد الرسمي فقط — يرفض التوكنات المزيفة."""
    try:
        now = int(time.time())
        if db.pending_deposits.count_documents({
            'coin': {'$in': ['USDT', 'USDT_BEP20']},
            'status': 'pending', 'expires_at': {'$gt': now}
        }) == 0:
            return

        cutoff_ms = int(time.time() * 1000) - (90 * 60 * 1000)

        # ── TRC20 عبر TronGrid ──
        addr_trc = get_setting('usdt_address', '')
        if addr_trc and addr_trc != 'Not Set':
            for tx_id, amount, t_ms in _fetch_trc20_usdt_deposits(addr_trc):
                try:
                    if t_ms and t_ms < cutoff_ms:
                        continue
                    tx_norm = normalize_tx_id(tx_id)
                    if db.used_transactions.find_one({'transaction_id': tx_norm}):
                        continue
                    pending = find_pending_deposit_for_amount(amount, 'USDT', tolerance=0.001)
                    if pending:
                        if auto_credit_from_pending(pending, tx_norm, "USDT (TRC20) On-chain",
                                                    actual_usd=amount):
                            logger.info(f"✅ USDT TRC20 on-chain: user {pending['user_id']} → ${amount:.2f}")
                except Exception as e:
                    logger.debug(f"trc20 tx err: {e}")
                    continue

        # ── BEP20 عبر BscScan ──
        addr_bep = get_setting('usdt_bep20_address', '')
        if addr_bep and addr_bep != 'Not Set':
            for tx_id, amount, t_ms in _fetch_bep20_usdt_deposits(addr_bep):
                try:
                    if t_ms and t_ms < cutoff_ms:
                        continue
                    tx_norm = normalize_tx_id(tx_id)
                    if db.used_transactions.find_one({'transaction_id': tx_norm}):
                        continue
                    pending = find_pending_deposit_for_amount(amount, 'USDT_BEP20', tolerance=0.001)
                    if pending:
                        if auto_credit_from_pending(pending, tx_norm, "USDT (BEP20) On-chain",
                                                    actual_usd=amount):
                            logger.info(f"✅ USDT BEP20 on-chain: user {pending['user_id']} → ${amount:.2f}")
                except Exception as e:
                    logger.debug(f"bep20 tx err: {e}")
                    continue
    except Exception as e:
        logger.error(f"check_usdt_blockchain_auto error: {e}")


def _check_usdt_binance_legacy():
    """🔍 (احتياطي) يفحص USDT عبر Binance API — للعناوين على Binance"""
    try:
        # نشيك إن في pending
        pending_count = db.pending_deposits.count_documents({
            'coin': {'$in': ['USDT', 'USDT_BEP20']},
            'status': 'pending',
            'expires_at': {'$gt': int(time.time())}
        })
        if pending_count == 0:
            return
        
        # نجلب آخر deposits من Binance
        res = execute_binance_call(
            lambda c: c.get_deposit_history(coin='USDT'),
            max_retries=5
        )
        
        if res is None:
            return
        
        current_time_ms = int(time.time() * 1000)
        cutoff_time_ms = current_time_ms - (45 * 60 * 1000)
        
        for d in res[:30]:
            try:
                tx_id = str(d.get('txId', ''))
                if not tx_id:
                    continue
                
                tx_time = int(d.get('insertTime', 0))
                if tx_time and tx_time < cutoff_time_ms:
                    continue
                
                # فقط الحوالات المؤكدة
                if int(d.get('status', -1)) != 1:
                    continue
                
                tx_id_normalized = normalize_tx_id(tx_id)
                
                if db.used_transactions.find_one({'transaction_id': tx_id_normalized}):
                    continue
                
                amt = float(d.get('amount', 0))
                if amt <= 0:
                    continue
                
                # نطابق مع pending (TRC20 أو BEP20)
                network = d.get('network', '').upper()
                coins_to_check = []
                if 'TRX' in network or 'TRC' in network:
                    coins_to_check = ['USDT']
                elif 'BSC' in network or 'BEP' in network:
                    coins_to_check = ['USDT_BEP20']
                else:
                    coins_to_check = ['USDT', 'USDT_BEP20']
                
                for coin_check in coins_to_check:
                    pending = find_pending_deposit_for_amount(amt, coin_check, tolerance=0.001)
                    if pending:
                        success = auto_credit_from_pending(pending, tx_id_normalized, f"USDT ({coin_check}) Auto")
                        if success:
                            logger.info(f"✅ AUTO-CREDITED USDT: user {pending['user_id']} → ${pending['base_amount_usd']:.2f}")
                        break
            except Exception as tx_err:
                logger.debug(f"Skip USDT tx: {tx_err}")
                continue
    except Exception as e:
        logger.error(f"check_usdt_blockchain_auto error: {e}")


# ============================================================
# 💱 تحويل عملات Binance إلى الدولار (BTC/BNB/ETH/... مو دولار!)
# ============================================================
# مشكلة: Binance Pay يسمح للمرسل يدفع بأي عملة (بيتكوين مثلاً). حقل amount
# يكون بوحدة تلك العملة مو بالدولار. فلو أضفناه مباشرة نعطي رصيداً غلط —
# وقد تكون ثغرة خطيرة: كمية كبيرة من عملة رخيصة = رصيد ضخم.
# الحل: نحوّل حسب السعر الحقيقي، ونرفض لو ما قدرنا نحدد السعر.

# العملات المستقرة (قيمتها ≈ 1 دولار) — نعتبرها دولاراً مباشرة
USD_STABLECOINS = {
    'USDT', 'USDC', 'BUSD', 'FDUSD', 'TUSD', 'DAI', 'USDP', 'PYUSD', 'USD',
}

# خريطة رموز CoinGecko (احتياطي لو Binance ما رجّع سعر)
_CG_IDS = {
    'BTC': 'bitcoin', 'ETH': 'ethereum', 'BNB': 'binancecoin', 'LTC': 'litecoin',
    'TON': 'the-open-network', 'TRX': 'tron', 'SOL': 'solana', 'XRP': 'ripple',
    'DOGE': 'dogecoin', 'ADA': 'cardano', 'MATIC': 'matic-network', 'DOT': 'polkadot',
    'AVAX': 'avalanche-2', 'SHIB': 'shiba-inu', 'BCH': 'bitcoin-cash', 'LINK': 'chainlink',
    'XLM': 'stellar', 'ATOM': 'cosmos', 'ETC': 'ethereum-classic', 'NEAR': 'near',
}

_coin_price_cache = {}   # {SYMBOL: (price, ts)} — cache صغير لتخفيف الضغط
_COIN_PRICE_TTL = 30     # ثانية


def get_coin_price_usd(symbol):
    """يجلب سعر أي عملة بالدولار (USDT) من عدة مصادر مباشرة موثوقة.
    - العملات المستقرة ترجّع 1.0
    - يجرّب: Coinbase → CryptoCompare → CoinGecko → Binance مباشر → Binance عبر بروكسي
      (المصادر المباشرة أولاً لأنها أسرع وأوثق ولا تعتمد على البروكسي المتعثّر)
    - يرجّع None فقط لو فشلت كل المصادر."""
    if not symbol:
        return None
    sym = str(symbol).strip().upper()
    if sym in USD_STABLECOINS:
        return 1.0

    now = time.time()
    c = _coin_price_cache.get(sym)
    if c and (now - c[1]) < _COIN_PRICE_TTL:
        return c[0]

    price = None

    # 1) Coinbase (مباشر، موثوق للعملات الرئيسية) — BTC-USD إلخ
    try:
        r = requests.get(f"https://api.coinbase.com/v2/prices/{sym}-USD/spot", timeout=8)
        if r.status_code == 200:
            p = float(r.json().get('data', {}).get('amount', 0) or 0)
            if p > 0:
                price = p
    except Exception as e:
        logger.debug(f"Coinbase price {sym} err: {e}")

    # 2) CryptoCompare (مباشر، يدعم رموزاً كثيرة، بدون مفتاح)
    if price is None:
        try:
            r = requests.get(
                "https://min-api.cryptocompare.com/data/price",
                params={"fsym": sym, "tsyms": "USD"}, timeout=8
            )
            if r.status_code == 200:
                p = float(r.json().get('USD', 0) or 0)
                if p > 0:
                    price = p
        except Exception as e:
            logger.debug(f"CryptoCompare price {sym} err: {e}")

    # 3) CoinGecko (مباشر، للعملات المعروفة)
    if price is None:
        cg_id = _CG_IDS.get(sym)
        if cg_id:
            try:
                r = requests.get(
                    "https://api.coingecko.com/api/v3/simple/price",
                    params={"ids": cg_id, "vs_currencies": "usd"}, timeout=8
                )
                if r.status_code == 200:
                    p = float(r.json().get(cg_id, {}).get('usd', 0) or 0)
                    if p > 0:
                        price = p
            except Exception as e:
                logger.debug(f"CoinGecko price {sym} err: {e}")

    # 4) Binance عام مباشر (قد يكون محظوراً جغرافياً، لكن نجرّب)
    if price is None:
        try:
            r = requests.get(
                "https://api.binance.com/api/v3/ticker/price",
                params={"symbol": f"{sym}USDT"}, timeout=6
            )
            if r.status_code == 200:
                p = float(r.json().get('price', 0) or 0)
                if p > 0:
                    price = p
        except Exception as e:
            logger.debug(f"Binance direct price {sym} err: {e}")

    # 5) Binance عبر بروكسي (آخر حل)
    if price is None:
        try:
            ticker = execute_binance_call(
                lambda cl: cl.get_symbol_ticker(symbol=f"{sym}USDT"),
                fast_mode=True, total_timeout=8
            )
            if ticker:
                p = float(ticker.get('price', 0) or 0)
                if p > 0:
                    price = p
        except Exception as e:
            logger.debug(f"Binance proxy price {sym} err: {e}")

    if price and price > 0:
        _coin_price_cache[sym] = (price, now)
        return price
    return None


def _binance_tx_currency(tx):
    """يستخرج عملة معاملة Binance (top-level currency/coin أو من fundsDetail)."""
    if not isinstance(tx, dict):
        return None
    cur = tx.get('currency') or tx.get('coin') or tx.get('_coin')
    if cur:
        return str(cur).upper()
    fd = tx.get('fundsDetail') or []
    if isinstance(fd, list):
        for item in fd:
            if isinstance(item, dict) and item.get('currency'):
                return str(item['currency']).upper()
    return None


def binance_amount_to_usd(amount, currency):
    """يحوّل مبلغ Binance (بعملته) إلى دولار.
    يرجّع (usd_value, price_used) أو (None, None) لو تعذّر تحديد السعر.
    ملاحظة: المبالغ السالبة (حوالات صادرة) ترجّع None فتُتجاهَل تلقائياً."""
    try:
        amt = float(amount or 0)
    except (TypeError, ValueError):
        return None, None
    if amt <= 0:   # <=0 يعني صادرة أو صفر → نتجاهلها
        return None, None
    cur = str(currency or 'USDT').strip().upper()
    if cur in USD_STABLECOINS:
        return round(amt, 6), 1.0
    price = get_coin_price_usd(cur)
    if price is None or price <= 0:
        return None, None
    usd = round(amt * price, 6)
    # تحذير لو المبلغ ضخم بشكل غير معتاد (احتياط ضد سعر شاذ)
    if usd > 20000:
        logger.warning(f"⚠️ تحويل Binance كبير: {amt} {cur} = ${usd:.2f} (price ${price})")
    return usd, price


def _binance_pay_request():
    """
    يجلب آخر معاملات Binance Pay باستخدام REST API مباشرة.
    يعيد حساب الـ timestamp والـ signature مع كل محاولة.
    """
    import hmac, hashlib, urllib.parse

    api_key = BINANCE_API_KEY
    api_secret = BINANCE_API_SECRET
    
    if not api_key or not api_secret:
        return None
    
    url = "https://api.binance.com/sapi/v1/pay/transactions"
    
    def _make_signed_params():
        """ينشئ params جديدة مع timestamp وsignature طازجين"""
        ts = int(time.time() * 1000)
        p = {'timestamp': ts, 'limit': 100, 'recvWindow': 60000}
        qs = urllib.parse.urlencode(p)
        sig = hmac.new(api_secret.encode(), qs.encode(), hashlib.sha256).hexdigest()
        p['signature'] = sig
        return p

    def _parse_response(resp):
        """يحلل الرد ويرجع البيانات أو None"""
        if resp.status_code == 200:
            data = resp.json()
            if data.get('status') == 'SUCCESS' or data.get('code') == '000000':
                return data.get('data', [])
            logger.warning(f"Binance Pay API: {data.get('code')} - {data.get('errorMessage', data.get('msg', ''))}")
            return None
        return False  # False = جرب بروكسي ثاني

    # نجرب مع بروكسيات أولاً
    global LAST_GOOD_PROXY
    if not VERIFIED_PROXIES:
        refresh_proxies(force=True)

    # 🚀 نرتّب القائمة بحيث آخر بروكسي نجح يكون أول واحد نجرّبه
    _proxy_list = list(VERIFIED_PROXIES[:10]) if VERIFIED_PROXIES else []
    if LAST_GOOD_PROXY and LAST_GOOD_PROXY in _proxy_list:
        _proxy_list.remove(LAST_GOOD_PROXY)
        _proxy_list.insert(0, LAST_GOOD_PROXY)

    _pay_start = time.time()
    for proxy in _proxy_list:
        if (time.time() - _pay_start) > 20:  # سقف زمني إجمالي
            break
        try:
            params = _make_signed_params()
            resp = requests.get(url, params=params, headers={'X-MBX-APIKEY': api_key},
                                timeout=6, proxies={'http': proxy, 'https': proxy})  # ⏱ كان 12
            result = _parse_response(resp)
            if result is not False:
                LAST_GOOD_PROXY = proxy   # ✅ نحفظ الناجح
                return result
            # 400/403 = بروكسي يعدّل الطلب، نجرب غيره
            _remove_dead_proxy(proxy)
        except Exception:
            _remove_dead_proxy(proxy)
            continue

    # آخر محاولة بدون بروكسي
    try:
        params = _make_signed_params()
        resp = requests.get(url, params=params, headers={'X-MBX-APIKEY': api_key}, timeout=10)
        result = _parse_response(resp)
        if result is not False:
            return result
    except Exception as e:
        logger.error(f"_binance_pay_request error: {e}")
    
    return None


def check_binance_pay_auto():
    """
    🔍 يفحص Binance Pay كل 10 ثواني.
    1️⃣ يطابق بالمبلغ الفريد (لو المستخدم بدأ deposit flow)
    2️⃣ يطابق بالـ Remark/Notes (لو المستخدم حط user_id مباشرة بدون deposit)
    """
    try:
        if not BINANCE_API_KEY or not BINANCE_API_SECRET:
            return

        transactions = _binance_pay_request()
        
        if transactions is None:
            return
        
        if not transactions:
            return

        current_time_ms = int(time.time() * 1000)
        cutoff_ms = current_time_ms - (24 * 60 * 60 * 1000)  # آخر 24 ساعة

        for tx in transactions:
            try:
                # نفضّل orderId الرقمي
                order_id = str(tx.get('orderId') or '').strip()
                trans_id = str(tx.get('transactionId') or tx.get('bizOrderNo') or '').strip()
                
                if order_id and order_id.isdigit():
                    tx_id = order_id
                elif trans_id:
                    tx_id = trans_id
                else:
                    continue

                tx_time = int(tx.get('transactionTime') or tx.get('createTime') or 0)
                if tx_time and tx_time < cutoff_ms:
                    continue

                tx_id_norm = normalize_tx_id(tx_id)

                if db.used_transactions.find_one({'transaction_id': tx_id_norm}):
                    continue

                # المبلغ — نحوّله للدولار حسب العملة (بيتكوين/BNB/... مو دولار!)
                _raw_amount = float(tx.get('amount') or tx.get('totalFee') or 0)
                _tx_cur = _binance_tx_currency(tx) or 'USDT'
                amount, _price_used = binance_amount_to_usd(_raw_amount, _tx_cur)
                if amount is None or amount <= 0:
                    continue

                # ─── 1️⃣ المسار الأول: مطابقة بحقل `note` (الأولوية الأعلى) ───
                # حسب توثيق Binance Pay الرسمي: حقل note يحتوي الملاحظة من المرسل
                # نفحصه أولاً لأنه أوضح وأدق من tolerance المبلغ
                try:
                    tx_keys = list(tx.keys())
                    logger.info(f"[BINANCE TX] tx_id={tx_id_norm[:20]}... amount=${amount:.4f} keys={tx_keys}")
                except: pass
                
                # نجمع الحقول النصية الفعلية (مش اسم المرسل!)
                remark_candidates = []
                for field in ('note', 'remark', 'orderTitle', 'memo', 'description',
                              'goodsName', 'goodsDetail', 'attachment'):
                    v = tx.get(field)
                    if v: remark_candidates.append(str(v))
                
                # حقول داخل fundsDetail (مش payerInfo — لأن payerInfo.name = اسم المرسل مش الـ note)
                fd = tx.get('fundsDetail') or []
                if isinstance(fd, list):
                    for item in fd:
                        if isinstance(item, dict):
                            for field in ('note', 'remark', 'memo', 'description'):
                                v = item.get(field)
                                if v: remark_candidates.append(str(v))
                
                combined_remark = ' '.join(c for c in remark_candidates if c).strip()
                
                # لو في note، نحاول matching بالـ user_id فيه
                target_uid_from_note = None
                if combined_remark:
                    logger.info(f"[BINANCE NOTE FOUND] tx={tx_id_norm[:20]} note={combined_remark[:150]!r}")
                    # نبحث عن user_id (5-12 خانة) في الـ note
                    uid_matches = re.findall(r'\b(\d{5,12})\b', combined_remark)
                    for potential_uid_str in uid_matches:
                        try:
                            potential_uid = int(potential_uid_str)
                        except: continue
                        user = db.users.find_one({'user_id': potential_uid})
                        if user and user.get('is_banned') != 1:
                            target_uid_from_note = potential_uid
                            break
                
                # ✅ لو لقينا user_id صحيح في الـ note → نضيف الرصيد فوراً (بدون deposit)
                if target_uid_from_note:
                    logger.info(f"✅ Binance Pay NOTE MATCH: user {target_uid_from_note} amount=${amount:.4f} note={combined_remark[:80]!r}")
                    
                    # 🔧 مهم: ما نحجز الـ tx بأنفسنا — credit_user() بنفسه يحجزها بشكل atomic.
                    # لو حجزناها قبله، يفشل credit_user لأنه يحسبها duplicate ويرفض الإضافة.
                    user_lang = (db.users.find_one({'user_id': target_uid_from_note}) or {}).get('language', 'ar')
                    try:
                        credit_user(target_uid_from_note, amount, tx_id_norm, user_lang, "Binance Pay (Auto Note)")
                        
                        # 🔓 الإصلاح: نُغلق أي إيداع معلّق للمستخدم ونفكّ القفل.
                        # بدونه: يُضاف الرصيد لكن يظل عالقاً في "لديك عملية دفع معلقة"
                        # (لأنه سوّى deposit flow ثم دفع بالـ note بدل المبلغ الفريد).
                        close_user_pending_and_unlock(
                            target_uid_from_note, tx_id_norm, via='binance_note'
                        )
                        
                        # بعد النجاح، نضيف معلومات الـ note للسجل (مش للحجز)
                        try:
                            db.used_transactions.update_one(
                                {'transaction_id': tx_id_norm},
                                {'$set': {
                                    'method': 'Binance Pay (Auto Note)',
                                    'remark': combined_remark[:200],
                                    'note_matched': True
                                }}
                            )
                        except: pass
                    except Exception as ce:
                        logger.error(f"credit_user fail in note match: {ce}")
                    continue  # خلصنا هالـ tx

                # ─── 2️⃣ المسار الثاني: مطابقة بالمبلغ الفريد (fallback لو ما في note) ───
                pending = find_pending_deposit_for_amount(amount, 'BINANCE', tolerance=0.0001)
                if pending:
                    uid = pending['user_id']
                    base_amount = float(pending.get('base_amount_usd', amount))

                    user = db.users.find_one({'user_id': uid})
                    if not user or user.get('is_banned') == 1:
                        continue

                    logger.info(f"✅ Binance Pay AMOUNT MATCH: user {uid} amount=${amount:.4f} → base=${base_amount:.2f}")
                    success = auto_credit_from_pending(pending, tx_id_norm, "Binance Pay")
                    if success:
                        logger.info(f"✅ Binance Pay credited (amount): user {uid} ${base_amount:.2f}")
                    continue

                # لا في note ولا pending — نتجاهل
                if not combined_remark:
                    logger.info(f"[BINANCE NO MATCH] tx={tx_id_norm[:20]} amount=${amount:.4f} no note no pending")

            except Exception as tx_err:
                logger.debug(f"Binance Pay tx error: {tx_err}")
                continue

    except Exception as e:
        logger.error(f"check_binance_pay_auto error: {e}")


# ============================================================
# 🟠 Bybit — طريقة دفع (تحويل داخلي UID + شبكات USDT)
# ============================================================
# التوثيق الرسمي (V5):
#   • on-chain : GET /v5/asset/deposit/query-record
#   • داخلي     : GET /v5/asset/deposit/query-internal-record
#   • المصادقة  : X-BAPI-API-KEY / X-BAPI-TIMESTAMP / X-BAPI-SIGN / X-BAPI-RECV-WINDOW
#                 توقيع HMAC-SHA256 على: timestamp + apiKey + recvWindow + queryString
#
# ⚠️ Bybit Pay للتجّار (QR + webhook) واجهة منفصلة تتطلب اعتماداً كشريك — غير مفعّلة.

# شبكات الإيداع المدعومة (يسهل إضافة غيرها لاحقاً)
BYBIT_NETWORKS = {
    'TRC20': {
        'coin': 'BYBIT_TRC20',
        'setting': 'bybit_addr_trc20',
        'btn_key': 'btn_bybit_trc20',
        'label_ar': 'USDT — شبكة TRC-20',
        'label_en': 'USDT — TRC-20 Network',
        'chains': ('TRX', 'TRC20', 'TRON', 'TRC-20'),
    },
    'BEP20': {
        'coin': 'BYBIT_BEP20',
        'setting': 'bybit_addr_bep20',
        'btn_key': 'btn_bybit_bep20',
        'label_ar': 'USDT — شبكة BEP-20',
        'label_en': 'USDT — BEP-20 Network',
        'chains': ('BSC', 'BEP20', 'BSC_BNB', 'BEP-20', 'BNB'),
    },
}

BYBIT_COINS = ['BYBIT_UID'] + [n['coin'] for n in BYBIT_NETWORKS.values()]

# تهدئة زر "فحص الدفع" (يمنع الضغط المتكرر واستنزاف حصة الـ API)
_BYBIT_CHECK_COOLDOWN = {}

# حالات النجاح حسب توثيق Bybit
_BYBIT_ONCHAIN_OK = {3}      # 3 = success
_BYBIT_INTERNAL_OK = {2}     # 2 = success


def _bybit_creds():
    """يرجّع (api_key, api_secret, uid, base_url). الأولوية للإعدادات ثم البيئة."""
    def _s(key, env, default=''):
        v = get_setting(key, '')
        if not v or v == 'Not Set':
            v = os.getenv(env, default)
        return (v or '').strip()

    return (
        _s('bybit_api_key', 'BYBIT_API_KEY'),
        _s('bybit_api_secret', 'BYBIT_API_SECRET'),
        _s('bybit_uid', 'BYBIT_UID'),
        _s('bybit_base_url', 'BYBIT_BASE_URL') or 'https://api.bybit.com',
    )


def _bybit_net_address(net_key):
    """عنوان الإيداع لشبكة معيّنة (TRC20 / BEP20)."""
    cfg = BYBIT_NETWORKS.get(net_key)
    if not cfg:
        return ''
    v = get_setting(cfg['setting'], '')
    if not v or v == 'Not Set':
        v = os.getenv(cfg['setting'].upper(), '')
    return (v or '').strip()


def bybit_is_configured():
    # مفتاح تعطيل صريح: لو bybit_disabled=1 نوقف Bybit تماماً
    #   (مفيد بعد الانتقال لـ Trust Wallet — يوقف أخطاء "API key invalid").
    try:
        if str(get_setting('bybit_disabled', '0')) == '1':
            return False
    except Exception:
        pass
    k, s, _u, _b = _bybit_creds()
    return bool(k and s)


def bybit_available_methods():
    """Only internal UID deposits are offered; keep legacy settlement code."""
    if not bybit_is_configured():
        return []
    _k, _s, uid_set, _b = _bybit_creds()
    return ['UID'] if uid_set else []


def _bybit_signed_request(path, params=None, timeout=8):
    """طلب موقّع لـ Bybit V5. يجرّب المباشر أولاً ثم البروكسيات."""
    api_key, api_secret, _uid, base = _bybit_creds()
    if not api_key or not api_secret:
        return None

    params = params or {}
    query = urllib.parse.urlencode(params)
    ts = str(int(time.time() * 1000))
    recv = '20000'
    try:
        sign = _hmac.new(api_secret.encode('utf-8'),
                         f"{ts}{api_key}{recv}{query}".encode('utf-8'),
                         _hashlib.sha256).hexdigest()
    except Exception as e:
        logger.error(f"[BYBIT] sign error: {e}")
        return None

    headers = {
        'X-BAPI-API-KEY': api_key,
        'X-BAPI-TIMESTAMP': ts,
        'X-BAPI-RECV-WINDOW': recv,
        'X-BAPI-SIGN': sign,
    }
    url = f"{base.rstrip('/')}{path}" + (f"?{query}" if query else "")

    def _parse(resp):
        """result عند النجاح، None عند خطأ شبكة، False عند رفض Bybit."""
        try:
            data = resp.json()
        except Exception:
            return None
        if data.get('retCode') == 0:
            return data.get('result') or {}
        _rc = data.get('retCode')
        logger.error(f"[BYBIT] retCode={_rc} retMsg={data.get('retMsg')}")
        # 🛑 إيقاف تلقائي: لو المفتاح غير صالح (10003) تكرر، نوقف Bybit
        #    حتى لا يملأ السجل بالأخطاء (خاصة بعد الانتقال لـ Trust Wallet).
        if _rc == 10003:
            try:
                global _BYBIT_INVALID_KEY_COUNT
                _BYBIT_INVALID_KEY_COUNT += 1
                if _BYBIT_INVALID_KEY_COUNT >= 5:
                    db.settings.update_one({'key': 'bybit_disabled'},
                                           {'$set': {'value': '1'}}, upsert=True)
                    logger.warning("[BYBIT] 🛑 أُوقف تلقائياً بعد تكرار خطأ المفتاح. "
                                   "للتشغيل: /bybit_on بعد إصلاح المفتاح.")
            except Exception:
                pass
        return False

    # 1) اتصال مباشر
    try:
        out = _parse(requests.get(url, headers=headers, timeout=timeout))
        if out is False:
            return None
        if out is not None:
            return out
    except Exception as e:
        logger.debug(f"[BYBIT] direct failed: {e}")

    # 2) عبر البروكسيات (تفضيل آخر بروكسي ناجح)
    global LAST_GOOD_PROXY
    try:
        if not VERIFIED_PROXIES:
            refresh_proxies(force=True)
        plist = list(VERIFIED_PROXIES[:8]) if VERIFIED_PROXIES else []
        if LAST_GOOD_PROXY and LAST_GOOD_PROXY in plist:
            plist.remove(LAST_GOOD_PROXY)
            plist.insert(0, LAST_GOOD_PROXY)
        started = time.time()
        for proxy in plist:
            if (time.time() - started) > 20:
                break
            try:
                out = _parse(requests.get(url, headers=headers, timeout=6,
                                          proxies={'http': proxy, 'https': proxy}))
                if out is False:
                    return None
                if out is not None:
                    LAST_GOOD_PROXY = proxy
                    return out
            except Exception:
                _remove_dead_proxy(proxy)
                continue
    except Exception as e:
        logger.debug(f"[BYBIT] proxy stage failed: {e}")

    return None


def get_bybit_deposits(kind='internal', coin=None, limit=50, tx_id=None):
    """Fetch bounded pages (Bybit accepts at most 50 records per request)."""
    path = ('/v5/asset/deposit/query-internal-record' if kind == 'internal'
            else '/v5/asset/deposit/query-record')
    wanted = max(1, min(int(limit), 500))
    rows, seen_cursors = [], set()
    cursor = None
    while len(rows) < wanted:
        params = {'limit': min(50, wanted - len(rows))}
        if coin:
            params['coin'] = coin
        if tx_id and kind == 'internal':
            params['txID'] = str(tx_id)
        if cursor:
            params['cursor'] = cursor
        res = _bybit_signed_request(path, params)
        if not isinstance(res, dict):
            raise RuntimeError('Bybit API request failed; check [BYBIT] retCode/connection logs')
        page = res.get('rows', [])
        if not isinstance(page, list):
            raise RuntimeError('Invalid Bybit deposit response')
        rows.extend(page[:wanted-len(rows)])
        cursor = res.get('nextPageCursor')
        if not page or not cursor or cursor in seen_cursors:
            break
        seen_cursors.add(cursor)
    return rows


def _bybit_row_txid(row):
    """يستخرج معرّف العملية.
    🔧 لا نعتمد على أسماء ثابتة (Bybit قد يستخدم txID/orderId/depositId...).
    نجرّب الأسماء المعروفة، وإلا نبحث في كل الحقول عن قيمة تشبه المعرّف."""
    if not isinstance(row, dict):
        return ''
    # 1) الأسماء المعروفة
    for k in ('txID', 'txId', 'id', 'transactionId', 'orderId', 'depositId',
              'internalId', 'transferId', 'orderNo', 'bizId'):
        v = row.get(k)
        if v not in (None, '', 0, '0'):
            return str(v)
    # 2) بحث ذكي: أي مفتاح فيه id/tx/order + قيمة طويلة تشبه معرّفاً
    for k, v in row.items():
        if v in (None, '', 0, '0'):
            continue
        kl = str(k).lower()
        if any(t in kl for t in ('id', 'tx', 'order', 'hash', 'no')):
            sv = str(v)
            if len(sv) >= 8 and re.match(r'^[A-Za-z0-9_\-]+$', sv):
                return sv
    return ''


def _bybit_all_ids(row):
    if not isinstance(row, dict):
        return []
    return [str(row[k]).strip() for k in ('txID', 'txId', 'id', 'transactionId', 'orderId',
            'depositId', 'internalId', 'transferId', 'orderNo', 'bizId')
            if row.get(k) not in (None, '', 0, '0')]


def _bybit_row_note(row):
    for k in ('remark', 'note', 'memo', 'tag', 'comment', 'description', 'message'):
        if row.get(k):
            return str(row[k])
    return ''


def _bybit_row_time_ms(row):
    """يرجّع وقت العملية بالملّي ثانية.
    🔧 مهم: Bybit يرجّع createdTime بالثواني (10 خانات مثل 1705393280)،
    والكود يقارنه بوقت بالملّي. بدون التطبيع يظنّ كل العمليات من 1970
    فيتخطّاها كلها ⇒ لا يصل أي إيداع! نطبّع الثواني إلى ملّي."""
    for k in ('successAt', 'createdTime', 'updatedTime', 'timestamp', 'createTime'):
        v = row.get(k)
        if not v:
            continue
        try:
            t = int(float(v))
        except Exception:
            continue
        if t <= 0:
            continue
        # < 1e12 يعني ثوانٍ (10 خانات) → نحوّلها ملّي
        if t < 1_000_000_000_000:
            t *= 1000
        return t
    return 0


def _bybit_row_is_success(row, kind):
    """هل العملية مكتملة؟
    🛡 للإيداع on-chain نتشدّد: لو الحالة مفقودة نرفض (قد تكون غير مؤكدة وتُعكس).
       للتحويل الداخلي نتساهل (فوري داخل المنصة)."""
    st = row.get('status', None)
    if st is None:
        return False
    try:
        st = int(st)
    except Exception:
        return False
    return st in (_BYBIT_INTERNAL_OK if kind == 'internal' else _BYBIT_ONCHAIN_OK)


def _bybit_row_usd(row):
    """يحوّل مبلغ السجل للدولار. يرجّع (usd|None, coin)."""
    coin = str(row.get('coin') or row.get('currency') or 'USDT').upper()
    try:
        amt = float(row.get('amount') or 0)
    except Exception:
        return None, coin
    if amt <= 0:
        return None, coin
    if coin in USD_STABLECOINS:
        return round(amt, 6), coin
    price = get_coin_price_usd(coin)
    if not price or price <= 0:
        return None, coin
    return round(amt * price, 6), coin


def _bybit_coin_key_for_chain(chain_raw):
    """يحدد أي شبكة (TRC20/BEP20) حسب حقل السلسلة من Bybit.
    🔧 نقرأ عدة أسماء محتملة للحقل (chain/chainType/network...)."""
    c = str(chain_raw or '').upper().replace('-', '').replace('_', '')
    if not c:
        return None
    for net_key, cfg in BYBIT_NETWORKS.items():
        for ch in cfg['chains']:
            if ch.replace('-', '').replace('_', '') in c:
                return cfg['coin']
    return None


def _bybit_row_chain(row):
    """يستخرج اسم الشبكة من أي حقل محتمل."""
    for k in ('chain', 'chainType', 'network', 'depositChain', 'chainName'):
        v = row.get(k)
        if v:
            return str(v)
    return ''


def _bybit_match_by_sender(sender_uid, usd, tolerance=0.01):
    """يطابق تحويل Bybit الداخلي بـ UID المرسِل + المبلغ الفريد معاً.

    الأمان: UID وحده لا يكفي (يمكن انتحال UID شخص آخر)، والمبلغ وحده قد
    يتكرر. اجتماعهما يجعل الانتحال شبه مستحيل.

    - نبحث عن إيداع معلّق لـ BYBIT_UID مسجّل عليه نفس sender_uid وقريب من المبلغ.
    - لو تعدّدت المطابقات (غموض) → لا نرجّع أحداً (أأمن من الخطأ).
    """
    sender_uid = str(sender_uid).strip()
    if not sender_uid:
        return None
    try:
        usd = float(usd)
        recs = list(db.pending_deposits.find({
            'coin': 'BYBIT_UID',
            'status': 'pending',
            'sender_uid': sender_uid,
            'expires_at': {'$gt': int(time.time())},
            'unique_amount_usd': {'$gte': usd - tolerance, '$lte': usd + tolerance}
        }))
        if not recs:
            return None
        if len(recs) == 1:
            return recs[0]
        # غموض: نأخذ الأقرب للمبلغ بالضبط، ولو تساوى اثنان نرفض
        recs.sort(key=lambda r: abs(float(r.get('unique_amount_usd', 0)) - usd))
        d0 = abs(float(recs[0].get('unique_amount_usd', 0)) - usd)
        d1 = abs(float(recs[1].get('unique_amount_usd', 0)) - usd)
        if abs(d0 - d1) < 1e-9:
            logger.warning(f"[BYBIT] غموض في مطابقة UID {sender_uid} بمبلغ ${usd} — رُفض للأمان")
            return None
        return recs[0]
    except Exception as e:
        logger.debug(f"_bybit_match_by_sender err: {e}")
        return None


def _bybit_match_internal_by_amount(usd, tolerance=0.004):
    """يطابق تحويل Bybit داخلي بالمبلغ الفريد فقط — للإيداعات المعلّقة على
    BYBIT_UID التي لا تحمل sender_uid مسجّلاً (توافقية / لم يُدخل المستخدم UID).

    المبلغ الفريد (بكسور ٤ خانات) مميّز بما يكفي. نطبّق نفس حارس الغموض:
    لو تعدّدت المطابقات بنفس القرب نرفض."""
    try:
        usd = float(usd)
        recs = list(db.pending_deposits.find({
            'coin': 'BYBIT_UID',
            'status': 'pending',
            'expires_at': {'$gt': int(time.time())},
            'unique_amount_usd': {'$gte': usd - tolerance, '$lte': usd + tolerance}
        }))
        if not recs:
            return None
        if len(recs) == 1:
            return recs[0]
        recs.sort(key=lambda r: abs(float(r.get('unique_amount_usd', 0)) - usd))
        d0 = abs(float(recs[0].get('unique_amount_usd', 0)) - usd)
        d1 = abs(float(recs[1].get('unique_amount_usd', 0)) - usd)
        if abs(d0 - d1) < 1e-9:
            logger.warning(f"[BYBIT] غموض في مطابقة المبلغ ${usd} (داخلي) — رُفض للأمان")
            return None
        return recs[0]
    except Exception as e:
        logger.debug(f"_bybit_match_internal_by_amount err: {e}")
        return None


# ============================================================
# 🛡 التحقق من شرعية إيداع Bybit (رفض العملات/الشبكات المزيفة)
# ============================================================
# العملات المسموح قبولها فقط (كلها مستقرة أو معروفة). أي شيء آخر يُرفض.
BYBIT_ALLOWED_COINS = {'USDT', 'USDC', 'USDD', 'TON', 'ETH', 'LTC', 'TRX', 'BNB'}
# الشبكات المسموحة لكل إيداع on-chain
BYBIT_ALLOWED_CHAINS = {
    'BSC', 'BEP20', 'BNB', 'TRX', 'TRC20', 'TRON', 'ETH', 'ERC20',
    'TON', 'LTC', 'ARBITRUM', 'ARB', 'MATIC', 'POLYGON',
}


def _bybit_verify_legit(row, kind):
    """يتحقق أن الإيداع بعملة وشبكة معتمدتين وحالته ناجحة.
    يرجّع (سليم؟, سبب الرفض).

    الحماية من العملات المزيفة: Bybit نفسه لا يودع توكنات مزيفة (يتحقق من
    العقد الرسمي قبل الإيداع)، لكن هذه طبقة ثانية ترفض أي عملة/شبكة خارج
    القائمة البيضاء — حتى لو تغيّر سلوك Bybit مستقبلاً."""
    # 1) العملة ضمن المسموح
    coin = str(row.get('coin') or row.get('currency') or '').upper().strip()
    if not coin:
        return False, "عملة فارغة"
    if coin not in BYBIT_ALLOWED_COINS:
        return False, f"عملة غير معتمدة: {coin}"

    # 2) الشبكة ضمن المسموح (لإيداعات on-chain فقط؛ الداخلي بلا شبكة)
    if kind == 'onchain':
        chain = str(_bybit_row_chain(row)).upper().replace('-', '').replace('_', '').strip()
        if chain:
            ok_chain = any(
                allowed.replace('-', '').replace('_', '') in chain
                for allowed in BYBIT_ALLOWED_CHAINS
            )
            if not ok_chain:
                return False, f"شبكة غير معتمدة: {chain}"

    # 3) الحالة ناجحة (يمنع قبول المعلّق/الملغى)
    if not _bybit_row_is_success(row, kind):
        return False, "حالة غير مكتملة"

    return True, ""


def check_bybit_auto():
    """🔍 يفحص إيداعات Bybit تلقائياً (داخلي + شبكات) ويضيف الرصيد.

    ملاحظة: بما أن عناوين USDT (TRC20/BEP20) قد تكون على Bybit أيضاً،
    نفحص كذلك الإيداعات المعلّقة بعملات USDT العادية ونطابقها ضد سجلّ
    Bybit on-chain — وإلا تحويلات زر USDT العادي لا تُفحص أبداً."""
    try:
        if not bybit_is_configured():
            return

        # كل العملات التي قد تصل عبر Bybit (Bybit الأصلية + USDT العادية على شبكاتها)
        onchain_match_coins = [c['coin'] for c in BYBIT_NETWORKS.values()] + ['USDT', 'USDT_BEP20']
        all_watch_coins = BYBIT_COINS + ['USDT', 'USDT_BEP20']

        now = int(time.time())
        if db.pending_deposits.count_documents({
            'coin': {'$in': all_watch_coins},
            'status': 'pending',
            'expires_at': {'$gt': now}
        }) == 0:
            return

        # نافذة أوسع من عمر الإيداع المعلّق (30 دقيقة) + هامش، تحسّباً لتأخّر المستخدم
        cutoff_ms = int(time.time() * 1000) - (90 * 60 * 1000)  # آخر 90 دقيقة

        for kind, label in (('internal', 'Bybit (UID Transfer)'),
                            ('onchain', 'Bybit (Network)')):
            try:
                rows = get_bybit_deposits(kind=kind, limit=200)
            except Exception as e:
                logger.debug(f"[BYBIT] fetch {kind} err: {e}")
                continue

            for row in rows or []:
                try:
                    if not _bybit_row_is_success(row, kind):
                        continue

                    tx_time = _bybit_row_time_ms(row)
                    if tx_time and tx_time < cutoff_ms:
                        continue

                    raw_tx = _bybit_row_txid(row)
                    if not raw_tx:
                        continue
                    tx_norm = normalize_tx_id(raw_tx)

                    if db.used_transactions.find_one({'transaction_id': tx_norm}):
                        continue

                    # 🛡 تحقق صارم من العملة والشبكة (رفض العملات/الشبكات غير المعتمدة)
                    #    Bybit أصلاً لا يودع العملات المزيفة، ونضيف هذه كطبقة ثانية.
                    _ok_coin, _reason = _bybit_verify_legit(row, kind)
                    if not _ok_coin:
                        logger.warning(f"[BYBIT] 🚫 رُفض إيداع غير معتمد: {_reason} | tx={raw_tx[:20]}")
                        continue

                    usd, coin_name = _bybit_row_usd(row)
                    if usd is None or usd <= 0:
                        logger.warning(f"[BYBIT] تعذّر تسعير {coin_name} — تخطّي {raw_tx[:20]}")
                        continue

                    # أي "عملة داخلية" نطابق عليها
                    if kind == 'internal':
                        coin_keys = ['BYBIT_UID']
                    else:
                        ck = _bybit_coin_key_for_chain(_bybit_row_chain(row))
                        # 🔧 دائماً نجرّب كل شبكات Bybit أيضاً (حتى لو عرفنا الشبكة)
                        #    حتى لا نفوّت إيداعاً بسبب اختلاف اسم حقل الشبكة.
                        all_nets = [c['coin'] for c in BYBIT_NETWORKS.values()]
                        coin_keys = ([ck] + [c for c in all_nets if c != ck]) if ck else list(all_nets)

                        # 🔧 مهم: نضيف عملات USDT العادية حسب الشبكة المكتشفة
                        #    (المستخدم قد يدفع عبر زر USDT العادي لعنوان على Bybit)
                        chain_raw = _bybit_row_chain(row)
                        if ck == 'BYBIT_BEP20' or 'BSC' in str(chain_raw).upper() or 'BEP' in str(chain_raw).upper():
                            coin_keys.append('USDT_BEP20')
                        elif ck == 'BYBIT_TRC20' or 'TR' in str(chain_raw).upper():
                            coin_keys.append('USDT')
                        else:
                            # شبكة غير مؤكدة → جرّب الاثنتين
                            coin_keys.extend(['USDT_BEP20', 'USDT'])

                    # 🆔 للتحويل الداخلي (UID): نطابق بـ UID المرسِل + المبلغ الفريد معاً
                    #    fromMemberId = رقم مرسِل التحويل في Bybit
                    if kind == 'internal':
                        sender = str(row.get('fromMemberId') or row.get('fromUid') or '').strip()
                        if sender:
                            _p = _bybit_match_by_sender(sender, usd)
                            if _p:
                                if auto_credit_from_pending(_p, tx_norm, label + " (UID)", actual_usd=usd):
                                    logger.info(f"✅ BYBIT UID+amount match: user {_p['user_id']} "
                                                f"← sender {sender} → ${_p['base_amount_usd']:.2f}")
                                continue

                        # احتياط: إيداع معلّق بنفس المبلغ الفريد لكن بلا sender_uid مسجّل
                        #   (إيداعات سُجّلت قبل نظام الـ UID، أو المستخدم لم يُدخل UID).
                        #   المبلغ الفريد وحده مميّز بما يكفي للمطابقة الآمنة.
                        _p2 = _bybit_match_internal_by_amount(usd)
                        if _p2:
                            # نخزّن UID المرسِل للسجل (للمراجعة)
                            try:
                                if sender:
                                    db.pending_deposits.update_one(
                                        {'pending_id': _p2.get('pending_id')},
                                        {'$set': {'sender_uid_detected': sender}})
                            except Exception:
                                pass
                            if auto_credit_from_pending(_p2, tx_norm, label + " (UID/amount)", actual_usd=usd):
                                logger.info(f"✅ BYBIT internal amount-match: user {_p2['user_id']} "
                                            f"→ ${_p2['base_amount_usd']:.2f} (sender {sender or '?'})")
                            continue

                        # وصل من UID لكن ما طابق — تشخيص
                        logger.warning(f"[BYBIT] تحويل داخلي من UID {sender} بمبلغ ${usd} "
                                       f"بلا مطابقة (UID أو المبلغ غير مسجّل) | tx={raw_tx[:16]}")
                        continue

                    # 1️⃣ مطابقة بالمبلغ الفريد (الأساس والأأمن)
                    matched = False
                    for ckey in coin_keys:
                        pending = find_pending_deposit_for_amount(usd, ckey, tolerance=0.004)
                        if pending:
                            if auto_credit_from_pending(pending, tx_norm, label, actual_usd=usd):
                                logger.info(f"✅ BYBIT auto-credit ({kind}): "
                                            f"user {pending['user_id']} → ${pending['base_amount_usd']:.2f}")
                            matched = True
                            break
                    if matched:
                        continue

                    # ⛔ مطابقة النقص مُلغاة عمداً (كانت تعطي الرصيد للشخص الخطأ).
                    #    on-chain لا يحمل هوية المُرسِل، فأي مبلغ ناقص لا يمكن نسبته
                    #    بيقين. بدل التخمين: نسجّل تنبيهاً فقط، والأدمن يضيف يدوياً.
                    try:
                        _sf_near = None
                        for ckey in coin_keys:
                            _cand = db.pending_deposits.find_one({
                                'coin': ckey, 'status': 'pending',
                                'expires_at': {'$gt': int(time.time())},
                                'unique_amount_usd': {'$gte': usd - 0.5, '$lte': usd + 0.05}
                            })
                            if _cand:
                                _sf_near = _cand
                                break
                        if _sf_near:
                            logger.warning(
                                f"[BYBIT] ⚠️ وصل ${usd:.2f} قريب من إيداع "
                                f"user {_sf_near['user_id']} (${_sf_near.get('unique_amount_usd',0):.4f}) "
                                f"لكن ليس مطابقاً تماماً — لم يُصرف (راجع يدوياً) | tx={raw_tx[:16]}")
                    except Exception:
                        pass

                    # 🔍 تشخيص: وصل مبلغ لكن ما لقينا إيداعاً معلّقاً مطابقاً
                    #    نسجّل أقرب الإيداعات المعلّقة لنعرف سبب عدم المطابقة
                    try:
                        _near = list(db.pending_deposits.find({
                            'coin': {'$in': coin_keys}, 'status': 'pending'
                        }).limit(5))
                        _near_amts = [round(float(p.get('unique_amount_usd', 0)), 6) for p in _near]
                        logger.warning(
                            f"[BYBIT] وصل ${usd} ({kind}) بلا مطابقة. "
                            f"المعلّقة {coin_keys}: {_near_amts or 'لا يوجد'} "
                            f"| tx={raw_tx[:16]}"
                        )
                    except Exception:
                        pass

                    # 2️⃣ مطابقة بالملاحظة (آيدي تيليجرام) — للتحويل الداخلي فقط
                    #    🛡 نشترط: مستخدم موجود + غير محظور + عنده إيداع معلّق لـ Bybit
                    #    (بدون هذه الشروط يمكن إرسال مبلغ صغير بملاحظة تحمل آيدي أي شخص)
                    if kind != 'internal':
                        continue
                    note = _bybit_row_note(row)
                    if not note:
                        continue
                    m = re.search(r'(?<!\d)(\d{6,12})(?!\d)', note)
                    if not m:
                        continue
                    note_uid = int(m.group(1))
                    u = db.users.find_one({'user_id': note_uid})
                    if not u or u.get('is_banned') == 1:
                        continue
                    has_pending = db.pending_deposits.find_one({
                        'user_id': note_uid,
                        'coin': {'$in': BYBIT_COINS},
                        'status': 'pending',
                        'expires_at': {'$gt': int(time.time())}
                    })
                    if not has_pending:
                        logger.info(f"[BYBIT] تخطّي مطابقة الملاحظة لـ {note_uid}: لا إيداع معلّق")
                        continue
                    try:
                        credit_user(note_uid, usd, tx_norm, u.get('language', 'ar'),
                                    f"{label} (Auto Note)")
                        close_user_pending_and_unlock(note_uid, tx_norm, via='bybit_note')
                        logger.info(f"✅ BYBIT note-match: {note_uid} → ${usd:.2f}")
                    except Exception as ce:
                        logger.error(f"[BYBIT] note credit fail: {ce}")
                except Exception as row_err:
                    logger.debug(f"[BYBIT] row err: {row_err}")
                    continue
    except Exception as e:
        logger.error(f"check_bybit_auto error: {e}")


