def _cgpt_show_my_subscriptions(uid, chat_id, message_id=None):
    l = get_lang(uid)
    subs = _cgpt_get_user_subscriptions(uid)
    if not subs:
        txt = get_text(uid, 'cg_notice_16')
        markup = InlineKeyboardMarkup()
        markup.add(create_btn(uid, 'btn_products', callback_data="open_shop"))
        if message_id:
            try: bot.edit_message_text(txt, chat_id, message_id, parse_mode="HTML", reply_markup=markup); return
            except Exception: pass
        bot.send_message(chat_id, txt, parse_mode="HTML", reply_markup=markup)
        return
    markup = InlineKeyboardMarkup(row_width=1)
    lines = [get_text(uid, 'cg_subs_title')]
    for i, s in enumerate(subs):
        rem = f"{s['remaining_days']} يوم" if l != 'en' else f"{s['remaining_days']} days"
        if s['remaining_days'] == 0:
            rem = f"{s['remaining_hours']} ساعة" if l != 'en' else f"{s['remaining_hours']} hours"
        lines.append(f"{i+1}. 📧 <code>{html.escape(s['email'])}</code>\n   ⏳ {rem}")
        # زر لكل اشتراك (نمرّر index)
        markup.add(_cgpt_cms_button(uid, 'cg_sub_item', f" — {s['email'][:22]} · {rem}", callback_data=f'cgsub_{i}'))
    # نحفظ الاشتراكات مؤقتاً للعميل (للوصول عند الضغط)
    try:
        db.cgpt_sub_cache.update_one({'_id': uid},
            {'$set': {'subs': subs, 'ts': int(time.time())}}, upsert=True)
    except Exception:
        pass
    txt = "\n".join(lines)
    if message_id:
        try: bot.edit_message_text(txt, chat_id, message_id, parse_mode="HTML", reply_markup=markup); return
        except Exception: pass
    bot.send_message(chat_id, txt, parse_mode="HTML", reply_markup=markup)


@bot.callback_query_handler(func=lambda call: call.data.startswith("cgsub_") and not call.data.startswith("cgsub_act_") and call.data != "cgsub_back")
def cgpt_sub_detail(call):
    """تفاصيل اشتراك واحد + أزرار التجديد/الترقية."""
    try: bot.answer_callback_query(call.id)
    except Exception: pass
    uid = call.from_user.id
    idx = int(call.data.replace("cgsub_", "")) if call.data.replace("cgsub_", "").isdigit() else -1
    try:
        cache = db.cgpt_sub_cache.find_one({'_id': uid})
        subs = cache.get('subs', []) if cache else []
    except Exception:
        subs = []
    if idx < 0 or idx >= len(subs):
        bot.answer_callback_query(call.id, "انتهت الجلسة، أعد /my_chatgpt", show_alert=True)
        return
    s = subs[idx]
    l = get_lang(uid)
    if l == 'en':
        rem_txt = f"{s['remaining_days']} days, {s['remaining_hours']} hours"
        txt = (
            f"⚙️ <b>Subscription Details</b>\n\n"
            f"📧 <b>Email:</b> <code>{html.escape(s['email'])}</code>\n"
            f"⏳ <b>Remaining:</b> {rem_txt}\n"
            f"📅 <b>Expires:</b> {s['expires_at'][:16]}\n\n"
            f"You can renew or upgrade (time is added to remaining):"
        )
        back_lbl = "🔙 Back"
    else:
        rem_txt = f"{s['remaining_days']} يوم و {s['remaining_hours']} ساعة"
        txt = (
            f"⚙️ <b>تفاصيل الاشتراك</b>\n\n"
            f"📧 <b>الإيميل:</b> <code>{html.escape(s['email'])}</code>\n"
            f"⏳ <b>المتبقّي:</b> {rem_txt}\n"
            f"📅 <b>ينتهي:</b> {s['expires_at'][:16]}\n\n"
            f"يمكنك التجديد أو الترقية (تُضاف المدة للمتبقّي):"
        )
        back_lbl = "🔙 رجوع"

    # Apply Business customization through the existing bilingual text system.
    txt = get_text(uid, 'cg_details', html.escape(s['email']), s['remaining_days'], s['remaining_hours'], s['expires_at']) or txt
    markup = InlineKeyboardMarkup(row_width=1)
    products = list(db.cgpt_products.find())
    for p in products:
        pid = str(p.get('_id'))
        durations = sorted(p.get('durations', []), key=lambda x: x.get('price', 0))
        for dur in durations:
            dur_id = dur.get('dur_id', '')
            label = (dur.get('label_en') or translate_duration_label(dur.get('label', ''), 'en')) if l == 'en' else dur.get('label', '')
            price = vip_unit(uid, f"cgpt_{pid}", float(dur.get('price', 0) or 0))[0]
            mins = dur.get('minutes', 0)
            days = round(mins / 1440, 1) if mins else 0
            _dsuffix = f"(+{days}d)" if l == 'en' else f"(+{days}ي)"
            markup.add(_cgpt_cms_button(uid, 'cg_upgrade', f' — {label} · ${price:g} {_dsuffix}',
                callback_data=f"cgsub_act_{idx}_{pid}_{dur_id}"))
    markup.add(create_btn(uid, 'cg_back', callback_data="cgsub_back"))
    bot.send_message(call.message.chat.id, txt, parse_mode="HTML", reply_markup=markup)


