        markup.add(
            InlineKeyboardButton("✅ أضفه", callback_data=f"extadd_{sid}_{ext_id}"),
            InlineKeyboardButton("🚫 تجاهل", callback_data=f"extign_{sid}_{ext_id}")
        )
