@bot.message_handler(commands=['fix_innocent_bans'])
def fix_innocent_bans_cmd(message):
    """🛡 يفك حظر المستخدمين اللي حُظروا بسبب bug في النظام (إرسال /start)"""
    uid = message.from_user.id
    if not _is_admin_check(uid):
        return
    
    # نبحث في theft_attempts عن المحاولات اللي الـ hash فيها /start أو نص قصير
    bug_attempts = list(db.theft_attempts.find({
        '$or': [
            {'transaction_id': {'$regex': '^/'}},
            {'transaction_id': {'$regex': '^start'}},
            {'transaction_id': {'$lte': 'aaaaaa'}}
        ]
    }))
    
    if not bug_attempts:
        bot.send_message(message.chat.id, "✅ ما في ضحايا للـ bug.")
        return
    
    unbanned_users = set()
    refunded_amounts = {}
    
    for attempt in bug_attempts:
        # نجمع IDs
        original_id = attempt.get('original_user_id') or attempt.get('original_claimer')
        thief_id = attempt.get('thief_user_id') or attempt.get('thief_attempt')
        seized = float(attempt.get('seized_balance', 0))
        
        for victim_id in [original_id, thief_id]:
            if not victim_id:
                continue
            try:
                victim_id = int(victim_id)
                # فك الحظر
                db.users.update_one(
                    {'user_id': victim_id},
                    {'$set': {'is_banned': 0}}
                )
                unbanned_users.add(victim_id)
                
                # إرجاع الرصيد لو فيه
                if victim_id == original_id and seized > 0:
                    refund = refunded_amounts.get(victim_id, 0) + seized
                    refunded_amounts[victim_id] = refund
                    db.users.update_one(
                        {'user_id': victim_id},
                        {'$inc': {'balance': seized}}
                    )
                    
                # نرسل رسالة للمستخدم
                try:
                    bot.send_message(
                        victim_id,
                        "✅ <b>تم فك حظر حسابك!</b>\n\n"
                        "🙏 نعتذر، كان هناك خطأ تقني في النظام حُظر بسببه حسابك.\n\n"
                        "💼 رصيدك مُرجع بالكامل.\n\n"
                        "<i>يمكنك استخدام البوت بشكل طبيعي الآن.</i>",
                        parse_mode="HTML"
                    )
                except: pass
            except Exception as e:
                logger.error(f"Failed to unban {victim_id}: {e}")
    
    # نحذف الـ records الخاطئة من theft_attempts
    db.theft_attempts.delete_many({
        '$or': [
            {'transaction_id': {'$regex': '^/'}},
            {'transaction_id': {'$regex': '^start'}}
        ]
    })
    
    # تقرير
    report = (
        f"✅ <b>تم فك حظر الضحايا!</b>\n\n"
        f"━━━━━━━━━━━━━━\n"
        f"👥 عدد المستخدمين اللي فُك حظرهم: <b>{len(unbanned_users)}</b>\n"
        f"💰 إجمالي المبالغ المُرجعة: <b>${sum(refunded_amounts.values()):.2f}</b>\n"
        f"━━━━━━━━━━━━━━\n\n"
        f"📋 <b>التفاصيل:</b>\n"
    )
    for u in list(unbanned_users)[:20]:
        refund = refunded_amounts.get(u, 0)
        report += f"   • <code>{u}</code>"
        if refund > 0:
            report += f" (+${refund:.2f})"
        report += "\n"
    
    if len(unbanned_users) > 20:
        report += f"\n... و {len(unbanned_users) - 20} مستخدم آخر"
    
    bot.send_message(message.chat.id, report, parse_mode="HTML")


@bot.callback_query_handler(func=lambda call: call.data in ("admin_panel_main", "admin_panel"))  # admin_panel: زر رجوع قديم في لوحة ChatGPT كان بلا معالج
@admin_required
def admin_panel_main_entry(call):
    """معالج فتح لوحة الأدمن (كان مفصولاً عن دالته بالخطأ)."""
    return admin_main_ui(call)


# ============================================================
# 🔌 متاجر API الخارجية (Multi-store) — جلب المنتجات + التسعير + الطلب التلقائي
# ============================================================
# كل متجر: {name, base_url, api_key, created_at}
# منتج مخصّص: ext_products {store_id, ext_id, name, desc, base_price(API),
#   markup_type('percent'|'fixed'|'manual'), markup_value, sell_price, hidden, emoji_id}

def _ext_parse_products(data):
    """يستخرج قائمة المنتجات من أي بنية رد (عالمي)."""
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for k in ('products', 'data', 'items', 'result', 'results',
                  'catalog', 'list', 'response'):
            v = data.get(k)
            if isinstance(v, list):
                return v
            if isinstance(v, dict):
                # قد تكون المنتجات داخل مستوى أعمق
                for k2 in ('products', 'data', 'items'):
                    if isinstance(v.get(k2), list):
                        return v[k2]
    return []


def _ext_deep_get(p, keys, default=None):
    """يبحث عن أول مفتD موجod (يدعم مفاتيح متعددة وحالات مختلفة)."""
    for k in keys:
        if k in p and p[k] not in (None, ''):
            return p[k]
        # بحث غير حسّاس لحالة الأحرف
        for pk in p:
            if pk.lower() == k.lower() and p[pk] not in (None, ''):
                return p[pk]
    return default


def _ext_extract_fields(p):
    """يستخرج حقول المنتج من أي تنسint متجr (عالمي بالكامل).
    يدعم أي أسماء حقول شائعة، وأي بنية."""
    if not isinstance(p, dict):
        return {'ext_id': '', 'name': 'Product', 'desc': '', 'desc_text': '',
                'sell_price': 0.0, 'cost_price': 0.0, 'stock': 0, 'available': False,
                'emoji_id': None, 'emoji_char': ''}
    # المعرّف
    ext_id = str(_ext_deep_get(p, ['id', 'product_id', 'productId', 'pid', 'sku', 'code'], ''))
    # الاسم
    name = _ext_deep_get(p, ['name', 'name_en', 'name_ar', 'title', 'product_name',
                             'productName', 'label'], f"Product {ext_id}")
    # الوصف
    desc = _ext_deep_get(p, ['description', 'desc', 'description_text', 'desc_en',
                             'desc_ar', 'details', 'body', 'text', 'about'], '')
    desc_text = _ext_deep_get(p, ['description_text', 'desc_text', 'plain_description'], '') or desc
    # السعر (سعري/ما يُعرض)
    sell_price = _ext_deep_get(p, ['price_usdt', 'list_price', 'price', 'unit_price',
                                   'sell_price', 'sale_price', 'amount', 'cost_usd',
                                   'retail_price', 'listPrice', 'unitPrice'], 0)
    # التكلفة (ما يُخصm مني)
    cost_price = _ext_deep_get(p, ['base_price_usdt', 'unit_price', 'cost', 'cost_price',
                                   'wholesale_price', 'base_price', 'basePriceUsdt',
                                   'costPrice'], None)
    if cost_price is None:
        cost_price = sell_price
    # المخزون
    stock = _ext_deep_get(p, ['stock', 'stock_count', 'quantity', 'qty', 'available_qty',
                              'inventory', 'stockCount', 'in_stock_count', 'count'], 0)
    try:
        stock = int(float(stock))
    except Exception:
        stock = 0
    # التوفّr
    available = _ext_deep_get(p, ['available', 'in_stock', 'is_available', 'active',
                                  'inStock', 'isAvailable'], None)
    if available is None:
        available = (stock > 0)
    else:
        if isinstance(available, str):
            available = available.strip().lower() not in ('false', '0', 'no', 'off', 'unavailable', 'out_of_stock')
        else:
            available = bool(available)
    if not available:
        stock = 0
    unlimited = p.get('unlimited') is True
    if unlimited and available:
        stock = 999999
    # الرمز المميّز (premium)
    emoji_id = _ext_deep_get(p, ['emoji_custom_id', 'custom_emoji_id', 'emoji_id',
                                 'customEmojiId', 'premium_emoji_id', 'tg_emoji_id'], None)
    # لو الرمز داخل emoji_guide أو حقل HTML
    if not emoji_id:
        guide = p.get('emoji_guide') if isinstance(p.get('emoji_guide'), dict) else {}
        emoji_id = guide.get('custom_emoji_id') or guide.get('emoji_id')
    if not emoji_id:
        import re as _re
        for hk in ('name_ar_html', 'name_en_html', 'name_html', 'desc_ar_html', 'title_html'):
            hv = p.get(hk, '')
            if hv:
                m = _re.search(r'emoji-id="(\d+)"', str(hv))
                if m:
                    emoji_id = m.group(1)
                    break
    # الرمز العادي
    emoji_char = _ext_deep_get(p, ['emoji', 'icon', 'emoji_char'], '') or ''
    try:
        sell_f = float(sell_price or 0)
    except Exception:
        sell_f = 0.0
    try:
        cost_f = float(cost_price or 0)
    except Exception:
        cost_f = sell_f
    return {
        'ext_id': ext_id, 'name': str(name), 'desc': str(desc), 'desc_text': str(desc_text),
        'sell_price': sell_f, 'cost_price': cost_f,
        'stock': stock, 'available': available, 'unlimited': unlimited,
        'emoji_id': emoji_id, 'emoji_char': emoji_char,
    }


def _ext_is_insight(store):
    from urllib.parse import urlsplit
    return urlsplit(str(store.get('base_url', ''))).hostname == 'api.insightxpro.store'


def _insight_request(store, method, path, body=None, idem_key=None, test=False):
    """Insight Store v1 contract (docs reviewed 2026-09-19)."""
    headers = _net_catalog_headers(store, path) if method == 'GET' else _ext_api_headers(store)
    payload = dict(body or {})
    if test:
        headers['X-Test-Mode'] = 'true'
    if idem_key:
        headers['Idempotency-Key'] = idem_key
        payload['idempotency_key'] = idem_key
    purchase = method == 'POST' and path == '/orders' and not test
    if purchase:
        if not idem_key:
            return False, {'error': 'idempotency key required'}
        try:
            db.ext_request_attempts.update_one({'_id': idem_key}, {'$setOnInsert': {
                'store_id': str(store['_id']), 'body': payload,
                'status': 'pending', 'created_at': int(time.time())}}, upsert=True)
        except Exception:
            return False, {'error': 'could not persist order reference; request not sent'}
    try:
        response = requests.request(method, 'https://api.insightxpro.store/api/v1' + path,
            headers=headers, json=payload if method in ('POST', 'PATCH') else None,
            timeout=60 if purchase else 20, allow_redirects=False)
        if method == 'GET' and path == '/products':
            logger.info('[EXT_SYNC] catalog response bytes=%d status=%d',
                        len(response.content), response.status_code)
        if response.status_code == 304 and method == 'GET':
            cached = _net_catalog_304(store, path)
            return (cached is not None), cached
        data = response.json()
        if not isinstance(data, dict):
            raise ValueError('unexpected response format')
        if response.status_code == 200:
            if path == '/products' and method == 'GET':
                if not isinstance(data.get('products'), list) or any(
                        not isinstance(item, dict) or 'id' not in item
                        for item in data['products']):
                    raise ValueError('invalid catalog response')
            if method == 'GET':
                _net_catalog_remember(store, path, response, data)
            if purchase:
                order = data.get('order', {})
                if (not isinstance(order, dict) or order.get('test')
                        or order.get('status') != 'completed'
                        or not order.get('order_id', order.get('id'))
                        or any(str(code).startswith('TEST-') for code in _ext_extract_codes(data))):
                    return False, {'uncertain': True, 'error': 'unconfirmed live order',
                                   'idempotency_key': idem_key}
                db.ext_request_attempts.update_one({'_id': idem_key},
                    {'$set': {'status': 'completed', 'response': data}})
            return True, data
        # No alternate-path retries on authentication/rate-limit errors.
        data['http_status'] = response.status_code
        if purchase and response.status_code not in (400, 401, 403, 404, 429, 500, 503):
            data['uncertain'] = True
        return False, data
    except Exception as exc:
        logger.warning('[INSIGHT] %s %s failed: %s', method, path, type(exc).__name__)
        return False, {'error': 'connection or response error', 'uncertain': purchase,
                       'idempotency_key': idem_key}


def _ext_hold_uncertain_order(uid, order_rec, response, lang):
    """Keep an ambiguous charge pending for reconciliation, never auto-refund it."""
    order_rec.update(status='pending_verification', error=str(response)[:300])
    db.ext_orders.insert_one(order_rec)
    bot.send_message(uid, "⏳ طلبك قيد التحقق. لا تكرر الشراء؛ لم يُحسم رد المتجر بعد."
                     if lang != 'en' else
                     "⏳ Your order is being verified. Do not repeat the purchase.")
    notify_admins("⚠️ طلب Insight يحتاج التحقق قبل التسليم أو رد الرصيد.\n"
                  + "User: " + str(uid) + "\nReference: " + str(order_rec['idempotency_key']))


def _ext_api_headers(store):
    """يبني headers المصادقة — يدعم كل تنسيقات المتاجر."""
    key = store.get('api_key', '')
    return {
        'Authorization': f'Bearer {key}',
        'X-API-Key': key,
        'X-Shop-API-Key': key,   # متاجر shop-api
        'Content-Type': 'application/json',
    }


def _ext_api_base(store):
    """يحدdد الـ base URL مع الـ prefix الصحيح.
    يدعم متاجر بمسD /api/v1 أو /shop-api/v1 (أو المستخدم كتبه كاملاً)."""
    base = str(store.get('base_url', '')).rstrip('/')
    # لو المستخدم كتب الـ prefix في الـ URL، نستخدمه كما هو
    if '/api/v1' in base or '/shop-api/v1' in base:
        return base
    # وإلا نستخدم الـ prefix المكتشف/المحفوظ
    prefix = store.get('api_prefix', '')
    if prefix:
        return base + prefix
    return base  # سيُكتشف لاحقاً


def _ext_api_diagnose(store):
    """يشخّص الاتصال بالمتجر — يرجّع تقريراً مفصّلاً عن كل محاولة."""
    if _ext_is_insight(store):
        ok, data = _insight_request(store, 'GET', '/balance')
        return '✅ Insight API connected' if ok else str(data)
    base = str(store.get('base_url', '')).rstrip('/')
    report = [f"🌐 Base URL: {base}"]
    if not base.startswith('http'):
        report.append("🚨 الـ URL لا يبدأ بـ http/https!")
        return "\n".join(report)
    if '/api/v1' in base or '/shop-api/v1' in base:
        prefixes = ['']
    else:
        prefixes = ['/api/v1', '/shop-api/v1', '/api', '/v1', '/shop-api', '']
    key = store.get('api_key', '')
    report.append(f"🔑 المفتاح: {key[:10]}...{key[-4:] if len(key) > 14 else ''}")
    report.append("")
    for prefix in prefixes:
        url = f"{base}{prefix}/products"
        try:
            r = requests.get(url, headers=_ext_api_headers(store), timeout=12)
            report.append(f"• {prefix or '(بلا)'}/products → HTTP {r.status_code}")
            if r.status_code == 200:
                report.append(f"  ✅ نجح! الرد: {str(r.text)[:150]}")
                return "\n".join(report)
            elif r.status_code == 401:
                report.append(f"  🔑 401 = المفتاح خطأ أو معطّل")
            elif r.status_code == 404:
                report.append(f"  ❓ 404 = المسار غير موجود (نجرّب غيره)")
            else:
                report.append(f"  ⚠️ {str(r.text)[:100]}")
        except requests.exceptions.Timeout:
            report.append(f"• {prefix or '(بلا)'}/products → ⏱ انتهى الوقت (المتجر بطيء/متوقف)")
        except requests.exceptions.ConnectionError as ce:
            report.append(f"• {prefix or '(بلا)'}/products → 🔌 فشل الاتصال (URL خطأ أو المتجر متوقف)")
            report.append(f"  {str(ce)[:100]}")
            break
        except Exception as e:
            report.append(f"• {prefix or '(بلا)'}/products → ❌ {str(e)[:100]}")
    report.append("")
    report.append("لم ينجح أي مسار. تحقق من الـ URL والمفتاح.")
    return "\n".join(report)


def _ext_api_get(store, path):
    """GET من متجر API خارجي — يكتشف الـ prefix تلقائياً. يرجّع JSON أو None."""
    if _ext_is_insight(store):
        ok, data = _insight_request(store, 'GET', path)
        return data if ok else None
    base = str(store.get('base_url', '')).rstrip('/')
    # المسارات المحتملة للـ prefix
    if '/api/v1' in base or '/shop-api/v1' in base:
        prefixes = ['']  # المستخدم كتبه كاملاً
    elif store.get('api_prefix') or store.get('api_prefix_known'):
        prefixes = [store.get('api_prefix', '')]  # مكتشف مسبقاً
    else:
        # نجرّب كل المسارات الشائعة للـ prefix
        prefixes = ['/api/v1', '/shop-api/v1', '/api', '/v1', '/shop-api',
                    '/store-api/v1', '/reseller/v1', '']
    for prefix in prefixes:
        url = f"{base}{prefix}{path}"
        try:
            r = requests.get(url, headers=_net_catalog_headers(store, path), timeout=15)
            if path == '/products':
                logger.info('[EXT_SYNC] catalog response bytes=%d status=%d',
                            len(r.content), r.status_code)
            if r.status_code == 304:
                return _net_catalog_304(store, path)
            if r.status_code == 200:
                # Remember root-prefix success so the next sync does not probe eight routes.
                if not store.get('api_prefix_known'):
                    try:
                        db.ext_stores.update_one({'_id': store['_id']},
                                                 {'$set': {'api_prefix': prefix, 'api_prefix_known': True}})
                        store['api_prefix'] = prefix
                        store['api_prefix_known'] = True
                    except Exception:
                        pass
                data = r.json()
                _net_catalog_remember(store, path, r, data)
                return data
            if r.status_code != 404:
                logger.warning(f"[EXT_API] GET {path} → {r.status_code}")
                return None  # Auth, rate limits and outages are not prefix-discovery failures.
        except Exception as e:
            logger.debug(f"[EXT_API] GET err: {e}")
            return None
    return None


def _ext_api_post(store, path, body, idem_key=None):
    """POST لمتجر API خارجي (طلب) — يستخdم الـ prefix المكتشف. يرجّع (ok, json|error_str)."""
    if path.rstrip('/') == '/orders':
        # A timeout can happen after the supplier has charged us. Never retry a
        # paid POST on another URL or report it as a definite refundable failure.
        return _api_external_supplier_order(
            store, body.get('product_id'), int(body.get('quantity', 1)),
            idem_key or ('tg_' + secrets.token_hex(16)))
    if _ext_is_insight(store):
        return _insight_request(store, 'POST', path, body, idem_key)
    base = str(store.get('base_url', '')).rstrip('/')
    if '/api/v1' in base or '/shop-api/v1' in base:
        prefixes = ['']
    elif store.get('api_prefix') or store.get('api_prefix_known'):
        prefixes = [store.get('api_prefix', '')]
    else:
        prefixes = ['/api/v1', '/shop-api/v1', '/api', '/v1', '/shop-api',
                    '/store-api/v1', '/reseller/v1', '']
    headers = _ext_api_headers(store)
    if idem_key:
        headers['Idempotency-Key'] = idem_key
    last_err = "unknown"
    for prefix in prefixes:
        url = f"{base}{prefix}{path}"
        try:
            r = requests.post(url, headers=headers, json=body, timeout=25)
            try:
                data = r.json()
            except Exception:
                data = {}
            if r.status_code in (200, 201):
                return True, data
            if r.status_code == 404:
                last_err = "404"
                continue  # نجرّب prefix آخر
            return False, str(data or r.status_code)
        except Exception as e:
            last_err = str(e)
    return False, last_err


def _ext_compute_sell_price(base_price, markup_type, markup_value):
    """يحسب سعر البيع حسب نوع التسعير."""
    try:
        bp = float(base_price or 0)
        mv = float(markup_value or 0)
        if markup_type == 'percent':
            return round(bp * (1 + mv / 100.0), 2)
        if markup_type == 'fixed':
            return round(bp + mv, 2)
        if markup_type == 'manual':
            return round(mv, 2)  # السعر اليدوي هو القيمة نفسها
    except Exception:
        pass
    return round(float(base_price or 0), 2)


