@bot.callback_query_handler(func=lambda call: call.data.startswith("ext_pok_"))
@admin_required
def ext_pick_confirm(call):
    """يضيف المنتجات المختارة (الخضراء) فقط — كمنتجات عادية."""
    try: bot.answer_callback_query(call.id, "⏳ جاري الإضافة...")
    except Exception: pass
    sid = call.data.replace("ext_pok_", "")
    try:
        store = db.ext_stores.find_one({'_id': ObjectId(sid)})
    except Exception:
        store = None
    if not store:
        bot.send_message(call.message.chat.id, "❌ المتجر غير موجود.")
        return
    picked = set(store.get('_pick_selected', []))
    if not picked:
        bot.send_message(call.message.chat.id, "⚠️ لم تختr أي منتج.")
        return
    data = _ext_api_get(store, '/products')
    prods = _ext_parse_products(data)
    _def_mt = store.get('default_markup_type', 'percent')
    _def_mv = store.get('default_markup_value', 0)
    added = 0
    for p in prods:
        _f = _ext_extract_fields(p)
        ext_id = _f['ext_id']
        if ext_id not in picked:
            continue
        existing = db.ext_products.find_one({'store_id': sid, 'ext_id': ext_id})
        if existing:
            continue  # مضاف مسبقاً
        _sell = _ext_compute_sell_price(_f['cost_price'], _def_mt, _def_mv)
        doc = {
            'store_id': sid, 'ext_id': ext_id, 'name': _f['name'],
            'desc': _f['desc'], 'desc_text': _f['desc_text'],
            'desc_en_html': _f['desc'], 'desc_ar_html': _f['desc'],
            'base_price': _f['sell_price'], 'cost_price': _f['cost_price'],
            'emoji_id': _f['emoji_id'], 'emoji_char': _f['emoji_char'],
            'stock': _f['stock'],
            'markup_type': _def_mt, 'markup_value': _def_mv,
            'sell_price': _sell, 'hidden': False, 'raw': p,
        }
        doc['_new_notice'] = __import__('uuid').uuid4().hex
        res = db.ext_products.insert_one(doc)
        added += 1
        try:
            _ext_flush_new_notice(dict(doc, _id=res.inserted_id))
        except Exception:
            logger.exception('New product announcement saved for retry')
        # بثّ منتج جديد (للعملاء + المستخدمين) — مثل المنتج العادي
        try:
            _emit_event('product.created', {
                'product_id': f"ext_{res.inserted_id}",
                'name_ar': _f['name'], 'name_en': _f['name'],
                'price': _sell, 'is_manual': False, 'is_hidden': False,
                'stock': _f['stock'], 'description': _f['desc'],
                'emoji': _f['emoji_char'], 'emoji_custom_id': _f['emoji_id'],
                'source': 'external_api',
            }, product_id=f"ext_{res.inserted_id}")
        except Exception:
            pass
    # نمسح الاختيار المؤقت
    db.ext_stores.update_one({'_id': ObjectId(sid)}, {'$unset': {'_pick_selected': ''}})
    markup = InlineKeyboardMarkup()
    markup.add(InlineKeyboardButton("📦 عرض المنتجات", callback_data=f"ext_prods_{sid}_0"))
    markup.add(InlineKeyboardButton("🔙 رجوع", callback_data=f"ext_store_{sid}"))
    bot.send_message(call.message.chat.id,
        f"✅ <b>تمت إضافة {added} منتج</b> كمنتجات عادية!\n\n"
        f"تظهر الآن في متجرك للزبائن بكل خصائص المنتج العادي.",
        parse_mode="HTML", reply_markup=markup)


@bot.callback_query_handler(func=lambda call: call.data.startswith("ext_prods_"))
@admin_required
def ext_list_products(call):
    """يعرض منتجات المتجر (صفحات) مع حالة الإخفاء والسعر."""
    try: bot.answer_callback_query(call.id)
    except Exception: pass
    raw = call.data.replace("ext_prods_", "")
    sid, _, page_s = raw.rpartition('_')
    page = int(page_s) if page_s.isdigit() else 0
    PER = 8
    prods = list(db.ext_products.find({'store_id': sid}).skip(page * PER).limit(PER))
    total = db.ext_products.count_documents({'store_id': sid})
    markup = InlineKeyboardMarkup(row_width=1)
    for p in prods:
        pid = str(p['_id'])
        eye = "👁" if not p.get('hidden') else "🚫"
        price = p.get('sell_price', p.get('base_price', 0))
        nm = str(p.get('name', ''))[:22]
        markup.add(InlineKeyboardButton(f"{eye} {nm} — ${price:.2f}", callback_data=f"ext_p_{pid}"))
    # تنقّل الصفحات
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton("⬅️", callback_data=f"ext_prods_{sid}_{page-1}"))
    if (page + 1) * PER < total:
        nav.append(InlineKeyboardButton("➡️", callback_data=f"ext_prods_{sid}_{page+1}"))
    if nav:
        markup.row(*nav)
    markup.add(InlineKeyboardButton("🔙 رجوع", callback_data=f"ext_store_{sid}"))
    txt = f"📦 <b>منتجات المتجر</b> ({total})\nصفحة {page+1}"
    try:
        bot.edit_message_text(txt, call.message.chat.id, call.message.message_id,
                              parse_mode="HTML", reply_markup=markup)
    except Exception:
        bot.send_message(call.message.chat.id, txt, parse_mode="HTML", reply_markup=markup)


@bot.callback_query_handler(func=lambda call: call.data.startswith("ext_p_") and not call.data.startswith("ext_prods_"))
@admin_required
def ext_product_detail(call):
    """تفاصيل منتج API: الاسم، الوصف، الرمز، السعر، وأزرار التعديل/الإخفاء."""
    try: bot.answer_callback_query(call.id)
    except Exception: pass
    pid = call.data.replace("ext_p_", "")
    try:
        p = db.ext_products.find_one({'_id': ObjectId(pid)})
    except Exception:
        p = None
    if not p:
        bot.send_message(call.message.chat.id, "❌ المنتج غير موجود.")
        return
    mt = p.get('markup_type', 'percent')
    mv = p.get('markup_value', 0)
    mt_label = {'percent': f'نسبة +{mv}%', 'fixed': f'ثابت +${mv}', 'manual': 'سعر يدوي'}.get(mt, mt)
    emoji_line = f"✨ رمز مميّز: <code>{html.escape(str(p.get('emoji_id')))}</code>\n" if p.get('emoji_id') else ""
    mt_label = html.escape(str(mt_label))
    hidden = p.get('hidden', False)
    # رابط المنتج (deep link) — مثل المنتج العادي
    bot_username = get_bot_username()
    link = f"https://t.me/{bot_username}?start=vext_{pid}"
    # نعرض الاسم والوصف بالـ HTML الأصلي (فيه رموز <tg-emoji> البريميوم)
    _name = str(p.get('name', ''))
    _desc = str(_ext_description_for_lang(p, get_lang(call.from_user.id)))
    def _has_html(s):
        return '<tg-emoji' in s or '<b>' in s or '<i>' in s or '<a' in s or '<code>' in s
    name_disp = _ext_safe_product_html(_name, 200)
    desc_disp = _ext_safe_product_html(_desc, 2400)
    icon_prefix = ""
    if p.get('emoji_id') and '<tg-emoji' not in _name:
        icon_prefix = f'<tg-emoji emoji-id="{html.escape(str(p["emoji_id"]), quote=True)}">{html.escape(str(p.get("emoji_char","✨")))}</tg-emoji> '
    txt = (
        f"{icon_prefix}<b>{name_disp}</b>\n\n"
        f"{emoji_line}"
        f"📝 {desc_disp}\n\n"
        f"💵 سعر API الأصلي: <b>${float(p.get('base_price',0)):.2f}</b>\n"
        f"🏷 التسعير: {mt_label}\n"
        f"💰 سعر البيع: <b>${float(p.get('sell_price',0)):.2f}</b>\n"
        f"📊 المخزون: <b>{_ext_stock_label(p)}</b>\n"
        f"👁 الحالة: {'🚫 مخفي' if hidden else '✅ ظاهر'}\n\n"
        f"🔗 <b>رابط المنتج:</b>\n<code>{html.escape(link)}</code>" + _notice_admin_links('ext_' + str(pid))
    )
    markup = InlineKeyboardMarkup(row_width=2)
    markup.add(
        InlineKeyboardButton("✏️ تعديل السعر", callback_data=f"ext_edit_{pid}"),
        InlineKeyboardButton("🚫 إخفاء" if not hidden else "👁 إظهار", callback_data=f"ext_hide_{pid}")
    )
    markup.add(
        InlineKeyboardButton("✏️ تعديل الاسم", callback_data=f"ext_editname_{pid}"),
        InlineKeyboardButton("📝 تعديل الوصف العربي", callback_data=f"ext_editdesc_ar_{pid}"),
        InlineKeyboardButton("📝 Edit English description", callback_data=f"ext_editdesc_en_{pid}")
    )
    markup.add(InlineKeyboardButton("📁 إضافة لمجلد", callback_data=f"ext_setcat_{pid}"))
    sid = p.get('store_id', '')
    markup.add(InlineKeyboardButton("🔙 رجوع", callback_data=f"ext_prods_{sid}_0"))
    try:
        bot.edit_message_text(txt, call.message.chat.id, call.message.message_id,
                              parse_mode="HTML", reply_markup=markup)
    except Exception as exc:
        if "message is not modified" in str(exc).lower():
            return
        if "parse entities" in str(exc).lower():
            # Do not retry the rejected HTML unchanged.
            txt = html.escape(txt)
        try:
            bot.send_message(call.message.chat.id, txt, parse_mode="HTML", reply_markup=markup)
        except Exception:
            logger.exception("[EXT] Failed to display admin product %s", pid)


@bot.callback_query_handler(func=lambda call: call.data.startswith("ext_hide_"))
@admin_required
def ext_toggle_hide(call):
    """يبدّل إخفاء/إظهار منتج API."""
    pid = call.data.replace("ext_hide_", "")
    try:
        p = db.ext_products.find_one({'_id': ObjectId(pid)})
    except Exception:
        p = None
    if not p:
        return
    new_hidden = not p.get('hidden', False)
    db.ext_products.update_one({'_id': p['_id']}, {'$set': {'hidden': new_hidden}})
    # 🔔 بثّ للمطوّرين: إظهار = منتج متاح، إخفاء = حُذف من العرض
    try:
        if new_hidden:
            _emit_event('product.updated', {
                'source': 'external_api', 'name': p.get('name', ''),
                'available': False,
            }, product_id=f"ext_{p['_id']}")
        else:
            _emit_event('product.created', {
                'source': 'external_api', 'name': p.get('name', ''),
                'price': p.get('sell_price', p.get('base_price')),
                'description': p.get('desc', ''), 'stock': p.get('stock', 0),
                'available': True,
            }, product_id=f"ext_{p['_id']}")
    except Exception:
        pass
    try:
        bot.answer_callback_query(call.id, "🚫 أُخفي" if new_hidden else "👁 أُظهر")
    except Exception:
        pass
    call.data = f"ext_p_{pid}"
    ext_product_detail(call)


