# ============================================================
# 🔗 دوال مساعدة: بحث الأدمن عن هاش على الشبكة (TON / LTC)
# ============================================================
# ملاحظة مهمة: إيداعات TON و LTC تروح لمحفظة البوت مباشرة على السلسلة،
# مو لـ Binance. فبحث الأدمن لازم يفحص شبكة TON (TONCenter/TonAPI)
# وشبكة LTC (litecoinspace/blockcypher) — مو Binance فقط.

def _tx_hash_to_bytes(h):
    """يحوّل هاش معاملة (hex أو base64/base64url) إلى 32 byte للمقارنة الموحّدة.

    السبب: مستكشفات TON (Tonviewer/Tonscan) تعرض الهاش بصيغة hex (64 حرف)،
    بينما TONCenter API يرجّعه بصيغة base64 (44 حرف). نفس الهاش لكن ترميز مختلف،
    فلو قارنّا نصياً ما يتطابقان أبداً. نحوّل الاثنين لـ bytes ونقارن.
    يرجّع None لو ما قدر يفك الترميز."""
    if not h:
        return None
    s = str(h).strip().replace(' ', '').replace('\n', '')
    # 1) جرّب hex أولاً (64 حرف hex = 32 byte، مع أو بدون 0x)
    try:
        hs = s[2:] if s.lower().startswith('0x') else s
        if len(hs) in (64, 66) and all(c in '0123456789abcdefABCDEF' for c in hs):
            return bytes.fromhex(hs[:64] if len(hs) == 66 else hs)
    except Exception:
        pass
    # 2) جرّب base64 / base64url (نحوّل url-safe ونضيف padding)
    try:
        b = s.replace('-', '+').replace('_', '/')
        b += '=' * (-len(b) % 4)
        raw = base64.b64decode(b)
        if len(raw) == 32:
            return raw
    except Exception:
        pass
    return None


def _tx_hash_matches(user_hash, api_hash):
    """يقارن هاشين مع مراعاة اختلاف الترميز (hex ضد base64) في TON.
    - يقارن الـ bytes لو أمكن (الأدق والأهم لـ TON)
    - يرجع للمقارنة النصية (substring) كخطة بديلة"""
    if not user_hash or not api_hash:
        return False
    ub = _tx_hash_to_bytes(user_hash)
    ab = _tx_hash_to_bytes(api_hash)
    if ub is not None and ab is not None and ub == ab:
        return True
    # fallback نصي (يغطي الحالات اللي فيها الهاش مو 32 byte قياسي)
    u = str(user_hash).strip().lower().replace(' ', '')
    a = str(api_hash).strip().lower().replace(' ', '')
    if u.startswith('0x'):
        u = u[2:]
    if a.startswith('0x'):
        a = a[2:]
    if not u or not a:
        return False
    return u == a or u in a or a in u


def _lookup_trc20_tx_by_hash(txid):
    """يستعلم عن معاملة TRON بهاشها مباشرة عبر TronScan.
    يرجّع dict فيه (amount, to, confirmed) أو None."""
    txid = str(txid).strip()
    if txid.lower().startswith('0x'):
        txid = txid[2:]
    data = _http_json("https://apilist.tronscanapi.com/api/transaction-info",
                      params={'hash': txid})
    if not data:
        return None
    try:
        trc = data.get('trc20TransferInfo') or []
        if isinstance(trc, dict):
            trc = [trc]
        for t in trc:
            contract = str(t.get('contract_address', '')).lower()
            if contract != USDT_CONTRACT_TRC20.lower():
                continue
            dec = int(t.get('decimals', 6))
            amt = int(t.get('amount_str', t.get('amount', 0))) / (10 ** dec)
            return {
                'amount': round(amt, 6),
                'to': str(t.get('to_address', '')),
                'confirmed': data.get('confirmed', True),
            }
    except Exception as e:
        logger.debug(f"trc20 hash lookup parse err: {e}")
    return None


def _lookup_bep20_tx_by_hash(txid):
    """يستعلم عن معاملة USDT على BSC بهاشها.
    أولاً عبر RPC العام (بلا مفتاح — مثل TON/LTC)، ثم Etherscan V2 احتياطاً."""
    # 1️⃣ RPC العام (بلا مفتاح)
    r = _lookup_bep20_via_rpc(txid)
    if isinstance(r, dict) and not r.get('_conn_fail'):
        if r.get('amount', 0) > 0:
            return r
        # RPC رد لكن ما فيه تحويل USDT مطابق → غير موجودة
        return None
    # لو RPC فشل اتصالاً، نجرّب V2 قبل ما نستسلم
    txid = str(txid).strip()
    if not txid.startswith('0x'):
        txid = '0x' + txid
    txid_l = txid.lower()
    api_key = get_setting('bscscan_api_key', '') or os.getenv('BSCSCAN_API_KEY', '')

    addr = get_setting('usdt_bep20_address', '')
    if addr and addr != 'Not Set':
        params = {
            'chainid': 56, 'module': 'account', 'action': 'tokentx',
            'contractaddress': USDT_CONTRACT_BEP20,
            'address': addr, 'page': 1, 'offset': 100, 'sort': 'desc',
        }
        if api_key:
            params['apikey'] = api_key
        data = _http_json("https://api.etherscan.io/v2/api", params=params)
        if data is None:
            return {'_conn_fail': True}
        if data.get('status') == '1' and isinstance(data.get('result'), list):
            for tx in data['result']:
                if str(tx.get('hash', '')).lower() != txid_l:
                    continue
                if str(tx.get('contractAddress', '')).lower() != USDT_CONTRACT_BEP20.lower():
                    continue
                dec = int(tx.get('tokenDecimal', 18))
                amt = int(tx.get('value', 0)) / (10 ** dec)
                return {'amount': round(amt, 6), 'to': str(tx.get('to', '')), 'confirmed': True}
    return None


def _admin_search_usdt_onchain(query):
    """يبحث عن هاش تحويل USDT على البلوكشين (TRC20 + BEP20).
    أولاً بالبحث المباشر بالهاش (الأضمن)، ثم في قائمة العنوان كاحتياط."""
    q = str(query).strip()

    # 1️⃣ بحث مباشر بالهاش (يجد المعاملة حتى لو قديمة أو صادرة)
    #    TRC20: هاش بلا 0x، طوله 64 hex
    def _strip0x(s):
        s = str(s).strip()
        return s[2:] if s.lower().startswith('0x') else s
    q_clean = _strip0x(q).lower()
    if len(q_clean) >= 40:
        # جرّب TRON
        conn_ok = False
        try:
            r = _lookup_trc20_tx_by_hash(q)
            if r and r.get('amount', 0) > 0:
                return {
                    'coin': 'USDT', 'label': '🟢 USDT (TRC20)',
                    'amount_usd': round(r['amount'], 4), 'crypto_amount': r['amount'],
                    'hash': q, 'when': 0, 'source_addr': r.get('to', ''),
                }
            if r is not None:
                conn_ok = True
        except Exception as e:
            logger.debug(f"trc20 direct err: {e}")
        # جرّب BSC
        try:
            r = _lookup_bep20_tx_by_hash(q)
            if isinstance(r, dict) and r.get('_conn_fail'):
                # فشل اتصال BscScan
                if not conn_ok:
                    return {'_conn_fail': True}
            elif r and r.get('amount', 0) > 0:
                return {
                    'coin': 'USDT_BEP20', 'label': '🟡 USDT (BEP20)',
                    'amount_usd': round(r['amount'], 4), 'crypto_amount': r['amount'],
                    'hash': q,
                    'when': (r.get('time_ms', 0) // 1000) if r.get('time_ms') else 0,
                    'source_addr': r.get('from', '') or r.get('to', ''),
                }
        except Exception as e:
            logger.debug(f"bep20 direct err: {e}")

    # 2️⃣ احتياط: البحث في قائمة العنوان (للهاش الجزئي)
    def _match(txid):
        t = _strip0x(str(txid)).lower()
        return t == q_clean or (len(q_clean) >= 16 and (q_clean in t or t in q_clean))

    try:
        addr = get_setting('usdt_address', '')
        if addr and addr != 'Not Set':
            for tx_id, amount, t_ms in _fetch_trc20_usdt_deposits(addr, limit=50):
                if _match(tx_id):
                    return {
                        'coin': 'USDT', 'label': '🟢 USDT (TRC20)',
                        'amount_usd': round(amount, 4), 'crypto_amount': amount,
                        'hash': tx_id, 'when': t_ms // 1000 if t_ms else 0, 'source_addr': '',
                    }
    except Exception as e:
        logger.debug(f"admin usdt trc20 search err: {e}")

    try:
        addr = get_setting('usdt_bep20_address', '')
        if addr and addr != 'Not Set':
            for tx_id, amount, t_ms in _fetch_bep20_usdt_deposits(addr, limit=50):
                if _match(tx_id):
                    return {
                        'coin': 'USDT_BEP20', 'label': '🟡 USDT (BEP20)',
                        'amount_usd': round(amount, 4), 'crypto_amount': amount,
                        'hash': tx_id, 'when': t_ms // 1000 if t_ms else 0, 'source_addr': '',
                    }
    except Exception as e:
        logger.debug(f"admin usdt bep20 search err: {e}")

    return None


def _admin_search_ton_tx(query):
    """يبحث عن هاش TON في شبكة TON (TONCenter ثم TonAPI) مقابل محفظة البوت.

    يرجّع dict:
      - {'is_sender': True, 'hash': ...}                لو الحوالة صادرة من محفظتنا
      - {'received_ton': float, 'utime': int, 'hash':..., 'source_addr':...}  لو إيداع
      - None لو ما لقى شيء
    """
    wallet_address = get_setting('ton_address')
    if not wallet_address or wallet_address == 'Not Set' or len(wallet_address) < 10:
        return None

    q = str(query).strip().replace(' ', '').replace('\n', '')

    # 1) TONCenter: آخر معاملات المحفظة
    try:
        res = requests.get(
            "https://toncenter.com/api/v2/getTransactions",
            params={"address": wallet_address, "limit": 100, "archival": "true"},
            timeout=15
        )
        if res.status_code == 200:
            data = res.json()
            if data.get("ok"):
                for tx in data.get("result", []):
                    tx_hash = tx.get("transaction_id", {}).get("hash", "")
                    if not _tx_hash_matches(q, tx_hash):
                        continue
                    in_msg = tx.get("in_msg", {}) or {}
                    source_addr = in_msg.get("source", "") or ""
                    if source_addr == wallet_address:
                        return {'is_sender': True, 'hash': tx_hash}
                    value_nano = int(in_msg.get("value", 0) or 0)
                    if value_nano <= 0:
                        continue
                    return {
                        'received_ton': value_nano / 1_000_000_000,
                        'utime': int(tx.get("utime", 0) or 0),
                        'hash': tx_hash,
                        'source_addr': source_addr,
                    }
    except Exception as e:
        logger.debug(f"[CHECK_TX] TONCenter list err: {e}")

    # 2) TonAPI (احتياطي)
    try:
        res2 = requests.get(
            f"https://tonapi.io/v2/blockchain/accounts/{wallet_address}/transactions",
            params={"limit": 100}, timeout=15
        )
        if res2.status_code == 200:
            for tx in res2.json().get("transactions", []):
                tx_hash = tx.get("hash", "")
                if not _tx_hash_matches(q, tx_hash):
                    continue
                in_msg = tx.get("in_msg", {}) or {}
                source = in_msg.get("source", {})
                source_addr = source.get("address", "") if isinstance(source, dict) else str(source or "")
                if source_addr == wallet_address:
                    return {'is_sender': True, 'hash': tx_hash}
                value_nano = int(in_msg.get("value", 0) or 0)
                if value_nano <= 0:
                    continue
                return {
                    'received_ton': value_nano / 1_000_000_000,
                    'utime': int(tx.get("utime", 0) or 0),
                    'hash': tx_hash,
                    'source_addr': source_addr,
                }
    except Exception as e:
        logger.debug(f"[CHECK_TX] TonAPI err: {e}")

    return None


def _admin_search_ltc_tx(query):
    """يبحث عن هاش LTC في الشبكة (litecoinspace ثم blockcypher) مقابل محفظة البوت.

    يرجّع dict:
      - {'is_sender': True, 'hash': ...}                          لو صادرة من محفظتنا
      - {'received_ltc': float, 'confirmed': bool, 'block_time': int, 'hash':...}  لو إيداع
      - None لو ما لقى / الهاش مو بصيغة LTC صالحة
    """
    wallet_address = get_setting('ltc_address')
    if not wallet_address or wallet_address == 'Not Set' or len(wallet_address) < 10:
        return None

    q = str(query).strip().replace(' ', '').replace('\n', '').lower()
    if q.startswith('0x'):
        q = q[2:]
    # هاش LTC/BTC = 64 حرف hex — لو مو كذا ما نتعب الـ API
    if not (len(q) == 64 and all(c in '0123456789abcdef' for c in q)):
        return None

    # 1) litecoinspace.org
    try:
        res = requests.get(f"https://litecoinspace.org/api/tx/{q}", timeout=10)
        if res.status_code == 200:
            data = res.json()
            for vin in data.get("vin", []):
                if vin.get("prevout", {}).get("scriptpubkey_address") == wallet_address:
                    return {'is_sender': True, 'hash': q}
            received = 0.0
            for vout in data.get("vout", []):
                if vout.get("scriptpubkey_address") == wallet_address:
                    received += float(vout.get("value", 0)) / 100000000.0
            if received > 0:
                return {
                    'received_ltc': received,
                    'block_time': int(data.get("status", {}).get("block_time", 0) or 0),
                    'confirmed': bool(data.get("status", {}).get("confirmed")),
                    'hash': q,
                }
    except Exception as e:
        logger.debug(f"[CHECK_TX] litecoinspace err: {e}")

    # 2) blockcypher (احتياطي)
    try:
        res2 = requests.get(f"https://api.blockcypher.com/v1/ltc/main/txs/{q}", timeout=10)
        if res2.status_code == 200:
            data2 = res2.json()
            for inp in data2.get("inputs", []):
                if wallet_address in inp.get("addresses", []):
                    return {'is_sender': True, 'hash': q}
            received = 0.0
            for output in data2.get("outputs", []):
                if wallet_address in output.get("addresses", []):
                    received += float(output.get("value", 0)) / 100000000.0
            if received > 0:
                return {
                    'received_ltc': received,
                    'block_time': 0,
                    'confirmed': (int(data2.get("confirmations", 0) or 0) >= 1),
                    'hash': q,
                }
    except Exception as e:
        logger.debug(f"[CHECK_TX] blockcypher err: {e}")

    return None


