@safe_next_step
def ad_check_tx_handle(message):
    """يفحص الهاش/Order ID في DB ويرجع النتيجة"""
    uid = message.from_user.id
    logger.info(f"[CHECK_TX] received from admin {uid}: text={(message.text or '')[:50]!r}")

    if not _is_admin_check(uid):
        logger.warning(f"[CHECK_TX] non-admin {uid} hit the handler")
        return
    
    text = (message.text or '').strip()
    if not text or text.lower() in ('/cancel', 'الغاء', 'إلغاء', 'cancel'):
        bot.send_message(uid, "❌ تم الإلغاء.")
        return
    
    # ننظف الـ text
    query = text.strip()
    query_norm = normalize_tx_id(query) if 'normalize_tx_id' in globals() else query.lower()
    
    bot.send_message(uid, f"🔍 جاري البحث عن: <code>{html.escape(query[:80])}</code>", parse_mode="HTML")
    
    # نبحث في used_transactions بأكثر من طريقة
    found = []
    seen_ids = set()  # عشان ما نكرر نفس النتيجة
    try:
        # 1) مطابقة كاملة (normalized)
        for r in db.used_transactions.find({'transaction_id': query_norm}).limit(5):
            if r['_id'] not in seen_ids:
                found.append(r); seen_ids.add(r['_id'])
        # 2) مطابقة كاملة (raw)
        if not found:
            for r in db.used_transactions.find({'transaction_id': query}).limit(5):
                if r['_id'] not in seen_ids:
                    found.append(r); seen_ids.add(r['_id'])
        # 3) regex - يحتوي
        if len(found) < 5:
            try:
                import re as _re_tx
                safe = _re_tx.escape(query[-20:] if len(query) > 20 else query)
                for r in db.used_transactions.find({'transaction_id': {'$regex': safe, '$options': 'i'}}).limit(5):
                    if r['_id'] not in seen_ids:
                        found.append(r); seen_ids.add(r['_id'])
                # 4) regex على remark/note كذلك
                for r in db.used_transactions.find({'remark': {'$regex': safe, '$options': 'i'}}).limit(5):
                    if r['_id'] not in seen_ids:
                        found.append(r); seen_ids.add(r['_id'])
            except Exception: pass

        # 5) 🆕 نبحث في balance_logs أيضاً (للإضافات اليدوية اللي حطها الأدمن بنوت)
        try:
            import re as _re_tx2
            safe2 = _re_tx2.escape(query[-20:] if len(query) > 20 else query)
            for r in db.balance_logs.find({
                '$or': [
                    {'note': query},
                    {'note': {'$regex': safe2, '$options': 'i'}}
                ]
            }).limit(5):
                # نحول لـ format يطابق used_transactions عشان العرض موحّد
                synth = {
                    '_id': r.get('_id'),
                    'transaction_id': f"[Manual Note] {r.get('note', '')[:50]}",
                    'user_id': r.get('user_id'),
                    'amount': r.get('amount', 0),
                    'method': f"Manual Gift by Admin ({r.get('type', '?')})",
                    'used_at': r.get('date', ''),
                    'remark': r.get('note', ''),
                    '_from_balance_logs': True
                }
                if synth['_id'] not in seen_ids:
                    found.append(synth); seen_ids.add(synth['_id'])
        except Exception as _be:
            logger.debug(f"balance_logs search err: {_be}")
    except Exception as e:
        bot.send_message(uid, f"❌ خطأ في البحث: {html.escape(str(e))}", parse_mode="HTML")
        return
    
    if not found:
        # 🆕 ما لقينا في DB — نفحص في Binance مباشرة
        # ممكن المعاملة وصلت لـ Binance لكن لسه ما عُولجت
        binance_match = None
        binance_source = None  # 'pay' أو 'deposit'
        try:
            import re as _re_b
            safe_b = _re_b.escape(query[-15:] if len(query) > 15 else query)
            pattern = _re_b.compile(safe_b, _re_b.IGNORECASE)

            # ⚡ تحسين السرعة: لو البحث هاش on-chain كامل (64 hex أو 66 مع 0x)،
            #    نتخطى فحص Binance Pay (لأنه يستخدم Order IDs مو هاشات) ونروح للإيداعات
            #    مباشرة. هذا يوفّر استدعاء بروكسي بطيء بلا فائدة.
            _q_hex = query.lower()[2:] if query.lower().startswith('0x') else query.lower()
            _is_onchain_hash = len(_q_hex) == 64 and all(c in '0123456789abcdef' for c in _q_hex)

            # 1) Binance Pay (Order ID / Transaction ID) — نتخطاه للهاش الكامل
            if not _is_onchain_hash:
                bot.send_message(uid, "🔍 لم تُسجَّل في النظام... جاري الفحص في Binance Pay مباشرة...")
                transactions = _binance_pay_request()
                if transactions:
                    for tx in transactions:
                        tx_id_fields = [
                            str(tx.get('orderId', '') or ''),
                            str(tx.get('transactionId', '') or ''),
                            str(tx.get('bizOrderNo', '') or ''),
                        ]
                        if any(pattern.search(f) for f in tx_id_fields):
                            binance_match = tx
                            binance_source = 'pay'
                            break
            else:
                bot.send_message(uid, "🔍 لم تُسجَّل في النظام... جاري الفحص في إيداعات Binance مباشرة...")

            # 2) Binance Deposits (TX Hash للكريبتو)
            #    🔧 بحث إيداعات متين يعالج أسباب "موجودة في بينانس لكن ما تُلقى":
            #      • كان يلفّ على قائمة عملات ثابتة (SOL/XRP/... خارجها تُفقد)
            #      • كان يفحص أول 50 سجل فقط (لو فيه إيداعات كثيرة، القديم يُفقد)
            #      • كان max_retries=2 (لو فشل البروكسي مرتين → يتخطى بصمت)
            #      • النافذة الزمنية الافتراضية قد تكون قصيرة (لو الإيداع أقدم يُفقد)
            #    الحل: استدعاء واحد لكل العملات + نافذة 90 يوم + صفحات (offset) + احتياطيات.
            if not binance_match:
                _now_ms = int(time.time() * 1000)
                _start_ms = _now_ms - (90 * 24 * 60 * 60 * 1000) + 120000  # 90 يوم ناقص دقيقتين

                def _fetch_deposits(with_window=True, coin=None, retries=5):
                    """يجلب سجلات الإيداع (كل العملات لو coin=None) عبر صفحات متعددة."""
                    out = []
                    offset = 0
                    for _pg in range(5):  # حتى 5000 سجل
                        kw = {'offset': offset, 'limit': 1000}
                        if with_window:
                            kw['startTime'] = _start_ms
                        if coin:
                            kw['coin'] = coin
                        try:
                            page = execute_binance_call(
                                lambda c, _k=dict(kw): c.get_deposit_history(**_k),
                                max_retries=retries
                            )
                        except Exception:
                            page = None
                        if not page:
                            break
                        if coin:
                            for _d in page:
                                _d.setdefault('_coin', coin)
                        out.extend(page)
                        if len(page) < 1000:
                            break  # آخر صفحة
                        offset += 1000
                    return out

                # (أ) الأساسي: كل العملات + نافذة 90 يوم
                all_deposits = _fetch_deposits(with_window=True, coin=None)
                # (ب) لو رجع فاضي: كل العملات بالنافذة الافتراضية
                if not all_deposits:
                    all_deposits = _fetch_deposits(with_window=False, coin=None)
                # (ج) آخر احتياطي: أهم العملات فرادى (لو الاستدعاء الشامل فشل تماماً)
                if not all_deposits:
                    for coin in ('USDT', 'BTC', 'ETH', 'BNB', 'TRX', 'LTC', 'SOL', 'XRP', 'DOGE', 'TON'):
                        part = _fetch_deposits(with_window=True, coin=coin, retries=2)
                        if part:
                            all_deposits.extend(part)

                if all_deposits:
                    for d in all_deposits:
                        tx_hash = str(d.get('txId', '') or '')
                        # مطابقة قوية: نصياً (regex) أو bytes (hex/base64)
                        if tx_hash and (pattern.search(tx_hash) or _tx_hash_matches(query, tx_hash)):
                            d['_coin'] = d.get('_coin') or d.get('coin', 'CRYPTO')
                            binance_match = d
                            binance_source = 'deposit'
                            break
        except Exception as be:
            logger.debug(f"Binance direct check err: {be}")

        if binance_match:
            # ✅ موجودة في Binance لكن غير معالجة
            if binance_source == 'pay':
                order_id = str(binance_match.get('orderId') or binance_match.get('transactionId') or '?')
                # نحوّل للدولار حسب العملة (بيتكوين/BNB/... مو دولار!)
                _pay_cur = _binance_tx_currency(binance_match) or 'USDT'
                _pay_usd, _ = binance_amount_to_usd(binance_match.get('amount') or 0, _pay_cur)
                amount_b = _pay_usd if (_pay_usd is not None) else 0.0
                note_b = str(binance_match.get('note') or '').strip()
                if _pay_cur not in USD_STABLECOINS:
                    note_b = (note_b + f" | أصل: {binance_match.get('amount')} {_pay_cur}").strip(' |')
                payer = binance_match.get('payerInfo') or {}
                payer_name = payer.get('name', '') if isinstance(payer, dict) else ''
                tx_time = int(binance_match.get('transactionTime') or 0)
                time_str = datetime.datetime.fromtimestamp(tx_time / 1000).strftime('%Y-%m-%d %H:%M') if tx_time else '?'
                source_label = "🟡 Binance Pay" if _pay_cur in USD_STABLECOINS else f"🟡 Binance Pay ({_pay_cur}→USD)"
            else:  # deposit
                order_id = str(binance_match.get('txId') or '?')
                coin_name = binance_match.get('_coin', 'CRYPTO')
                # نحوّل للدولار حسب عملة الإيداع
                _dep_usd, _ = binance_amount_to_usd(binance_match.get('amount') or 0, coin_name)
                amount_b = _dep_usd if (_dep_usd is not None) else 0.0
                note_b = ''
                if coin_name not in USD_STABLECOINS:
                    note_b = f"أصل: {binance_match.get('amount')} {coin_name}"
                payer_name = binance_match.get('address', '')[:20] + '...' if binance_match.get('address') else ''
                tx_time = int(binance_match.get('insertTime') or 0)
                time_str = datetime.datetime.fromtimestamp(tx_time / 1000).strftime('%Y-%m-%d %H:%M') if tx_time else '?'
                source_label = f"💎 Crypto Deposit ({coin_name})"

            pending_credit_id = f"pc_{int(time.time())}_{order_id[-10:]}"
            # نحفظ المبلغ بالكريبتو والعملة عشان لو فشل السعر نعيد الحساب وقت الإضافة
            try:
                _crypto_amount = float(binance_match.get('amount') or 0)
            except Exception:
                _crypto_amount = 0.0
            _crypto_amount = abs(_crypto_amount)
            if binance_source == 'pay':
                _crypto_currency = _binance_tx_currency(binance_match) or 'USDT'
            else:
                _crypto_currency = binance_match.get('_coin') or binance_match.get('coin') or 'CRYPTO'

            db.pending_admin_credits.insert_one({
                '_id': pending_credit_id,
                'tx_id': normalize_tx_id(order_id),
                'amount': amount_b,
                'crypto_amount': _crypto_amount,
                'crypto_currency': _crypto_currency,
                'note': note_b,
                'payer_name': payer_name,
                'source': binance_source,
                'created_at': datetime.datetime.utcnow(),
                'admin_id': uid
            })

            text = (
                f"⚠️ <b>المعاملة موجودة لكن غير مُعالَجَة!</b>\n\n"
                f"📡 <b>المصدر:</b> {source_label}\n"
                f"🆔 <b>ID/Hash:</b> <code>{html.escape(order_id[:60])}</code>\n"
            )
            if amount_b and amount_b > 0:
                text += f"💰 <b>المبلغ:</b> <b>${amount_b:.4f}</b>\n"
            else:
                # فشل جلب السعر — نعرض الكريبتو بوضوح بدل $0.00
                text += (
                    f"💰 <b>المبلغ:</b> <code>{_crypto_amount:.8f} {html.escape(str(_crypto_currency))}</code>\n"
                    f"⚠️ <i>تعذّر تحويله للدولار الآن — سيُعاد حسابه عند الإضافة، أو أدخله يدوياً.</i>\n"
                )
            if payer_name:
                text += f"👤 <b>المرسل:</b> <code>{html.escape(payer_name)}</code>\n"
            text += f"📅 <b>الوقت:</b> {time_str}\n"
            if note_b:
                text += f"📝 <b>Note:</b> <code>{html.escape(note_b)}</code>\n"
            text += "\n💡 <i>المبلغ متاح للإضافة لمستخدم.</i>"

            markup = InlineKeyboardMarkup()
            _btn_label = (f"💰 إضافة ${amount_b:.2f} لمستخدم"
                          if (amount_b and amount_b > 0)
                          else "💵 إضافة لمستخدم (تحديد المبلغ)")
            markup.add(InlineKeyboardButton(
                _btn_label,
                callback_data=f"credit_pending_{pending_credit_id}"
            ))
            bot.send_message(uid, text, parse_mode="HTML", reply_markup=markup)
            return

        # ============================================================
        # 🔗 ما لقينا في Binance — نفحص شبكات TON و LTC مباشرة (على السلسلة)
        # ============================================================
        # مهم: إيداعات TON/LTC تروح لمحفظة البوت على السلسلة، مو Binance.
        # فبدون هالفحص، الأدمن ما بيلقى أبداً هاش TON ولا LTC.
        onchain_match = None       # dict فيه coin/amount_usd/...
        onchain_is_sender = None   # (coin, hash) لو الحوالة صادرة من محفظتنا
        try:
            # --- 🟠 Bybit (سجلات داخلية + on-chain) ---
            if not onchain_match and not onchain_is_sender and bybit_is_configured():
                try:
                    by_r = admin_search_bybit_tx(query)
                except Exception:
                    by_r = None
                    bot.send_message(uid, '⚠️ تعذّر إكمال بحث Bybit؛ هذا لا يعني أن التحويل غير موجود. راجع /bybit_status وسجل [BYBIT].')
                if by_r:
                    if by_r.get('amount_usd'):
                        onchain_match = {
                            'coin': by_r.get('coin', 'USDT'),
                            'label': by_r.get('label', '🟠 Bybit'),
                            'amount_usd': by_r['amount_usd'],
                            'crypto_amount': by_r.get('crypto_amount', 0),
                            'hash': by_r.get('hash', query),
                            'when': int(by_r.get('when', 0) or 0) // 1000,
                            'source_addr': by_r.get('note', '') or '',
                        }
                    else:
                        bot.send_message(
                            uid,
                            f"⚠️ <b>لقيت العملية في Bybit</b> "
                            f"({by_r.get('crypto_amount', 0)} {html.escape(str(by_r.get('coin','')))}) "
                            f"لكن تعذّر تحويلها للدولار الآن.\n"
                            f"🆔 <code>{html.escape(str(by_r.get('hash', query))[:70])}</code>\n\n"
                            f"<i>جرّب بعد دقيقة، أو أضف الرصيد يدوياً من (شحن رصيد).</i>",
                            parse_mode="HTML"
                        )
                        return
            elif not bybit_is_configured():
                bot.send_message(uid, '⚠️ بحث Bybit متوقف أو مفاتيحه ناقصة. استخدم /bybit_status لمعرفة السبب.')

            bot.send_message(uid, "🔍 لم تُوجد في Binance... جاري الفحص في شبكات TON و LTC مباشرة...")

            # --- TON (TONCenter + TonAPI) ---
            ton_r = _admin_search_ton_tx(query) if not onchain_match else None
            if ton_r:
                if ton_r.get('is_sender'):
                    onchain_is_sender = ('TON', ton_r.get('hash', query))
                else:
                    ton_price = get_ton_price_usd()
                    if ton_price:
                        onchain_match = {
                            'coin': 'TON', 'label': '💎 Toncoin (TON)',
                            'amount_usd': round(ton_r['received_ton'] * ton_price, 4),
                            'crypto_amount': ton_r['received_ton'],
                            'hash': ton_r.get('hash', query),
                            'when': ton_r.get('utime', 0),
                            'source_addr': ton_r.get('source_addr', ''),
                        }
                    else:
                        # لقينا الحوالة بس سعر TON فشل — نبلّغ الأدمن بدل ما نقول "غير موجودة"
                        bot.send_message(
                            uid,
                            f"⚠️ <b>لقيت حوالة TON على الشبكة</b> "
                            f"({ton_r['received_ton']:.6f} TON) لكن تعذّر جلب سعر TON الآن.\n"
                            f"🆔 <code>{html.escape(str(ton_r.get('hash', query))[:70])}</code>\n\n"
                            f"<i>جرّب بعد دقيقة، أو أضف الرصيد يدوياً من (شحن رصيد).</i>",
                            parse_mode="HTML"
                        )
                        return

            # --- LTC (litecoinspace + blockcypher) — لو TON ما لقى ---
            if not onchain_match and not onchain_is_sender:
                ltc_r = _admin_search_ltc_tx(query)
                if ltc_r:
                    if ltc_r.get('is_sender'):
                        onchain_is_sender = ('LTC', ltc_r.get('hash', query))
                    else:
                        ltc_price = get_ltc_price_usd()
                        if ltc_price:
                            onchain_match = {
                                'coin': 'LTC', 'label': '🔵 Litecoin (LTC)',
                                'amount_usd': round(ltc_r['received_ltc'] * ltc_price, 4),
                                'crypto_amount': ltc_r['received_ltc'],
                                'hash': ltc_r.get('hash', query),
                                'when': ltc_r.get('block_time', 0),
                                'confirmed': ltc_r.get('confirmed', True),
                                'source_addr': '',
                            }
                        else:
                            bot.send_message(
                                uid,
                                f"⚠️ <b>لقيت حوالة LTC على الشبكة</b> "
                                f"({ltc_r['received_ltc']:.8f} LTC) لكن تعذّر جلب سعر LTC الآن.\n"
                                f"🆔 <code>{html.escape(str(ltc_r.get('hash', query))[:70])}</code>\n\n"
                                f"<i>جرّب بعد دقيقة، أو أضف الرصيد يدوياً من (شحن رصيد).</i>",
                                parse_mode="HTML"
                            )
                            return

            # --- 🔗 USDT على البلوكشين (TRC20 + BEP20) — لعناوين Trust Wallet ---
            if not onchain_match and not onchain_is_sender:
                bot.send_message(uid, "🔍 جاري الفحص في USDT على البلوكشين (TronScan + BscScan)...")
                usdt_r = _admin_search_usdt_onchain(query)
                if isinstance(usdt_r, dict) and usdt_r.get('_conn_fail'):
                    bot.send_message(
                        uid,
                        "⚠️ <b>تعذّر الاتصال بمستكشفات البلوكشين (TronScan/BscScan).</b>\n\n"
                        "السيرفر لا يصل إليها حالياً — لذلك لا يمكن البحث عن USDT.\n"
                        "الحلول:\n"
                        "• فعّل البروكسي في السيرفر\n"
                        "• تأكد أن السيرفر يصل الإنترنت الخارجي\n"
                        "• جرّب مرة أخرى بعد قليل\n\n"
                        "<i>هذه أيضاً سبب عدم وصول إيداعات USDT تلقائياً.</i>",
                        parse_mode="HTML")
                    return
                if usdt_r:
                    onchain_match = usdt_r

        except Exception as oe:
            logger.debug(f"[CHECK_TX] on-chain search err: {oe}")

        # حوالة صادرة من محفظتنا (مو إيداع)
        if onchain_is_sender:
            _coin, _hash = onchain_is_sender
            bot.send_message(
                uid,
                f"⚠️ <b>هذه حوالة صادرة من محفظتنا ({_coin}) — ليست إيداعاً.</b>\n\n"
                f"🆔 <code>{html.escape(str(_hash)[:70])}</code>\n\n"
                f"<i>لا يمكن إضافتها لمستخدم.</i>",
                parse_mode="HTML"
            )
            return

        # ✅ لقينا إيداع على الشبكة لكنه غير معالَج — نعرضه مع زر الإضافة
        if onchain_match:
            amt_usd = onchain_match['amount_usd']
            _hash = onchain_match['hash']
            _coin = onchain_match['coin']
            pending_credit_id = f"pc_{int(time.time())}_{str(_hash)[-10:]}"
            db.pending_admin_credits.insert_one({
                '_id': pending_credit_id,
                'tx_id': normalize_tx_id(_hash),
                'amount': amt_usd,
                'note': f"{_coin} on-chain ({onchain_match['crypto_amount']:.6f} {_coin})",
                'payer_name': onchain_match.get('source_addr', '') or '',
                'source': f"onchain_{_coin.lower()}",
                'created_at': datetime.datetime.utcnow(),
                'admin_id': uid
            })

            when_str = '؟ (غير متوفر)'
            if onchain_match.get('when'):
                try:
                    _dt = datetime.datetime.fromtimestamp(int(onchain_match['when']))
                    when_str = _dt.strftime('%Y-%m-%d %H:%M:%S') + ' UTC'
                except Exception:
                    pass

            src = onchain_match.get('source_addr', '') or ''
            src_line = f"👤 <b>المُرسِل:</b> <code>{html.escape(str(src)[:50])}</code>\n" if src else ""

            text = (
                f"✅ <b>المعاملة موجودة على الشبكة</b>\n"
                f"<i>(غير مُعالَجة بعد — متاحة للإضافة)</i>\n\n"
                f"📡 <b>المصدر:</b> {onchain_match['label']}\n"
                f"💰 <b>المبلغ:</b> <b>${amt_usd:.4f}</b>  "
                f"(<code>{onchain_match['crypto_amount']:.6f} {_coin}</code>)\n"
                f"📅 <b>التاريخ والوقت:</b> {when_str}\n"
                f"{src_line}"
                f"🆔 <b>Hash:</b>\n<code>{html.escape(str(_hash)[:70])}</code>\n\n"
                f"💡 <i>اضغط الزر لإضافة المبلغ لمستخدم.</i>"
            )
            markup = InlineKeyboardMarkup()
            markup.add(InlineKeyboardButton(
                f"💰 إضافة ${amt_usd:.2f} لمستخدم",
                callback_data=f"credit_pending_{pending_credit_id}"
            ))
            bot.send_message(uid, text, parse_mode="HTML", reply_markup=markup)
            return

        # لا في DB ولا في Binance ولا على شبكات TON/LTC
        bot.send_message(
            uid,
            f"❌ <b>المعاملة غير موجودة في أي مكان</b>\n\n"
            f"🔎 البحث: <code>{html.escape(query[:80])}</code>\n\n"
            f"<i>الأسباب المحتملة:</i>\n"
            f"• الـ Hash / ID غلط أو ناقص\n"
            f"• لـ TON: أرسل الـ TxID الكامل (64 حرف hex) مو in_msg hash القصير\n"
            f"• الحوالة لم تُؤكَّد بعد على الشبكة (انتظر دقيقة وأعد المحاولة)\n"
            f"• الحوالة أُرسلت لمحفظة/شبكة مختلفة\n"
            f"• المعاملة أقدم من حدود الـ API",
            parse_mode="HTML"
        )
        return
    
    # لقينا — نعرض تفاصيل كل النتائج
    bot.send_message(uid, f"✅ <b>لقيت {len(found)} نتيجة:</b>", parse_mode="HTML")
    
    for i, r in enumerate(found, 1):
        try:
            tx_id = r.get('transaction_id', '?')
            user_id = r.get('user_id', '?')
            amount = r.get('amount', 0)
            method = r.get('method', '?')
            used_at = r.get('used_at', '')
            remark = r.get('remark', '')
            
            # نجيب اسم المستخدم
            user_doc = db.users.find_one({'user_id': user_id}) if isinstance(user_id, int) else None
            username = ''
            first_name = ''
            if user_doc:
                username = user_doc.get('username', '') or ''
                first_name = user_doc.get('first_name', '') or ''

            # نجيب رصيده الحالي
            user_balance = float(user_doc.get('balance', 0)) if user_doc else 0

            # 🆕 رابط قابل للضغط حتى لو ما عنده يوزر (tg://user?id=...)
            display_name = first_name or username or str(user_id)
            user_link = f'<a href="tg://user?id={user_id}">{html.escape(display_name)}</a>'

            detail = (
                f"━━━ #{i} ━━━\n"
                f"🆔 <b>TX:</b> <code>{html.escape(str(tx_id))}</code>\n"
                f"👤 <b>المستخدم:</b> {user_link}\n"
                f"🔢 <b>User ID:</b> <code>{user_id}</code>"
            )
            # نضيف اليوزر لو موجود (قابل للضغط أيضاً)
            if username:
                detail += f"\n📱 <b>Username:</b> <a href=\"https://t.me/{html.escape(username)}\">@{html.escape(username)}</a>"
            detail += (
                f"\n💰 <b>المبلغ:</b> <b>${float(amount):.4f}</b>\n"
                f"💼 <b>الرصيد الحالي:</b> <b>${user_balance:.2f}</b>\n"
                f"🔄 <b>الطريقة:</b> {html.escape(str(method))}\n"
                f"📅 <b>الوقت:</b> {str(used_at)[:19]}"
            )
            if remark:
                detail += f"\n📝 <b>Note:</b> <code>{html.escape(str(remark)[:200])}</code>"

            # disable_web_page_preview عشان رابط t.me ما يفتح preview كبير
            bot.send_message(uid, detail, parse_mode="HTML", disable_web_page_preview=True)
        except Exception as fe:
            bot.send_message(uid, f"❌ Error formatting result #{i}: {fe}")


@bot.callback_query_handler(func=lambda call: call.data.startswith("credit_pending_"))
def credit_pending_handler(call):
    """يطلب من الأدمن User ID أو username لإضافة المبلغ المعلق"""
    if not _is_admin_check(call.from_user.id):
        try: bot.answer_callback_query(call.id, "❌ ليس لديك صلاحية", show_alert=True)
        except: pass
        return
    bot.answer_callback_query(call.id)

    pending_id = call.data.replace("credit_pending_", "")
    pending = db.pending_admin_credits.find_one({'_id': pending_id})
    if not pending:
        bot.send_message(call.message.chat.id, "❌ المعاملة منتهية أو محذوفة. اضغط 🔍 فحص معاملة من جديد.")
        return

    msg = bot.send_message(
        call.message.chat.id,
        f"💰 <b>إضافة ${float(pending['amount']):.4f}</b>\n\n"
        f"أرسل <b>User ID</b> (رقم) أو <b>@username</b> للمستخدم اللي يستلم المبلغ:\n\n"
        f"❌ للإلغاء: <b>الغاء</b>",
        parse_mode="HTML"
    )
    bot.register_next_step_handler(msg, credit_pending_exec, pending_id)


@safe_next_step
def credit_pending_exec(message, pending_id):
    """ينفذ إضافة الرصيد للمستخدم المحدد"""
    uid = message.from_user.id
    if not _is_admin_check(uid):
        return

    text = (message.text or '').strip()
    if not text or text.lower() in ('/cancel', 'الغاء', 'إلغاء', 'cancel'):
        bot.send_message(uid, "❌ تم الإلغاء.")
        return

    pending = db.pending_admin_credits.find_one({'_id': pending_id})
    if not pending:
        bot.send_message(uid, "❌ المعاملة منتهية. ابدأ من جديد.")
        return

    # نحدد المستخدم — رقم أو username
    target_uid = None
    target_user = None

    if text.startswith('@'):
        text = text[1:]

    if text.isdigit():
        try:
            target_uid = int(text)
            target_user = db.users.find_one({'user_id': target_uid})
        except: pass

    if not target_user:
        import re as _re_un
        target_user = db.users.find_one({
            'username': {'$regex': f'^{_re_un.escape(text)}$', '$options': 'i'}
        })
        if target_user:
            target_uid = target_user.get('user_id')

    if not target_user or not target_uid:
        bot.send_message(
            uid,
            f"❌ ما لقيت مستخدم بالاسم: <code>{html.escape(text)}</code>\n\n"
            f"<i>تأكد إن المستخدم عمل /start في البوت قبل.</i>",
            parse_mode="HTML"
        )
        return

    if target_user.get('is_banned') == 1:
        bot.send_message(uid, f"❌ المستخدم <code>{target_uid}</code> محظور!", parse_mode="HTML")
        return

    amount = float(pending['amount'])
    tx_id = pending['tx_id']
    note = pending.get('note', '')
    user_lang = target_user.get('language', 'ar')

    # 💱 لو المبلغ صفر (فشل جلب السعر وقت البحث) → نعيد التحويل الآن من الكريبتو
    if amount <= 0:
        _c_amt = float(pending.get('crypto_amount') or 0)
        _c_cur = str(pending.get('crypto_currency') or '').upper()
        if _c_amt > 0 and _c_cur:
            _usd, _ = binance_amount_to_usd(_c_amt, _c_cur)
            if _usd and _usd > 0:
                amount = _usd
                try:
                    db.pending_admin_credits.update_one(
                        {'_id': pending['_id']}, {'$set': {'amount': amount}}
                    )
                except Exception: pass

    # لو ما زال صفراً → نوقف بدل ما نضيف $0.00 للمستخدم
    if amount <= 0:
        _c_amt = float(pending.get('crypto_amount') or 0)
        _c_cur = str(pending.get('crypto_currency') or 'CRYPTO').upper()
        bot.send_message(
            uid,
            f"⚠️ <b>ما قدرت أحدد قيمة الحوالة بالدولار.</b>\n\n"
            f"💰 <b>الأصل:</b> <code>{_c_amt:.8f} {html.escape(_c_cur)}</code>\n\n"
            f"<i>تعذّر جلب سعر العملة الآن. جرّب بعد دقيقة، أو أضف المبلغ يدوياً "
            f"للمستخدم من (شحن رصيد) بعد ما تحسب قيمته.</i>",
            parse_mode="HTML"
        )
        return

    # 🔖 نحدد اسم الطريقة حسب مصدر المعاملة (عشان ما نسمّي إيداع TON "Binance Pay")
    _src = pending.get('source', '')
    if _src == 'onchain_ton':
        method_label = "Toncoin (TON) (Admin Manual Match)"
    elif _src == 'onchain_ltc':
        method_label = "Litecoin (LTC) (Admin Manual Match)"
    elif _src == 'deposit':
        method_label = "Crypto Deposit (Admin Manual Match)"
    else:
        method_label = "Binance Pay (Admin Manual Match)"

    try:
        credit_user(target_uid, amount, tx_id, user_lang, method_label)
        # 🔓 نُغلق أي إيداع معلّق للمستخدم ونفكّ قفله (الأدمن حل دفعته)
        close_user_pending_and_unlock(target_uid, tx_id, via='admin_manual_match')
        try:
            db.used_transactions.update_one(
                {'transaction_id': tx_id},
                {'$set': {
                    'method': method_label,
                    'remark': note,
                    'manual_assigned_by': uid,
                    'manual_assigned_at': datetime.datetime.utcnow()
                }}
            )
        except: pass
        db.pending_admin_credits.delete_one({'_id': pending_id})

        username = target_user.get('username', '')
        first_name = target_user.get('first_name', '')
        display = first_name or username or str(target_uid)
        user_link = f'<a href="tg://user?id={target_uid}">{html.escape(display)}</a>'

        result_text = (
            f"✅ <b>تم إضافة الرصيد بنجاح!</b>\n\n"
            f"👤 <b>المستخدم:</b> {user_link}\n"
            f"🔢 <b>User ID:</b> <code>{target_uid}</code>\n"
        )
        if username:
            result_text += f"📱 <b>Username:</b> @{html.escape(username)}\n"
        result_text += (
            f"💰 <b>المبلغ المُضاف:</b> <b>${amount:.4f}</b>\n"
            f"🆔 <b>TX:</b> <code>{html.escape(tx_id[:40])}</code>\n\n"
            f"<i>المستخدم استلم إشعار تلقائي بإضافة الرصيد.</i>"
        )
        bot.send_message(uid, result_text, parse_mode="HTML", disable_web_page_preview=True)
    except Exception as ce:
        logger.error(f"manual credit fail: {ce}")
        bot.send_message(uid, f"❌ فشل: {html.escape(str(ce))}", parse_mode="HTML")


