_PRODUCT_EDIT_NAV = {}
_PRODUCT_EDIT_NAV_LOCK = threading.Lock()


def _remember_product_edit_parent(uid, pid, parent):
    key = (int(uid), str(pid).removeprefix('cgpt_main_'))
    with _PRODUCT_EDIT_NAV_LOCK:
        now = time.monotonic()
        if len(_PRODUCT_EDIT_NAV) >= 4096:
            oldest = min(_PRODUCT_EDIT_NAV, key=lambda k: _PRODUCT_EDIT_NAV[k][1])
            _PRODUCT_EDIT_NAV.pop(oldest, None)
        _PRODUCT_EDIT_NAV[key] = (parent, now)


def _product_edit_parent(uid, pid, cat_id=None):
    key = (int(uid), str(pid).removeprefix('cgpt_main_'))
    with _PRODUCT_EDIT_NAV_LOCK:
        found = _PRODUCT_EDIT_NAV.get(key)
    if found and time.monotonic() - found[1] < 86400:
        return found[0]
    return f"vi_p_{key[1]}_c_{cat_id}" if cat_id else 'ad_p_edit'


@bot.callback_query_handler(func=lambda call: call.data == "ad_p_edit")
@admin_required
def admin_edit_list(call):
    bot.answer_callback_query(call.id)
    l = get_lang(call.from_user.id)
    prods = list(db.products.find())
    
    # ترتيب أبجدي حسب لغة الأدمن
    def sort_key(x):
        if l == 'en':
            return str(x.get('name_en', x.get('name_ar', ''))).lower()
        return str(x.get('name_ar', x.get('name_en', ''))).lower()
    prods.sort(key=sort_key)
    
    markup = InlineKeyboardMarkup(row_width=1)
    for p in prods:
        pid = p.get('id', str(p.get('_id', '')))
        hidden_icon = " 👻" if p.get('is_hidden', False) else ""
        
        # عرض الاسم حسب لغة الأدمن
        p_name = p.get('name_en') if l == 'en' else p.get('name_ar')
        if not p_name:
            p_name = p.get('name_ar') or p.get('name_en') or 'بدون اسم'
        
        btn_text = f"📝 {clean_name(p_name)}{hidden_icon}"
        _remember_product_edit_parent(call.from_user.id, pid, 'ad_p_edit')
        btn_kwargs = {'text': btn_text, 'callback_data': f"edit_p_{pid}"}
        
        # إضافة الإيموجي المميز (Premium Emoji) للزر
        custom_emoji_id = p.get('custom_emoji_id')
        if custom_emoji_id:
            btn_kwargs['icon_custom_emoji_id'] = custom_emoji_id
        
        markup.add(CustomInlineButton(**btn_kwargs))
    
    markup.add(InlineKeyboardButton("🔙 Back", callback_data="admin_panel_main"))
    bot.edit_message_text("👇 Select Product:", call.message.chat.id, call.message.message_id, reply_markup=markup)

@bot.callback_query_handler(func=lambda call: call.data.startswith("edit_p_"))
@admin_required
def admin_edit_opts(call):
    bot.answer_callback_query(call.id)
    raw_ep = call.data.replace("edit_p_", "")
    if '_c_' in raw_ep:
        pid, cat_id_back = raw_ep.split('_c_', 1)
    else:
        pid = raw_ep
        cat_id_back = None
    p = find_product(pid)
    if not p: return
    
    # suffix لتمرير cat_id في كل الأزرار
    c_sfx = f"_c_{cat_id_back}" if cat_id_back else ""
    
    # Shorten pid for callback_data
    short_pid = str(pid).replace("cgpt_main_", "") if str(pid).startswith("cgpt_main_") else str(pid)
    
    markup = InlineKeyboardMarkup(row_width=2)
    markup.add(InlineKeyboardButton("💵 Price", callback_data=f"ep_price_{short_pid}{c_sfx}"))
    markup.add(InlineKeyboardButton("📝 Desc (AR)", callback_data=f"ep_dar_{short_pid}{c_sfx}"),
               InlineKeyboardButton("📝 Desc (EN)", callback_data=f"ep_den_{short_pid}{c_sfx}"))
    markup.add(InlineKeyboardButton("✏️ Name (AR)", callback_data=f"ep_nar_{short_pid}{c_sfx}"),
               InlineKeyboardButton("✏️ Name (EN)", callback_data=f"ep_nen_{short_pid}{c_sfx}"))
    markup.add(InlineKeyboardButton("📁 Change Folder", callback_data=f"ep_setcat_{short_pid}{c_sfx}"),
               InlineKeyboardButton("⭐ Custom Emoji", callback_data=f"ep_emoji_{short_pid}{c_sfx}"))
    markup.add(InlineKeyboardButton("🏷 خصومات الكمية", callback_data=f"ep_disc_{short_pid}{c_sfx}"),
               InlineKeyboardButton("💰 سعر التكلفة", callback_data=f"pcost_{short_pid}"))
    markup.add(InlineKeyboardButton("💹 ربح المنتج (حسب كل سعر)", callback_data=f"pprofit_{short_pid}"))
    hide_txt = "👁️ Show Product" if p.get('is_hidden', False) else "🙈 Hide Product"
    markup.add(InlineKeyboardButton(hide_txt, callback_data=f"toggle_hide_{short_pid}{c_sfx}"))
    # زر رجوع: للمنتج نفسه وليس لقائمة الأدمن
    back_cb = _product_edit_parent(call.from_user.id, short_pid, cat_id_back)
    # زر جعله أول في مجلده
    p_doc = find_product(pid)
    if p_doc:
        p_cat = p_doc.get('catalog_id') or (cat_id_back if cat_id_back else None)
        if p_cat:
            markup.add(InlineKeyboardButton("⬆️ جعله أول في المجلد", callback_data=f"p_set_first_{short_pid}_{p_cat}"))
    markup.add(InlineKeyboardButton("🔙 Back", callback_data=back_cb))
    
    bot_username = get_bot_username()
    link = f"https://t.me/{bot_username}?start=p_{short_pid}"
    txt = f"⚙️ <b>Options for product:</b> {clean_name(p.get('name_ar', p.get('name_en', '')))}" + _notice_admin_links(pid)
    for row in _notice_pair(call.from_user.id, pid).keyboard:
        markup.row(*row)
    try: bot.edit_message_text(txt, call.message.chat.id, call.message.message_id, reply_markup=markup, parse_mode="HTML")
    except: pass


