# ============================================================
# 🔄 مزامنة تعديلات المنتج مع مشتركي الـ API
# ============================================================
def _emit_product_updated_after_edit(func):
    """Decorator: يبثّ حدث product.updated تلقائياً بعد أي تعديل ناجح للمنتج.

    ⚠️ المشكلة التي يحلّها: admin_save_edit كان يحدّث db.products لكن ما يبثّ
    أي حدث، فمشتركو الـ API (والـ webhooks) يظلون على البيانات القديمة —
    السعر والاسم والوصف ما تتحدث عندهم أبداً.

    نستخدم decorator بدل إضافة _emit_event في كل مسار داخل الدالة، لأن الدالة
    فيها مسارات خروج كثيرة (سعر/اسم/وصف/إيموجي) وسهل نسيان واحد.
    نقارن المنتج قبل وبعد، ونبثّ الحقول التي تغيّرت فعلاً فقط.
    """
    @functools.wraps(func)
    def wrapper(message, field, pid, cat_id_back=None, *a, **kw):
        _watch = ('price', 'name_ar', 'name_en', 'desc_ar', 'desc_en',
                  'custom_emoji_id', 'is_hidden', 'discount_tiers')
        # لقطة "قبل"
        before = {}
        try:
            _p = find_product(pid)
            if _p:
                before = {k: _p.get(k) for k in _watch}
        except Exception:
            pass

        result = func(message, field, pid, cat_id_back, *a, **kw)
        _invalidate_products_cache()

        # لقطة "بعد" + بثّ التغييرات
        try:
            _p2 = find_product(pid)
            if _p2:
                after = {k: _p2.get(k) for k in _watch}
                changes = {k: after[k] for k in _watch if before.get(k) != after[k]}
                if changes:
                    pid_e = str(_p2.get('id', str(_p2.get('_id', ''))))
                    _emit_event('product.updated', {
                        'product_id': pid_e,
                        'changes': changes,
                        'product': {
                            'id': pid_e,
                            'name_ar': _p2.get('name_ar', ''),
                            'name_en': _p2.get('name_en', ''),
                            'desc_ar': _p2.get('desc_ar', ''),
                            'desc_en': _p2.get('desc_en', ''),
                            'store_price': float(_p2.get('price', 0) or 0),
                            'is_hidden': bool(_p2.get('is_hidden', False)),
                            'custom_emoji_id': _p2.get('custom_emoji_id'),
                            'discount_tiers': _p2.get('discount_tiers', []),
                        }
                    }, product_id=pid_e)
                    logger.info(f"🔄 product.updated بُثّ للمطورين: {pid_e} → {list(changes.keys())}")
        except Exception as _e:
            logger.debug(f"emit product.updated err: {_e}")

        return result
    return wrapper


# ----------- حفظ تعديل المنتج + إشعار تخفيض السعر -----------
@_emit_product_updated_after_edit
def admin_save_edit(message, field, pid, cat_id_back=None):
    val = message.text or ""
    
    # زر رجوع: يرجع للمنتج وليس للقائمة
    back_cb = f"edit_p_{pid}_c_{cat_id_back}" if cat_id_back else f"edit_p_{pid}"
    
    # دعم الإلغاء
    if val.strip().lower() in ['الغاء', 'cancel', '/cancel']:
        markup_cancel = InlineKeyboardMarkup()
        markup_cancel.add(InlineKeyboardButton("🔙 رجوع للمنتج", callback_data=back_cb))
        bot.send_message(message.chat.id, "❌ تم إلغاء التعديل.", reply_markup=markup_cancel)
        return
    
    keys = {"price": "price", "dar": "desc_ar", "den": "desc_en", "nar": "name_ar", "nen": "name_en"}
    p = find_product(pid)
    if not p: 
        bot.send_message(message.chat.id, "❌ المنتج لم يعد موجوداً.")
        return

    if field == "emoji":
        emoji_id = None
        if message.entities:
            for ent in message.entities:
                if ent.type == 'custom_emoji':
                    emoji_id = ent.custom_emoji_id
                    break
        if not emoji_id and re.fullmatch(r'\d{8,25}', val.strip()):
            emoji_id = val.strip()                # رقم الإيموجي (من الموقع)
        if not emoji_id:
            bot.send_message(message.chat.id, "❌ لم يتم العثور على رمز Premium (أو أرسل رقم الإيموجي). أعد المحاولة من قائمة تعديل المنتج.")
            return
        
        # Save it
        db.products.update_one({'_id': p['_id']}, {'$set': {'custom_emoji_id': emoji_id}})
        
        # Also sync to db.cgpt_products if it's a ChatGPT product
        cgpt_id = p.get('cgpt_product_id')
        if cgpt_id:
            try:
                from bson import ObjectId
                db.cgpt_products.update_one({'_id': ObjectId(cgpt_id)}, {'$set': {'custom_emoji_id': emoji_id}})
            except: pass
            
        back_markup = InlineKeyboardMarkup()
        back_markup.add(InlineKeyboardButton("🔙 رجوع للمنتج", callback_data=back_cb))
        bot.send_message(message.chat.id, f"✅ <b>تم تحديث الأيقونة المميزة للمنتج بنجاح!</b>", parse_mode="HTML", reply_markup=back_markup)
        return

    if field == "price":
        try:
            new_price = float(val)
            if new_price < 0:
                bot.send_message(message.chat.id, "❌ السعر لا يمكن أن يكون سالباً.")
                return
            old_price = float(p.get('price', 0))
            db.products.update_one({'_id': p['_id']}, {'$set': {'price': new_price}})
            if new_price != old_price:
                _price_log(p, 'price', old_price, new_price, getattr(message.from_user, 'id', None))
            
            # رسالة توضح التغيير
            if new_price < old_price:
                change_emoji = "📉"
                change_txt = f"تم تخفيض السعر من <b>${old_price:.2f}</b> إلى <b>${new_price:.2f}</b>"
            elif new_price > old_price:
                change_emoji = "📈"
                change_txt = f"تم رفع السعر من <b>${old_price:.2f}</b> إلى <b>${new_price:.2f}</b>"
            else:
                change_emoji = "✅"
                change_txt = f"السعر بقي نفسه: <b>${new_price:.2f}</b>"
            
            back_markup = InlineKeyboardMarkup()
            back_markup.add(InlineKeyboardButton("💹 ربح المنتج", callback_data=f"pprofit_{pid}"),
                            InlineKeyboardButton("💰 سعر التكلفة", callback_data=f"pcost_{pid}"))
            back_markup.add(InlineKeyboardButton("🔙 رجوع للمنتج", callback_data=back_cb))
            bot.send_message(message.chat.id, f"{change_emoji} <b>تم التحديث!</b>\n{change_txt}\n\n"
                             f"{price_profit_lines(old_price, new_price, p.get('cost'))}", parse_mode="HTML", reply_markup=back_markup)
            
            # برودكاست فقط لو السعر نزل
            if new_price < old_price:
                def broadcast_price_drop(admin_id):
                    # 🔘 زر الانتقال للمنتج (كان الإشعار يُرسل بلا زر إطلاقاً!)
                    # نطبّع الـ pid بنفس طريقة أزرار المتجر (نشيل بادئة cgpt_main_)
                    # وإلا الزر ينكسر مع منتجات ChatGPT.
                    _raw_pid = str(p.get('id', str(p.get('_id', ''))))
                    _pid_btn = _raw_pid.replace("cgpt_main_", "") if _raw_pid.startswith("cgpt_main_") else _raw_pid

                    # لو المنتج مخفي، ما فيه فائدة من الإشعار أصلاً
                    if p.get('is_hidden'):
                        bot.send_message(admin_id, "⚠️ المنتج مخفي — لم يُرسل إشعار التخفيض.")
                        return

                    _nu = _notify_url(_raw_pid)          # زر الشراء يفتح الموقع على المنتج
                    users = list(db.users.find())
                    success = 0
                    fail = 0
                    for u in users:
                        try:
                            # نتخطى المحظورين (ما ينفع نرسل لهم عرضاً ما يقدرون يشترونه)
                            if u.get('is_banned') == 1:
                                continue

                            u_lang = u.get('lang', 'ar') if u.get('lang_chosen') else 'en'
                            if u_lang not in ['ar', 'en']: u_lang = 'en'
                            
                            custom_emoji_id = p.get('custom_emoji_id')
                            icon_html = f'<tg-emoji emoji-id="{custom_emoji_id}">✨</tg-emoji> ' if custom_emoji_id else '📦 '
                            p_name = icon_html + clean_name(p.get(f'name_{u_lang}', p.get('name_en')))
                            
                            alert_msg = get_text(u['user_id'], 'price_drop', p_name, old_price, new_price)

                            # 🔘 نبني الزر بلغة المستخدم
                            _mk = InlineKeyboardMarkup()
                            _btn_txt = (f"🛒 شراء الآن — ${new_price:.2f}"
                                        if u_lang == 'ar' else
                                        f"🛒 Buy Now — ${new_price:.2f}")
                            _mk = _notice_pair(u['user_id'], _raw_pid, fallback_cb=f'vi_p_{_pid_btn}')

                            bot.send_message(u['user_id'], alert_msg, parse_mode="HTML", reply_markup=_mk)
                            success += 1
                            time.sleep(0.05)
                        except: 
                            fail += 1
                            continue
                    bot.send_message(admin_id, f"📢 <b>تقرير إشعار التخفيض للمنتج ({p.get('name_ar')}):</b>\n🟢 مستلمين: {success}\n🔴 محظورين: {fail}", parse_mode="HTML")
                
                threading.Thread(target=broadcast_price_drop, args=(message.chat.id,), daemon=True).start()
                bot.send_message(message.chat.id, "📢 تم بدء إرسال إشعار التخفيض للجميع وسيصلك تقرير قريباً.")
        except Exception as e: 
            bot.send_message(message.chat.id, f"❌ خطأ في السعر. تأكد من إرسال رقم صحيح (مثال: 5.99)")
    else:
        # للأسماء والأوصاف — دعم Premium Emojis + ترجمة تلقائية
        final_text = extract_custom_emojis_to_html(message)
        
        if field in ['nar', 'dar']:
            # عربي → ترجم للإنجليزي تلقائياً
            try:
                translated = (_translate_product_description(final_text) if field == 'dar'
                              else safe_translate_for_cms(final_text, 'en'))
            except ValueError as exc:
                bot.send_message(message.chat.id, str(exc))
                return
            if field == 'nar':
                db.products.update_one({'_id': p['_id']}, {'$set': {'name_ar': final_text, 'name_en': translated}})
                
                # 🆕 مزامنة مع db.cgpt_products
                cgpt_id = p.get('cgpt_product_id')
                if cgpt_id:
                    try:
                        from bson import ObjectId
                        db.cgpt_products.update_one({'_id': ObjectId(cgpt_id)}, {'$set': {'name': final_text, 'name_en': translated}})
                    except: pass
                    
                back_markup2 = InlineKeyboardMarkup()
                back_markup2.add(InlineKeyboardButton("🔙 رجوع للمنتج", callback_data=back_cb))
                bot.send_message(message.chat.id, f"✅ <b>تم تحديث الاسم!</b>\n\n🇸🇦 العربي: {final_text}\n🇬🇧 الإنجليزي (مترجم تلقائياً): {translated}", parse_mode="HTML", reply_markup=back_markup2)
            else:
                db.products.update_one({'_id': p['_id']}, {'$set': dict({'desc_ar': final_text, 'desc_translation_pending': translated is None,
                                                                          'desc_translation_attempts': 0},
                             **({'desc_en': translated} if translated is not None else {}))})
                
                # 🆕 مزامنة مع db.cgpt_products
                cgpt_id = p.get('cgpt_product_id')
                if cgpt_id:
                    try:
                        from bson import ObjectId
                        db.cgpt_products.update_one({'_id': ObjectId(cgpt_id)}, {'$set': dict({'desc': final_text, 'desc_translation_pending': translated is None,
                                                                                              'desc_translation_attempts': 0},
                                         **({'desc_en': translated} if translated is not None else {}))})
                    except: pass
                    
                back_markup3 = InlineKeyboardMarkup()
                back_markup3.add(InlineKeyboardButton("🔙 رجوع للمنتج", callback_data=back_cb))
                desc_notice = "✅ <b>تم تحديث الوصف العربي + ترجمته للإنجليزي تلقائياً.</b>"
                if translated is None:
                    desc_notice = "✅ حُفظ الوصف العربي. ⚠️ تعذر الاتصال بالمترجم أو لم يرجع ترجمة مكتملة. بقي الوصف الإنجليزي السابق؛ أعد المحاولة أو عدّله من زره."
                bot.send_message(message.chat.id, desc_notice, parse_mode="HTML", reply_markup=back_markup3)
        else:
            # إنجليزي فقط
            db.products.update_one({'_id': p['_id']}, {'$set': {keys[field]: final_text}})
            
            # 🆕 مزامنة مع db.cgpt_products
            cgpt_id = p.get('cgpt_product_id')
            if cgpt_id:
                try:
                    from bson import ObjectId
                    field_name = keys[field]
                    if field_name == 'name_en':
                        db.cgpt_products.update_one({'_id': ObjectId(cgpt_id)}, {'$set': {'name_en': final_text}})
                    elif field_name == 'desc_en':
                        db.cgpt_products.update_one({'_id': ObjectId(cgpt_id)}, {'$set': {'desc_en': final_text}})
                except: pass
                
            back_markup4 = InlineKeyboardMarkup()
            back_markup4.add(InlineKeyboardButton("🔙 رجوع للمنتج", callback_data=back_cb))
            bot.send_message(message.chat.id, "✅ <b>تم التحديث بنجاح.</b>", parse_mode="HTML", reply_markup=back_markup4)

