@bot.callback_query_handler(func=lambda call: call.data.startswith("del_p_ok_"))
@admin_required
def admin_del_exec(call):
    bot.answer_callback_query(call.id)
    pid = call.data.replace("del_p_ok_", "")
    try:
        p = find_product(pid)
        if not p: return
        pid_str = str(pid)
        queries = [{'product_id': pid_str}]
        if pid_str.isdigit(): queries.append({'product_id': int(pid_str)})
        try: queries.append({'product_id': float(pid_str)})
        except: pass
        db.product_stock.delete_many({'$or': queries})
        # سجل طلبات العملاء والأرباح يبقى — نحفظ اسم المنتج عشان يطلع في «طلباتي» بدل «منتج محذوف»
        _remember_deleted_product(p)
        db.products.delete_one({'_id': p['_id']})
        _catalog_pull_product(p)
        _invalidate_products_cache()
        # 🔄 بث حدث للمزامنة
        try:
            _emit_event('product.deleted', {
                'product_id': pid_str
            }, product_id=pid_str)
        except: pass
        bot.answer_callback_query(call.id, "✅ Deleted Successfully!", show_alert=True)
        admin_main_ui(call)
    except: bot.answer_callback_query(call.id, "❌ Error", show_alert=True)

