def ad_gift_note_step2(message, target_uid):
    # ✅ فحص الإلغاء
    if _is_cancel_msg(message):
        bot.send_message(message.chat.id, "❌ تم إلغاء العملية.")
        try: show_user_admin_profile(message.chat.id, target_uid)
        except: pass
        return
    try:
        val = float(message.text.strip())
        if not _vip_amount_sane(val):
            raise ValueError("amount out of range")
        msg = bot.send_message(message.chat.id,
            "📝 <b>أرسل الملاحظة (نوت):</b>\n"
            "<i>مثال: hash العملية، Order ID، رقم تحويل، أو أي سبب</i>\n\n"
            "💡 <i>هذه النوت راح تظهر في البحث عن المعاملة من زر</i> 🔍 <i>فحص معاملة</i>\n\n"
            "<i>للإلغاء: اكتب <b>الغاء</b> أو اضغط الزر</i>",
            parse_mode="HTML", reply_markup=_cancel_markup(target_uid))
        bot.register_next_step_handler(msg, ad_gift_note_exec, target_uid, val)
    except:
        bot.send_message(message.chat.id, "❌ خطأ في الرقم.\nللإلغاء اضغط زر الإلغاء، أو حاول مرة ثانية بإرسال الرقم.")


def ad_gift_note_exec(message, target_uid, val):
    # ✅ فحص الإلغاء
    if _is_cancel_msg(message):
        bot.send_message(message.chat.id, "❌ تم إلغاء العملية.")
        try: show_user_admin_profile(message.chat.id, target_uid)
        except: pass
        return
    try:
        note = message.text.strip()
        u = db.users.find_one_and_update({'user_id': target_uid}, {'$inc': {'balance': val}}, return_document=True)
        if not u:
            raise ValueError('المستخدم غير موجود')
        _invalidate_user_cache(target_uid)
        new_bal = round(float(u.get('balance', 0)), 4)
        import datetime as _dt
        _bl = db.balance_logs.insert_one({
            'user_id': target_uid,
            'type': 'manual',
            'amount': val,
            'old_balance': round(float(u.get('balance', 0)) - val, 4),
            'balance_source': 'atomic_wallet_update',
            'note': note,
            'new_balance': new_bal,
            'by_admin': message.from_user.id,
            'date': _dt.datetime.utcnow()
        })

        # 🆕 نحفظ نسخة في used_transactions كذلك عشان زر "فحص معاملة" يلقاها
        # transaction_id = الـ note نفسها (normalized) — يخلي البحث يربط الـ hash/order ID بالنوت
        try:
            tx_id_from_note = normalize_tx_id(note) if note else f"manual_{int(_dt.datetime.utcnow().timestamp())}"
            db.used_transactions.insert_one({
                'transaction_id': tx_id_from_note,
                'user_id': target_uid,
                'amount': val,
                'method': 'Manual Gift (Admin)',
                'used_at': _dt.datetime.utcnow(),
                'remark': note,
                'manual': True,
                'by_admin': message.from_user.id
            })
        except Exception as _ute:
            # duplicate ممكن لو نفس النوت دخل قبل — مش مشكلة
            logger.debug(f"manual gift tx record skipped: {_ute}")

        bot.send_message(message.chat.id,
            f"✅ <b>تم تعديل الرصيد بنجاح</b>\n\n"
            f"👤 <b>المستخدم:</b> <code>{target_uid}</code>\n"
            f"💰 <b>المبلغ:</b> <b>${val:.2f}</b>\n"
            f"💼 <b>الرصيد الجديد:</b> <b>${new_bal:.2f}</b>\n"
            f"📝 <b>النوت:</b> <code>{html.escape(note)}</code>\n\n"
            f"🔍 <i>تقدر تبحث عن هذي العملية من زر 🔍 فحص معاملة بـ النوت أو جزء منها</i>",
            parse_mode="HTML")
        try: notify_balance_gift(target_uid, val, note=note, gift_type='manual')
        except Exception as _e: logger.debug(f"gift notify err: {_e}")
        vip_after_admin_balance(message.chat.id, target_uid, val, _bl.inserted_id, message.from_user.id)
        show_user_admin_profile(message.chat.id, target_uid)
    except Exception as e:
        bot.send_message(message.chat.id, f"❌ خطأ: {e}")

@bot.callback_query_handler(func=lambda call: call.data.startswith("ad_view_ballogs_"))
@admin_required
def ad_view_balance_logs(call):
    """عرض سجل التعديلات المالية لمستخدم معين (للأدمن)"""
    bot.answer_callback_query(call.id)
    parts = call.data.replace("ad_view_ballogs_", "").rsplit("_", 1)
    target_uid = int(parts[0])
    page = int(parts[1]) if len(parts) > 1 else 0
    per_page = 5
    logs = list(db.balance_logs.find({'user_id': target_uid}).sort('_id', -1).skip(page * per_page).limit(per_page))
    total = db.balance_logs.count_documents({'user_id': target_uid})
    if not logs:
        bot.answer_callback_query(call.id, "لا يوجد سجل بعد.", show_alert=True)
        return
    import datetime as _dt
    txt = f"📋 <b>سجل التعديلات المالية للمستخدم</b> <code>{target_uid}</code>\n\n"
    for log in logs:
        t = log.get('type', 'manual')
        amt = log.get('amount', 0)
        note = log.get('note', '')
        date = log.get('date', '')
        sign = "+" if amt >= 0 else ""
        type_label = _BAL_LBL_AR.get(t) or ("🔄 تعويض" if t == 'compensation' else "💰 إضافة عادية")
        date_str = date.strftime("%Y-%m-%d %H:%M") if hasattr(date, 'strftime') else str(date)[:16]
        txt += f"{type_label}\n💵 <b>{sign}${amt:.2f}</b> | 🕐 {date_str}\n"
        if note:
            txt += f"📝 النوت: <code>{note}</code>\n"
        txt += "──────────\n"
    markup = InlineKeyboardMarkup(row_width=2)
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton("⬅️ السابق", callback_data=f"ad_view_ballogs_{target_uid}_{page-1}"))
    if (page + 1) * per_page < total:
        nav.append(InlineKeyboardButton("➡️ التالي", callback_data=f"ad_view_ballogs_{target_uid}_{page+1}"))
    if nav: markup.add(*nav)
    markup.add(InlineKeyboardButton("🔙 رجوع", callback_data=f"ad_u_det_{target_uid}"))
    try:
        bot.edit_message_text(txt, call.message.chat.id, call.message.message_id, reply_markup=markup, parse_mode="HTML")
    except:
        bot.send_message(call.message.chat.id, txt, reply_markup=markup, parse_mode="HTML")

_BAL_LBL_AR = {'ref_reward': '🎁 مكافأة إحالات', 'ref_clawback': '↩️ خصم إحالة طلعت', 'ref_refund': '🤝 رجوع إحالة'}
_BAL_LBL_EN = {'ref_reward': '🎁 Referral reward', 'ref_clawback': '↩️ Referral deducted', 'ref_refund': '🤝 Referral back'}


