_SETTING_KEYS = {
    "set_v_log": "log_channel",
    "set_v_usdt": "usdt_address",
    "set_v_ltc": "ltc_address",
    "set_v_wallet": "wallet_address",
    "set_v_usdt_bep20": "usdt_bep20_address",
    "set_v_ton": "ton_address",
    "set_v_bybit_key": "bybit_api_key",
    "set_v_bybit_secret": "bybit_api_secret",
    "set_v_bybit_uid": "bybit_uid",
    "set_v_bybit_trc20": "bybit_addr_trc20",
    "set_v_bybit_bep20": "bybit_addr_bep20",
    "set_v_bscscan": "bscscan_api_key",
}


def _validate_setting_value(mode, val):
    """يتحقق من صيغة القيمة. يرجّع (سليم؟، رسالة الخطأ).
    🛡 الأهم: يمنع وضع عنوان شبكة في خانة شبكة أخرى — خطأ يضيّع أموال المستخدمين."""
    v = (val or '').strip()
    if not v:
        return False, "❌ القيمة فارغة."

    # عناوين TRC20 (ترون): تبدأ بـ T وطولها 34
    if mode in ("set_v_bybit_trc20", "set_v_usdt"):
        if v.startswith('0x'):
            return False, ("❌ <b>هذا عنوان BEP20 وليس TRC20!</b>\n\n"
                           "عنوان TRC20 يبدأ بحرف <b>T</b>.\n"
                           "<i>وضعه هنا يضيّع أموال المستخدمين.</i>")
        if not (v.startswith('T') and len(v) == 34):
            return False, "❌ عنوان TRC20 غير صالح — يبدأ بحرف <b>T</b> وطوله 34 خانة."

    # عناوين BEP20 (BSC): تبدأ بـ 0x وطولها 42
    if mode in ("set_v_bybit_bep20", "set_v_usdt_bep20"):
        if v.startswith('T') and len(v) == 34:
            return False, ("❌ <b>هذا عنوان TRC20 وليس BEP20!</b>\n\n"
                           "عنوان BEP20 يبدأ بـ <b>0x</b>.\n"
                           "<i>وضعه هنا يضيّع أموال المستخدمين.</i>")
        if not (v.lower().startswith('0x') and len(v) == 42):
            return False, "❌ عنوان BEP20 غير صالح — يبدأ بـ <b>0x</b> وطوله 42 خانة."

    _is_trc20 = v.startswith('T') and len(v) == 34
    _is_bep20 = v.lower().startswith('0x') and len(v) == 42
    # TON: EQ…/UQ… (48 خانة) أو الصيغة الخام 0:…
    if mode == "set_v_ton":
        if _is_trc20 or _is_bep20:
            return False, "❌ <b>هذا عنوان USDT وليس TON!</b>\n\nعنوان TON يبدأ بـ <b>EQ</b> أو <b>UQ</b> وطوله 48 خانة."
        if not (re.fullmatch(r'(?:[EU][Qf]|[k0]Q)[A-Za-z0-9_\-]{46}', v) or re.fullmatch(r'-?[01]:[0-9a-fA-F]{64}', v)):
            return False, "❌ عنوان TON غير صالح — يبدأ بـ <b>EQ</b> أو <b>UQ</b> وطوله 48 خانة."
    # LTC: L… / M… / 3… أو ltc1…
    if mode == "set_v_ltc":
        if _is_trc20 or _is_bep20:
            return False, "❌ <b>هذا عنوان USDT وليس LTC!</b>\n\nعنوان LTC يبدأ بـ <b>L</b> أو <b>M</b> أو <b>ltc1</b>."
        if not (re.fullmatch(r'[LM3][a-km-zA-HJ-NP-Z1-9]{25,33}', v) or re.fullmatch(r'ltc1[02-9ac-hj-np-z]{8,87}', v)):
            return False, "❌ عنوان LTC غير صالح — يبدأ بـ <b>L</b> أو <b>M</b> أو <b>ltc1</b>."
    # Binance Pay ID: أرقام
    if mode == "set_v_wallet":
        if not re.fullmatch(r'\d{5,12}', v):
            return False, "❌ Binance Pay ID لازم يكون أرقام فقط (من صفحة Pay في بينانس)."
    # قناة السجلات: @يوزر أو -100… (أو off للإيقاف)
    if mode == "set_v_log":
        if v.lower() in ('off', 'إيقاف', 'ايقاف', 'not set'):
            return True, ""
        if not (re.fullmatch(r'@[A-Za-z0-9_]{4,32}', v) or re.fullmatch(r'-100\d{6,}', v)):
            return False, "❌ أرسل يوزر القناة (مثل <code>@my_logs</code>) أو الأيدي (يبدأ بـ <code>-100</code>). للإيقاف: <code>off</code>"
        try:
            st = bot.get_chat_member(v, bot.get_me().id).status
            if st not in ('administrator', 'creator'):
                return False, "❌ البوت مو مشرف في هذي القناة — ارفعه مشرف (مع صلاحية النشر) وجرب مرة ثانية."
        except Exception:
            return False, "❌ ما قدرت أوصل للقناة — تأكد من اليوزر/الأيدي وإن البوت مشرف فيها."
    # BscScan API Key
    if mode == "set_v_bscscan":
        if not re.fullmatch(r'[A-Za-z0-9]{20,64}', v):
            return False, "❌ مفتاح BscScan غير صالح — انسخه كامل من bscscan.com/myapikey (حروف وأرقام)."

    # الـ UID: أرقام فقط
    if mode == "set_v_bybit_uid":
        if not v.isdigit():
            return False, "❌ الـ UID لازم يكون أرقاماً فقط."

    # مفاتيح Bybit: طول معقول ولا تحوي مسافات
    if mode in ("set_v_bybit_key", "set_v_bybit_secret"):
        if ' ' in v:
            return False, "❌ المفتاح يحتوي مسافة — تأكد من النسخ الصحيح."
        if len(v) < 10:
            return False, "❌ القيمة قصيرة جداً — تأكد من نسخها كاملة."

    return True, ""


def admin_save_setting(message, mode):
    # 🛡 لو أرسل الأدمن صورة أو ملف بدل نص
    if not message.text:
        bot.send_message(message.chat.id, "❌ أرسل نصاً فقط. أعد المحاولة.")
        return
    val = message.text.strip()

    if val in ("الغاء", "إلغاء", "/cancel"):
        bot.send_message(message.chat.id, "❌ تم الإلغاء.")
        return

    db_key = _SETTING_KEYS.get(mode)
    if not db_key:
        bot.send_message(message.chat.id, "❌ إعداد غير معروف.")
        return

    ok, err = _validate_setting_value(mode, val)
    if not ok:
        bot.send_message(message.chat.id, err + "\n\n<i>لم يُحفظ شيء. جرّب مرة ثانية.</i>",
                         parse_mode="HTML")
        return

    if mode == "set_v_log" and val.lower() in ('off', 'إيقاف', 'ايقاف', 'not set'):
        val = "Not Set"                          # إيقاف قناة السجلات
    db.settings.update_one({'key': db_key}, {'$set': {'value': val}}, upsert=True)

    # تأكيد يخفي الأسرار
    shown = ("••••••" + val[-4:]) if mode in ("set_v_bybit_key", "set_v_bybit_secret", "set_v_bscscan") else val
    bot.send_message(message.chat.id,
                     f"✅ <b>تم الحفظ.</b>\n<code>{html.escape(str(shown))}</code>",
                     parse_mode="HTML")

